-- SCOM native Seraphim AI roster repair (Lua-only).
-- Use the loaded faction roster, not availability of a Chosen donor.
-- This AI module does not repair missing templates or change their canBuild
-- permissions. The v6 package includes a separate, narrowly scoped core fix
-- for five missing zero-vision economy templates. See the package README.
local seraphimAliasRegistrationLogged = false
local seraphimAliasBySource = {}

local function TemplateHasTag(template, tagName)
    if not template then return false end
    if template.hasTags and template.hasTags[tagName] then return true end
    for _, templateTag in ipairs(template.tags or {}) do
        if templateTag == tagName then return true end
    end
    return false
end

local function IsNativeSeraphimTemplateId(templateId)
    return type(templateId) == "string"
        and string.match(templateId, "^us[lasn]%d%d%d%d$") ~= nil
end

local function IsPlayableNativeSeraphimTemplate(templateId)
    local template = UnitTemplates[templateId]
    if not IsNativeSeraphimTemplateId(templateId) or not template
        or not template.general or template.general.tpId ~= templateId
        or not TemplateHasTag(template, "SERAPHIM") then return false end
    for _, tag in ipairs({ "EDA", "CHOSEN", "GUARD", "PROMETHEAN", "DEMO_UI_ONLY",
        "SCFA_CIVILIAN", "SCFA_UNSELECTABLE", "SCFA_INSIGNIFICANTUNIT" }) do
        if TemplateHasTag(template, tag) then return false end
    end
    local placement = template.additions and template.additions.scoHydroPlacement
    return not placement or placement.normalConstructionSupported ~= false
end

local function IsAvailableFactionTemplate(factionTags, templateId)
    return templateId and UnitTemplates[templateId]
        and AvailableUnits[templateId] == true
        and factionTags and factionTags[templateId] == true
end

-- ParseTagsFromString caches expanded sets. Re-indexing a template does not
-- refresh an expression that was evaluated before that template was registered.
-- Keep the declared expressions and the cache-table identities; reconcile only
-- their native Seraphim memberships. No template or build-queue function is changed.
local function RefreshNativeSeraphimBuildSnapshots(nativeIds)
    if type(ParseTagsFromString) ~= "function" then return 0 end
    local seen, refreshed = {}, 0
    for _, templateId in ipairs(nativeIds) do
        local construction = UnitTemplates[templateId].construction
        local expression = construction and construction.canBuild
        if type(expression) == "string" and not seen[expression] then
            seen[expression] = true
            local chunk, compileError = load("return " .. expression,
                "@SanctuaryRush/native-build-tags", "t", { Tags = Tags })
            local ok, current = false, compileError
            if chunk then ok, current = pcall(chunk) end
            if ok and type(current) == "table" then
                local cachedOk, cached = pcall(ParseTagsFromString, expression)
                if cachedOk and type(cached) == "table" and cached ~= current then
                    local changed = false
                    local obsolete = {}
                    for targetId in pairs(cached) do
                        if IsNativeSeraphimTemplateId(targetId) and not current[targetId] then
                            obsolete[#obsolete + 1] = targetId
                        end
                    end
                    for _, targetId in ipairs(obsolete) do
                        cached[targetId] = nil
                        changed = true
                    end
                    for targetId, allowed in pairs(current) do
                        if allowed and IsPlayableNativeSeraphimTemplate(targetId)
                            and not cached[targetId] then
                            cached[targetId] = true
                            changed = true
                        end
                    end
                    if changed then refreshed = refreshed + 1 end
                elseif not cachedOk then
                    AILog("[SeraphimRushBuildV6] Cannot refresh native build expression for "
                        .. templateId .. ": " .. tostring(cached), true)
                end
            else
                AILog("[SeraphimRushBuildV6] Native build expression left unchanged for "
                    .. templateId .. ": " .. tostring(current), true)
            end
        end
    end
    return refreshed
end

local function RegisterApprovedSeraphimAliases()
    if type(AvailableUnits) ~= "table" or type(UnitTemplates) ~= "table"
        or type(Tags) ~= "table" then return end
    local sourcePrefixes = { usl = "ucl", usa = "uca", usn = "ucn", uss = "ucs" }
    local nativeIds = {}
    for templateId in pairs(UnitTemplates) do
        if IsPlayableNativeSeraphimTemplate(templateId) then
            nativeIds[#nativeIds + 1] = templateId
        end
    end
    table.sort(nativeIds)
    for _, templateId in ipairs(nativeIds) do
        local template = UnitTemplates[templateId]
        AvailableUnits[templateId] = true
        -- Tags.__index returns an unregistered empty set. Use rawget to create
        -- persistent memberships; retain the engine's category-set metatable.
        local function register(tag)
            if type(rawget(Tags, tag)) ~= "table" then Tags[tag] = {} end
            Tags[tag][templateId] = true
        end
        for _, tag in ipairs(template.tags or {}) do register(tag) end
        register("ALL_UNITS")
        register(templateId)
        local sourceId = sourcePrefixes[string.sub(templateId, 1, 3)] .. string.sub(templateId, 4)
        seraphimAliasBySource[sourceId] = templateId
    end
    local refreshedSnapshots = RefreshNativeSeraphimBuildSnapshots(nativeIds)
    if not seraphimAliasRegistrationLogged or refreshedSnapshots > 0 then
        AILog(("[SeraphimRushBuildV6] nativeLoaded=%d uss1601Available=%s uss1611Available=%s refreshedBuildSnapshots=%d"):format(
            #nativeIds, tostring(AvailableUnits.uss1601 == true),
            tostring(AvailableUnits.uss1611 == true), refreshedSnapshots), true)
        seraphimAliasRegistrationLogged = true
    end
end

local function IsValidSeraphimRushConstructionTemplateId(templateId)
    if not IsPlayableNativeSeraphimTemplate(templateId) then return false end
    local template = UnitTemplates[templateId]
    return TemplateHasTag(template, "STRUCTURE")
        or (TemplateHasTag(template, "MOBILE") and TemplateHasTag(template, "TECH4")
            and TemplateHasTag(template, "BUILDABLE_BY_T3_ENGINEER"))
end

-- WantStructures also carries engineer-built mobile experimentals. Ordinary
-- factory-produced units are not construction targets for an engineer.
local function IsSeraphimRushStructureTemplateId(templateId)
    return IsValidSeraphimRushConstructionTemplateId(templateId)
end

-- Run before any subsequent former imports expand tag expressions.
RegisterApprovedSeraphimAliases()

-- GetFormersFromFile is called before the location manager begins evaluating
-- its cached former checks.  Clone the active hard-rush former pool here so
-- category expressions can be filtered before any build request is selected.
local function CloneSeraphimFormerValue(value, visited)
    if type(value) ~= "table" then return value end
    visited = visited or {}
    if visited[value] then return visited[value] end
    local clone = {}
    visited[value] = clone
    for key, nestedValue in pairs(value) do
        clone[CloneSeraphimFormerValue(key, visited)] = CloneSeraphimFormerValue(nestedValue, visited)
    end
    local valueMetatable = getmetatable(value)
    if valueMetatable then setmetatable(clone, valueMetatable) end
    return clone
end

local function AddSeraphimAliasesToWantedStructures(former)
    local wantedStructures = former and former.WantStructures
    if type(wantedStructures) ~= "table" then return 0, 0 end

    local addedCount = 0
    local removedForeignCount = 0
    for _, wantedUnitLine in pairs(wantedStructures) do
        if type(wantedUnitLine) == "table" then
            local aliasesToAdd = {}
            for sourceId, isWanted in pairs(wantedUnitLine) do
                local targetId = isWanted and seraphimAliasBySource[sourceId]
                if targetId and not wantedUnitLine[targetId] then
                    aliasesToAdd[#aliasesToAdd + 1] = targetId
                end
            end
            for _, targetId in ipairs(aliasesToAdd) do
                wantedUnitLine[targetId] = true
                addedCount = addedCount + 1
            end

            local foreignIds = {}
            for templateId, isWanted in pairs(wantedUnitLine) do
                if isWanted == true and not IsSeraphimRushStructureTemplateId(templateId) then
                    foreignIds[#foreignIds + 1] = templateId
                end
            end
            for _, templateId in ipairs(foreignIds) do
                wantedUnitLine[templateId] = nil
                removedForeignCount = removedForeignCount + 1
            end
        end
    end
    return addedCount, removedForeignCount
end

local function IsHydrocarbonTemplateId(templateId)
    if type(templateId) ~= "string" then return false end
    local template = UnitTemplates[templateId]
    return TemplateHasTag(template, "HYDROCARBON")
        or TemplateHasTag(template, "SCFA_HYDROCARBON")
end

local function IsSanctuaryRushArmy(armyIndex)
    local army = Armies and Armies[armyIndex]
    local settings = army and army.ai and army.ai.settings
    local directory = settings and settings.modDirectory
    return type(directory) == "string"
        and string.match(string.gsub(directory, "\\", "/"), "([^/]+)/?$") == "AI-Scom"
end

local function IsHardSanctuaryRushArmy(armyIndex)
    local army = Armies and Armies[armyIndex]
    return IsSanctuaryRushArmy(armyIndex)
        and army.ai.settings.difficulty == "hard"
end

local function IsHardSeraphimRushArmy(armyIndex)
    local army = Armies and Armies[armyIndex]
    return army and army.faction == 4 and IsHardSanctuaryRushArmy(armyIndex)
end

local function IsInvalidHardSeraphimConstruction(armyIndex, templateId)
    local army = Armies and Armies[armyIndex]
    return army and army.faction == 4
        and not IsValidSeraphimRushConstructionTemplateId(templateId)
end

-- WantStructures and WantUnits contain expanded tag sets, not only literal IDs.
-- Scrub the expanded sets so a hydrocarbon template cannot survive category
-- selection under another name or priority.
local function RemoveHydrocarbonCandidates(value, visited)
    if type(value) ~= "table" then return 0 end
    visited = visited or {}
    if visited[value] then return 0 end
    visited[value] = true

    local hydrocarbonKeys = {}
    local removedCount = 0
    for key, nestedValue in pairs(value) do
        if IsHydrocarbonTemplateId(key)
            or (type(nestedValue) == "string" and IsHydrocarbonTemplateId(nestedValue))
        then
            hydrocarbonKeys[#hydrocarbonKeys + 1] = key
        elseif type(nestedValue) == "table" then
            removedCount = removedCount + RemoveHydrocarbonCandidates(nestedValue, visited)
        end
    end
    for _, key in ipairs(hydrocarbonKeys) do
        value[key] = nil
        removedCount = removedCount + 1
    end
    return removedCount
end

local rushFactionNames = {
    [1] = "EDA",
    [2] = "CHOSEN",
    [3] = "GUARD",
    [4] = "SERAPHIM",
}

local rushFactionPrefixes = {
    [1] = "ues",
    [2] = "ucs",
    [3] = "ugs",
    [4] = "uss",
}

local function ResolveOpeningEconomyTarget(armyIndex, nativeId)
    local army = Armies and Armies[armyIndex]
    local factionTags = army and Tags[rushFactionNames[army.faction]]
    if IsAvailableFactionTemplate(factionTags, nativeId) then
        return nativeId
    end
    return nil
end

local function AddNativeOpeningEconomyTargets(armyIndex, former)
    local army = Armies[armyIndex]
    local factionName = army and rushFactionNames[army.faction]
    local factionPrefix = army and rushFactionPrefixes[army.faction]
    local wantedStructures = former and former.WantStructures
    if not factionName or not factionPrefix or type(wantedStructures) ~= "table" then return 0, 0 end

    local factionTags = Tags[factionName]
    local preferredGenerator = factionPrefix.."1611"
    local preferredExtractor = factionPrefix.."1601"
    local generatorTarget = ResolveOpeningEconomyTarget(armyIndex, preferredGenerator)
    local extractorTarget = ResolveOpeningEconomyTarget(armyIndex, preferredExtractor)
    local generatorAvailable = generatorTarget ~= nil
    local extractorAvailable = extractorTarget ~= nil
    local generatorLines = 0
    local extractorLines = 0

    for _, wantedUnitLine in pairs(wantedStructures) do
        if type(wantedUnitLine) == "table" then
            local isT1EnergyLine = false
            local isT1ExtractorLine = false
            for templateId in pairs(wantedUnitLine) do
                local template = UnitTemplates[templateId]
                if TemplateHasTag(template, "STRUCTURE") and TemplateHasTag(template, "TECH1") then
                    if TemplateHasTag(template, "ENERGY_PRODUCTION") then
                        isT1EnergyLine = true
                    elseif TemplateHasTag(template, "ALLOYS_EXTRACTION") then
                        isT1ExtractorLine = true
                    end
                end
            end
            if isT1EnergyLine and generatorAvailable then
                wantedUnitLine[generatorTarget] = true
                generatorLines = generatorLines + 1
            end
            if isT1ExtractorLine and extractorAvailable then
                wantedUnitLine[extractorTarget] = true
                extractorLines = extractorLines + 1
            end
        end
    end
    return generatorLines, extractorLines
end

local function IsAdditionalLandFactoryFormer(formerName)
    if type(formerName) ~= "string" or not string.find(formerName, "Factory Land", 1, true) then
        return false
    end
    -- These are the two permitted first-factory fallbacks.  Every other land
    -- factory former is a second-or-later production-capacity request.
    return formerName ~= "BC123 Factory Land Recover good ECO"
        and formerName ~= "BC123 Factory Land Recover 1st"
end

local function SameRushTagSet(a, b)
    if a == b then return true end
    if type(a) ~= "table" or type(b) ~= "table" then return false end
    for id, value in pairs(a) do if value and not b[id] then return false end end
    for id, value in pairs(b) do if value and not a[id] then return false end end
    return true
end

local function AppendOpeningFactoryGate(former)
    if type(former.FormerConditions) ~= "table" then
        former.FormerConditions = {}
    end
    local hasOpeningGate = false
    local hasCompletedFactoryGate = false
    for _, condition in ipairs(former.FormerConditions) do
        if condition[1] == "BlockIfStrategyActive"
            and condition[2] and condition[2][1] == "OpeningEconomyFocus"
        then
            hasOpeningGate = true
        elseif condition[1] == "MoreThanUnitsInArmyAtBase"
            and condition[2] and condition[2][1] == 0
            and SameRushTagSet(condition[2][2], Tags.LAND_FACTORY)
        then
            hasCompletedFactoryGate = true
        end
    end
    if not hasOpeningGate then
        former.FormerConditions[#former.FormerConditions + 1] = {
            "BlockIfStrategyActive", { "OpeningEconomyFocus" },
        }
    end
    if not hasCompletedFactoryGate then
        -- Prevent a second factory from being reserved while the first is
        -- still a placement ghost or unfinished construction.
        former.FormerConditions[#former.FormerConditions + 1] = {
            "MoreThanUnitsInArmyAtBase", { 0, Tags.LAND_FACTORY, false },
        }
    end
end

local function NormalizeRushFormers(armyIndex, formers)
    local army = Armies and Armies[armyIndex]
    local isHardRush = IsHardSanctuaryRushArmy(armyIndex)
    local isSeraphim = army and army.faction == 4
    if not IsSanctuaryRushArmy(armyIndex) or type(formers) ~= "table"
        or (not isSeraphim and not isHardRush) then
        return formers
    end

    if isSeraphim then RegisterApprovedSeraphimAliases() end
    local normalizedFormers = {}
    local normalizedAlloyFormers = 0
    local normalizedStructureAliases = 0
    local normalizedForeignStructureCandidates = 0
    local normalizedHydrocarbonCandidates = 0
    local normalizedGeneratorLines = 0
    local normalizedExtractorLines = 0
    local normalizedFactoryGates = 0
    for formerIndex, former in ipairs(formers) do
        local normalizedFormer = CloneSeraphimFormerValue(former)
        if isSeraphim then
            local aliasesAdded, foreignCandidatesRemoved = AddSeraphimAliasesToWantedStructures(normalizedFormer)
            normalizedStructureAliases = normalizedStructureAliases + aliasesAdded
            normalizedForeignStructureCandidates = normalizedForeignStructureCandidates + foreignCandidatesRemoved
        end

        if isHardRush then
            normalizedHydrocarbonCandidates = normalizedHydrocarbonCandidates
                + RemoveHydrocarbonCandidates(normalizedFormer)
            local generatorLines, extractorLines = AddNativeOpeningEconomyTargets(armyIndex, normalizedFormer)
            normalizedGeneratorLines = normalizedGeneratorLines + generatorLines
            normalizedExtractorLines = normalizedExtractorLines + extractorLines
            if IsAdditionalLandFactoryFormer(normalizedFormer.FormerName) then
                AppendOpeningFactoryGate(normalizedFormer)
                normalizedFactoryGates = normalizedFactoryGates + 1
            end
        end

        -- These are the two must-have Seraphim T1 economic blueprints.  Only
        -- the native uss* IDs are valid; other faction source data is never
        -- used as a Seraphim substitute.
        local alloyTarget = isSeraphim and ResolveOpeningEconomyTarget(armyIndex, "uss1601")
        local energyTarget = isSeraphim and ResolveOpeningEconomyTarget(armyIndex, "uss1611")
        if isSeraphim and normalizedFormer.AIPlan == "planEngineerCapAlloySpot"
            and type(normalizedFormer.WantStructures) == "table"
            and alloyTarget
        then
            normalizedAlloyFormers = normalizedAlloyFormers + 1
            for _, wantedUnitLine in pairs(normalizedFormer.WantStructures) do
                if type(wantedUnitLine) == "table" then
                    wantedUnitLine[alloyTarget] = true
                end
            end
        end
        if isSeraphim and normalizedFormer.FormerName == "B1 Opening Organic Energy"
            and type(normalizedFormer.WantStructures) == "table"
            and energyTarget
        then
            for _, wantedUnitLine in pairs(normalizedFormer.WantStructures) do
                if type(wantedUnitLine) == "table" then
                    wantedUnitLine[energyTarget] = true
                end
            end
        end
        normalizedFormers[formerIndex] = normalizedFormer
    end

    if army.ai and not army.ai._sanctuaryRushHardBuildPolicyLogged then
        AILog((" --- SanctuaryRushHardBuildPolicy [A:%d] formers=%d hydrocarbonCandidatesRemoved=%d "
            .."t1GeneratorLines=%d t1ExtractorLines=%d additionalFactoryGates=%d seraphimAlloyFormers=%d "
            .."seraphimStructureAliases=%d seraphimForeignStructureCandidatesRemoved=%d]"):format(
            armyIndex, #normalizedFormers, normalizedHydrocarbonCandidates,
            normalizedGeneratorLines,
            normalizedExtractorLines, normalizedFactoryGates,
            normalizedAlloyFormers, normalizedStructureAliases,
            normalizedForeignStructureCandidates
        ), true)
        army.ai._sanctuaryRushHardBuildPolicyLogged = true
    end
    return normalizedFormers
end

if AIFunctions.GetFormersFromFile
    and AIFunctions._sanctuaryRushSeraphimFormerRosterVersion ~= 5
then
    local getFormersFromFile = AIFunctions.GetFormersFromFile
    AIFunctions.GetFormersFromFile = function(armyIndex, minPriority, debug, ignoreAISettings)
        -- Category expressions are evaluated by the original loader, not by
        -- NormalizeRushFormers. Populate native tags before those expressions.
        if IsSanctuaryRushArmy(armyIndex) then RegisterApprovedSeraphimAliases() end
        local formers = getFormersFromFile(armyIndex, minPriority, debug, ignoreAISettings)
        return NormalizeRushFormers(armyIndex, formers)
    end
    AIFunctions._sanctuaryRushSeraphimFormerRosterVersion = 5
end

-- A manager may already hold this table on a late profile import. Update it in
-- place instead of only wrapping future calls to GetFormersFromFile.
for armyIndex, army in pairs(Armies or {}) do
    local pool = army.ai and army.ai.formerpool
    if IsSanctuaryRushArmy(armyIndex) and type(pool) == "table" then
        local normalized = NormalizeRushFormers(armyIndex, pool)
        if normalized ~= pool then
            for key in pairs(pool) do pool[key] = nil end
            for key, former in pairs(normalized) do pool[key] = former end
        end
    end
end

-- Report actual engine eligibility once per native builder class. This distinguishes
-- a missing AI candidate from a missing template or a core construction restriction.
local function ReportNativeSeraphimBuilderAccess(armyIndex, builders)
    local army = Armies and Armies[armyIndex]
    if not army or army.faction ~= 4 or not army.ai then return end
    army.ai._seraphimRushBuildAccessReported = army.ai._seraphimRushBuildAccessReported or {}
    local reported = army.ai._seraphimRushBuildAccessReported
    for _, builder in ipairs(builders or {}) do
        if IsNativeSeraphimTemplateId(builder.tpId) and not reported[builder.tpId] then
            reported[builder.tpId] = true
            local results = {}
            for _, targetId in ipairs({ "uss1601", "uss1611" }) do
                local allowed = "unknown"
                if buildQueueUtils and type(buildQueueUtils.CanBuild) == "function" then
                    local ok, result = pcall(buildQueueUtils.CanBuild, builder, targetId, 1)
                    allowed = ok and tostring(result == true) or ("error:" .. tostring(result))
                end
                results[#results + 1] = targetId .. "{loaded="
                    .. tostring(UnitTemplates[targetId] ~= nil) .. ",available="
                    .. tostring(AvailableUnits[targetId] == true) .. ",sourceDomain="
                    .. tostring(Tags.SCFA_ALLUNITS[targetId] == true) .. ",canBuild="
                    .. allowed .. "}"
            end
            AILog("[SeraphimRushBuildV6] army=" .. tostring(armyIndex)
                .. " builder=" .. builder.tpId .. " " .. table.concat(results, " "), true)
        end
    end
end

local OPENING_ECONOMY_DURATION_SECONDS = 120

---Stops the bounded hard-mode opening focus and leaves its one-shot sentinel intact.
---@param armyIndex integer Army index that owns the opening phase
---@param aiState table AI state captured when the phase started
---@param reason string Human-readable stop reason for telemetry
---@return nil
local function StopOpeningEconomyFocus(armyIndex, aiState, reason)
    local openingEconomy = aiState and aiState.openingEconomy
    if not openingEconomy or openingEconomy.stopped then return end

    openingEconomy.stopped = true
    openingEconomy.stoppedAt = GetGameTimeSeconds()
    openingEconomy.stopReason = reason
    if aiState.strategySwitches then
        aiState.strategySwitches.OpeningEconomyFocus = false
    end
    AILog(" --- OpeningEconomyFocusStop [A:"..armyIndex.."] Time:"..openingEconomy.stoppedAt.." Reason:"..reason)
end

---Maintains the temporary opening policy without blocking any AI behavior thread.
---@param armyIndex integer Army index that owns the phase
---@param aiState table AI state captured when the opening focus started
---@return nil
local function OpeningEconomyFocusThread(armyIndex, aiState)
    local openingEconomy = aiState.openingEconomy
    while openingEconomy and not openingEconomy.stopped
        and (RushBalance.Enabled(Armies[armyIndex]) and RushBalance.OpeningFocus(Armies[armyIndex])
            or not RushBalance.Enabled(Armies[armyIndex]) and GetGameTimeSeconds() < openingEconomy.endsAt) do
        local army = Armies[armyIndex]
        if not army or army.ai ~= aiState or aiState.isAlive == false then
            StopOpeningEconomyFocus(armyIndex, aiState, "AI no longer active")
            return
        end
        WaitTicks(10)
    end
    StopOpeningEconomyFocus(armyIndex, aiState, RushBalance.Enabled(Armies[armyIndex]) and "opening economy established" or "duration complete")
end

---Returns the build target created by the most recently accepted BUILD order.
---@param builder table Engineer or commander that received the order
---@return table|nil Construction placement ghost, when the order was accepted
local function GetLatestBuildOrderTarget(builder)
    local orders = builder and builder.orders
    if not orders then return nil end

    local activeOrder = orders.activeOrder
    if activeOrder and activeOrder.orderTask == OrderTasks.BUILD then
        return activeOrder.unitGettingBuilt
    end

    local queuedOrders = orders.queuedOrders
    local queuedOrder = queuedOrders and queuedOrders[#queuedOrders]
    if queuedOrder and queuedOrder.orderTask == OrderTasks.BUILD then
        return queuedOrder.unitGettingBuilt
    end
    return nil
end

---Starts one exact two-minute hard-mode economy-building phase on the first factory placement.
---@param armyIndex integer Army index that placed the factory
---@param factoryTarget table|nil Newly created construction placement ghost
---@return nil
local function TryStartOpeningEconomyFocus(armyIndex, factoryTarget)
    local army = Armies[armyIndex]
    local aiState = army and army.ai
    if not aiState or aiState.isAlive == false or not aiState.settings or aiState.settings.difficulty ~= "hard" then return end
    if aiState.openingEconomyStarted or not factoryTarget or factoryTarget.dead or not factoryTarget:HasTags(Tags.FACTORY) then return end

    local factoryCount = 0
    for _, unit in pairs(army.units or {}) do
        if not unit.dead and unit:HasTags(Tags.FACTORY) then
            factoryCount = factoryCount + 1
            if factoryCount > 1 then return end
        end
    end
    if factoryCount ~= 1 then return end

    local startedAt = GetGameTimeSeconds()
    local openingEconomy = {
        startedAt = startedAt,
        endsAt = startedAt + OPENING_ECONOMY_DURATION_SECONDS,
        stopped = false,
    }

    aiState.openingEconomyStarted = true
    aiState.openingEconomy = openingEconomy
    aiState.strategySwitches = aiState.strategySwitches or {}
    aiState.strategySwitches.OpeningEconomyFocus = true
    AILog(" --- OpeningEconomyFocusStart [A:"..armyIndex.."] Start:"..startedAt.." End:"..openingEconomy.endsAt)
    NewThread(OpeningEconomyFocusThread, armyIndex, aiState)
end

---Copies the shared randomized-position result before an order retains it.
---@param position table Source waypoint
---@return table Independent randomized waypoint
local function GetRandomizedPositionCopy(position)
    local randomizedPosition = AIFunctions.GetRandomPostitionAround(position)
    return { x = randomizedPosition.x, y = randomizedPosition.y, z = randomizedPosition.z }
end

---Returns the fallback focus army index for host-side code.
---@return integer Focus army index
local function GetFocusArmy() return 1 end -- temporary fallback, host has no access to client focus state

---Sorts builder units by increasing range to the build location.
---@param a table Builder unit with ai.rangeToBuildLocation
---@param b table Builder unit with ai.rangeToBuildLocation
---@return boolean Returns true when a should be sorted before b
local function SortBuilderUnitsAscendingByRangeToBuildLocationValue(a, b)
    return a.ai.rangeToBuildLocation < b.ai.rangeToBuildLocation
end

---Sorts builder units by increasing assist range.
---@param a table Builder unit with ai.assistRange
---@param b table Builder unit with ai.assistRange
---@return boolean Returns true when a should be sorted before b
local function SortBuilderUnitsAscendingByAssistRangeValue(a, b)
    return a.ai.assistRange < b.ai.assistRange
end

---Sorts possible unit records by increasing assister count.
---@param a table Possible unit record with assister
---@param b table Possible unit record with assister
---@return boolean Returns true when a should be sorted before b
local function SortPossibleUnitsAscendingByAssisterValue(a, b)
    return a.assister < b.assister
end

---Sorts units by decreasing resource cost.
---@param a table Unit record with unitResourceCost
---@param b table Unit record with unitResourceCost
---@return boolean Returns true when a should be sorted before b
local function SortUnitsToCoverDescendingByUnitResourceCostValue(a, b)
    return a.unitResourceCost > b.unitResourceCost
end

--- Returns a reusable single-element array for the given unit.
--- @param unit table  -- unit object, unit.ai must already exist
--- @return table      -- single-element array containing the unit
local function UnitAsArray(unit)
    local singleUnitArray = unit.ai.singleUnitArray
    if not singleUnitArray then
        singleUnitArray = { unit }
        unit.ai.singleUnitArray = singleUnitArray
    end
    return singleUnitArray
end

---Returns the maximum vision or radar radius available to a land microing unit.
---@param unit table Unit class table
---@return number Returns maximum intel radius
local function GetLandMicroUnitIntelRadius(unit)
    local intel = unit.tp.intel or {}
    return math.max(intel.visionRadius or 0, intel.radarRadius or 0)
end

---Checks whether a support unit currently provides target intel coverage.
---@param platoonUnits table Platoon unit list
---@param targetPosition table Target position formatted as {x, y, z}
---@return boolean Returns true when a support unit covers the target position
local function HasLandMicroSupportIntelCoverage(platoonUnits, targetPosition)
    for _, unit in ipairs(platoonUnits) do
        if not unit.dead and unit.ai.IsShieldOnlyUnit then
            local intelRadius = GetLandMicroUnitIntelRadius(unit) - LAND_MICRO_INTEL_POSITION_MARGIN
            if intelRadius > 0 then
                local unitPosition = unit:GetPosition()
                if Distance2DSquared(unitPosition.x, unitPosition.z, targetPosition.x, targetPosition.z) <= intelRadius * intelRadius then return true end
            end
        end
    end
    return false
end

---Returns whether an indirect-fire unit should hold position to aim or finish its salvo.
---@param unit table Unit class table
---@return boolean Returns true while the primary indirect-fire weapon needs a stable firing position
local function ShouldLandMicroUnitHoldForIndirectFire(unit)
    local weaponMicroData = unit.ai.weaponMicroData
    local primaryWeapon = weaponMicroData and weaponMicroData.primaryWeapon
    return weaponMicroData and weaponMicroData.rangeRingType == "IndirectFire" and primaryWeapon and ((primaryWeapon.salvosRemaining or 0) > 0 or (primaryWeapon.reloadTimer or 0) <= weaponMicroData.indirectFireAimPreparationTime)
end

---Sorts land attack units by lateral position and then from front to rear.
---@param firstUnit table First unit
---@param secondUnit table Second unit
---@return boolean Returns true when the first unit belongs before the second unit
local function SortLandMicroFormationUnitsByPosition(firstUnit, secondUnit)
    local firstLateralPosition = firstUnit.ai.landMicroFormationLateralPosition
    local secondLateralPosition = secondUnit.ai.landMicroFormationLateralPosition
    if firstLateralPosition == secondLateralPosition then
        local firstForwardPosition = firstUnit.ai.landMicroFormationForwardPosition
        local secondForwardPosition = secondUnit.ai.landMicroFormationForwardPosition
        if firstForwardPosition == secondForwardPosition then return firstUnit.id.index < secondUnit.id.index end
        return firstForwardPosition > secondForwardPosition
    end
    return firstLateralPosition < secondLateralPosition
end

---Sorts land attack units by their stable formation order.
---@param firstUnit table First unit
---@param secondUnit table Second unit
---@return boolean Returns true when the first unit belongs before the second unit
local function SortLandMicroTargetAssignmentUnits(firstUnit, secondUnit)
    local firstFormationIndex = firstUnit.ai.landMicroFormationIndex or math.huge
    local secondFormationIndex = secondUnit.ai.landMicroFormationIndex or math.huge
    if firstFormationIndex == secondFormationIndex then return firstUnit.id.index < secondUnit.id.index end
    return firstFormationIndex < secondFormationIndex
end

---Clears land formation state after close combat ends.
---@param platoon table Platoon class table
---@return nil
local function ClearLandMicroFormationData(platoon)
    platoon.ai.landMicroFormationData = nil
    for _, unit in pairs(platoon:GetUnits()) do
        if unit.ai then
            unit.ai.landMicroFormationPosition = nil
            unit.ai.landMicroFormationOrderedPosition = nil
            unit.ai.landMicroFormationForwardPosition = nil
            unit.ai.landMicroFormationLateralPosition = nil
            unit.ai.landMicroFormationIndex = nil
            unit.ai.landMicroFormationAdvancePosition = nil
            unit.ai.landMicroOrderedAttackPosition = nil
            unit.ai.landMicroOrderedAttackTarget = nil
            unit.ai.microTarget = nil
            unit.ai.landMicroIsIntelSpotter = nil
            unit.ai.landMicroTargetAssignmentIndex = nil
            unit.ai.landMicroTerrainCache = nil
        end
    end
end

---Reuses recent land line-of-sight results while neither unit moved far enough to change the terrain path.
---@param unit table The attacking unit
---@param target table The target unit
---@param rangeRingType string The weapon range ring type
---@param formerTableDebug boolean Enables debug output
---@param unitPosition table Cached attacking unit position
---@param targetPosition table Cached target unit position
---@return boolean Returns true when terrain blocks the weapon path
local function CheckCachedLandMicroBlockingTerrain(unit, target, rangeRingType, formerTableDebug, unitPosition, targetPosition)
    if rangeRingType == "AntiAir" then return false end
    local terrainCache = unit.ai.landMicroTerrainCache
    local recheckDistanceSquared = LAND_MICRO_TERRAIN_RECHECK_DISTANCE * LAND_MICRO_TERRAIN_RECHECK_DISTANCE
    if terrainCache and terrainCache.target == target and terrainCache.rangeRingType == rangeRingType and terrainCache.remainingTurns > 0 and Distance2DSquared(terrainCache.unitPositionX, terrainCache.unitPositionZ, unitPosition.x, unitPosition.z) <= recheckDistanceSquared and Distance2DSquared(terrainCache.targetPositionX, terrainCache.targetPositionZ, targetPosition.x, targetPosition.z) <= recheckDistanceSquared then
        terrainCache.remainingTurns = terrainCache.remainingTurns - 1
        return terrainCache.blocked
    end
    local terrainBlocked = CheckBlockingTerrain(unit, target, rangeRingType, formerTableDebug, unitPosition, targetPosition)
    terrainCache = terrainCache or {}
    terrainCache.target = target
    terrainCache.rangeRingType = rangeRingType
    terrainCache.blocked = terrainBlocked
    terrainCache.remainingTurns = (terrainBlocked and LAND_MICRO_TERRAIN_BLOCKED_RECHECK_TURNS or LAND_MICRO_TERRAIN_UNBLOCKED_RECHECK_TURNS) - 1
    terrainCache.unitPositionX = unitPosition.x
    terrainCache.unitPositionZ = unitPosition.z
    terrainCache.targetPositionX = targetPosition.x
    terrainCache.targetPositionZ = targetPosition.z
    unit.ai.landMicroTerrainCache = terrainCache
    return terrainBlocked
end

---Creates a broad and shallow land formation facing the current enemy group.
---@param platoon table Platoon class table
---@param platoonUnits table Platoon units
---@param platoonPosition table Current platoon position
---@param targetPlatoonCenterPosition table Current enemy group center
---@param ownPlatoonThreat number Current platoon threat against the target layer
---@param enemyGroupThreat number Current enemy group threat against the platoon layer
---@return nil
local function InitializeLandMicroFormationData(platoon, platoonUnits, platoonPosition, targetPlatoonCenterPosition, ownPlatoonThreat, enemyGroupThreat)
    local formationUnits = {}
    local formationUnitSpacing = LAND_MICRO_FORMATION_MINIMUM_UNIT_SPACING
    for _, unit in pairs(platoonUnits) do
        if unit.ai.eState == "PlatoonControlled" and not unit.dead and not unit.ai.IsShieldOnlyUnit then
            table.insert(formationUnits, unit)
            local collisionSize = unit.tp.collisionInfo and unit.tp.collisionInfo.collisionSize
            if collisionSize then
                formationUnitSpacing = math.max(formationUnitSpacing, collisionSize.x + LAND_MICRO_FORMATION_COLLISION_CLEARANCE, collisionSize.z + LAND_MICRO_FORMATION_COLLISION_CLEARANCE)
            end
        end
    end
    if #formationUnits < LAND_MICRO_FORMATION_MINIMUM_UNIT_COUNT then
        platoon.ai.landMicroFormationData = {phase = "Engaging", unitSpacing = formationUnitSpacing}
        return
    end
    if ownPlatoonThreat > 0 and enemyGroupThreat < ownPlatoonThreat * LAND_MICRO_FORMATION_MINIMUM_ENEMY_THREAT_RATIO then
        platoon.ai.landMicroFormationData = {phase = "Engaging", unitSpacing = formationUnitSpacing}
        if lobbyOptionsAI.debugGameTelemetry then
            AILog(" --- TacticalLandFormation [A:"..platoon.army.id.."][P:"..platoon.id.."] Phase:Skipped Reason:EnemyThreatBelowMinimumRatio OwnThreat:"..tostring(ownPlatoonThreat).." EnemyThreat:"..tostring(enemyGroupThreat).." MinimumEnemyThreatRatio:"..tostring(LAND_MICRO_FORMATION_MINIMUM_ENEMY_THREAT_RATIO).." PlatoonUnits:"..tostring(#formationUnits))
        end
        return
    end
    local forwardDirectionX = targetPlatoonCenterPosition.x - platoonPosition.x
    local forwardDirectionZ = targetPlatoonCenterPosition.z - platoonPosition.z
    local forwardDirectionLength = math.sqrt(forwardDirectionX * forwardDirectionX + forwardDirectionZ * forwardDirectionZ)
    if forwardDirectionLength > 0 then
        forwardDirectionX = forwardDirectionX / forwardDirectionLength
        forwardDirectionZ = forwardDirectionZ / forwardDirectionLength
    else
        forwardDirectionX = 1
        forwardDirectionZ = 0
    end
    local lateralDirectionX = -forwardDirectionZ
    local lateralDirectionZ = forwardDirectionX
    for _, unit in ipairs(formationUnits) do
        local unitPosition = unit:GetPosition()
        local relativePositionX = unitPosition.x - platoonPosition.x
        local relativePositionZ = unitPosition.z - platoonPosition.z
        unit.ai.landMicroFormationForwardPosition = relativePositionX * forwardDirectionX + relativePositionZ * forwardDirectionZ
        unit.ai.landMicroFormationLateralPosition = relativePositionX * lateralDirectionX + relativePositionZ * lateralDirectionZ
    end
    table.sort(formationUnits, SortLandMicroFormationUnitsByPosition)
    local desiredFormationColumnCount = math.ceil(math.sqrt(#formationUnits * LAND_MICRO_FORMATION_WIDTH_FACTOR))
    local formationRowCount = math.ceil(#formationUnits / desiredFormationColumnCount)
    local formationColumnCount = math.ceil(#formationUnits / formationRowCount)
    platoon.ai.landMicroFormationData = {
        phase = "Forming",
        turnCount = 0,
        unitSpacing = formationUnitSpacing,
        forwardDirectionX = forwardDirectionX,
        forwardDirectionZ = forwardDirectionZ,
    }
    if lobbyOptionsAI.debugGameTelemetry then
        AILog(" --- TacticalLandFormation [A:"..platoon.army.id.."][P:"..platoon.id.."] Phase:Forming OwnThreat:"..tostring(ownPlatoonThreat).." EnemyThreat:"..tostring(enemyGroupThreat).." MinimumEnemyThreatRatio:"..tostring(LAND_MICRO_FORMATION_MINIMUM_ENEMY_THREAT_RATIO).." PlatoonUnits:"..tostring(#formationUnits))
    end
    for formationUnitIndex, unit in ipairs(formationUnits) do
        local formationColumnIndex = math.floor((formationUnitIndex - 1) / formationRowCount)
        local formationRowIndex = (formationUnitIndex - 1) % formationRowCount
        local remainingFormationUnitCount = #formationUnits - formationColumnIndex * formationRowCount
        local currentColumnUnitCount = math.min(formationRowCount, remainingFormationUnitCount)
        local lateralOffset = (formationColumnIndex - (formationColumnCount - 1) / 2) * formationUnitSpacing
        local forwardOffset = ((currentColumnUnitCount - 1) / 2 - formationRowIndex) * formationUnitSpacing
        local formationPosition = {
            x = platoonPosition.x + forwardDirectionX * forwardOffset + lateralDirectionX * lateralOffset,
            y = platoonPosition.y,
            z = platoonPosition.z + forwardDirectionZ * forwardOffset + lateralDirectionZ * lateralOffset,
        }
        SnapToGround(formationPosition, formationPosition)
        local clampedFormationPosition = RushMovementV18.Clamp(formationPosition)
        unit.ai.landMicroFormationPosition = {x = clampedFormationPosition.x, y = clampedFormationPosition.y, z = clampedFormationPosition.z}
        unit.ai.landMicroFormationIndex = formationUnitIndex
        unit.ai.landMicroFormationOrderedPosition = nil
        unit.ai.landMicroFormationForwardPosition = nil
        unit.ai.landMicroFormationLateralPosition = nil
    end
end

---Moves land attack units into their assigned formation and reports positions to support units.
---@param platoon table Platoon class table
---@param platoonUnits table Platoon units
---@param targetPlatoonCenterPosition table Current enemy group center
---@return table Returns attack units and their protected positions
local function MoveLandMicroFormationUnits(platoon, platoonUnits, targetPlatoonCenterPosition)
    local formationData = platoon.ai.landMicroFormationData
    formationData.turnCount = formationData.turnCount + 1
    local formationUnitCount = 0
    local readyFormationUnitCount = 0
    local unitsToCover = {}
    for _, unit in pairs(platoonUnits) do
        local formationPosition = unit.ai.landMicroFormationPosition
        if unit.ai.eState == "PlatoonControlled" and not unit.dead and not unit.ai.IsShieldOnlyUnit and formationPosition then
            formationUnitCount = formationUnitCount + 1
            unit.ai.microTarget = nil
            unit.ai.Blocked = false
            local unitPosition = unit:GetPosition()
            if Distance2DSquared(unitPosition.x, unitPosition.z, formationPosition.x, formationPosition.z) <= LAND_MICRO_FORMATION_READY_DISTANCE * LAND_MICRO_FORMATION_READY_DISTANCE then
                readyFormationUnitCount = readyFormationUnitCount + 1
            end
            local orderedFormationPosition = unit.ai.landMicroFormationOrderedPosition
            if not orderedFormationPosition or Distance2DSquared(formationPosition.x, formationPosition.z, orderedFormationPosition.x, orderedFormationPosition.z) > LAND_MICRO_ORDER_POSITION_CHANGE_DISTANCE * LAND_MICRO_ORDER_POSITION_CHANGE_DISTANCE then
                HostIssueOrder(OrderTasks.MOVE, UnitAsArray(unit), false, formationPosition, nil)
                unit.ai.landMicroFormationOrderedPosition = {x = formationPosition.x, y = formationPosition.y, z = formationPosition.z}
            end
            local unitSmartPosition = unit.ai.smartPos or {x = 0, y = 0, z = 0}
            unitSmartPosition.x = formationPosition.x
            unitSmartPosition.y = formationPosition.y
            unitSmartPosition.z = formationPosition.z
            unit.ai.smartPos = unitSmartPosition
            table.insert(unitsToCover, {unitResourceCost = unit.ai.unitResourceCost, smartPos = unitSmartPosition, microTargetPos = targetPlatoonCenterPosition})
        end
    end
    local formationReadyRatio = formationUnitCount > 0 and readyFormationUnitCount / formationUnitCount or 1
    if formationData.turnCount >= LAND_MICRO_FORMATION_MAXIMUM_TURNS or formationData.turnCount >= LAND_MICRO_FORMATION_MINIMUM_TURNS and formationReadyRatio >= LAND_MICRO_FORMATION_READY_RATIO then
        formationData.phase = "Advancing"
        for _, unit in pairs(platoonUnits) do
            if unit.ai then unit.ai.landMicroFormationOrderedPosition = nil end
        end
        if lobbyOptionsAI.debugGameTelemetry then
            AILog(" --- TacticalLandFormation [A:"..platoon.army.id.."][P:"..platoon.id.."] Phase:Advancing Ready:"..tostring(readyFormationUnitCount).."/"..tostring(formationUnitCount).." Turns:"..tostring(formationData.turnCount))
        end
    end
    if #unitsToCover > 0 then table.sort(unitsToCover, SortUnitsToCoverDescendingByUnitResourceCostValue) end
    return unitsToCover
end

---Advances a formed land platoon without changing its unit offsets until the first weapon contact.
---@param platoon table Platoon class table
---@param platoonUnits table Platoon units
---@param targetPlatoonCenterPosition table Current enemy group center
---@param cachedTargetUnits table Cached enemy units
---@param cachedTargetPositions table Cached enemy positions keyed by unit
---@param cachedTargetCount integer Number of cached enemy units
---@return table|nil unitsToCover Attack units and their protected positions
---@return boolean weaponContactReached Whether individual combat movement may begin
local function AdvanceLandMicroFormationUnits(platoon, platoonUnits, targetPlatoonCenterPosition, cachedTargetUnits, cachedTargetPositions, cachedTargetCount)
    local formationData = platoon.ai.landMicroFormationData
    for _, unit in pairs(platoonUnits) do
        if unit.ai.eState == "PlatoonControlled" and not unit.dead and not unit.ai.IsShieldOnlyUnit and unit.ai.landMicroFormationPosition then
            local maximumWeaponRange = unit.ai.maxWeaponRange or 0
            if maximumWeaponRange > 0 then
                local unitPosition = unit:GetPosition()
                for targetIndex = 1, cachedTargetCount do
                    local targetPosition = cachedTargetPositions[cachedTargetUnits[targetIndex]]
                    if targetPosition and Distance2DSquared(unitPosition.x, unitPosition.z, targetPosition.x, targetPosition.z) <= maximumWeaponRange * maximumWeaponRange then
                        formationData.phase = "Engaging"
                        for _, formationUnit in pairs(platoonUnits) do
                            if formationUnit.ai then formationUnit.ai.landMicroFormationOrderedPosition = nil end
                        end
                        if lobbyOptionsAI.debugGameTelemetry then
                            AILog(" --- TacticalLandFormation [A:"..platoon.army.id.."][P:"..platoon.id.."] Phase:Engaging Reason:WeaponContact PlatoonUnits:"..tostring(table.getn(platoonUnits)))
                        end
                        return nil, true
                    end
                end
            end
        end
    end
    local forwardDirectionX = formationData.forwardDirectionX
    local forwardDirectionZ = formationData.forwardDirectionZ
    local minimumAdvanceDistance
    for _, unit in pairs(platoonUnits) do
        local formationPosition = unit.ai.landMicroFormationPosition
        local maximumWeaponRange = unit.ai.maxWeaponRange or 0
        if unit.ai.eState == "PlatoonControlled" and not unit.dead and not unit.ai.IsShieldOnlyUnit and formationPosition and maximumWeaponRange > 0 then
            for targetIndex = 1, cachedTargetCount do
                local targetPosition = cachedTargetPositions[cachedTargetUnits[targetIndex]]
                if targetPosition then
                    local targetOffsetX = targetPosition.x - formationPosition.x
                    local targetOffsetZ = targetPosition.z - formationPosition.z
                    local forwardDistance = targetOffsetX * forwardDirectionX + targetOffsetZ * forwardDirectionZ
                    local lateralDistanceSquared = math.max(0, targetOffsetX * targetOffsetX + targetOffsetZ * targetOffsetZ - forwardDistance * forwardDistance)
                    local formationContactRange = math.max(1, maximumWeaponRange - 1)
                    local formationContactRangeSquared = formationContactRange * formationContactRange
                    if forwardDistance >= 0 and lateralDistanceSquared <= formationContactRangeSquared then
                        local advanceDistance = math.max(0, forwardDistance - math.sqrt(formationContactRangeSquared - lateralDistanceSquared))
                        minimumAdvanceDistance = minimumAdvanceDistance and math.min(minimumAdvanceDistance, advanceDistance) or advanceDistance
                    end
                end
            end
        end
    end
    if not minimumAdvanceDistance then
        formationData.phase = "Engaging"
        if lobbyOptionsAI.debugGameTelemetry then
            AILog(" --- TacticalLandFormation [A:"..platoon.army.id.."][P:"..platoon.id.."] Phase:Engaging Reason:NoForwardContact PlatoonUnits:"..tostring(table.getn(platoonUnits)))
        end
        return nil, true
    end
    formationData.advanceDistance = math.max(formationData.advanceDistance or 0, minimumAdvanceDistance)
    if lobbyOptionsAI.debugGameTelemetry and not formationData.advanceOrderTelemetryLogged then
        formationData.advanceOrderTelemetryLogged = true
        AILog(" --- TacticalLandFormation [A:"..platoon.army.id.."][P:"..platoon.id.."] Phase:Advancing Reason:FormationMove Distance:"..tostring(formationData.advanceDistance).." PlatoonUnits:"..tostring(table.getn(platoonUnits)))
    end
    local unitsToCover = {}
    for _, unit in pairs(platoonUnits) do
        local formationPosition = unit.ai.landMicroFormationPosition
        if unit.ai.eState == "PlatoonControlled" and not unit.dead and not unit.ai.IsShieldOnlyUnit and formationPosition then
            unit.ai.microTarget = nil
            unit.ai.Blocked = false
            local advancePosition = unit.ai.landMicroFormationAdvancePosition or {x = 0, y = 0, z = 0}
            advancePosition.x = formationPosition.x + forwardDirectionX * formationData.advanceDistance
            advancePosition.y = formationPosition.y
            advancePosition.z = formationPosition.z + forwardDirectionZ * formationData.advanceDistance
            SnapToGround(advancePosition, advancePosition)
            local clampedAdvancePosition = RushMovementV18.Clamp(advancePosition)
            advancePosition.x = clampedAdvancePosition.x
            advancePosition.y = clampedAdvancePosition.y
            advancePosition.z = clampedAdvancePosition.z
            unit.ai.landMicroFormationAdvancePosition = advancePosition
            local orderedFormationPosition = unit.ai.landMicroFormationOrderedPosition
            if not orderedFormationPosition or Distance2DSquared(advancePosition.x, advancePosition.z, orderedFormationPosition.x, orderedFormationPosition.z) > LAND_MICRO_ORDER_POSITION_CHANGE_DISTANCE * LAND_MICRO_ORDER_POSITION_CHANGE_DISTANCE then
                HostIssueOrder(OrderTasks.MOVE, UnitAsArray(unit), false, advancePosition, nil)
                unit.ai.landMicroFormationOrderedPosition = {x = advancePosition.x, y = advancePosition.y, z = advancePosition.z}
            end
            local unitSmartPosition = unit.ai.smartPos or {x = 0, y = 0, z = 0}
            unitSmartPosition.x = advancePosition.x
            unitSmartPosition.y = advancePosition.y
            unitSmartPosition.z = advancePosition.z
            unit.ai.smartPos = unitSmartPosition
            table.insert(unitsToCover, {unitResourceCost = unit.ai.unitResourceCost, smartPos = unitSmartPosition, microTargetPos = targetPlatoonCenterPosition})
        end
    end
    if #unitsToCover > 0 then table.sort(unitsToCover, SortUnitsToCoverDescendingByUnitResourceCostValue) end
    return unitsToCover, false
end

---Places one land unit in a distinct firing arc or reserve position around its assigned target.
---@param unit table Attack unit
---@param unitPosition table Current unit position
---@param targetPosition table Current target position
---@param retreatDirectionX number Direction from the enemy group towards the platoon
---@param retreatDirectionZ number Direction from the enemy group towards the platoon
---@param targetAssignmentIndex integer One-based assignment index for this target
---@param targetAssignmentCount integer Number of units assigned to this target
---@param formationUnitSpacing number Minimum position spacing
---@param maximumAttackRadius number Maximum distance from the target
---@param smartAttackPosition table Reusable output position
---@return nil
local function SetLandMicroAttackPosition(unit, unitPosition, targetPosition, retreatDirectionX, retreatDirectionZ, targetAssignmentIndex, targetAssignmentCount, formationUnitSpacing, maximumAttackRadius, smartAttackPosition)
    if retreatDirectionX == 0 and retreatDirectionZ == 0 then
        retreatDirectionX = unitPosition.x - targetPosition.x
        retreatDirectionZ = unitPosition.z - targetPosition.z
        local retreatDirectionLength = math.sqrt(retreatDirectionX * retreatDirectionX + retreatDirectionZ * retreatDirectionZ)
        if retreatDirectionLength > 0 then
            retreatDirectionX = retreatDirectionX / retreatDirectionLength
            retreatDirectionZ = retreatDirectionZ / retreatDirectionLength
        else
            retreatDirectionX = 1
            retreatDirectionZ = 0
        end
    end
    maximumAttackRadius = math.max(1, maximumAttackRadius)
    local remainingTargetAssignmentIndex = targetAssignmentIndex
    local remainingTargetAssignmentCount = targetAssignmentCount
    local attackRadius = maximumAttackRadius
    while attackRadius >= 1 do
        local chordRatio = math.min(1, formationUnitSpacing / (2 * attackRadius))
        local angularSpacing = 2 * math.asin(chordRatio)
        local firingArcCapacity = math.max(1, math.floor(LAND_MICRO_ATTACK_ARC_ANGLE / angularSpacing) + 1)
        local firingArcUnitCount = math.min(firingArcCapacity, remainingTargetAssignmentCount)
        if remainingTargetAssignmentIndex <= firingArcUnitCount then
            local angleOffset = firingArcUnitCount > 1 and (remainingTargetAssignmentIndex - (firingArcUnitCount + 1) / 2) * angularSpacing or 0
            local angleCosine = math.cos(angleOffset)
            local angleSine = math.sin(angleOffset)
            local attackDirectionX = retreatDirectionX * angleCosine - retreatDirectionZ * angleSine
            local attackDirectionZ = retreatDirectionX * angleSine + retreatDirectionZ * angleCosine
            smartAttackPosition.x = targetPosition.x + attackDirectionX * attackRadius
            smartAttackPosition.y = targetPosition.y
            smartAttackPosition.z = targetPosition.z + attackDirectionZ * attackRadius
            return
        end
        remainingTargetAssignmentIndex = remainingTargetAssignmentIndex - firingArcUnitCount
        remainingTargetAssignmentCount = remainingTargetAssignmentCount - firingArcUnitCount
        attackRadius = attackRadius - formationUnitSpacing
    end
    local reserveUnitsPerRow = math.max(1, math.floor(maximumAttackRadius * 2 / formationUnitSpacing) + 1)
    local reserveRowIndex = math.floor((remainingTargetAssignmentIndex - 1) / reserveUnitsPerRow)
    local reserveColumnIndex = (remainingTargetAssignmentIndex - 1) % reserveUnitsPerRow
    local remainingReserveUnitCount = remainingTargetAssignmentCount - reserveRowIndex * reserveUnitsPerRow
    local currentReserveRowUnitCount = math.min(reserveUnitsPerRow, remainingReserveUnitCount)
    local lateralDirectionX = -retreatDirectionZ
    local lateralDirectionZ = retreatDirectionX
    local lateralOffset = (reserveColumnIndex - (currentReserveRowUnitCount - 1) / 2) * formationUnitSpacing
    local retreatOffset = maximumAttackRadius + (reserveRowIndex + 1) * formationUnitSpacing
    smartAttackPosition.x = targetPosition.x + retreatDirectionX * retreatOffset + lateralDirectionX * lateralOffset
    smartAttackPosition.y = targetPosition.y
    smartAttackPosition.z = targetPosition.z + retreatDirectionZ * retreatOffset + lateralDirectionZ * lateralOffset
end

---Gets the maximum naval platoon range against water and coastal targets.
---@param platoon table Naval platoon
---@return number maximumWeaponRange Maximum usable weapon range
local function GetNavalMaximumWeaponRange(platoon)
    return math.max(GetPlatoonMaxWeaponRange(platoon, "WaterSurface"), GetPlatoonMaxWeaponRange(platoon, "Land"))
end

---Returns whether a unit is currently available as an attack target.
---@param targetUnit table|nil Target unit
---@return boolean targetAvailable Target can receive attack orders
local function IsAttackTargetAvailable(targetUnit)
    return targetUnit and not targetUnit.dead and not targetUnit.CaptureInProgress and not targetUnit.ReclaimInProgress
end

---Returns whether at least one active platoon weapon can damage the target in its current layer.
---@param platoon table Attacking platoon
---@param targetUnit table|nil Candidate target
---@return boolean canShoot Target can be attacked by a real platoon weapon
local function CanPlatoonShootTarget(platoon, targetUnit)
    if not IsAttackTargetAvailable(targetUnit) then return false end
    for _, unit in pairs(platoon.units or {}) do
        if not unit.dead then
            for _, weapon in ipairs(unit.weapons or {}) do
                if weapon.enabled and not weapon.isDeathExplosion and weapon:CanShootAt(targetUnit) then return true end
            end
        end
    end
    return false
end

---Gets the nearest completed enemy that an actual platoon weapon can damage.
---@param platoon table Attacking platoon
---@param position table Search origin
---@param maximumRange number Search radius
---@param tags table Required target tags
---@return table|nil targetUnit Closest compatible target
local function GetClosestShootableEnemy(platoon, position, maximumRange, tags)
    local closestTarget
    local closestDistanceSquared = maximumRange * maximumRange
    local blocked,now=platoon.ai.commanderBlockedTargets,GetGameTimeSeconds()
    for _, enemyUnit in pairs(AIFunctions.GetEnemyUnitsOnMap(platoon.army.id)) do
        if (not blocked or not blocked[enemyUnit] or blocked[enemyUnit]<=now)
            and not enemyUnit.dead and enemyUnit:IsCompleted() and enemyUnit:HasTags(tags) and CanPlatoonShootTarget(platoon, enemyUnit) then
            local enemyPosition = enemyUnit:GetPosition()
            local distanceSquared = Distance2DSquared(position.x, position.z, enemyPosition.x, enemyPosition.z)
            if distanceSquared <= closestDistanceSquared and AIMarkerGenerator.CanGraphAreaTo(position, enemyPosition, platoon.ai.movementLayer) then
                closestTarget = enemyUnit
                closestDistanceSquared = distanceSquared
            end
        end
    end
    return closestTarget
end

---Uses weapon-aware target selection only for plans that explicitly request it.
---@param platoon table Attacking air platoon
---@param position table Search origin
---@param maximumRange number Search radius
---@param tags table Required target tags
---@return table|nil targetUnit Closest target allowed by the plan
local function GetClosestBomberTarget(platoon, position, maximumRange, tags)
    if platoon.ai.requireShootableTarget then
        return GetClosestShootableEnemy(platoon, position, maximumRange, tags)
    end
    return AIFunctions.GetClosestEnemy(platoon.army.id, position, maximumRange, tags, platoon.ai.movementLayer, false)
end

---Gets the closest enemy reachable by a naval platoon without leaving its water graph area.
---@param platoon table Naval platoon
---@param position table Search position
---@param maximumRange number Maximum search radius
---@param tags table Target tags
---@param includeUnfinished boolean Include unfinished targets
---@return table|nil targetUnit Closest reachable target
local function GetClosestEnemyForPlatoon(platoon, position, maximumRange, tags, includeUnfinished)
    if platoon.ai.isNavalPlatoon then
        return AIFunctions.GetClosestNavalEnemy(platoon.army.id, position, maximumRange, tags, platoon.ai.waterGraphArea, GetNavalMaximumWeaponRange(platoon), includeUnfinished)
    end
    return AIFunctions.GetClosestEnemy(platoon.army.id, position, maximumRange, tags, platoon.ai.movementLayer, includeUnfinished)
end

---Updates a naval platoon's weapon target layer for a water or coastal target.
---@param platoon table Naval platoon
---@param targetUnit table|nil Current target unit
---@return nil
local function UpdateNavalTargetLayer(platoon, targetUnit)
    if not platoon.ai.isNavalPlatoon then return end
    platoon.ai.targetLayer = targetUnit and targetUnit.tp.hasTags.NAVAL and "WaterSurface" or "Land"
end

---Keep expansion structures inside the location creator's 30-unit marker radius.
local function FindExpansionConstructionPosition(platoon, expansionPosition)
    local formerTable = platoon.ai.formerTable
    local constructionPosition = AIFunctions.FindPlaceToBuild(platoon.army.id, platoon.ai.nextBuildingtpId, expansionPosition, platoon.ai.constructionSpacing, formerTable.AdjacentToStructure, 30, formerTable.AvoidStructureWithinDistance)
    if not constructionPosition or Distance2DSquared(expansionPosition.x, expansionPosition.z, constructionPosition.x, constructionPosition.z) >= 30 * 30 then
        constructionPosition = AIFunctions.FindPlaceToBuild(platoon.army.id, platoon.ai.nextBuildingtpId, expansionPosition, platoon.ai.constructionSpacing, false, 30, formerTable.AvoidStructureWithinDistance)
    end
    if constructionPosition and Distance2DSquared(expansionPosition.x, expansionPosition.z, constructionPosition.x, constructionPosition.z) < 30 * 30 then
        return constructionPosition
    end
end
---Selects the next construction position, including shoreline validation for naval factories.
---@param platoon table Engineer platoon
---@return table|false buildPosition Selected build position
local function FindNextConstructionPosition(platoon,placementBuilder)
    local formerTable = platoon.ai.formerTable
    if platoon.ai.expansionCenter then
        return FindExpansionConstructionPosition(platoon, platoon.ai.expansionCenter)
    end
    if formerTable.BuildNavalFactory then
        local buildPosition, waterGraphArea, navalPosition = AIFunctions.FindNavalFactoryBuildPosition(platoon.army.id, platoon.ai.nextBuildingtpId, platoon.ai.basePosition)
        platoon.ai.waterGraphArea = waterGraphArea
        platoon.ai.navalPosition = navalPosition
        platoon.ai.buildApproachPosition = buildPosition
        return buildPosition
    end
    platoon.ai.waterGraphArea = nil
    platoon.ai.navalPosition = nil
    platoon.ai.buildApproachPosition = nil
    local constructionSearchCenter = platoon.ai.basePosition
    if formerTable.BuildBehindBase then
        local sourceArmy = Armies[platoon.army.id]
        local closestEnemyBasePosition, closestEnemyBaseDistanceSquared
        for targetArmyIndex, targetArmy in pairs(Armies) do
            if sourceArmy:IsEnemy(targetArmy) and RushReliability.HasLivingUnits(targetArmy) then
                local enemyBasePosition = RushReliability.MainBasePosition(targetArmyIndex)
                local enemyBaseDistanceSquared = enemyBasePosition and Distance2DSquared(constructionSearchCenter.x, constructionSearchCenter.z, enemyBasePosition.x, enemyBasePosition.z)
                if enemyBaseDistanceSquared and (not closestEnemyBaseDistanceSquared or enemyBaseDistanceSquared < closestEnemyBaseDistanceSquared) then
                    closestEnemyBasePosition = enemyBasePosition
                    closestEnemyBaseDistanceSquared = enemyBaseDistanceSquared
                end
            end
        end
        if closestEnemyBasePosition then
            local enemyDirectionX = closestEnemyBasePosition.x - constructionSearchCenter.x
            local enemyDirectionZ = closestEnemyBasePosition.z - constructionSearchCenter.z
            local enemyDirectionLength = math.sqrt(enemyDirectionX * enemyDirectionX + enemyDirectionZ * enemyDirectionZ)
            if enemyDirectionLength > 0 then
                constructionSearchCenter = {x = constructionSearchCenter.x - enemyDirectionX / enemyDirectionLength * formerTable.BuildBehindBase, y = constructionSearchCenter.y, z = constructionSearchCenter.z - enemyDirectionZ / enemyDirectionLength * formerTable.BuildBehindBase}
            end
        end
    end
    constructionSearchCenter = RushReliability.Clamp(constructionSearchCenter, 8)
    local builder = placementBuilder or GetPlatoonConstructionBuilder(platoon, platoon:GetUnits())
    return AIFunctions.FindPlaceToBuild(platoon.army.id, platoon.ai.nextBuildingtpId, constructionSearchCenter, platoon.ai.constructionSpacing, formerTable.AdjacentToStructure, platoon.ai.baseRadius, formerTable.AvoidStructureWithinDistance, {builder=builder})
end

