-------------------------------------------------------------------------------------------------------------------------------------

---Builds a faction map for loaded T4 templates that the assigned engineers can really construct.
---This deliberately bypasses only the stock AvailableUnits roster, which does not contain every
---runtime mod unit. Runtime tags, faction ownership, the engineer build menu and real economy are
---still authoritative.
---@param builders table Assigned engineer units
---@param formerTable table Former data containing LoadedTech4Domain
---@return table|nil List containing one faction-to-template build request
local function GetLoadedBuildableTech4Structures(builders, formerTable)
    local domainTag = formerTable.LoadedTech4Domain and Tags[formerTable.LoadedTech4Domain]
    if not domainTag then return nil end

    local factionBuilds = {}
    for _, builder in ipairs(builders or {}) do
        local factionTag = builder.factionTag
        local factionTemplates = factionTag and Tags[factionTag]
        local builderTpId = builder.tpId
        local canConstruct = not builder.dead
            and builder:IsCompleted()
            and Tags.MOBILE[builderTpId]
            and Tags.ENGINEER[builderTpId]
            and Tags.TECH3[builderTpId]
            and builder.tp
            and builder.tp.construction
            and builder.tp.construction.canBuild
        if factionTemplates and canConstruct and not factionBuilds[factionTag] then
            local candidates = {}
            for tpId, template in pairs(UnitTemplates) do
                local economy = template and template.economy
                local cost = economy and economy.cost
                local specialPlacement = template and template.additions and template.additions.scoHydroPlacement
                local availability = AvailableUnits and AvailableUnits[tpId]
                if template
                    and availability ~= false
                    and RushReliability.Footprint(template)
                    and Tags.MOBILE[tpId]
                    and Tags.TECH4[tpId]
                    and not (Tags.SHIELD and Tags.SHIELD[tpId])
                    and Tags.BUILDABLE_BY_T3_ENGINEER[tpId]
                    and domainTag[tpId]
                    and factionTemplates[tpId]
                    and not (Tags.DEMO_UI_ONLY and Tags.DEMO_UI_ONLY[tpId])
                    and not (specialPlacement and specialPlacement.normalConstructionSupported == false)
                    and economy and economy.buildTime and economy.buildTime > 0
                    and cost and cost.energy and cost.alloys
                    and RushReliability.CanBuilderBuild(builder, tpId)
                    and (formerTable.AllowEcoStorageDrain or AIFunctions.IsBuildableWithoutEconStorageDrain(builder.army.id, builder.tpId, tpId))
                then
                    local ownedCount = 0
                    for _, unit in pairs(Armies[builder.army.id].units or {}) do
                        if not unit.dead and unit.tpId == tpId then ownedCount = ownedCount + 1 end
                    end
                    candidates[#candidates + 1] = {
                        id = tpId,
                        private = availability == nil,
                        ownedCount = ownedCount,
                        buildTime = template.economy and template.economy.buildTime or math.huge,
                    }
                end
            end
            table.sort(candidates, function(first, second)
                if first.ownedCount ~= second.ownedCount then return first.ownedCount < second.ownedCount end
                if first.private ~= second.private then return first.private end
                if first.buildTime ~= second.buildTime then return first.buildTime < second.buildTime end
                return first.id < second.id
            end)
            if candidates[1] then factionBuilds[factionTag] = candidates[1].id end
        end
    end
    if next(factionBuilds) then return {factionBuilds} end
end

---Checks live mod templates and local T3 engineers without relying on the stock roster.
---@param armyIndex integer Army index
---@param baseName string Base whose free engineers may start the build
---@param domainName string LAND, AIR or NAVAL
---@param minimumCompleted integer Required completed mobile T4 count in this domain
---@param maximumStarted integer Maximum completed, under-construction and reserved T4 count
---@return boolean True when a real, affordable build can start
function CanStartLoadedTech4Build(armyIndex, baseName, domainName, minimumCompleted, maximumStarted)
    local army = Armies[armyIndex]
    local domainTag = Tags[domainName]
    if not army or not army.ai or not domainTag then return false end

    local completedCount = 0
    local startedCount = 0
    for _, unit in pairs(army.units or {}) do
        local tpId = unit.tpId
        if not unit.dead and domainTag[tpId] and Tags.MOBILE[tpId] and Tags.TECH4[tpId] then
            startedCount = startedCount + 1
            if unit:IsCompleted() then completedCount = completedCount + 1 end
        end
    end
    for _, reservation in pairs(army.ai.ecoReserve or {}) do
        local tpId = reservation.tpId
        if tpId and domainTag[tpId] and Tags.MOBILE[tpId] and Tags.TECH4[tpId] then startedCount = startedCount + 1 end
    end
    if completedCount < minimumCompleted or startedCount >= maximumStarted then return false end

    local builders = AIFunctions.GetEngineersAssignedToBasePool(armyIndex, baseName, Tags.MOBILE * Tags.ENGINEER * Tags.TECH3, 1)
    if not builders then return false end
    return GetLoadedBuildableTech4Structures(builders, {LoadedTech4Domain = domainName}) ~= nil
end

---Executing build orders for engineers. Get unused engineers, move the engineer to a buildplace and build a building.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planBeachhead(platoon,armyIndex,baseName,formerTable)
    return Import("AI/mods/AI-Scom/RushBeachhead.lua").Plan(platoon,armyIndex,baseName,formerTable)
end

function planBuildWithEngineer(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for platoon found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") builder ready to build, max ("..maxUnits..") are allowed.")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planBuildWithEngineer")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, platoon.ai.basePosition)
    -- get the unit we want to build
    --[[
        unitBuildList = {
            { CHOSEN="ucs1511", EDA="ues1511", GUARD="ugs1511" },
            { CHOSEN="ucs1512", EDA="ues1512", GUARD="ugs1512" },
            { CHOSEN="ucs1501", EDA="ues1001", GUARD="ugs1501" }
        }
    --]]
    ReportNativeSeraphimBuilderAccess(armyIndex, useBuilder)
    local assignedBuilderOverride = useBuilder
    local unitBuildList
    if formerTable.LoadedTech4Domain then
        unitBuildList = GetLoadedBuildableTech4Structures(useBuilder, formerTable)
    else
        unitBuildList = AIFunctions.GetWantStructures(armyIndex, baseName, formerTable, assignedBuilderOverride, maxUnits)
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] unitBuildList:"..repr(unitBuildList))
    end
    if not unitBuildList or not unitBuildList[1] then
        if formerTable.DebugPlatoon then
            AILog("- WARNING: Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] unitBuildList is empty on first index?!? Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
        end
        ExitPlatoon(platoon)
        return
    end
    -- The selector still sees the original idle pool, including its base reserve.
    -- Only commit builders once a build request exists.
    -- assign units to platoon
    platoon:AssignUnits(useBuilder)
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] Set platoon movement layer to: "..platoon.ai.movementLayer)
    end
    -- Naval construction must not enter the land builder's centre-MOVE/retry loop.
    -- Retain native selection above and the normal idempotent cleanup on exit.
    if formerTable.BuildNavalFactory then
        RushNavalConstruction.Run(platoon, unitBuildList[1], {
            reserveCallback = ClearReserveEcoCallback,
            clearReservation = ClearConstructionBuilderEconomyReservation,
        })
        ExitPlatoon(platoon)
        return
    end
    -- Let the host advance accepted BUILD orders directly. Planning uses a
    -- private view so a yielding lookahead never replaces the current target.
    local constructionAI=platoon.ai
    if RushReliability.RunConstructionQueue(platoon,unitBuildList,maxUnits,{
        place=function(ids,lead)
            local view={army=platoon.army,id=platoon.id,ai=table.shallowCopy(constructionAI)}
            function view:GetUnits() return platoon:GetUnits() end
            view.ai.nextBuildingtpIds=ids
            view.ai.nextBuildingtpId,view.ai.constructionSpacing=getNextbuildingAndSpacing(view)
            view.ai.nextBuildingtpId=ids[lead.factionTag]
            local position
            if formerTable.RushEmergencyShield then
                position=RushBaseLayout.FindEmergencyShield(platoon,lead,view.ai.nextBuildingtpId)
            elseif formerTable.RushGroundDefense then
                -- Site claims belong to the live construction assignment, not
                -- the disposable lookahead view used by ordinary placement.
                position=RushBaseLayout.FindGroundDefense(platoon,lead,view.ai.nextBuildingtpId)
            elseif formerTable.RushAdjacencyStorage then
                position=RushBaseLayout.FindStorage(platoon,lead,view.ai.nextBuildingtpId)
            else position=FindNextConstructionPosition(view,lead) end
            return position,view.ai.constructionSpacing
        end,
        valid=(formerTable.RushGroundDefense or formerTable.RushAdjacencyStorage or formerTable.RushMassFabrication
            or formerTable.RushEmergencyShield)
            and function(id,position,lead)
                if formerTable.RushEmergencyShield then return RushBaseLayout.ValidateEmergencyShield(platoon,lead,id,position) end
                if formerTable.RushGroundDefense then return RushBaseLayout.ValidateGroundDefense(platoon,lead,id,position) end
                if formerTable.RushAdjacencyStorage then return RushBaseLayout.ValidateStorage(platoon,lead,id,position) end
                return Import("AI/mods/AI-Scom/RushMassFabrication.lua").ValidateBuild(platoon,lead,id,position)
            end or nil,
        route=formerTable.RushEmergencyShield and function(lead,position)
            return RushBaseLayout.EmergencyShieldRoute(platoon,lead,position)
        end or nil,
        trim=RemoveOverMaxBuilderFromPlatoon,
        minimum=minUnits,
        started=function(index,target)
            TryStartOpeningEconomyFocus(index,target)
            if formerTable.RushMassFabrication then
                Import("AI/mods/AI-Scom/RushMassFabrication.lua").RegisterBuild(platoon.army,target)
            end
        end,
    }) then
        if platoon.ai==constructionAI then ExitPlatoon(platoon) end
        return
    end
    -- Non-structure projects retain their specialised legacy construction flow.
    while unitBuildList[1] do
        -- select the next building we want to build
        platoon.ai.nextBuildingtpIds = table.remove(unitBuildList, 1)
        platoon.ai.nextBuildingtpId, platoon.ai.constructionSpacing = getNextbuildingAndSpacing(platoon)
        -- find a place to build (always relative to the base, not the engineer)
        platoon.ai.placeToBuild = FindNextConstructionPosition(platoon)
        if platoon.ai.placeToBuild then
            if formerTable.DebugPlatoon then
                AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] nextBuilding: ["..platoon.ai.nextBuildingtpId.."] ("..UnitTemplates[platoon.ai.nextBuildingtpId].general.unitTypeName..") at position:("..platoon.ai.placeToBuild.x..", "..platoon.ai.placeToBuild.z..")")
            end
        else
            AILog("- WARNING: Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] no placeToBuild found!")
            ExitPlatoon(platoon)
            return
        end
        -- keep the builders closest to the selected build location
        local buildersByRangeToBuildLocation = platoon:GetUnits()
        for _, builder in pairs(buildersByRangeToBuildLocation) do
            builder.ai.rangeToBuildLocation = Distance2DSquared(builder:GetPosition().x, builder:GetPosition().z, platoon.ai.placeToBuild.x, platoon.ai.placeToBuild.z)
        end
        table.sort(buildersByRangeToBuildLocation, SortBuilderUnitsAscendingByRangeToBuildLocationValue)
        local constructionBuilder, constructionBuilderIndex = GetPlatoonConstructionBuilder(platoon, buildersByRangeToBuildLocation)
        if not constructionBuilder then
            AILog("- WARNING: Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] no platoon engineer can build the requested structure -> Disbanding"..GetPlatoonConstructionWarningDetails(platoon))
            ExitPlatoon(platoon)
            return
        end
        -- Keep a capable engineer when closer engineers can only assist.
        table.insert(buildersByRangeToBuildLocation, 1, table.remove(buildersByRangeToBuildLocation, constructionBuilderIndex))
        RemoveOverMaxBuilderFromPlatoon(platoon, buildersByRangeToBuildLocation, maxUnits)
        -- main engineer loop. - Move to target and build
        while platoon.ai.placeToBuild do
            if formerTable.DebugPlatoon then
                AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] -------Main Loop------- Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] --------------")
            end
            -- Complete canceled assignments before checking the remaining engineers' build permissions.
            for _, builder in pairs(platoon:GetUnits()) do
                if builder.platoon == platoon and RushReliability.Own(Armies[armyIndex],builder) and builder.ai.eState == "Disband" then
                    if lobbyOptionsAI.debugUnitEState then
                        builder.ai.orderText = "disband from build platoon"
                    end
                    HostClearOrder(UnitAsArray(builder))
                    ClearConstructionBuilderEconomyReservation(builder)
                    ClearUnitTemporaryPlatoonData(builder, "planBuildWithEngineer")
                    platoon:RemoveUnits(UnitAsArray(builder))
                end
            end
            if platoon:GetNumOfUnits() < 1 then
                ExitPlatoon(platoon)
                return
            end
            --check if we need to assign more builders to the platoon.
            if not formerTable.MaximumAlloyIncomeRatio then subPlanGetMoreBuilders(platoon, maxUnits) end
            --rebuild unit table, maybe we lost some in battle
            useBuilder = platoon:GetUnits()
            if ENGINEERBUILDDEBUGDRAW and armyIndex == GetFocusArmy() then
                for i, builder in pairs(useBuilder) do
                    if not builder.ai.engineerBuildDebugThread then
                        builder.ai.engineerBuildDebugThread = NewThread(EngineerBuildDebugThread, builder)
                    end
                end
            end
            -- save range to buildplace to all engineers
            for i, builder in pairs(useBuilder) do
                builder.ai.rangeToBuildLocation = Distance2DSquared( builder:GetPosition().x,  builder:GetPosition().z, platoon.ai.placeToBuild.x, platoon.ai.placeToBuild.z )
            end
            -- sort builder by range, closest first
            table.sort(useBuilder, SortBuilderUnitsAscendingByRangeToBuildLocationValue)
            constructionBuilder = GetPlatoonConstructionBuilder(platoon, useBuilder)
            if not constructionBuilder then
                AILog("- WARNING: Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] no platoon engineer can build the requested structure -> Disbanding"..GetPlatoonConstructionWarningDetails(platoon))
                ExitPlatoon(platoon)
                return
            end
            -- loop over units and assign tasks
            for i, builder in pairs(useBuilder) do
                if formerTable.DebugPlatoon then
                    AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..".")
                end
                if not IsValidPlatoonUnit(builder) then
                    AILog("- WARNING: Fn planBuildWithEngineer():[A:"..builder.army.id.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
                elseif builder.platoon ~= platoon or not RushReliability.Own(Armies[armyIndex],builder) then
                    -- Ignore stale recruitment snapshots after a helper yielded.
                elseif not platoon.ai.placeToBuild then
                    if formerTable.DebugPlatoon then
                        AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] placeToBuild = nil.")
                    end
                    break
                elseif not platoon.ai.nextBuildingtpIds[builder.factionTag] and builder.ai.eState ~= "Disband" and builder.ai.eState ~= "Finishing" and builder.ai.eState ~= "Finished" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanAssistConstructionBuilder, constructionBuilder)
                elseif not builder.ai.eState then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanSetConstructionArea)
                elseif builder.ai.eState == "StartMoveToDestination" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanStartMoveToBuildDestination, platoon.ai.placeToBuild, platoon.ai.nextBuildingtpIds and platoon.ai.nextBuildingtpIds[builder.factionTag], builder == constructionBuilder) -- Only the first capable engineer queues the build order.
                elseif builder.ai.eState == "MovingToDestination" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanMovingToBuildDestination, platoon.ai.placeToBuild, builder.ai.buildRange)
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanDisbandOnFinishedUnit)
                elseif builder.ai.eState == "MovingDestinationReached" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanStartToBuild)
                elseif builder.ai.eState == "Building" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanBuilding)
                elseif builder.ai.eState == "Assisting" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanBuildingAssist)
                elseif builder.ai.eState == "Finishing" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanFinishing)
                elseif builder.ai.eState == "Finished" then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanFinished)
                else
                    AILog("- WARNING: Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
                end
                if platoon:GetNumOfUnits() < 1 then
                    if formerTable.DebugPlatoon then
                        AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
                    end
                    ExitPlatoon(platoon)
                end
            end
            WaitTicks(10)
        end
        -- Release approach reservations before ending or replacing the construction request.
        for _, builder in pairs(platoon:GetUnits()) do
            HostClearOrder(UnitAsArray(builder))
            ClearConstructionBuilderEconomyReservation(builder)
            ClearUnitTemporaryPlatoonData(builder, "RC3 completed construction request")
        end
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildWithEngineer():[A:"..armyIndex.."][P:"..platoon.id.."] Disbanding... Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planBuildWithEngineer")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planBuildWithEngineer platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Draw debug markers for engineer construction behavior.
---@param builder table Unit class table. Contains functions and data for a unit
---@return nil
function EngineerBuildDebugThread(builder)
    local builderPosition
    local buildPosition
    while builder.platoon and not builder.dead do
        if not builder.platoon or not builder.platoon.ai then
            break
        end
        builderPosition = builder:GetPosition()
        if builder.platoon.ai.placeToBuild then
            buildPosition = builder.platoon.ai.placeToBuild
            Engine.DrawCircle(SnapToGround(buildPosition), 1, AIFunctions.HEXtoRGBA("FF000000"))
            Engine.DrawArrow(builderPosition, buildPosition, AIFunctions.HEXtoRGBA("FF00FFFF"))
        end
        if builder.ai.eState == "Building" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FF40FF4F"))
        elseif builder.ai.eState == "Assisting" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FFFFA500"))
        elseif builder.ai.eState == "Finishing" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FFFF40FF"))
        elseif builder.ai.eState == "Disband" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FF000000"))
        end
        WaitTicks(1)
    end
    builder.ai.engineerBuildDebugThread = nil
end
---Find the first platoon engineer that can start the requested construction.
---@param platoon table Platoon containing the construction request
---@param builders table Engineers in preferred construction order
---@return table|nil, number|nil Capable engineer and its index
function GetPlatoonConstructionBuilder(platoon, builders)
    for builderIndex, builder in ipairs(builders) do
        local buildingTemplateIdentifier = platoon.ai.nextBuildingtpIds[builder.factionTag]
        if buildingTemplateIdentifier and IsValidPlatoonUnit(builder) and builder.platoon == platoon and builder.ai.eState ~= "Disband" and builder.tp.construction and builder.tp.construction.canBuild and buildQueueUtils.CanBuild(builder, buildingTemplateIdentifier, 1) then
            return builder, builderIndex
        end
    end
end
---Describe the former, requested structures and current engineers, then validate their blueprint permissions.
---@param platoon table Platoon containing the construction request
---@return string Multiline warning details with a can-build result for every engineer
function GetPlatoonConstructionWarningDetails(platoon)
    local formerName = tostring(platoon.ai.formerTable.FormerName)
    local requestedTemplates = platoon.ai.nextBuildingtpIds or {}
    local requestedStructures = {}
    for factionTag, buildingTemplateIdentifier in pairs(requestedTemplates) do
        local requestedTemplate = UnitTemplates[buildingTemplateIdentifier]
        requestedStructures[#requestedStructures + 1] = "FactionStructure "..tostring(factionTag)..": "..tostring(buildingTemplateIdentifier).." ("..tostring(requestedTemplate and requestedTemplate.general and requestedTemplate.general.unitTypeName)..");"
    end
    table.sort(requestedStructures)
    local engineerDetails, validationDetails = {}, {}
    for _, builder in ipairs(platoon:GetUnits()) do
        local engineerIdentifier = tostring(builder.factionTag)..":"..tostring(builder.tpId)
        engineerDetails[#engineerDetails + 1] = engineerIdentifier.." ("..tostring(builder.tp and builder.tp.general and builder.tp.general.unitTypeName)..")"
        local canBuildRequestedStructure = false
        local checkedStructureIdentifier = requestedTemplates[builder.factionTag] or platoon.ai.nextBuildingtpId
        -- Validate current blueprint permissions without queued upgrades or platoon eligibility filters.
        if builder.tp and builder.tp.construction and builder.tp.construction.canBuild then
            for _, buildingTemplateIdentifier in pairs(requestedTemplates) do
                if buildQueueUtils.CanBuild(builder, buildingTemplateIdentifier, 1) then
                    canBuildRequestedStructure = true
                    checkedStructureIdentifier = buildingTemplateIdentifier
                    break
                end
            end
        end
        local checkedStructureTemplate = UnitTemplates[checkedStructureIdentifier]
        local checkedStructureName = checkedStructureTemplate and checkedStructureTemplate.general and checkedStructureTemplate.general.unitTypeName or checkedStructureIdentifier
        validationDetails[#validationDetails + 1] = "Check: "..engineerIdentifier.." can build ("..tostring(checkedStructureName)..") ("..tostring(canBuildRequestedStructure)..")"
    end
    table.sort(engineerDetails)
    table.sort(validationDetails)
    local warningLines = {"", "Former:["..formerName.."],"}
    for _, structureDetails in ipairs(requestedStructures) do warningLines[#warningLines + 1] = structureDetails end
    warningLines[#warningLines + 1] = "Platoon Engineers ("..#engineerDetails.."): "..(#engineerDetails > 0 and table.concat(engineerDetails, "; ") or "none")
    for _, validationResult in ipairs(validationDetails) do warningLines[#warningLines + 1] = validationResult end
    return table.concat(warningLines, "\r\n")
end
---Follow a capable engineer and assist its construction until the platoon finishes.
---@param builder table Engineer without a matching construction template
---@param constructionBuilder table Platoon engineer that can start construction
---@return string Next engineer state
function subPlanAssistConstructionBuilder(builder, constructionBuilder)
    local constructionTarget = builder.platoon.ai.buildedUnit
    if constructionTarget and (constructionTarget.dead or constructionTarget:IsCompleted()) then
        HostClearOrder(UnitAsArray(builder))
        return "Finishing"
    end
    local assistTarget = constructionTarget or constructionBuilder
    if not builder.unitBeingBuilt and (not builder.assistBehaviorIsActive or builder.assistBehaviorAssistedUnit ~= assistTarget) then
        local buildingTemplateIdentifier = constructionTarget and constructionTarget.tpId or builder.platoon.ai.nextBuildingtpIds[constructionBuilder.factionTag]
        if not builder.platoon.ai.formerTable.AllowEcoStorageDrain and not RushBalance.Affordable(builder, buildingTemplateIdentifier) then return "Disband" end
        HostIssueOrder(OrderTasks.ASSISTUNIT, UnitAsArray(builder), false, assistTarget:GetPosition(), {targetGlobalId = assistTarget.id})
    end
    if lobbyOptionsAI.debugUnitEState then builder.ai.orderText = "Assisting construction [U:"..assistTarget.id.index.."]" end
    return "AssistingConstructionBuilder"
end
---Sub function to set next building and construction spacing
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return string Returns next building and construction spacing
function getNextbuildingAndSpacing(platoon)
    local factionIndexToName = {[1] = "EDA", [2] = "CHOSEN", [3] = "GUARD", [4] = "SERAPHIM" }
    local armyFactionName = factionIndexToName[Armies[platoon.army.id].faction]
    local nextBuilding
    local structureSpacing = 0
    -- do we have a tpId for the armies faction? if not, use any Id we found
    for aFName, tpId in pairs(platoon.ai.nextBuildingtpIds) do
        nextBuilding = tpId
        if aFName == armyFactionName then
            break
        end
    end
    if armyFactionName == "SERAPHIM" then
        nextBuilding = platoon.ai.nextBuildingtpIds.SERAPHIM
    end
    if not nextBuilding then
        AILog("- WARNING: Fn getNextbuildingAndSpacing():[A:"..platoon.army.id.."][P:"..platoon.id.."] nextBuilding = nil ??? platoon.ai.nextBuildingtpIds:"..repr(platoon.ai.nextBuildingtpIds))
        nextBuilding = ""
    end
    if platoon.ai.formerTable.WantStructuresSpacing then
        if type(platoon.ai.formerTable.WantStructuresSpacing) == "number" then
            local spacing = platoon.ai.formerTable.WantStructuresSpacing
            if spacing > -1 and spacing < 50 then
            else
                AILog("- WARNING: Fn getNextbuildingAndSpacing():[A:"..platoon.army.id.."][P:"..platoon.id.."] WantStructuresSpacing is out of bounds 0 -> 50 ("..platoon.ai.formerTable.WantStructuresSpacing.."), Former ["..platoon.ai.formerTable.FormerName.."], AIPlan ["..platoon.ai.formerTable.AIPlan.."]")
            end
            structureSpacing = platoon.ai.formerTable.WantStructuresSpacing
        else
            AILog("- WARNING: Fn getNextbuildingAndSpacing():[A:"..platoon.army.id.."][P:"..platoon.id.."] WantStructuresSpacing is not a number ("..repr(platoon.ai.formerTable.WantStructuresSpacing).."), Former ["..platoon.ai.formerTable.FormerName.."], AIPlan ["..platoon.ai.formerTable.AIPlan.."]")
        end
    else
        AILog("- WARNING: Fn getNextbuildingAndSpacing():[A:"..platoon.army.id.."][P:"..platoon.id.."] no WantStructuresSpacing found, defaulting to 0, Former ["..platoon.ai.formerTable.FormerName.."], AIPlan ["..platoon.ai.formerTable.AIPlan.."]")
    end
    return nextBuilding, structureSpacing
end

---Sub function to add more builders to the platoon
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param maxUnits integer number of units that can be assigned to the platoon
---@return nil
function subPlanGetMoreBuilders(platoon, maxUnits)
    -- Shared first-project assistance owns new helpers; attached workers finish their work.
    local assistTags = platoon.ai.formerTable.AssistBuildUnits
    if assistTags and RushHeavyPolicy.Enabled(platoon.army) then
        local first = RushHeavyPolicy.FirstTarget(platoon.army)
        if first then
            for _, tags in pairs(assistTags) do if first:HasTags(tags) then return end end
        end
    end
    local platoonUnitCount = platoon:GetNumOfUnits()
    local neededUnitCount = maxUnits - platoonUnitCount
    --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] Platoon has ("..platoonUnitCount.."/"..maxUnits..") units, and can use "..neededUnitCount.." additional units.")
    -- get units from the former NeedMobileBuilder table
    if neededUnitCount > 0 then
        local useBuilder, _, _, reserveForBase = AIFunctions.GetNeedMobileBuilder(platoon.army.id, platoon.ai.baseName, platoon.ai.formerTable)
        if useBuilder then
            --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to work")
            -- Check if there are any variables left from a previous function
            CheckUnitsForLeftover(useBuilder, "subPlanGetMoreBuilders")
            -- remove as much units as we need to stay at base
            useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, platoon.ai.basePosition)
            useBuilder = GetAffordableBuildAssistEngineers(platoon, useBuilder, neededUnitCount)
            -- remove unit over the max limit
            useBuilder = RemoveOverMaxBuilder(useBuilder, maxUnits - platoonUnitCount)
            -- assign unts to platoon
            platoonUnitCount = table.getn(useBuilder)
            --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] adding "..platoonUnitCount.." builders to the platoon")
            platoon:AssignUnits(useBuilder)
        else
            --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] No additional builder for platoon found")
        end
    end
    return
end

---Sub function to set the path to the the construction area
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanSetConstructionArea(builder)
    local owner,assignment,unitAI=builder.army,builder.platoon,builder.ai
    local assignmentAI=assignment and assignment.ai
    if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        local buildTime = UnitTemplates[builder.platoon.ai.nextBuildingtpId].economy.buildTime / builder.tp.construction.buildPower
        local energyPerSecond = UnitTemplates[builder.platoon.ai.nextBuildingtpId].economy.cost.energy / buildTime
        local resourcePerSecond = UnitTemplates[builder.platoon.ai.nextBuildingtpId].economy.cost.alloys / buildTime
        AILog("* Fn subPlanSetConstructionArea():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Get path to build area ["..builder.platoon.ai.nextBuildingtpId.."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpId].general.unitTypeName..") Recource/second: (A:"..resourcePerSecond.." E:"..energyPerSecond..") Buildtime: (B:"..buildTime..")")
    end
    -- Build immediately when the selected site is already in reach. Routing
    -- through its centre wastes time and makes the builder obstruct its own site.
    if builder.platoon.ai.placeToBuild then
        local range = builder.construction and builder.construction.range
            or builder.tp.construction.range or 6
        local position, site = builder:GetPosition(), builder.platoon.ai.placeToBuild
        builder.ai.buildRange = range
        builder.ai.stuckCount = 0
        builder.ai.progressCheckTicks = 0
        if Distance2DSquared(position.x, position.z, site.x, site.z) <= math.max(1, range - 0.5)^2 then
            builder.ai.path = false
            return subPlanStartToBuild(builder)
        end
        local pathDestination = builder.platoon.ai.buildApproachPosition or builder.platoon.ai.placeToBuild
        local path, info = AIMarkerGenerator.GeneratePathTo(builder.army.id, builder:GetPosition(), pathDestination, builder.platoon.ai.movementLayer, true, CalculatePlatoonThreat(builder.platoon))
        if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
        if path then
            -- set variables for the next task
            builder.ai.path = path
            builder.ai.buildRange = range
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
            return "StartMoveToDestination"
        end
    end
    -- ToDo: Transport engineer to destination, for now just block the buildplace
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("- WARNING: Fn subPlanSetConstructionArea():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no path to platoon.ai.placeToBuild, need Transport!.")
    end
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "No path, need transport! ["..repr(builder.platoon.ai.nextBuildingtpIds and builder.platoon.ai.nextBuildingtpIds[builder.factionTag]).."]"
    end
    Armies[builder.army.id].ai.blacklistedBuildPlaces[""..math.floor(builder.platoon.ai.placeToBuild.x).."-"..math.floor(builder.platoon.ai.placeToBuild.z)..""] = true
    builder.platoon.ai.placeToBuild = FindNextConstructionPosition(builder.platoon)
    return nil
end

-- Bookkeeping transitions can run on the next tick while another worker is
-- travelling. Keep elapsed-time stall observations at their original cadence.
local function BuilderObservationDue(unit)
    local now=GetGameTimeSeconds();local data=unit.ai
    local watch=data.rushBuilderObservation
    if not watch or watch.platoon~=unit.platoon or watch.state~=data.eState or now<watch.at then
        data.rushBuilderObservation={platoon=unit.platoon,state=data.eState,at=now}
        return true
    end
    if now-watch.at<1 then return false end
    watch.at=now
    return true
end

---Sub function to set move orders along waypoints to the destination
---@param unit table Unit class table. Contains functions and data for a unit
---@param placeToBuild table Position formated as {x=0,y=0,z=0}
---@param reserveEcoTpId string Unit tpId for eco reserving while moving to the destination
---@return string Returns the next e(xecute)State for the unit
function subPlanStartMoveToDestination(unit, placeToBuild, reserveEcoTpId)
    local owner,assignment,unitAI=unit.army,unit.platoon,unit.ai
    local assignmentAI=assignment and assignment.ai
    if not RushReliability.CurrentAssignment(unit,owner,assignment,unitAI,assignmentAI) then return "Disband" end
    unit.ai.rushGenericMove = nil
    if unit.ai.path then
        if reserveEcoTpId then
            AIFunctions.SetReserveEco(unit.army.id, unit.id.index, reserveEcoTpId, placeToBuild)
            unit:AddCallback(ClearReserveEcoCallback, "OnDestroyed")
        end
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "StartMoveToDestination"
        end
        local path = AIMarkerGenerator.StraightenPath(unit.ai.path)
        if not RushReliability.CurrentAssignment(unit,owner,assignment,unitAI,assignmentAI) then return "Disband" end
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] start moving path to destination.")
        end
        HostClearOrder(UnitAsArray(unit))
        WaitTicks(3)
        if not RushReliability.CurrentAssignment(unit,owner,assignment,unitAI,assignmentAI) then return "Disband" end
        for z, nodePos in pairs(path) do
            HostIssueOrder(OrderTasks.MOVE, UnitAsArray(unit), true, nodePos, nil) --orderTask, unitsArray, append, position, payload
        end
        return "MovingToDestination"
    end
    if unit.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartMoveToDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] no path to destination, Disbanding")
    end
    return "Disband"
end

---Moves a unit toward the destination and detects movement stalls using short-term progress checks.
---Rebuilds the path if the unit repeatedly fails to make movement progress.
---@param unit table The unit to be moved
---@param destination table Position formatted as {x=0,y=0,z=0}
---@param distance number Allowed arrival distance to destination
---@return string Returns the current movement state or MovingDestinationReached when destination is reached
function subPlanMovingToDestination(unit, destination, distance)
    local currentPosition = unit:GetPosition()
    unit.ai.stuckCount = unit.ai.stuckCount or 0
    unit.ai.progressCheckTicks = unit.ai.progressCheckTicks or 0
    -- reached destination
    local distToDestination = Distance2DSquared(currentPosition.x, currentPosition.z, destination.x, destination.z)
    local distanceSquared = distance * distance
    if distToDestination <= distanceSquared then
        unit.ai.lastProgressPosition = false
        unit.ai.progressCheckTicks = 0
        unit.ai.stuckCount = 0
        unit.ai.logStuckState = false
        -- stop movement after arrival
        HostClearOrder(UnitAsArray(unit))
        return "MovingDestinationReached"
    end
    -- initialize progress anchor
    if not unit.ai.lastProgressPosition then
        unit.ai.lastProgressPosition = currentPosition
        unit.ai.progressCheckTicks = 0
    end
    -- avoid evaluating movement every tick
    if not BuilderObservationDue(unit) then return unit.ai.eState end
    unit.ai.progressCheckTicks = unit.ai.progressCheckTicks + 1
    if unit.ai.progressCheckTicks >= 5 then
        local progressDistanceSquared = Distance2DSquared(currentPosition.x, currentPosition.z, unit.ai.lastProgressPosition.x, unit.ai.lastProgressPosition.z)
        -- reset stuck detection after real movement progress
        if progressDistanceSquared > 64 then -- 8 units moved
            unit.ai.lastProgressPosition = currentPosition
            unit.ai.progressCheckTicks = 0
            unit.ai.stuckCount = 0
            unit.ai.logStuckState = false
        else
            -- increase stuck counter if movement progress is too small
            unit.ai.stuckCount = unit.ai.stuckCount + 1
            unit.ai.progressCheckTicks = 0
            unit.ai.logStuckState = true
            if unit.ai.stuckCount > 3 then
                -- RC12: a lost path is not a valid argument to MakeShortPath.
                -- Rebuild against the real movement graph before touching orders.
                local owner, assignment = unit.army, unit.platoon
                local recovery = unit.ai.rushGenericMove
                if not recovery or Distance2DSquared(recovery.x,recovery.z,destination.x,destination.z)>1 then
                    recovery={x=destination.x,z=destination.z,retries=0}
                    unit.ai.rushGenericMove=recovery
                end
                if unit.unitBeingBuilt or unit.buildBehaviorIsActive then return unit.ai.eState end
                if recovery.retries>=3 then return "Disband" end
                recovery.retries=recovery.retries+1
                local path
                if type(unit.ai.path)=="table" and #unit.ai.path>0 then
                    path=AIMarkerGenerator.MakeShortPath(currentPosition,unit.ai.path)
                else
                    local layer=(RushMovementV18.UnitMovementLayer(unit) or "Land")
                    path=AIMarkerGenerator.GeneratePathTo(owner.id,currentPosition,destination,layer,true,0)
                end
                if type(path)=="table" and #path>0 then path=AIMarkerGenerator.StraightenPath(path) end
                -- Path generation can yield across death, capture or reassignment.
                if unit.dead or unit.army~=owner or owner.units[unit.id.index]~=unit or unit.platoon~=assignment
                    or not unit.ai or unit.ai.rushGenericMove~=recovery then return "Disband" end
                if unit.unitBeingBuilt or unit.buildBehaviorIsActive then return unit.ai.eState end
                if type(path)~="table" or #path==0 then
                    unit.ai.path=false
                    AILog("[RushWork] army="..owner.id.." event=movement-no-path builder="..unit.id.index,true)
                    return "Disband"
                end
                unit.ai.path=path
                HostClearOrder(UnitAsArray(unit))
                for _, nodePos in ipairs(path) do
                    HostIssueOrder(OrderTasks.MOVE, UnitAsArray(unit), true, nodePos, nil)
                end
                unit.ai.lastProgressPosition = currentPosition
                unit.ai.progressCheckTicks = 0
                unit.ai.stuckCount = 0
                unit.ai.logStuckState = false
            end
        end
    end
    if lobbyOptionsAI.debugUnitEState or unit.ai.logStuckState then
        unit.ai.orderText = "Moving - stucked:" .. unit.ai.stuckCount .. " times."
    end
    return unit.ai.eState
end

---Sub function to set move orders along waypoints to the destination
---@param unit table Unit class table. Contains functions and data for a unit
---@param placeToBuild table Position formated as {x=0,y=0,z=0}
---@param reserveEcoTpId string Unit tpId for eco reserving while moving to the destination
---@param issueBuild boolean Add the build order after movement if true
---@return string Returns the next e(xecute)State for the unit
function subPlanStartMoveToBuildDestination(unit, placeToBuild, reserveEcoTpId, issueBuild)
    local owner,assignment,unitAI=unit.army,unit.platoon,unit.ai
    local assignmentAI=assignment and assignment.ai
    if not RushReliability.CurrentAssignment(unit,owner,assignment,unitAI,assignmentAI) then return "Disband" end
    unit.ai.rushNoBuildOrdersSince = nil
    if issueBuild
        and (
            type(reserveEcoTpId) ~= "string"
            or UnitTemplates[reserveEcoTpId] == nil
            or unit.factionTag == nil
            or Tags[unit.factionTag] == nil
            or not Tags[unit.factionTag][reserveEcoTpId]
        )
    then
        AILog(
            "- WARNING: Fn subPlanStartMoveToBuildDestination(): missing valid faction-owned build template; refusing BUILD order for "
                .. repr(unit.factionTag)
                .. " / " .. repr(reserveEcoTpId),
            unit.platoon.ai.formerTable.DebugPlatoon)
        return "Disband"
    end
    -- Capacity projects commit their BUILD only after arrival, when the
    -- actual builder/template budget can be checked against current spending.
    if assignmentAI.formerTable.RushCapacityDomain then issueBuild = false end
    RushReliability.BeginBuildMove(unit, reserveEcoTpId, placeToBuild, issueBuild)
    if unit.ai.path then
        local nextBuildingTemplateId = unit.platoon.ai.nextBuildingtpIds
            and unit.platoon.ai.nextBuildingtpIds[unit.factionTag]
        if IsInvalidHardSeraphimConstruction(unit.army.id, nextBuildingTemplateId) then
            if reserveEcoTpId then
                AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
            end
            HostClearOrder(UnitAsArray(unit))
            AILog("- WARNING: SanctuaryRush blocked non-Seraphim construction order while moving [A:"..unit.army.id.."] Template:"..tostring(nextBuildingTemplateId))
            return "Disband"
        end
        if IsHardSanctuaryRushArmy(unit.army.id)
            and IsHydrocarbonTemplateId(nextBuildingTemplateId)
        then
            if reserveEcoTpId then
                AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
            end
            HostClearOrder(UnitAsArray(unit))
            AILog("- WARNING: SanctuaryRush blocked hydrocarbon build order [A:"..unit.army.id.."] Template:"..tostring(nextBuildingTemplateId))
            return "Disband"
        end
        if reserveEcoTpId then
            AIFunctions.SetReserveEco(unit.army.id, unit.id.index, reserveEcoTpId, placeToBuild)
            unit:AddCallback(ClearReserveEcoCallback, "OnDestroyed")
        end
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "StartMoveToDestination"
        end
        local path = AIMarkerGenerator.StraightenPath(unit.ai.path)
        if not RushReliability.CurrentAssignment(unit,owner,assignment,unitAI,assignmentAI) then return "Disband" end
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToBuildDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] start moving path to destination.")
        end
        HostClearOrder(UnitAsArray(unit))
        WaitTicks(3)
        if not RushReliability.CurrentAssignment(unit,owner,assignment,unitAI,assignmentAI) then return "Disband" end
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToBuildDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] OrderTasks.MOVE ")
        end
        for z, nodePos in ipairs(path) do
            HostIssueOrder(OrderTasks.MOVE, UnitAsArray(unit), true, nodePos, nil) --orderTask, unitsArray, append, position, payload
        end
        if issueBuild then
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToBuildDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] add build after moving path to destination.")
        end
            HostIssueOrder(OrderTasks.BUILD, UnitAsArray(unit), true, placeToBuild, {tpId = reserveEcoTpId, armyId = unit.army.id }) --orderTask, unitsArray, append, position, payload
            TryStartOpeningEconomyFocus(unit.army.id, GetLatestBuildOrderTarget(unit))
        end
        return "MovingToDestination"
    end
    if unit.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartMoveToBuildDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] no path to destination, Disbanding")
    end
    return "Disband"
end

---Moves a unit toward the destination and detects movement stalls using short-term progress checks.
---Rebuilds the path if the unit repeatedly fails to make movement progress.
---@param unit table The unit to be moved
---@param destination table Position formatted as {x=0,y=0,z=0}
---@param distance number Allowed arrival distance to destination
---@return string Returns the current movement state or MovingDestinationReached when destination is reached
function subPlanMovingToBuildDestination(unit, destination, distance)
    -- Use the builder's real range. A fixed eight-unit arrival radius can stop
    -- short T1 engineers before their queued generator build becomes active.
    distance = type(distance)=="number" and math.max(1,distance) or 6
    local currentPosition = unit:GetPosition()
    unit.ai.stuckCount = unit.ai.stuckCount or 0
    unit.ai.progressCheckTicks = unit.ai.progressCheckTicks or 0

    local distToDestination = Distance2DSquared(currentPosition.x, currentPosition.z, destination.x, destination.z)
    if unit.unitBeingBuilt then
        unit.ai.lastProgressPosition = false
        unit.ai.progressCheckTicks = 0
        unit.ai.stuckCount = 0
        unit.ai.logStuckState = false
        unit.platoon.ai.buildedUnit = unit.unitBeingBuilt
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMovingToBuildDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Unit has already started building, return MovingDestinationReached. distToDestination:"..distToDestination)
        end
        return "MovingDestinationReached"
    end
    -- reached destination
    local distanceSquared = distance * distance
    if distToDestination <= distanceSquared then
        unit.ai.lastProgressPosition = false
        unit.ai.progressCheckTicks = 0
        unit.ai.stuckCount = 0
        unit.ai.logStuckState = false
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMovingToBuildDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Destination reached, return MovingDestinationReached. distToDestination:"..distToDestination)
        end
        return "MovingDestinationReached"
    else
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMovingToBuildDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] still moving to destination [distToDestination:"..distToDestination.."] > [distanceSquared:"..distanceSquared.."]")
        end
    end
    -- Rush v7: an engineer without active or queued orders cannot progress.
    -- Reuse the existing checked path-recovery route after three seconds.
    local activeOrder = unit.orders and unit.orders.activeOrder
    local queuedOrders = unit.orders and unit.orders.queuedOrders
    if not activeOrder and (not queuedOrders or next(queuedOrders) == nil) then
        unit.ai.rushNoBuildOrdersSince = unit.ai.rushNoBuildOrdersSince or GetGameTimeSeconds()
        if GetGameTimeSeconds() - unit.ai.rushNoBuildOrdersSince >= 3 then
            unit.ai.stuckCount = 4
            unit.ai.progressCheckTicks = 5
            unit.ai.rushNoBuildOrdersSince = GetGameTimeSeconds()
        end
    else
        unit.ai.rushNoBuildOrdersSince = nil
    end
    -- initialize progress anchor
    if not unit.ai.lastProgressPosition then
        unit.ai.lastProgressPosition = currentPosition
        unit.ai.progressCheckTicks = 0
    end
    -- avoid evaluating movement every tick
    if not BuilderObservationDue(unit) then return unit.ai.eState end
    unit.ai.progressCheckTicks = unit.ai.progressCheckTicks + 1
    if unit.ai.progressCheckTicks >= 5 then
        local progressDistanceSquared = Distance2DSquared(currentPosition.x, currentPosition.z, unit.ai.lastProgressPosition.x, unit.ai.lastProgressPosition.z)
        -- reset stuck detection after real movement progress
        if progressDistanceSquared > 64 then -- 8 units moved
            unit.ai.lastProgressPosition = currentPosition
            unit.ai.progressCheckTicks = 0
            unit.ai.stuckCount = 0
            unit.ai.logStuckState = false
        else
            -- increase stuck counter if movement progress is too small
            unit.ai.stuckCount = unit.ai.stuckCount + 1
            unit.ai.progressCheckTicks = 0
            unit.ai.logStuckState = true
            if unit.ai.stuckCount > 3 then
                if lobbyOptionsAI.debugGameTelemetry then
                    local activeOrder = unit.orders and unit.orders.activeOrder
                    local queuedOrders = unit.orders and unit.orders.queuedOrders or {}
                    local orderPosition = activeOrder and activeOrder.positionFloat3
                    AILog(" --- TacticalConstructionStall [A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Former:"..unit.platoon.ai.formerTable.FormerName.." Target:"..tostring(unit.platoon.ai.nextBuildingtpId).." Position:["..currentPosition.x..","..currentPosition.z.."] Destination:["..destination.x..","..destination.z.."] Distance:"..math.sqrt(distToDestination).." ActiveOrder:"..tostring(activeOrder and activeOrder.orderTask).." OrderPosition:["..tostring(orderPosition and orderPosition.x)..","..tostring(orderPosition and orderPosition.z).."] QueuedOrders:"..#queuedOrders.." BuildTarget:"..tostring(unit.buildBehaviorActualUnit and unit.buildBehaviorActualUnit.id.index))
                end
                local recovered = RushReliability.RecoverBuildMove(unit, destination, CalculatePlatoonThreat(unit.platoon))
                if recovered ~= "MovingToDestination" then return recovered end
                unit.ai.lastProgressPosition = currentPosition
                unit.ai.progressCheckTicks = 0
                unit.ai.stuckCount = 0
                unit.ai.logStuckState = false
            end
        end
    end
    if lobbyOptionsAI.debugUnitEState or unit.ai.logStuckState then
        unit.ai.orderText = "Moving - stucked:" .. unit.ai.stuckCount .. " times."
    end
    return unit.ai.eState
end

---Sub function to check if we have already finished a task
---@param unit table Unit class table. Contains functions and data for a unit
---@return bool Returns nil if unit is finished
function subPlanResetOnFinishedUnit(unit)
    if CheckOnFinishedUnit(unit) then
        AILog("subPlanResetOnFinishedUnit returned eState ("..unit.ai.eState..")")
        return unit.ai.eState
    end
    AILog("subPlanResetOnFinishedUnit returned false")
    return nil
end

---Sub function to check if we have already finished a task
---@param unit table Unit class table. Contains functions and data for a unit
---@return bool Returns "Disband" if unit is finished
function subPlanDisbandOnFinishedUnit(unit)
    if CheckOnFinishedUnit(unit) then
        return unit.ai.eState
    end
    if unit.ai.reservedEco then
        unit:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
    end
    return "Disband"
end

---Matches the host's completed repair state, including construction and progress restoration.
function IsRepairTargetFinished(target)
    return target:IsCompleted() and target:GetHealth() >= target:GetMaxHealth()
        and (target.captureProgress or 0) <= 0 and (target.reclaimProgress or 0) <= 0
end
---Checks the status of a unit to determine if it needs to assist, repair, recharge, reclaim, or if its current task should be canceled.
---@param unit table Unit class table containing the unit's current state and related data
---@return boolean|string Returns false if the unit's task should be canceled, otherwise returns the unit's current state
function CheckOnFinishedUnit(unit)
    -- check if we need to assist a unit and if the unit is already finshed
    local cancel = false
    if unit.dead then
        return false
    elseif unit.unitBeingAssist then
        if unit.unitBeingAssist.dead then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingAssist is not valid!")
            end
            unit.unitBeingAssist = nil
            cancel = true
        elseif unit.unitBeingAssist.upgrader then
            if unit.unitBeingAssist:GetHealth() == unit.unitBeingAssist:GetMaxHealth() then
                if unit.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingAssist has upgraded to 100%!")
                end
                unit.unitBeingAssist = nil
                cancel = true
            else
                if unit.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingAssist is upgrading")
                end
            end
        elseif unit.unitBeingAssist:IsCompleted() then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingAssist is finished!")
            end
            unit.unitBeingAssist = nil
            cancel = true
        else
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingAssist is not finished")
            end
        end
    -- while moving
    elseif unit.unitNeedRepair then
        if unit.unitNeedRepair.dead then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitNeedRepair is not valid!")
            end
            unit.unitNeedRepair = nil
            cancel = true
        elseif IsRepairTargetFinished(unit.unitNeedRepair) then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitNeedRepair is repaired to 100%!")
            end
            unit.unitNeedRepair = nil
            cancel = true
        else
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitNeedRepair is repairing")
            end
        end
    -- while repairing
    elseif unit.unitBeingRepaired then
        if unit.unitBeingRepaired.dead then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingRepaired is not valid!")
            end
            cancel = true
        elseif IsRepairTargetFinished(unit.unitBeingRepaired) then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingRepaired is repaired to 100%!")
            end
            cancel = true
        else
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingRepaired is repairing")
            end
        end
    elseif unit.unitBeingRecharge then
        if unit.unitBeingRecharge.dead then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingRecharge is not valid!")
            end
            unit.unitBeingRecharge = nil
            cancel = true
        elseif unit.unitBeingRecharge:GetHealth() == unit.unitBeingRecharge:GetMaxHealth() then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingRecharge is recharged to 100%!")
            end
            unit.unitBeingRecharge = nil
            cancel = true
        else
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingRecharge is recharged")
            end
        end
    elseif unit.unitBeingReclaimed then
        if unit.unitBeingReclaimed.dead or not unit.reclaimBehaviorIsActive then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingReclaimed is not valid!")
            end
            cancel = true
        else
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingReclaimed is reclaiming")
            end
        end
    elseif unit.unitBeingBuilt then
        if unit.unitBeingBuilt:IsCompleted() then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] found finished unitBeingBuilt. Disband!")
            end
            cancel = true
        else
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unitBeingBuilt!")
            end
        end
    end
    if cancel then
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn CheckOnFinishedUnit():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Order canceled")
        end
        if unit.ai.reservedEco then
            unit:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
            AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
        end
        return false
    end
    return unit.ai.eState
end

---Sub function to start building
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartToBuild(builder)
    local owner,assignment,unitAI=builder.army,builder.platoon,builder.ai
    local assignmentAI=assignment and assignment.ai
    if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
    -- did we reserve eco while moving to the buildplace?
    if builder.ai.reservedEco then
        builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
    end
    if not builder.factionTag then
        AILog("- WARNING: Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] builder has no factionTag")
        return "Disband"
    end
    if not builder.platoon.ai.nextBuildingtpIds then
        AILog("- WARNING: Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] platoon is missing nextBuildingtpIds")
        return "Disband"
    end
    if not builder.platoon.ai.nextBuildingtpIds[builder.factionTag] then
        AILog("- WARNING: Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] platoon is missing nextBuildingtpIds["..builder.factionTag.."] "..builder.platoon.ai.formerTable.FormerName)
        return "Disband"
    end
    local nextBuildingTemplateId = builder.platoon.ai.nextBuildingtpIds[builder.factionTag]
    if IsInvalidHardSeraphimConstruction(builder.army.id, nextBuildingTemplateId) then
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
        HostClearOrder(UnitAsArray(builder))
        AILog("- WARNING: SanctuaryRush blocked non-Seraphim construction order [A:"..builder.army.id.."] Template:"..tostring(nextBuildingTemplateId))
        return "Disband"
    end
    if IsHardSanctuaryRushArmy(builder.army.id)
        and IsHydrocarbonTemplateId(nextBuildingTemplateId)
    then
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
        AILog("- WARNING: SanctuaryRush blocked hydrocarbon build order [A:"..builder.army.id.."] Template:"..tostring(nextBuildingTemplateId))
        return "Disband"
    end
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "StartToBuild ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."]"
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has reached the buildplace -> try to build.")
    end
    if not builder.platoon.ai.buildedUnit then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] platon has no buildedUnit")
        end
        if builder.unitBeingBuilt then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Already building initial unit: ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..")")
            end
            builder.platoon.ai.buildedUnit = builder.unitBeingBuilt
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "Constructing ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] "..repr(UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName)..""
            end
            return "Building"
        elseif AIFunctions.CanBuildStructureAt(builder.army.id, builder.platoon.ai.nextBuildingtpIds[builder.factionTag], builder.platoon.ai.placeToBuild, 0) then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unit CanBuildStructureAt true")
            end
            local former = builder.platoon.ai.formerTable
            local funded
            if former.RushCapacityDomain then funded = RushBalance.CapacityAffordable(builder,nextBuildingTemplateId)
            else funded = former.AllowEcoStorageDrain or RushBalance.Affordable(builder,nextBuildingTemplateId) end
            if funded then
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Issued Build Order: ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..")")
                end
                HostIssueOrder(OrderTasks.BUILD, UnitAsArray(builder), false, builder.platoon.ai.placeToBuild, {tpId = builder.platoon.ai.nextBuildingtpIds[builder.factionTag], armyId = builder.army.id }) --orderTask, unitsArray, append, position, payload
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "searching for unitBeingBuilt ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."], "..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName
                end
                -- The host creates the placement ghost before the engineer moves or turns into build range.
                local constructionOrder = builder.orders and builder.orders.activeOrder
                local constructionTarget = constructionOrder and constructionOrder.orderTask == OrderTasks.BUILD and constructionOrder.unitGettingBuilt
                TryStartOpeningEconomyFocus(builder.army.id, constructionTarget)
                local openingFactoryLimit
                if Tags.LAND_FACTORY[nextBuildingTemplateId] and assignmentAI.baseName == "MAIN" then
                    local otherFactory = false
                    for _, unit in pairs(owner.units or {}) do
                        if unit ~= constructionTarget and not unit.dead and unit:HasTags(Tags.FACTORY) then
                            otherFactory = true
                            break
                        end
                    end
                    if not otherFactory then openingFactoryLimit = 15 end
                end
                local workState,ticks,reason=RushReliability.WaitForConstructionStart(builder,constructionTarget,constructionOrder,openingFactoryLimit)
                if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
                if workState=="Finished" then
                    assignmentAI.buildedUnit=constructionTarget
                    return "Finishing"
                elseif workState=="TimedOut" then
                    AILog("- WARNING: construction startup timed out [A:"..owner.id.."][P:"..assignment.id.."][U:"..builder.id.index.."] Reason:"..reason.." Template:"..nextBuildingTemplateId)
                    return RushReliability.ReleaseFailedConstructionStart(builder,nextBuildingTemplateId,assignmentAI.placeToBuild,reason,true)
                elseif workState~="Working" then
                    AILog("[RushWork] army="..owner.id.." event=construction-start-canceled builder="..builder.id.index.." reason="..tostring(reason),true)
                    return nil
                end
                if ticks>30 and (lobbyOptionsAI.debugGameTelemetry or assignmentAI.formerTable.DebugPlatoon) then
                    AILog("[RushWork] army="..owner.id.." event=construction-start-delayed mode=build builder="..builder.id.index.." ticks="..ticks.." unit="..nextBuildingTemplateId,true)
                end
                if builder.ai.stuckCount > 0 then
                    if builder.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] FOUND unitBeingBuilt!")
                    end
                    if lobbyOptionsAI.debugUnitEState then
                        builder.ai.orderText = "found unitBeingBuilt ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."], "..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName
                    end
                end
                if builder.unitBeingBuilt then
                    if builder.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Building initial unit: ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..")")
                    end
                    builder.platoon.ai.buildedUnit = builder.unitBeingBuilt
                    if lobbyOptionsAI.debugUnitEState then
                        builder.ai.orderText = "Constructing ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] "..repr(UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName)..""
                    end
                    return "Building"
                else
                    AILog("- WARNING: Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] builder.unitBeingBuilt = nil IssueOrder[build] ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..") failed ???")
                    if lobbyOptionsAI.debugUnitEState then
                        builder.ai.orderText = "Constructing failed ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] "..repr(UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName)..""
                    end
                    return nil
                end
            else
                -- we don't have the eco to build this, cancel this building
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no ECO for building initial unit: ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..") (disbanding...)")
                end
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "disband from engineer platoon (no ECO)"
                end
                return "Disband"
            end
        else
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] buildplace is not free!!!")
            end
            local testUnit = AIFunctions.GetClosestUnitAtPosition(builder.army.id, builder.platoon.ai.placeToBuild, 2, true)
            if testUnit then
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] analysing unit at buildplace:")
                end
                if not testUnit:IsCompleted() then
                    if builder.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Unit incomplete, assisting:")
                    end
                    builder.platoon.ai.buildedUnit = testUnit
                    return builder.ai.eState
                else
                    if builder.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Unit complete, delete buildplace")
                    end
                    builder.platoon.ai.placeToBuild = nil
                    return nil
                end

            else
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no unit at buildplace found !?!, searching for new place, reset all builders")
                end
                --search for a new buildplace, the old one is no longer available
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "buildplace is not free, searching for new place"
                end
                HostClearOrder(UnitAsArray(builder))
                builder.platoon.ai.placeToBuild = FindNextConstructionPosition(builder.platoon)
                for i, platoonBuilder in pairs(builder.platoon:GetUnits()) do
                    if IsValidPlatoonUnit(platoonBuilder) then
                        HostClearOrder(UnitAsArray(platoonBuilder))
                        platoonBuilder.ai.eState = nil
                        platoonBuilder.ai.path = nil
                        platoonBuilder.ai.lastPosition = false
                        platoonBuilder.ai.highestDist = false
                        platoonBuilder.ai.stuckCount = 0
                        platoonBuilder.ai.progressCheckTicks = 0
                        platoonBuilder.ai.logStuckState = false
                    end
                end
                if builder.platoon.ai.placeToBuild then
                    if builder.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] nextBuilding: ["..builder.platoon.ai.nextBuildingtpId.."] at alternativ position:("..builder.platoon.ai.placeToBuild.x..", "..builder.platoon.ai.placeToBuild.z..")")
                    end
                    return "StartMoveToDestination"
                end
            end
            builder.platoon.ai.placeToBuild = nil
            return nil
        end
    else
        if builder.unitBeingBuilt then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Already assisting initial unit: ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..")")
            end
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "Constructing ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] "..repr(UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName)..""
            end
            return "Building"
        elseif builder.platoon.ai.formerTable.AllowEcoStorageDrain or AIFunctions.IsBuildableWithoutEconStorageDrain(builder.army.id, builder.tpId, builder.platoon.ai.buildedUnit.tpId) then
            builder.unitBeingAssist = builder.platoon.ai.buildedUnit
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Issued Assist Order.")
            end
            if not builder.platoon.ai.buildedUnit.dead then
                if builder.unitBeingBuilt == builder.platoon.ai.buildedUnit then
                    AILog("- WARNING: Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Assister is already building ["..builder.platoon.ai.buildedUnit.tpId.."] "..repr(UnitTemplates[builder.platoon.ai.buildedUnit.tpId].general.unitTypeName).."")
                    return "Assisting"
                else
                    HostIssueOrder(OrderTasks.ASSISTUNIT, UnitAsArray(builder), false, builder.platoon.ai.placeToBuild, {targetGlobalId = builder.platoon.ai.buildedUnit.id }) --orderTask, unitsArray, append, position, payload
                end
            else
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("- WARNING: Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] buildedUnit.id is invalid: "..builder.platoon.ai.buildedUnit.id.index)
                end
            end
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "searching for unitBeingBuilt ["..builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag].."], "..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag]].general.unitTypeName
            end
            local constructionTarget = builder.platoon.ai.buildedUnit
            local assistanceOrder = builder.orders and builder.orders.activeOrder
            local workState,ticks,reason=RushReliability.WaitForConstructionStart(builder,constructionTarget,assistanceOrder)
            if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
            if workState=="Finished" then return "Finishing"
            elseif workState=="TimedOut" then
                AILog("- WARNING: construction assist startup timed out [A:"..owner.id.."][P:"..assignment.id.."][U:"..builder.id.index.."] Reason:"..reason.." Template:"..constructionTarget.tpId)
                return RushReliability.ReleaseFailedConstructionStart(builder,constructionTarget.tpId,assignmentAI.placeToBuild,reason,false)
            elseif workState~="Working" then
                builder.unitBeingAssist=nil
                return nil
            end
            if ticks>30 and (lobbyOptionsAI.debugGameTelemetry or assignmentAI.formerTable.DebugPlatoon) then
                AILog("[RushWork] army="..owner.id.." event=construction-start-delayed mode=assist builder="..builder.id.index.." ticks="..ticks.." unit="..constructionTarget.tpId,true)
            end
            if builder.ai.stuckCount > 0 then
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Assister FOUND unitBeingBuilt!")
                end
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "found unitBeingBuilt ["..builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag].."], "..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag]].general.unitTypeName
                end
            end
            if builder.unitBeingBuilt then
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Assisting initial unit!")
                end
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "Assisting ["..builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag].."] "..repr(UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag]].general.unitTypeName)..""
                end
                return "Assisting"
            else
                AILog("- WARNING: Fn subPlanStartToBuild():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] builder.unitBeingBuilt = nil IssueOrder[build] ["..builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag]].general.unitTypeName..") failed ???")
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "Constructing failed ["..builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag].."] "..repr(UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag]].general.unitTypeName)..""
                end
                return nil
            end
        else
            -- we don't have the eco to build this, cancel this building
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "disband from engineer platoon (no ECO)"
            end
            return "Disband"
        end
    end
    return builder.ai.eState
end

---Sub function that waits for finishing the construction build
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanBuilding(builder)
    local constructionTarget = builder.platoon.ai.buildedUnit
    if builder:HasTags(Tags.COMMAND) and constructionTarget
        and RushCommanderWork.ConstructionTarget(builder) == constructionTarget then
        return builder.ai.eState
    end
    if not builder.unitBeingBuilt and builder.buildBehaviorIsActive and builder.buildBehaviorActualUnit == constructionTarget
        and constructionTarget and not constructionTarget.dead and not constructionTarget:IsCompleted() then
        -- A paused or repositioning host builder still owns its unfinished construction.
        return builder.ai.eState
    end
    if not builder.unitBeingBuilt then
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Finished build ["..builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag].."], "..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.platoon.ai.buildedUnit.factionTag]].general.unitTypeName
        end
        HostClearOrder(UnitAsArray(builder))
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanBuilding():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no unitBeingBuilt: ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..")")
        end
        if builder.platoon.ai.buildedUnit and builder.platoon.ai.buildedUnit:IsCompleted() then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanBuilding():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] platoon.ai.buildedUnit = finished.")
            end
            return "Finishing"
        end
        local health = 100 / builder.platoon.ai.buildedUnit:GetMaxHealth() * builder.platoon.ai.buildedUnit:GetHealth()
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanBuilding():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no unitBeingBuilt, platoon.ai.buildedUnit = ("..health.."% health)")
        end
        builder.platoon.ai.placeToBuild = nil
        return nil
    end
    local health = 100 / builder.platoon.ai.buildedUnit:GetMaxHealth() * builder.platoon.ai.buildedUnit:GetHealth()
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanBuilding():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Building: ["..builder.platoon.ai.nextBuildingtpIds[builder.factionTag].."] ("..UnitTemplates[builder.platoon.ai.nextBuildingtpIds[builder.factionTag]].general.unitTypeName..") ("..health.."% health)")
    end
    return builder.ai.eState
end

---Sub function that waits for finishing the construction assist
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanBuildingAssist(builder)
    local constructionTarget = builder.buildBehaviorActualUnit
    local assistTarget = builder.unitBeingAssist
    local commanderFoundation = builder:HasTags(Tags.COMMAND)
        and RushCommanderWork.ConstructionTarget(builder)
    if commanderFoundation and (commanderFoundation == assistTarget
        or commanderFoundation == builder.platoon.ai.buildedUnit) then
        return builder.ai.eState
    end
    if not builder.unitBeingBuilt and builder.buildBehaviorIsActive and constructionTarget and not constructionTarget.dead
        and not constructionTarget:IsCompleted() and (constructionTarget == assistTarget or constructionTarget == builder.platoon.ai.buildedUnit
        or assistTarget and constructionTarget == assistTarget.upgradeBehaviorTargetUnit) then
        -- Absence of the work routine does not finish an active construction behavior.
        return builder.ai.eState
    end
    if not builder.unitBeingBuilt or builder.unitBeingBuilt:IsCompleted() then
        HostClearOrder(UnitAsArray(builder))
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Finished assisting"
        end
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanBuildingAssist():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] builder.unitBeingBuilt = finished.")
        end
        return "Finishing"
    end
    local health = 100 / builder.unitBeingBuilt:GetMaxHealth() * builder.unitBeingBuilt:GetHealth()
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanBuildingAssist():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Assisting: ["..builder.unitBeingBuilt.tpId.."] ("..builder.unitBeingBuilt.tp.general.unitTypeName..") ("..health.."% health)")
    end
    return builder.ai.eState
end

---Sub function that waits for finishing the construction build and assist
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanFinishing(builder)
    -- An assistance target from an earlier construction order must not block this platoon's completion.
    if builder.unitBeingAssist and builder.unitBeingAssist ~= builder.platoon.ai.buildedUnit then builder.unitBeingAssist = nil end
    local waitForFinish = false
    if not waitForFinish and builder.unitBeingBuilt then
        waitForFinish = true
        if builder.unitBeingBuilt.dead or builder.unitBeingBuilt:IsCompleted() then
            HostClearOrder(UnitAsArray(builder))
        else
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("- WARNING: Fn subPlanFinishing():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] [eState] = Finishing. unitBeingBuilt not NIL target progress:"..builder.unitBeingBuilt.progress.." ("..builder.unitBeingBuilt:GetHealth().."/"..builder.unitBeingBuilt:GetMaxHealth()..")")
            end
        end
    end
    if not waitForFinish and builder.unitBeingAssist then
        waitForFinish = true
        if builder.unitBeingAssist.dead or builder.unitBeingAssist:IsCompleted() then
            builder.unitBeingAssist = nil
        else
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("- WARNING: Fn subPlanFinishing():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] [eState] = Finishing. unitBeingAssist not NIL target progress:"..builder.unitBeingAssist.progress.." ("..builder.unitBeingAssist:GetHealth().."/"..builder.unitBeingAssist:GetMaxHealth()..")")
            end
        end
    end
    if not waitForFinish and builder.ai.reservedEco then
        waitForFinish = true
        builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
    end
    if not waitForFinish then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanFinishing():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unit is finished with build/assist -> Finished")
        end
        HostClearOrder(UnitAsArray(builder))
        builder.ai.eState = "Finished"
        -- unit is builded, set all units to "Finishing"
        for i, builder in pairs(builder.platoon:GetUnits()) do
            if builder.ai.eState ~= "Finished" then
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanFinishing():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..", switched to Finishing")
                end
                builder.ai.eState = "Finishing"
            end
        end
        return "Finished"
    end
    return builder.ai.eState
end

---Sub function that waits for all builder to finishe the construction
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanFinished(builder)
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "Finished"
    end
    -- check if all builders are finished, then go to the next building
    local allFinished = true
    for i, builder in pairs(builder.platoon:GetUnits()) do
        if builder.ai.eState ~= "Finished" then
            allFinished = false
            break
        end
    end
    if allFinished then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanFinished():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] All units finished!")
        end
        builder.platoon.ai.placeToBuild = false
        builder.platoon.ai.buildedUnit = false
        -- reset all builders
        for i, builder in pairs(builder.platoon:GetUnits()) do
            builder.ai.eState = nil
        end
        return nil
    end
    return builder.ai.eState
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------- Cap Alloy Spot -----------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing build orders for cap alloy spots.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planEngineerCapAlloySpot(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    local planAI=platoon.ai
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.capRadiusMin = formerTable.AIPlanData.SearchInnerRing or 0
    platoon.ai.capRadiusMax = formerTable.AIPlanData.SearchOuterRing or 600
    platoon.ai.maxCap = formerTable.AIPlanData.MaxCap
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    -- ToDo Alloy: this check should be based on the strategymanager data
    --check if we have alloy marker
    if not GameInfo.MapData.markers or not GameInfo.MapData.markers.Alloys then
        AILog("- WARNING: Fn planEngineerCapAlloySpot(): no .markers.Alloys found in GameInfo.MapData")
        ExitPlatoon(platoon)
        return
    end
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for cap alloy found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to cap resource spot")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planEngineerCapAlloySpot")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, platoon.ai.basePosition)
    -- remove unit over the max limit
    useBuilder = RemoveOverMaxBuilder(useBuilder, maxUnits)
    -- get the unit we want to build
    ReportNativeSeraphimBuilderAccess(armyIndex, useBuilder)
    local unitBuildList = AIFunctions.GetWantStructures(armyIndex, baseName, formerTable, useBuilder, maxUnits)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] unitBuildList:"..repr(unitBuildList))
    end
    if not unitBuildList or not unitBuildList[1] then
        if formerTable.DebugPlatoon then
            AILog("- WARNING: Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] unitBuildList is empty on first index?!? Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
        end
        ExitPlatoon(platoon)
        return
    end
    -- assign units to platoon
    platoon:AssignUnits(useBuilder)
    useBuilder = nil
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] platoon movementLayer: "..platoon.ai.movementLayer)
    end
    platoon.ai.nextBuildingtpId = table.remove(unitBuildList, 1)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] NextBuildingtpId:"..repr(platoon.ai.nextBuildingtpId))
    end

    --Debug
    if formerTable.DebugPlatoon then
        NewThread(AlloyFieldsRenderThread, platoon)
    end

    --main cap loop
    while platoon.ai==planAI and Armies[armyIndex].ai.isAlive~=false and Armies[armyIndex]:PlatoonExists(platoon) do
        if formerTable.DebugPlatoon then
            AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] REPEAT ------------------------------------------- platoon units: "..platoon:GetNumOfUnits().."")
        end
        --check if we need to assign more builders to the platoon.
        if Armies[armyIndex].ai.bases[baseName] then subPlanGetMoreAlloyBuilders(platoon, maxUnits) end
        if platoon.ai~=planAI or Armies[armyIndex].ai.isAlive==false then return end
        local transition=false
        -- loop over units and assign tasks
        for i, builder in pairs(platoon:GetUnits()) do
            local beforeState=builder.ai.eState
            if formerTable.DebugPlatoon then
                AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..".")
            end
            if not IsValidPlatoonUnit(builder) then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planEngineerCapAlloySpot():[A:"..builder.army.id.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
                end
            elseif not RushReliability.CurrentAssignment(builder,Armies[armyIndex],platoon,builder.ai,planAI) then
                -- Captured/reassigned workers belong to their replacement plan.
            elseif not builder.ai.eState then
                RushReliability.ApplyBuilderStep(builder,platoon,function(u) return subPlanSetClosestAlloyField(platoon,u) end)
            elseif builder.ai.eState == "StartMoveToAlloyField" then
                RushReliability.ApplyBuilderStep(builder,platoon,subPlanStartMoveToAlloyField)
            elseif builder.ai.eState == "MovingToAlloyField" then
                RushReliability.ApplyBuilderStep(builder,platoon,subPlanMovingToAlloyField)
            elseif builder.ai.eState == "StartBuildAlloyField" then
                RushReliability.ApplyBuilderStep(builder,platoon,subPlanStartBuildAlloyField)
            elseif builder.ai.eState == "WaitBuildingAlloyField" then
                RushReliability.ApplyBuilderStep(builder,platoon,subPlanWaitBuildAlloyField)
            elseif builder.ai.eState == "BuildingAlloyField" then
                RushReliability.ApplyBuilderStep(builder,platoon,subPlanBuildingAlloyField)
            elseif builder.ai.eState == "StartCaptureAlloyField" then
                RushReliability.ApplyBuilderStep(builder,platoon,subPlanStartCaptureAlloyField)
            elseif builder.ai.eState == "CapturingAlloyField" then
                RushReliability.ApplyBuilderStep(builder,platoon,subPlanCapturingAlloyField)
            elseif builder.ai.eState == "Disband" then
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "disband from alloyCap platoon"
                end
                ClearUnitTemporaryPlatoonData(builder, "planEngineerCapAlloySpot")
                platoon:RemoveUnits(UnitAsArray(builder))
                if formerTable.DebugPlatoon then
                    AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] after disbanding unit from platoon. Number platoon units: "..platoon:GetNumOfUnits().."")
                end
            else
                AILog("- WARNING: Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
            end
            if builder.platoon==platoon and builder.ai.eState~=beforeState then transition=true end
        end
        if platoon:GetNumOfUnits() < 1 then
            if formerTable.DebugPlatoon then
                AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
            end
            break
        end
        WaitTicks(transition and 1 or 10)
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerCapAlloySpot():[A:"..armyIndex.."][P:"..platoon.id.."] Disbanding.")
    end
    if platoon.ai~=planAI then return end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planEngineerCapAlloySpot")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planEngineerCapAlloySpot platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Debug draw for alloy fields
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return nil This function does not return, it's a endless loop thread
function AlloyFieldsRenderThread(platoon)
    while Armies[platoon.army.id]:PlatoonExists(platoon) do
        if GetFocusArmy() == platoon.army.id then
            for _, alloyfields in pairs(Armies[platoon.army.id].ai.alloyFields) do
                alloyfields.y = alloyfields.y or 0
                local _, terrainHeight = Engine.SampleTerrainHeight(alloyfields)
                alloyfields.y = terrainHeight + 5
                Engine.DrawCircle( SnapToGround(alloyfields), 25, AIFunctions.HEXtoRGBA("FF0000FF") )
                for _, alloy in pairs(alloyfields) do
                    if type(alloy) == "table" then
                        Engine.DrawCircle( SnapToGround(alloy.position), 2, AIFunctions.HEXtoRGBA("FFFF0000") )
                        Engine.DrawLine( alloy.position, alloyfields, AIFunctions.HEXtoRGBA("FF0000FF") )
                    end
                end
            end
        end
        WaitTicks(1)
    end
end

---Collects current Alloy spot assignments from other own and mutually allied capture platoons.
function GetReservedAlloySpots(platoon)
    local reservedAlloySpots = {}
    for _, friendlyArmy in pairs(Armies) do
        if friendlyArmy.ai and friendlyArmy.ai.isAlive ~= false and (friendlyArmy == platoon.army or platoon.army:IsAlly(friendlyArmy) and friendlyArmy:IsAlly(platoon.army)) then
            for _, otherPlatoon in pairs(friendlyArmy.platoons or {}) do
                local otherPlatoonData = otherPlatoon.ai
                if otherPlatoon ~= platoon and not otherPlatoon.dead and otherPlatoonData and otherPlatoonData.formerTable and otherPlatoonData.formerTable.AIPlan == "planEngineerCapAlloySpot" then
                    for _, otherBuilder in pairs(otherPlatoon:GetUnits()) do
                        local builderData = otherBuilder.ai
                        local assignedSpot = builderData and builderData.nextResourceSpot
                        if assignedSpot and assignedSpot.position and not otherBuilder.dead and otherBuilder.army == friendlyArmy and otherBuilder.platoon == otherPlatoon and builderData.eState ~= "Disband" then
                            local position = assignedSpot.position
                            reservedAlloySpots[math.floor(position.x).."-"..math.floor(position.z)] = true
                        end
                    end
                end
            end
        end
    end
    return reservedAlloySpots
end
---Returns the closest eligible spot inside the platoon's capture ring, independent of its field center.
---@return table|nil The selected alloy spot
function GetClosestAlloySpotInCaptureRange(platoon, field, referencePosition, reservedAlloySpots, excludedSpots)
    local basePosition = platoon.ai.basePosition
    local minimumRadiusSquared = (platoon.ai.capRadiusMin or 0)^2
    local maximumRadiusSquared = (platoon.ai.capRadiusMax or 600)^2
    local blacklist = Armies[platoon.army.id].ai.alloyFieldBlacklist
    reservedAlloySpots = reservedAlloySpots or GetReservedAlloySpots(platoon)
    excludedSpots = excludedSpots or {}
    local closestSpot, closestDistanceSquared
    for _, spot in pairs(field) do
        if type(spot) == "table" and spot.position then
            local position = spot.position
            local baseDistanceSquared = Distance2DSquared(basePosition.x, basePosition.z, position.x, position.z)
            local spotKey = math.floor(position.x).."-"..math.floor(position.z)
            if baseDistanceSquared >= minimumRadiusSquared and baseDistanceSquared <= maximumRadiusSquared and not blacklist[spotKey] and not reservedAlloySpots[spotKey] and not excludedSpots[spotKey]
                and (not platoon.ai.formerTable.RushPersistentExpansion
                    or RushExpansion.SpotAllowed(platoon.army,position,platoon.ai.nextBuildingtpId,field.key)) then
                local distanceSquared = Distance2DSquared(referencePosition.x, referencePosition.z, position.x, position.z)
                if not closestDistanceSquared or distanceSquared < closestDistanceSquared then
                    closestSpot, closestDistanceSquared = spot, distanceSquared
                end
            end
        end
    end
    return closestSpot
end

---Allows a moving builder's exact Alloy target to change owner only for a substantial distance advantage.
function CanReassignMovingAlloyBuilder(builder, otherBuilder, alloySpot)
    local otherBuilderData = otherBuilder.ai
    local assignedSpot = otherBuilderData and otherBuilderData.nextResourceSpot
    if otherBuilder.dead or otherBuilder.army ~= builder.army or otherBuilder.platoon ~= builder.platoon or not assignedSpot or not assignedSpot.position then return false end
    if otherBuilderData.eState ~= "StartMoveToAlloyField" and otherBuilderData.eState ~= "MovingToAlloyField" then return false end
    local targetPosition = alloySpot.position
    if assignedSpot.position.x ~= targetPosition.x or assignedSpot.position.z ~= targetPosition.z then return false end
    local builderPosition = builder:GetPosition()
    local otherBuilderPosition = otherBuilder:GetPosition()
    local builderDistanceSquared = Distance2DSquared(builderPosition.x, builderPosition.z, targetPosition.x, targetPosition.z)
    local otherBuilderDistanceSquared = Distance2DSquared(otherBuilderPosition.x, otherBuilderPosition.z, targetPosition.x, targetPosition.z)
    local constructionRange = otherBuilderData.buildRange or otherBuilder.tp and otherBuilder.tp.construction and otherBuilder.tp.construction.range or 6
    return otherBuilderDistanceSquared > constructionRange * constructionRange and builderDistanceSquared * 4 < otherBuilderDistanceSquared
end
---Sub function to select the closest reachable alloy spot to the builder within the defined radius ring.
---@param platoon table Platoon data container
---@param builder table Unit that will capture/build the alloy field
---@return string Next execute state
function subPlanSetClosestAlloyField(platoon, builder)
    local army,unitAI,planAI=builder.army,builder.ai,platoon.ai
    local guarded=planAI.formerTable.RushPersistentExpansion==true
    -- runtime measurement start for profiling and statistics
    local START = os.clock()
    -- large sentinel value used to find the shortest path distance
    local huge = 1e50
    -- abort if maximum allowed captures for this platoon were already reached
    if builder.platoon.ai.maxCap and builder.platoon.ai.maxCap <= 0 then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSetClosestAlloyField():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] maxCap reached -> disband")
        end
        AIFunctions.SetRuntimeStats(platoon.army.id, START, "subPlanSetClosestAlloyField()")
        return "Disband"
    end
    -- reference to army-wide AI data
    local ai = Armies[platoon.army.id].ai
    -- alloyFields now include enemy extractor spots
    if next(ai.alloyFields) == nil then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSetClosestAlloyField():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] no alloyFields -> disband")
        end
        AIFunctions.SetRuntimeStats(platoon.army.id, START, "subPlanSetClosestAlloyField()")
        return "Disband"
    end
    -- current builder position (used for pathfinding start)
    local builderPos = builder:GetPosition()
    -- capture radius taken from former AIPlanData (real distances, not squared)
    local minRadius = platoon.ai.capRadiusMin or 0
    local maxRadius = platoon.ai.capRadiusMax or 600
    -- all units currently assigned to this platoon
    local units = platoon:GetUnits()
    local reservedAlloySpots = GetReservedAlloySpots(platoon)
    -- threat value of the individually moving builder used to bias path generation
    local builderThreat = AIFunctions.GetUnitThreatValueByLayer(builder, "Land")
    -- best candidate field and path found so far
    local bestField = nil
    local bestPath = nil
    local bestSpot = nil
    local bestPreviousOwner = nil
    local bestPathDistance = huge
    -- diagnostic counters used for detailed debug logging
    local totalFields = 0
    local blacklisted = 0
    local outOfRadius = 0
    local takenByOther = 0
    local stolenFromOther = 0
    local noPath = 0
    local candidatesInRadius = 0
    local pathTested = 0
    if guarded then
        bestField,bestSpot,bestPath,bestPathDistance=RushExpansion.FindSpot(platoon,builder,GetReservedAlloySpots)
        if not RushReliability.CurrentAssignment(builder,army,platoon,unitAI,planAI) then return "Disband" end
    else
    -- iterate over all known alloy fields
    local startTime = os.clock()
    local alloyFields = ai.alloyFields
    local fieldIndex, field = next(alloyFields, nil)
    while fieldIndex do
        if type(field) == "table" and field.x and field.z then
            totalFields = totalFields + 1
            -- field center position
            local centerX, centerZ = field.x, field.z
            if guarded and not RushReliability.CurrentAssignment(builder,army,platoon,unitAI,planAI) then return "Disband" end
            -- persistent unique key for blacklist and comparisons
            local fieldKey = field.key
            if not fieldKey then
                fieldKey = centerX.."-"..centerZ
                field.key = fieldKey
            end
            -- skip permanently blacklisted fields
            if ai.alloyFieldBlacklist[fieldKey] then
                blacklisted = blacklisted + 1
            else
                -- Try spots independently because Hover-clustered fields can straddle disconnected Land graphs.
                local excludedSpots = {}
                local closestAlloySpot = GetClosestAlloySpotInCaptureRange(platoon, field, builderPos, reservedAlloySpots, excludedSpots)
                if not closestAlloySpot then
                    outOfRadius = outOfRadius + 1
                else
                    candidatesInRadius = candidatesInRadius + 1
                    while closestAlloySpot do
                        local targetPosition = closestAlloySpot.position
                        local spotKey = math.floor(targetPosition.x).."-"..math.floor(targetPosition.z)
                        excludedSpots[spotKey] = true
                        local builderFieldDistance = Distance2DSquared(builderPos.x, builderPos.z, targetPosition.x, targetPosition.z)
                        local fieldOwner = nil
                        local fieldOwnerDistance = nil
                        for i = 1, #units do
                            local other = units[i]
                            if other.id.index ~= builder.id.index and other.ai then
                                local otherSpot = other.ai.nextResourceSpot
                                if otherSpot and otherSpot.position and otherSpot.position.x == targetPosition.x and otherSpot.position.z == targetPosition.z then
                                    local otherState = other.ai.eState
                                    if otherState == "StartMoveToAlloyField" or otherState == "MovingToAlloyField" then
                                        local otherPos = other:GetPosition()
                                        local otherFieldDistance = Distance2DSquared(otherPos.x, otherPos.z, targetPosition.x, targetPosition.z)
                                        if not fieldOwnerDistance or otherFieldDistance < fieldOwnerDistance then
                                            fieldOwner = other
                                            fieldOwnerDistance = otherFieldDistance
                                        end
                                    else
                                        fieldOwner = other
                                        fieldOwnerDistance = 0
                                        break
                                    end
                                end
                            end
                        end
                        if not fieldOwner or builderFieldDistance < fieldOwnerDistance and CanReassignMovingAlloyBuilder(builder, fieldOwner, closestAlloySpot) then
                            pathTested = pathTested + 1
                            -- generate a path from builder to the selected spot
                            local path, info = AIMarkerGenerator.GeneratePathTo(platoon.army.id, builderPos, targetPosition, platoon.ai.movementLayer, true, builderThreat)
                            if guarded and not RushReliability.CurrentAssignment(builder,army,platoon,unitAI,planAI) then return "Disband" end
                            if not path then
                                if guarded then RushExpansion.Defer(army,targetPosition,30,builder) end
                                noPath = noPath + 1
                            else
                                local pathDistance = AIMarkerGenerator.GetPathDistance(path)
                                if pathDistance and pathDistance < bestPathDistance then
                                    bestPathDistance = pathDistance
                                    bestField = field
                                    bestPath = path
                                    bestSpot = closestAlloySpot
                                    bestPreviousOwner = fieldOwner
                                end
                                if pathDistance then break end
                            end
                        else
                            takenByOther = takenByOther + 1
                        end
                        closestAlloySpot = GetClosestAlloySpotInCaptureRange(platoon, field, builderPos, reservedAlloySpots, excludedSpots)
                    end
                end
            end
        end
        fieldIndex, field = next(alloyFields, fieldIndex)
        startTime = DelayAtX(startTime, 0.015, "subPlanSetClosestAlloyField fieldIndex %s", fieldIndex or "end")
    end
    end -- original field search for non-persistent capture plans
    -- no usable field found: emit full diagnostic summary and disband
    if not bestField or not bestPath then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSetClosestAlloyField():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] no field | total="..totalFields.." blacklisted="..blacklisted.." outOfRadius="..outOfRadius.." inRadius="..candidatesInRadius.." taken="..takenByOther.." stolen="..stolenFromOther.." pathTested="..pathTested.." noPath="..noPath.." radius=["..minRadius..","..maxRadius.."]")
        end
        AIFunctions.SetRuntimeStats(platoon.army.id, START, "subPlanSetClosestAlloyField()")
        return "Disband"
    end
    if guarded and (not RushReliability.CurrentAssignment(builder,army,platoon,unitAI,planAI)
        or not RushExpansion.SpotAllowed(army,bestSpot.position,planAI.nextBuildingtpId,bestField.key)) then return nil end
    -- Path searches can yield; another capture platoon may have assigned this spot in the meantime.
    if GetReservedAlloySpots(platoon)[math.floor(bestSpot.position.x).."-"..math.floor(bestSpot.position.z)] then
        AIFunctions.SetRuntimeStats(platoon.army.id, START, "subPlanSetClosestAlloyField()")
        return nil
    end
    if bestPreviousOwner then
        -- The selected owner may have reached its spot while path searches yielded.
        if not CanReassignMovingAlloyBuilder(builder, bestPreviousOwner, bestSpot) then
            AIFunctions.SetRuntimeStats(platoon.army.id, START, "subPlanSetClosestAlloyField()")
            return nil
        end
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSetClosestAlloyField():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] taking alloy field from farther builder [U:"..bestPreviousOwner.id.index.."]")
        end
        HostClearOrder(UnitAsArray(bestPreviousOwner))
        bestPreviousOwner.ai.nextResourceField = nil
        bestPreviousOwner.ai.nextResourceSpot = nil
        bestPreviousOwner.ai.closestAlloySpot = nil
        bestPreviousOwner.ai.captureTarget = nil
        bestPreviousOwner.ai.path = nil
        bestPreviousOwner.ai.pathDistanceToField = nil
        bestPreviousOwner.ai.lastPosition = false
        bestPreviousOwner.ai.highestDist = false
        bestPreviousOwner.ai.stuckCount = 0
        bestPreviousOwner.ai.eState = nil
        stolenFromOther = stolenFromOther + 1
        if lobbyOptionsAI.debugUnitEState then
            bestPreviousOwner.ai.orderText = "alloy field reassigned"
        end
    end
    -- assign chosen field, exact alloy spot and movement path to the builder
    builder.ai.nextResourceField = bestField
    builder.ai.nextResourceSpot = bestSpot
    builder.ai.path = bestPath
    builder.ai.pathDistanceToField = bestPathDistance
    if guarded then builder.ai.rushAlloyRetries=0 end
    if lobbyOptionsAI.debugGameTelemetry then
        AILog(" --- TacticalAlloyAssignment [A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] Target:["..tostring(bestSpot.position.x)..","..tostring(bestSpot.position.z).."] PathDistance:"..tostring(bestPathDistance))
    end
    -- construction range used later during build logic
    builder.ai.buildRange = builder.tp.construction.range or 6
    -- reset movement tracking helpers
    builder.ai.lastPosition = false
    builder.ai.highestDist = false
    -- record runtime statistics and continue with movement state
    AIFunctions.SetRuntimeStats(platoon.army.id, START, "subPlanSetClosestAlloyField()")
    return "StartMoveToAlloyField"
end

---Sub function to set move orders along waypoints to the alloy filed
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartMoveToAlloyField(builder)
    local army,platoon,unitAI=builder.army,builder.platoon,builder.ai
    local planAI=platoon and platoon.ai
    if builder.ai.path then
        local path = AIMarkerGenerator.StraightenPath(builder.ai.path)
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] start moving to alloy spot.")
        end
        HostClearOrder(UnitAsArray(builder))
        WaitTicks(3)
        if not RushReliability.CurrentAssignment(builder,army,platoon,unitAI,planAI) then return "Disband" end
        for z, nodePos in pairs(path) do
            HostIssueOrder(OrderTasks.MOVE, UnitAsArray(builder), true, nodePos, nil) --orderTask, unitsArray, append, position, payload
        end
        local destinationPosition = builder.ai.nextResourceSpot and builder.ai.nextResourceSpot.position or builder.ai.nextResourceField
        if destinationPosition then
            HostIssueOrder(OrderTasks.MOVE, UnitAsArray(builder), true, destinationPosition, nil) --orderTask, unitsArray, append, position, payload
        end
        return "MovingToAlloyField"
    elseif builder.ai.nextResourceField then
        --use transport here
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no path, need transport (debug:disbanding)")
        end
        return "Disband"
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartMoveToAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no alloy spot set, disbanding")
    end
    return "Disband"
end

---Continues moving an engineer to its selected alloy field and handles stuck movement.
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Next engineer state
function subPlanMovingToAlloyField(builder)
    local army,platoon,unitAI=builder.army,builder.platoon,builder.ai
    local planAI=platoon and platoon.ai
    local guarded=planAI and planAI.formerTable.RushPersistentExpansion==true
    local currentPosition = builder:GetPosition()
    if guarded then
        local spot=unitAI.nextResourceSpot
        if not spot or not spot.position then return "Disband" end
        if GetGameTimeSeconds()>=(unitAI.rushAlloySafetyAt or 0) then
            unitAI.rushAlloySafetyAt=GetGameTimeSeconds()+3
            if not RushExpansion.SpotAllowed(army,spot.position,planAI.nextBuildingtpId) then
                RushExpansion.Defer(army,spot.position,30)
                HostClearOrder(UnitAsArray(builder))
                unitAI.nextResourceSpot=nil;unitAI.nextResourceField=nil;unitAI.path=nil
                return nil
            end
        end
    end
    builder.ai.lastPosition = builder.ai.lastPosition or currentPosition
    local moveDistance = Distance2DSquared(currentPosition.x, currentPosition.z, builder.ai.lastPosition.x, builder.ai.lastPosition.z)
    local destinationPosition = builder.ai.nextResourceSpot and builder.ai.nextResourceSpot.position or builder.ai.nextResourceField
    local distToDestination = Distance2DSquared(currentPosition.x, currentPosition.z, destinationPosition.x, destinationPosition.z)
    local buildRangeSquared = builder.ai.buildRange * builder.ai.buildRange
    if distToDestination <= buildRangeSquared then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMovingToAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] distToDestination < builder.ai.buildRange -> StartToBuild")
        end
        HostClearOrder(UnitAsArray(builder))
        return "StartBuildAlloyField"
    end
    if not BuilderObservationDue(builder) then return builder.ai.eState end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanMovingToAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder is out of range and moving to the alloy spot...")
    end
    -- check if we are still moving
    if not builder.ai.highestDist or moveDistance > builder.ai.highestDist then
        if moveDistance > (30*30) then
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
        else
            builder.ai.highestDist = moveDistance
            builder.ai.stuckCount = 0
        end
    else
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMovingToAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder is stucked (moveDistance:"..moveDistance..")")
        end
        builder.ai.stuckCount = builder.ai.stuckCount + 1
        if builder.ai.stuckCount > 3 then
            if guarded then
                -- Repeated failed travel must release a continuous expansion
                -- slot; never keep shortening a bad route forever.
                local retries=unitAI.rushAlloyRetries or 0
                if retries>=3 then
                    RushExpansion.Defer(army,destinationPosition,30,builder)
                    HostClearOrder(UnitAsArray(builder))
                    return "Disband"
                end
                unitAI.rushAlloyRetries=retries+1
                local path=AIMarkerGenerator.GeneratePathTo(army.id,currentPosition,destinationPosition,
                    planAI.movementLayer,true,AIFunctions.GetUnitThreatValueByLayer(builder,"Land"))
                if not RushReliability.CurrentAssignment(builder,army,platoon,unitAI,planAI) then return "Disband" end
                if type(path)~="table" or not next(path) then
                    RushExpansion.Defer(army,destinationPosition,30,builder)
                    HostClearOrder(UnitAsArray(builder));return "Disband"
                end
                unitAI.path=path;unitAI.lastPosition=false;unitAI.highestDist=false;unitAI.stuckCount=0
                return "StartMoveToAlloyField"
            end
            HostClearOrder(UnitAsArray(builder))
            builder.ai.path = AIMarkerGenerator.MakeShortPath(currentPosition, builder.ai.path)
            local path = AIMarkerGenerator.StraightenPath(builder.ai.path)
            for _, nodePos in ipairs(path) do
                HostIssueOrder(OrderTasks.MOVE, UnitAsArray(builder), true, GetRandomizedPositionCopy(nodePos), nil)
            end
            -- Keep the remaining waypoints queued and finish at the exact selected spot.
            HostIssueOrder(OrderTasks.MOVE, UnitAsArray(builder), true, destinationPosition, nil)
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
        end
    end
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "Moving ("..moveDistance..") to alloy spot - stucked:"..builder.ai.stuckCount.." times."
    end
    return builder.ai.eState
end

---Returns the enemy alloy extractor located on the given alloy spot.
---@param armyIndex integer Index number of the army
---@param alloySpotPosition table Position formatted as {x=0,y=0,z=0}
---@return table Enemy alloy extractor target table, nil otherwise
function GetEnemyAlloyExtractorAtAlloySpot(armyIndex, alloySpotPosition)
    if not Armies[armyIndex].ai.targets then
        return nil
    end
    local targets = Armies[armyIndex].ai.targets.enemyAlloyExtractors
    if not targets then
        return nil
    end
    for _, target in ipairs(targets) do
        if target.pos and target.targetGlobalId then
            if target.pos.x == alloySpotPosition.x and target.pos.z == alloySpotPosition.z then
                return target
            end
        end
    end
    return nil
end

---Returns the closest uncaptured enemy engineer inside the selected alloy spot construction range.
---@param armyIndex integer Index number of the army
---@param alloySpotPosition table Position formatted as {x=0,y=0,z=0}
---@param captureRadius number Maximum distance from the alloy spot
---@return table Enemy engineer unit, nil otherwise
function GetEnemyEngineerAtAlloySpot(armyIndex, alloySpotPosition, captureRadius)
    local closestEnemyEngineer = nil
    local closestDistanceSquared = nil
    local enemyEngineers = AIFunctions.GetEnemyUnitsAroundPosition(armyIndex, alloySpotPosition, captureRadius, Tags.MOBILE * Tags.LAND * Tags.ENGINEER - Tags.COMMAND - Tags.ENGINEERING_STATION, false)
    for _, enemyEngineer in ipairs(enemyEngineers) do
        if not enemyEngineer.capturers or not enemyEngineer.capturers[1] then
            local enemyEngineerPosition = enemyEngineer:GetPosition()
            local distanceSquared = Distance2DSquared(enemyEngineerPosition.x, enemyEngineerPosition.z, alloySpotPosition.x, alloySpotPosition.z)
            if not closestDistanceSquared or distanceSquared < closestDistanceSquared then
                closestEnemyEngineer = enemyEngineer
                closestDistanceSquared = distanceSquared
            end
        end
    end
    return closestEnemyEngineer
end

---Sub function to start building a alloy extractor
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartBuildAlloyField(builder)
    local army,platoon,unitAI=builder.army,builder.platoon,builder.ai
    local planAI=platoon and platoon.ai
    local guarded=planAI and planAI.formerTable.RushPersistentExpansion==true
    builder.ai.alloyConstructionTarget = nil
    -- check if we have already reached the maxcap
    if builder.platoon.ai.maxCap and builder.platoon.ai.maxCap <= 0 then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] max cap reached, disbanding...")
        end
        return "Disband"
    end
    -- get the selected alloy spot in the field
    local closestAlloySpotPOS
    local closestAlloySpot = builder.ai.nextResourceSpot or GetClosestAlloySpotInCaptureRange(builder.platoon, builder.ai.nextResourceField, builder:GetPosition())
    -- did we found a alloy spot in the list?
    if closestAlloySpot then
        if guarded and not RushExpansion.SpotAllowed(army,closestAlloySpot.position,planAI.nextBuildingtpId,
            builder.ai.nextResourceField and builder.ai.nextResourceField.key) then
            RushExpansion.Defer(army,closestAlloySpot.position,30)
            builder.ai.nextResourceSpot=nil
            builder.ai.nextResourceField=nil
            return nil
        end
        builder.ai.nextResourceSpot = closestAlloySpot
        closestAlloySpotPOS = SnapToGround({ x = closestAlloySpot.position.x, y = closestAlloySpot.position.y, z = closestAlloySpot.position.z })
        builder.ai.closestAlloySpot = closestAlloySpot
        -- Approach each new spot through the same path and stuck recovery used for the first spot.
        local builderPosition = builder:GetPosition()
        local buildRange = builder.ai.buildRange or 6
        if Distance2DSquared(builderPosition.x, builderPosition.z, closestAlloySpotPOS.x, closestAlloySpotPOS.z) > buildRange * buildRange then
            local builderThreat = AIFunctions.GetUnitThreatValueByLayer(builder, "Land")
            local path = AIMarkerGenerator.GeneratePathTo(army.id, builderPosition, closestAlloySpotPOS, planAI.movementLayer, true, builderThreat)
            if not RushReliability.CurrentAssignment(builder,army,platoon,unitAI,planAI) then return "Disband" end
            if not path then
                if guarded then
                    RushExpansion.Defer(army,closestAlloySpotPOS,30,builder)
                    builder.ai.nextResourceSpot=nil;builder.ai.nextResourceField=nil
                end
                return nil
            end
            if guarded and not RushExpansion.SpotAllowed(army,closestAlloySpotPOS,planAI.nextBuildingtpId) then return "Disband" end
            builder.ai.path=path
            builder.ai.nextResourceSpot = closestAlloySpot
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
            builder.ai.stuckCount = 0
            return "StartMoveToAlloyField"
        end
        builder.ai.captureTarget = GetEnemyEngineerAtAlloySpot(builder.army.id, closestAlloySpotPOS, builder.ai.buildRange or 6)
        if builder.ai.captureTarget then
            if lobbyOptionsAI.debugGameTelemetry then
                AILog("* Fn subPlanStartBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Enemy engineer [U:"..builder.ai.captureTarget.id.index.."] at selected alloy spot, switching to opportunistic capture.")
            end
        else
            builder.ai.captureTarget = closestAlloySpot.captureTarget or GetEnemyAlloyExtractorAtAlloySpot(builder.army.id, closestAlloySpotPOS)
            if builder.ai.captureTarget then
                builder.ai.captureTarget = GetUnitById(builder.ai.captureTarget.targetGlobalId)
                if builder.ai.captureTarget and (builder.ai.captureTarget.dead or not builder.army:IsEnemy(builder.ai.captureTarget.army)) then
                    builder.ai.captureTarget = nil
                end
            end
        end
        if builder.ai.captureTarget then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Enemy unit found at selected alloy spot, switching to capture.")
            end
            return "StartCaptureAlloyField"
        end
        local nextBuildingTemplateId = builder.platoon.ai.nextBuildingtpId[builder.factionTag]
        if IsInvalidHardSeraphimConstruction(builder.army.id, nextBuildingTemplateId) then
            AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
            HostClearOrder(UnitAsArray(builder))
            AILog("- WARNING: SanctuaryRush blocked non-Seraphim alloy construction order [A:"..builder.army.id.."] Template:"..tostring(nextBuildingTemplateId))
            return "Disband"
        end
        if AIFunctions.CanBuildStructureAt(builder.army.id, nextBuildingTemplateId, closestAlloySpotPOS, 0) then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Issued Build Order.")
            end
            HostIssueOrder(OrderTasks.BUILD, UnitAsArray(builder), false, closestAlloySpotPOS, {tpId = nextBuildingTemplateId, armyId = builder.army.id }) --orderTask, unitsArray, append, position, payload
            local constructionOrder = builder.orders and builder.orders.activeOrder
            if constructionOrder and constructionOrder.orderTask == OrderTasks.BUILD then
                builder.ai.alloyConstructionTarget = constructionOrder.unitGettingBuilt
            end
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "searching for unitBeingBuilt ["..nextBuildingTemplateId.."], "..UnitTemplates[nextBuildingTemplateId].general.unitTypeName
            end
            -- using builder.ai.stuckCount variable to check if we have found unitBeingBuilt after some time
            builder.ai.stuckCount = 0
            return "WaitBuildingAlloyField"
        end
        HostClearOrder(UnitAsArray(builder))
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] CanBuildStructureAt FAILED."..repr(closestAlloySpot))
        end
        RemoveSpotFromList(builder, builder.ai.closestAlloySpot)
    end
    -- no spot in list left, get new spots
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no spot left in list, reset.")
    end
    return nil
end

---Sub function that waits for starting the alloy extractor build
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanWaitBuildAlloyField(builder)
    local constructionTarget = builder.ai.alloyConstructionTarget
    if constructionTarget and (constructionTarget.dead or constructionTarget:IsCompleted()) then
        if not constructionTarget.dead then RemoveSpotFromList(builder, builder.ai.closestAlloySpot) end
        builder.ai.alloyConstructionTarget = nil
        return "StartBuildAlloyField"
    end
    if builder.unitBeingBuilt and (not constructionTarget or builder.unitBeingBuilt == constructionTarget) then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanWaitBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder FOUND unitBeingBuilt! after "..builder.ai.stuckCount.." loops.")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Constructing ["..builder.platoon.ai.nextBuildingtpId[builder.factionTag].."] "..repr(UnitTemplates[ builder.platoon.ai.nextBuildingtpId[builder.factionTag] ].general.unitTypeName)..""
        end
        RemoveSpotFromList(builder, builder.ai.closestAlloySpot)
        return "BuildingAlloyField"
    end
    if not BuilderObservationDue(builder) then return builder.ai.eState end
    builder.ai.stuckCount = builder.ai.stuckCount + 1
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "waiting for unitBeingBuilt ["..builder.platoon.ai.nextBuildingtpId[builder.factionTag].."], "..UnitTemplates[ builder.platoon.ai.nextBuildingtpId[builder.factionTag] ].general.unitTypeName.." ("..builder.ai.stuckCount..")"
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanWaitBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder waiting for unitBeingBuilt ("..builder.ai.stuckCount..")!")
    end
    if builder.ai.stuckCount > 60 then
        AILog("- WARNING: Fn subPlanWaitBuildAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no unitBeingBuilt; waited ("..builder.ai.stuckCount.." times)")
        HostClearOrder(UnitAsArray(builder))
        return "StartBuildAlloyField"
    end
    return builder.ai.eState
end

---Sub function that waits for finishing the alloy extractor build
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanBuildingAlloyField(builder)
    local constructionTarget = builder.ai.alloyConstructionTarget
    if not builder.unitBeingBuilt and builder.buildBehaviorIsActive and builder.buildBehaviorActualUnit == constructionTarget
        and constructionTarget and not constructionTarget.dead and not constructionTarget:IsCompleted() then
        return builder.ai.eState
    end
    if not builder.unitBeingBuilt then
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Finished build ["..builder.platoon.ai.nextBuildingtpId[builder.factionTag].."], "..UnitTemplates[ builder.platoon.ai.nextBuildingtpId[builder.factionTag] ].general.unitTypeName
        end
        HostClearOrder(UnitAsArray(builder))
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanBuildingAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Finished building (unitBeingBuilt = nil)")
        end
        -- get the nest spot inside the alloy field
        builder.ai.alloyConstructionTarget = nil
        return "StartBuildAlloyField"
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanBuildingAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Building alloy extractor")
    end
    return builder.ai.eState
end

---Sub function to start capturing an enemy alloy extractor.
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartCaptureAlloyField(builder)
    if not builder.ai.captureTarget or builder.ai.captureTarget.dead or not builder.army:IsEnemy(builder.ai.captureTarget.army) then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no capture target, returning to build.")
        end
        builder.ai.captureTarget = nil
        return "StartBuildAlloyField"
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Issued Capture Order.")
    end
    HostIssueOrder(OrderTasks.CAPTURE, UnitAsArray(builder), false, builder.ai.captureTarget:GetPosition(), {targetGlobalId = builder.ai.captureTarget.id }) --orderTask, unitsArray, append, position, payload
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "searching for unitBeingCaptured "
    end
    if not builder.ai.captureTarget:HasTags(Tags.ENGINEER) then
        RemoveSpotFromList(builder, builder.ai.closestAlloySpot)
    end
    -- using builder.ai.stuckCount variable to check if we have found unitBeingCaptured after some time
    builder.ai.stuckCount = 0
    while not builder.unitBeingCaptured do
        if builder.dead or not builder.platoon then
            return nil
        end
        if not builder.ai.captureTarget or builder.ai.captureTarget.dead then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("- WARNING: Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] captureTarget became invalid while waiting for unitBeingCaptured!")
            end
            builder.ai.captureTarget = nil
            return nil
        end
        if builder.ai.captureTarget:HasTags(Tags.ENGINEER) then
            local captureRadius = builder.ai.buildRange or 6
            local alloySpotPosition = builder.ai.closestAlloySpot and builder.ai.closestAlloySpot.position
            local captureTargetPosition = builder.ai.captureTarget:GetPosition()
            if not alloySpotPosition or Distance2DSquared(captureTargetPosition.x, captureTargetPosition.z, alloySpotPosition.x, alloySpotPosition.z) > captureRadius * captureRadius then
                AILog("* Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Enemy engineer left the selected alloy spot; capture canceled.")
                HostClearOrder(UnitAsArray(builder))
                builder.ai.captureTarget = nil
                return "StartBuildAlloyField"
            end
        end
        if not builder.army:IsEnemy(builder.ai.captureTarget.army) then
            HostClearOrder(UnitAsArray(builder))
            builder.ai.captureTarget = nil
            return nil
        end
        builder.ai.stuckCount = builder.ai.stuckCount + 1
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("- WARNING: Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no unitBeingCaptured!")
        end
        if builder.ai.stuckCount > 30 then
            AILog("- WARNING: Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no unitBeingCaptured; waited ("..builder.ai.stuckCount.." times)")
            HostClearOrder(UnitAsArray(builder))
            break
        end
        WaitTicks(1)
    end
    if builder.ai.stuckCount > 0 and builder.ai.stuckCount < 30 then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder FOUND unitBeingCaptured!")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "found unitBeingCaptured ["..builder.unitBeingCaptured.tpId.."], "..builder.unitBeingCaptured.tp.general.unitTypeName
        end
    end
    if builder.unitBeingCaptured then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] capturing unit!")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Capturing ["..builder.unitBeingCaptured.tpId.."] "..repr(builder.unitBeingCaptured.tp.general.unitTypeName)..""
        end
        return "CapturingAlloyField"
    else
        AILog("- WARNING: Fn subPlanStartCaptureAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] builder.unitBeingCaptured = nil IssueOrder[CAPTURE] failed!!!")
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Capturing failed"
        end
    end
    builder.ai.stuckCount = 0
    builder.ai.captureTarget = nil
    return "StartBuildAlloyField"
end

---Sub function that waits for finishing an enemy unit capture at an alloy spot.
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanCapturingAlloyField(builder)
    local captureTarget = builder.ai.captureTarget
    local captureIsActive = captureTarget and not captureTarget.dead and builder.captureBehaviorIsActive and builder.captureBehaviorTarget == captureTarget
    if (builder.unitBeingCaptured or captureIsActive) and captureTarget and captureTarget:HasTags(Tags.ENGINEER) then
        local captureRadius = builder.ai.buildRange or 6
        local alloySpotPosition = builder.ai.closestAlloySpot and builder.ai.closestAlloySpot.position
        local captureTargetPosition = captureTarget:GetPosition()
        if not alloySpotPosition or Distance2DSquared(captureTargetPosition.x, captureTargetPosition.z, alloySpotPosition.x, alloySpotPosition.z) > captureRadius * captureRadius then
            AILog("* Fn subPlanCapturingAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Enemy engineer left the selected alloy spot; active capture canceled.")
            HostClearOrder(UnitAsArray(builder))
            builder.ai.captureTarget = nil
            return "StartBuildAlloyField"
        end
    end
    -- The capture routine may pause while the matching behavior still owns its target.
    if not builder.unitBeingCaptured and captureIsActive and builder.army:IsEnemy(captureTarget.army) then return builder.ai.eState end
    if not builder.unitBeingCaptured then
        if builder.ai.captureTarget and builder.ai.captureTarget:HasTags(Tags.ENGINEER) and builder.ai.captureTarget.captureProgress >= builder.ai.captureTarget.tp.economy.buildTime then
            AILog("* Fn subPlanCapturingAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Enemy engineer captured at selected alloy spot.")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Enemy unit at alloy spot captured"
        end
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanCapturingAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Enemy unit at alloy spot captured.")
        end
        builder.ai.stuckCount = 0
        builder.ai.captureTarget = nil
        return "StartBuildAlloyField"
    else
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanCapturingAlloyField():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Capturing enemy unit at alloy spot.")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "Capturing ["..builder.unitBeingCaptured.tpId.."] "..repr(builder.unitBeingCaptured.tp.general.unitTypeName).." captureProgress:"..builder.unitBeingCaptured.captureProgress
        end
    end
    return builder.ai.eState
end

---Sub function to remove a used spot from the alloy filed list
---@param builder table Unit class table. Contains functions and data for a unit
---@param spotToRemove table alloy spot that we want to remove
---@return string Returns the next e(xecute)State for the builder
function RemoveSpotFromList(builder, spotToRemove)
    -- Clear the consumed target so the next build selects another spot in this field.
    if builder.ai.nextResourceSpot == spotToRemove then
        builder.ai.nextResourceSpot = nil
    end
    local spotCount = 0
    for i, AlloySpot in pairs(builder.ai.nextResourceField) do
        if type(AlloySpot) == "table" then
            if AlloySpot == spotToRemove then
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn RemoveSpotFromList():[A:"..builder.army.id.."][P:"..builder.platoon.id.."] removing alloy spot from list")
                end
                builder.ai.nextResourceField[i] = nil
                if builder.platoon.ai.maxCap then
                    builder.platoon.ai.maxCap = builder.platoon.ai.maxCap - 1
                end
            else
                spotCount = spotCount + 1
            end
        end
    end
    -- if no spot left, delete the fieled from the list
    if spotCount == 0 then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn RemoveSpotFromList():[A:"..builder.army.id.."][P:"..builder.platoon.id.."] no alloy spots left, try to delete alloy field from list")
        end
        for i, alloyfield in pairs(Armies[builder.army.id].ai.alloyFields) do
            if alloyfield.x == builder.ai.nextResourceField.x and alloyfield.z == builder.ai.nextResourceField.z then
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn RemoveSpotFromList():[A:"..builder.army.id.."][P:"..builder.platoon.id.."] no alloy spots left, deleting alloy field from list")
                end
                Armies[builder.army.id].ai.alloyFields[i] = nil
            end
        end
    end
end

---Sub function to add more builders to the alloy cap platoon
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param maxUnits integer Number of units that can be assigned to the alloy cap platoon
---@return nil
function subPlanGetMoreAlloyBuilders(platoon, maxUnits)
    local unAssignedCount = 0
    local platoonUnits = platoon:GetUnits()
    local platoonUnitCount = #platoonUnits
    if platoonUnitCount >= maxUnits then return end
    local alloyFields = Armies[platoon.army.id].ai.alloyFields
    local lockedFields = platoon.ai.lockedFields or {}
    local reservedAlloySpots = GetReservedAlloySpots(platoon)
    -- Build lookup table of already assigned alloy spots
    local assignedMap = {}
    for i = 1, #platoonUnits do
        local builder = platoonUnits[i]
        local spot = builder.ai and builder.ai.nextResourceField
        if spot then
            local key = math.floor(spot.x + 0.5) .. "-" .. math.floor(spot.z + 0.5)
            assignedMap[key] = true
        end
    end
    -- Count unassigned alloy fields within cap radius range
    for _, alloyfield in pairs(alloyFields) do
        if GetClosestAlloySpotInCaptureRange(platoon, alloyfield, platoon.ai.basePosition, reservedAlloySpots) then
            local key = math.floor(alloyfield.x + 0.5) .. "-" .. math.floor(alloyfield.z + 0.5)
            if not assignedMap[key] and not lockedFields[key] then
                unAssignedCount = unAssignedCount + 1
            end
        end
    end
    -- Skip if there are no free fields left
    if unAssignedCount <= 0 then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanGetMoreAlloyBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] no free alloy fields left, skip adding builders")
        end
        return
    end
    -- Determine how many more units can be added
    local neededUnitCount = math.min(maxUnits - platoonUnitCount, unAssignedCount)
    if neededUnitCount <= 0 then return end
    -- Request new mobile builder units
    local useBuilder, _, _, reserveForBase = AIFunctions.GetNeedMobileBuilder(platoon.army.id, platoon.ai.baseName, platoon.ai.formerTable)
    if not useBuilder then return end
    -- Sanitize and trim the candidate unit list
    CheckUnitsForLeftover(useBuilder, "subPlanGetMoreAlloyBuilders")
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, platoon.ai.basePosition)
    useBuilder = RemoveOverMaxBuilder(useBuilder, neededUnitCount)
    local addedCount = #useBuilder
    if addedCount > 0 then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanGetMoreAlloyBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] adding "..addedCount.." builders to the platoon")
        end
        platoon:AssignUnits(useBuilder)
    end
end


--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------------- Extractor Upgrade ---------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

-- Persistent extractor ownership must not recruit or replace native paid work.
local function RushExtractorAvailable(platoon,unit)
    if not RushBalance.Own(platoon.army,unit) or not unit:IsCompleted()
        or unit.platoon and unit.platoon~=platoon or RushReliability.Working(unit)
        or type(unit.GetPause)=="function" and unit:GetPause() then return false end
    local orders=unit.orders
    return not orders or not orders.activeOrder and not (orders.queuedOrders and next(orders.queuedOrders))
end

---Executing upgrade orders for alloy extractors.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planAlloyExtractorUpgrade(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planAlloyExtractorUpgrade():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    repeat
        if formerTable.DebugPlatoon then
            AILog("* Fn planAlloyExtractorUpgrade():[A:"..armyIndex.."][P:"..platoon.id.."] REPEAT -------------------------------------------")
        end
        if not RushBalance.Enabled(platoon.army) then
            platoon.ai.ecoUpgradeRatio = subPlanGetEcoUpgradeRatio(platoon)
        end
        subPlanGetMoreAlloyExtractors(platoon)
        local currentGameTimeSeconds = GetGameTimeSeconds()
        for i, extractor in pairs(platoon:GetUnits()) do
            local extractorIsUnderAttack = AIFunctions.IsUnderAttack(extractor)
            AITargetManager.UpdateAlloyExtractorEmergencyTarget(extractor, currentGameTimeSeconds, extractorIsUnderAttack)
            if not extractor.rangeToBase then
                local distSquared = Distance2DSquared(extractor:GetPosition().x, extractor:GetPosition().z, platoon.ai.basePosition.x, platoon.ai.basePosition.z)
                extractor.rangeToBase = distSquared
                if lobbyOptionsAI.debugUnitEState then
                    extractor.ai.orderText = "Range to base: "..math.floor(math.sqrt(distSquared))
                end
            end
        end
        AITargetManager.CleanupAlloyExtractorEmergencyTargets(armyIndex, currentGameTimeSeconds)
        if formerTable.DebugPlatoon then
            AILog("* Fn planAlloyExtractorUpgrade():[A:"..armyIndex.."][P:"..platoon.id.."] [eState] = "..repr(platoon.ai.eState)..".")
        end
        if not platoon.ai.eState or platoon.ai.eState == "Check For Upgrade" then
            platoon.ai.eState = subPlanCheckForExtractorUpgrade(platoon)
        elseif platoon.ai.eState == "Upgrade TECH1" then
            platoon.ai.eState = subPlanUpgradeExtractor(platoon, "TECH1")
        elseif platoon.ai.eState == "Upgrade TECH2" then
            platoon.ai.eState = subPlanUpgradeExtractor(platoon, "TECH2")
        else
            AILog("- WARNING: Fn planAlloyExtractorUpgrade():[A:"..armyIndex.."][P:"..platoon.id.."] unknown extractor eState ??? ["..repr(platoon.ai.eState).."]")
        end
        if platoon:GetNumOfUnits() < 1 then
            if formerTable.DebugPlatoon then
                AILog("* Fn planAlloyExtractorUpgrade():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
            end
            break
        end
        WaitTicks(10)
    until platoon.ai.eState == "Disband"
    if formerTable.DebugPlatoon then
        AILog("* Fn planAlloyExtractorUpgrade():[A:"..armyIndex.."][P:"..platoon.id.."] Disband.")
    end
    for i, unit in pairs(platoon:GetUnits()) do
        if RushBalance.Enabled(platoon.army) then platoon:OnUnitRemoved(unit)
        else platoon:RemoveUnits(UnitAsArray(unit)) end
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planAlloyExtractorUpgrade platoon (finished)"
        end
    end
    ExitPlatoon(platoon)
end

---Sub function to add not asigned alloy extractors to the platoon
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return nil
function subPlanGetMoreAlloyExtractors(platoon)
    local platoonUnitCount = platoon:GetNumOfUnits()
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanGetMoreAlloyExtractors():[A:"..platoon.army.id.."][P:"..platoon.id.."] Platoon has ("..platoonUnitCount..") extractors")
    end

    local extractors = AIFunctions.GetListOfArmyUnitsByTags(platoon.army.id,(Tags.STRUCTURE * Tags.ALLOYS_EXTRACTION), false)
    local extractorArmyCount = table.getn(extractors)
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanGetMoreAlloyExtractors():[A:"..platoon.army.id.."][P:"..platoon.id.."] Army has ("..extractorArmyCount..") extractors")
    end

    local extractorsToAdd = {}
    for _, unit in pairs(extractors) do
        -- Existing native upgrades and unrelated orders keep their owner.
        if not unit.platoon and (not RushBalance.Enabled(platoon.army) or RushExtractorAvailable(platoon,unit)) then
            --assign to platoon
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanGetMoreAlloyExtractors():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..unit.id.index.."] adding extractor to platoon")
            end
            CheckUnitsForLeftover({unit}, "planAlloyExtractorUpgrade")
            platoon:AssignUnits(UnitAsArray(unit))
        end
    end
    return
end

---Sub function to calculate the amount of eco we can use for extractor upgrades
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return number Returns the amount of eco we can use for extractor upgrades (in %)
function subPlanGetEcoUpgradeRatio(platoon)
    if RushBalance.Enabled(platoon.army) then
        local snapshot=RushBalance.CurrentSnapshot(platoon.army)
        return Import("AI/mods/AI-Scom/RushEconomyPolicy.lua").ExtractorShare(platoon.army,snapshot,GetGlobalAlloyUpgradeCost(platoon))
    end
    local difficultyAI = Armies[platoon.army.id].ai.settings.difficulty
    local RatioTable
    if difficultyAI == "easy" then
        RatioTable = {
            {gameMinutes = 30, ratio = 0.35},
            {gameMinutes = 25, ratio = 0.30},
            {gameMinutes = 20, ratio = 0.25},
            {gameMinutes = 15, ratio = 0.20},
            {gameMinutes = 10, ratio = 0.15},
            {gameMinutes = 6,  ratio = 0.10},
            {gameMinutes = 3,  ratio = 0.05},
            {gameMinutes = 0,  ratio = 0.00}
        }
    elseif difficultyAI == "medium" then
        RatioTable = {
            {gameMinutes = 30, ratio = 0.40},
            {gameMinutes = 25, ratio = 0.35},
            {gameMinutes = 20, ratio = 0.30},
            {gameMinutes = 15, ratio = 0.25},
            {gameMinutes = 10, ratio = 0.20},
            {gameMinutes = 6,  ratio = 0.10},
            {gameMinutes = 3,  ratio = 0.05},
            {gameMinutes = 0,  ratio = 0.00}
        }
    else
        RatioTable = {
            {gameMinutes = 30, ratio = 0.30},
            {gameMinutes = 25, ratio = 0.25},
            {gameMinutes = 20, ratio = 0.20},
            {gameMinutes = 15, ratio = 0.15},
            {gameMinutes = 10, ratio = 0.10},
            {gameMinutes = 6,  ratio = 0.00},
            {gameMinutes = 3,  ratio = 0.00},
            {gameMinutes = 0,  ratio = 0.00}
        }
    end
    local alloyIncome = Armies[platoon.army.id].economy.totals.alloys.income * 10
    local gameTime = GetGameTimeSeconds() / 60
    local ratio = 0.50
    if Armies[platoon.army.id].HasParagon or alloyIncome > 1000 then
        ratio = 0.90
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanGetEcoUpgradeRatio():[A:"..platoon.army.id.."][P:"..platoon.id.."] Paragon active or Alloy > 1000. Eco running with "..(ratio*100).."%")
        end
    elseif alloyIncome > 600 then
        ratio = 0.50
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanGetEcoUpgradeRatio():[A:"..platoon.army.id.."][P:"..platoon.id.."] Alloy > 600. Eco running with "..(ratio*100).."%")
        end
    else
        for _, data in ipairs(RatioTable) do
            if gameTime > data.gameMinutes then
                ratio = data.ratio
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetEcoUpgradeRatio():[A:"..platoon.army.id.."][P:"..platoon.id.."] Gametime > "..data.gameMinutes.." Min. Eco running with "..(ratio*100).."%")
                end
                return ratio
            end
        end
    end
    return ratio
end

---On Hard, prefer the nearest home extractors while keeping army-wide upgrade fallbacks.
---@param platoon table Extractor upgrade platoon
---@return table candidates Own completed extractors eligible for the current home-upgrade phase
---@return boolean prioritizeHome Whether the base-first policy is active
function GetExtractorUpgradeCandidates(platoon)
    if RushBalance.Enabled(platoon.army) and platoon.army.ai.settings.difficulty=="hard" then
        return RushBalance.HomeUpgradeCandidates(platoon.army,platoon:GetUnits()),true
    end
    local formerTable = platoon.ai.formerTable
    if not formerTable.PrioritizeHomeExtractorUpgrades or Armies[platoon.army.id].ai.settings.difficulty ~= "hard" then
        return platoon:GetUnits(), false
    end
    local baseExtractors, homeExtractors = {}, {}
    local basePosition = platoon.ai.basePosition
    local baseRadiusSquared = platoon.ai.baseRadius * platoon.ai.baseRadius
    for _, extractor in pairs(platoon:GetUnits()) do
        if IsValidPlatoonUnit(extractor) and extractor.army.id == platoon.army.id and extractor:IsCompleted() then
            local extractorPosition = extractor:GetPosition()
            extractor.rangeToBase = Distance2DSquared(extractorPosition.x, extractorPosition.z, basePosition.x, basePosition.z)
            if extractor.rangeToBase <= baseRadiusSquared then table.insert(baseExtractors, extractor) end
        end
    end
    table.sort(baseExtractors, function(firstExtractor, secondExtractor)
        if firstExtractor.rangeToBase == secondExtractor.rangeToBase then return firstExtractor.id.index < secondExtractor.id.index end
        return firstExtractor.rangeToBase < secondExtractor.rangeToBase
    end)
    local homeUpgradePending = false
    for _, extractor in ipairs(baseExtractors) do
        if #homeExtractors >= formerTable.HomeExtractorUpgradeCount then break end
        table.insert(homeExtractors, extractor)
        if extractor.tp.hasTags.TECH1 or extractor.tp.hasTags.TECH2 then homeUpgradePending = true end
    end
    return homeUpgradePending and homeExtractors or baseExtractors, true
end

-- Check and submission use the same exact-unit policy. On hard difficulty,
-- HomeUpgradeCandidates supplies the ordered home phases and affordable fallback.
local function RushExtractorCandidate(platoon,techLevel,force)
    local army=platoon.army
    local snapshot=RushBalance.CurrentSnapshot(army,force)
    if not snapshot then return nil end
    local policy=Import("AI/mods/AI-Scom/RushEconomyPolicy.lua")
    local candidates=GetExtractorUpgradeCandidates(platoon)
    local ordered=army.ai.settings.difficulty=="hard"
    local selected,selectedId,nearest
    for _,unit in ipairs(candidates or {}) do
        if unit.platoon==platoon and RushExtractorAvailable(platoon,unit)
            and (not techLevel or unit:HasTags(Tags[techLevel]))
            and (RushBalance.Tier(unit.tp)==1 or platoon.ai.formerTable.MaximumExtractorUpgradeTechnologyLevel~=1) then
            local allowed,id=policy.CanUpgradeExtractor(unit,snapshot)
            id=id or type(unit.GetUpgradeTpId)=="function" and unit:GetUpgradeTpId()
            if allowed and id then
                if ordered then return unit,id end
                local p=unit:GetPosition();local center=platoon.ai.basePosition
                local distance=Distance2DSquared(p.x,p.z,center.x,center.z)
                if not nearest or distance<nearest or distance==nearest and unit.id.index<selected.id.index then
                    selected,selectedId,nearest=unit,id,distance
                end
            end
        end
    end
    return selected,selectedId
end

---Sub function to check if we need to upgrade an extractor
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return string Returns the next executeState for the builder
function subPlanCheckForExtractorUpgrade(platoon)
    if RushBalance.Enabled(platoon.army) then
        local extractor=RushExtractorCandidate(platoon,nil,false)
        return extractor and "Upgrade TECH"..RushBalance.Tier(extractor.tp) or "Check For Upgrade"
    end
    -- check if we have a minimum of 4 extractors and no extractor is upgrading
    local hasFreeTech1 = false
    local hasFreeTech2 = false
    local isUpgrading = false
    local hasTech1Candidate = false
    local useExtractor, prioritizeHome = GetExtractorUpgradeCandidates(platoon)
    for _, extractor in pairs(platoon:GetUnits()) do
        if IsValidPlatoonUnit(extractor) and extractor.upgradeTarget then isUpgrading = true end
    end
    for _, extractor in pairs(useExtractor) do
        if IsValidPlatoonUnit(extractor) then
            if extractor.tp.hasTags.TECH1 then
                hasTech1Candidate = true
                if extractor.upgradeTarget then
                    isUpgrading = true
                elseif not prioritizeHome or not AIFunctions.IsUnderAttack(extractor) then
                    hasFreeTech1 = true
                end
            elseif extractor.tp.hasTags.TECH2 and platoon.ai.formerTable.MaximumExtractorUpgradeTechnologyLevel ~= 1 then
                if extractor.upgradeTarget then
                    isUpgrading = true
                elseif not prioritizeHome or not AIFunctions.IsUnderAttack(extractor) then
                    hasFreeTech2 = true
                end
            end
        end
    end
    -- Recheck the former's ECO limits before every new upgrade because this platoon persists across all extractors.
    if not isUpgrading then
        local minimumTrend = platoon.ai.formerTable.ExtractorUpgradeMinimumTrend
        if minimumTrend and not AIFunctions.MoreThanEcoTrend(platoon.army.id, platoon.ai.baseName, minimumTrend[1], minimumTrend[2]) then
            return "Check For Upgrade"
        end
        local minimumStorageLevel = platoon.ai.formerTable.ExtractorUpgradeMinimumStorageLevel
        if minimumStorageLevel and not AIFunctions.MoreThanEcoStorageLevel(platoon.army.id, platoon.ai.baseName, minimumStorageLevel[1], minimumStorageLevel[2]) then
            return "Check For Upgrade"
        end
    end
    -- do we have captured 75% of "our" alloy spots? (our = all spots divided by player)
    if not isUpgrading and AIFunctions.MoreThanAlloyExtractorFairSharePercent(platoon.army.id, 75) then
        if hasFreeTech1 then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanCheckForExtractorUpgrade():[A:"..platoon.army.id.."][P:"..platoon.id.."] Extractor >= 75% fair share -> Force Upgrade TECH1.")
            end
            return "Upgrade TECH1"
        end
    end
    -- Upgrade if we have more than 20 allyo income
    if not isUpgrading and Armies[platoon.army.id].economy.totals.alloys.income * 10 >= 20 then
        if hasFreeTech1 then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanCheckForExtractorUpgrade():[A:"..platoon.army.id.."][P:"..platoon.id.."] AlloyIncome="..(Armies[platoon.army.id].economy.totals.alloys.income * 10).." >= 20 -> Force Upgrade TECH1.")
            end
            return "Upgrade TECH1"
        end
    end
    -- Check if we we are under the eco ratio for upgrades
    if not IsGlobalAlloyIncomeGreaterThanAlloyUpgradeCostRatio(platoon) then
        return "Check For Upgrade"
    end
    -- If we have only 20% TECH1 extractors left (and 80% TECH2), then upgrade TECH2 to TECH3
    -- Base-first upgrades must not wait for distant expansion extractors to reach Tech 2.
    local technologyThreeReady = prioritizeHome and not hasTech1Candidate or not prioritizeHome and AIFunctions.UnitRatio(platoon.army.id, nil, 0.25, Tags.ALLOYS_EXTRACTION * Tags.TECH1, '<=', Tags.ALLOYS_EXTRACTION * Tags.TECH2)
    if not AIFunctions.IsStrategyActive(platoon.army.id, platoon.ai.baseName, "EnemyInLandPanicZone") and hasFreeTech2 and technologyThreeReady then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanCheckForExtractorUpgrade():[A:"..platoon.army.id.."][P:"..platoon.id.."] Tech 3 candidate ready. Base-first policy: "..tostring(prioritizeHome))
        end
        if HaveEcoForExtractorUpgrade(platoon, "TECH2") then
            return "Upgrade TECH2"
        end
    end
    -- Try to upgrade more TECH1
    if hasFreeTech1 and HaveEcoForExtractorUpgrade(platoon, "TECH1") then
        return "Upgrade TECH1"
    end
    -- Check if we have TECH1 or TECH2 extractors for upgrade
    if not hasFreeTech1 and not hasFreeTech2 then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanCheckForExtractorUpgrade():[A:"..platoon.army.id.."][P:"..platoon.id.."] no TECH1 or TECH2 extractor left for upgrade; keep monitoring extractors.")
        end
        return "Check For Upgrade"
    end
    -- We can't upgrade (no eco or all units are already upgrading)
    return "Check For Upgrade"
end

---Check if we have more alloy income than alloy upgrade cost ratio
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return boolean Returns true if we have more alloy income than alloy upgrade cost ratio
function IsGlobalAlloyIncomeGreaterThanAlloyUpgradeCostRatio(platoon)
    -- get ratio for alloy upgrade
    local ratio = platoon.ai.ecoUpgradeRatio
    --get global alloy upgrade cost
    local globalAlloyUpgradeCost = GetGlobalAlloyUpgradeCost(platoon)
    --get army alloy income
    local gobalAlloyIncome = Armies[platoon.army.id].economy.totals.alloys.income * 10
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn IsGlobalAlloyIncomeGreaterThanAlloyUpgradeCostRatio():globalAlloyUpgradeCost / gobalAlloyIncome > Ratio: ("..globalAlloyUpgradeCost..") / ("..gobalAlloyIncome..") = ("..(globalAlloyUpgradeCost / gobalAlloyIncome).."%) <= ("..ratio.."%) - "..repr(globalAlloyUpgradeCost / gobalAlloyIncome <= ratio))
    end
    return globalAlloyUpgradeCost / gobalAlloyIncome <= ratio
end

---Calculate the cost of all active upgrading alloy extractors
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return boolean Returns true if we have more alloy income than alloy upgrade cost ratio
function GetGlobalAlloyUpgradeCost(platoon)
    local globalAlloyUpgradeCost = 0
    --loop over platoon units and check for upgrading units
    for _, unit in pairs(platoon:GetUnits()) do
        if not IsValidPlatoonUnit(unit) then
            AILog("- WARNING: Fn GetGlobalAlloyUpgradeCost():[A:"..unit.army.id.."][U:"..unit.id.index.."] unit is not a valid platoon unit!")
        --Is the unit upgrading?
        elseif unit.upgradeTarget then
--            Engine.DrawCircle( unit:GetPosition(), 6, AIFunctions.HEXtoRGBA("FFFFFFFF") )
--            Engine.DrawCircle( unit:GetPosition(), 6.5, AIFunctions.HEXtoRGBA("FF0000FF") )
--            Engine.DrawCircle( unit:GetPosition(), 7, AIFunctions.HEXtoRGBA("FF00FFFF") )
            --add upgrading extractor to globalAlloyUpgradeCost
            local construction = unit.upgradeTarget.resourceEntities and unit.upgradeTarget.resourceEntities.construction
            local assistedAlloyCost = construction and construction.outcome and construction.outcome.alloys or 0
            -- Include active assistants without treating a paused or newly queued upgrade as free.
            globalAlloyUpgradeCost = globalAlloyUpgradeCost + math.max(GetExtractorUpgradeCost(unit.tpId), assistedAlloyCost * Constants.TickRate)
        end
    end
    return globalAlloyUpgradeCost
end

---Calculate the upgrade cost for an extractor
---@param extractorTpId string Extractor template id
---@return number Returns the alloy cost per second for an extractor upgrade
---@return number Returns the energy cost per second for an extractor upgrade
function GetExtractorUpgradeCost(extractorTpId)
    local buildpower = UnitTemplates[extractorTpId].construction.buildPower
    local upgradeToTpId = UnitTemplates[extractorTpId].construction.upgradesTo
    -- get eco for the unit we want to check
    local buildTime = UnitTemplates[upgradeToTpId].economy.buildTime / buildpower
    local energyCostPerSecond = UnitTemplates[upgradeToTpId].economy.cost.energy / buildTime
    local alloyCostPerSecond = UnitTemplates[upgradeToTpId].economy.cost.alloys / buildTime
    --AILog("* Fn GetExtractorUpgradeCost():Upgrade cost for ("..UnitTemplates[extractorTpId].general.unitTypeName..") is ("..alloyCostPerSecond..")")
    return alloyCostPerSecond, energyCostPerSecond
end

---Check if we have the eco to upgrade more extractors
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param techLevel string Tech tag used to find the extractor
---@return boolean Returns true if we have the eco to upgrade more extractors
function HaveEcoForExtractorUpgrade(platoon, techLevel)
    -- get ratio for alloy upgrade
    local ratio = platoon.ai.ecoUpgradeRatio
    --search for a tech x alloy extractor
    local extractorTpId = "ues1601"
    for _, unit in pairs(platoon:GetUnits()) do
        if not IsValidPlatoonUnit(unit) then
            AILog("- WARNING: Fn HaveEcoForExtractorUpgrade():[A:"..unit.army.id.."][U:"..unit.id.index.."] unit is not a valid platoon unit!")
        elseif unit:HasTags(Tags.STRUCTURE * Tags.ALLOYS_EXTRACTION * Tags[techLevel]) then
            extractorTpId = unit.tpId
            break
        end
    end
    --get cost for extractor
    local extractorAlloyCost, extractorEnergyCost = GetExtractorUpgradeCost(extractorTpId)
    if techLevel == "TECH2" and not AIFunctions.MoreThanEnergyTrend(platoon.army.id, platoon.ai.baseName, extractorEnergyCost) then
        return false
    end
    --get army alloy income
    local gobalAlloyIncome = Armies[platoon.army.id].economy.totals.alloys.income * 10
    --get global alloy upgrade cost
    local globalAlloyUpgradeCost = GetGlobalAlloyUpgradeCost(platoon) + extractorAlloyCost
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn HaveEcoForExtractorUpgrade():globalAlloyUpgradeCost / gobalAlloyIncome > Ratio: ("..globalAlloyUpgradeCost..") / ("..gobalAlloyIncome..") = ("..(globalAlloyUpgradeCost / gobalAlloyIncome).."%) <= ("..ratio.."%) - "..repr(globalAlloyUpgradeCost / gobalAlloyIncome <= ratio))
    end
    return globalAlloyUpgradeCost / gobalAlloyIncome <= ratio
end

---Sub function to start extractor upgrade
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param techLevel string Tech tag used to find the extractor
---@return string Returns the next e(xecute)State for the platoon
function subPlanUpgradeExtractor(platoon, techLevel)
    if RushBalance.Enabled(platoon.army) then
        -- Re-price after the state transition; another owner may have spent
        -- resources or submitted an upgrade since the candidate was selected.
        local extractor,id=RushExtractorCandidate(platoon,techLevel,true)
        if extractor and RushExtractorAvailable(platoon,extractor) and extractor.platoon==platoon
            and extractor:GetUpgradeTpId()==id then
            buildQueueUtils.AddToBuildQueue(extractor,id,buildQueueUtils.NewEntryIds(1))
        end
        return "Check For Upgrade"
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanUpgradeExtractor(): Upgrading the closest "..techLevel.." extractor")
    end
    if techLevel == "TECH2" and AIFunctions.IsStrategyActive(platoon.army.id, platoon.ai.baseName, "EnemyInLandPanicZone") then
        return "Check For Upgrade"
    end
    local useExtractor, prioritizeHome = GetExtractorUpgradeCandidates(platoon)
    local closestDist, closestExtractor
    for _, extractor in pairs(useExtractor) do
        if not IsValidPlatoonUnit(extractor) then
            AILog("- WARNING: Fn subPlanUpgradeExtractor():[A:"..extractor.army.id.."][U:"..extractor.id.index.."] unit is not a valid platoon unit!")
        elseif not closestDist or closestDist > extractor.rangeToBase then
            if not extractor.upgradeTarget and extractor:HasTags(Tags[techLevel]) and (not prioritizeHome or not AIFunctions.IsUnderAttack(extractor)) then
                closestDist = extractor.rangeToBase
                closestExtractor = extractor
            end
        end
    end
    if closestExtractor then
        local upgradeTemplateIdentifier = closestExtractor:GetUpgradeTpId()
        local _, extractorEnergyCost = GetExtractorUpgradeCost(closestExtractor.tpId)
        -- Cover the selected upgrade's energy demand and pending construction; Alloy allocation stays with the existing upgrade budget.
        if not AIFunctions.MoreThanEnergyTrend(platoon.army.id, platoon.ai.baseName, extractorEnergyCost) then
            if platoon.ai.formerTable.DebugPlatoon then AILog("* Fn subPlanUpgradeExtractor():[A:"..platoon.army.id.."][U:"..closestExtractor.id.index.."] Waiting for uncommitted Energy income.") end
            return "Check For Upgrade"
        end
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanUpgradeExtractor():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..closestExtractor.id.index.."] ["..closestExtractor.tpId.."] "..repr(closestExtractor.tp.general.unitTypeName).." is upgrading to ["..closestExtractor.tp.construction.upgradesTo.."] "..repr(UnitTemplates[closestExtractor.tp.construction.upgradesTo].general.unitTypeName).."")
        end
        buildQueueUtils.AddToBuildQueue(closestExtractor, upgradeTemplateIdentifier, buildQueueUtils.NewEntryIds(1))
        if lobbyOptionsAI.debugGameTelemetry then
            local extractorPosition = closestExtractor:GetPosition()
            AILog(" --- TacticalExtractorUpgrade [A:"..platoon.army.id.."][U:"..closestExtractor.id.index.."] Target:"..upgradeTemplateIdentifier.." Position:["..extractorPosition.x..","..extractorPosition.z.."] BaseDistance:"..math.sqrt(closestExtractor.rangeToBase).." BaseFirst:"..tostring(prioritizeHome))
        end
        if lobbyOptionsAI.debugUnitEState then
            closestExtractor.ai.orderText = "upgrading to ["..closestExtractor.tp.construction.upgradesTo.."] "..repr(UnitTemplates[closestExtractor.tp.construction.upgradesTo].general.unitTypeName)..""
        end
    end
    return "Check For Upgrade"
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------- Build New Expansion --------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing build orders to create a new expansion.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planEstablishBaseExpansion(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for platoon found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") builder ready to build, max ("..maxUnits..") are allowed.")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planEstablishBaseExpansion")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, platoon.ai.basePosition)
    -- remove unit over the max limit
    useBuilder = RemoveOverMaxBuilder(useBuilder, maxUnits)
    if #useBuilder < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for platoon found")
        end
        ExitPlatoon(platoon)
        return
    end
    -- assign units to platoon
    platoon:AssignUnits(useBuilder)
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] Set platoon movement layer to: "..platoon.ai.movementLayer)
    end
    -- get the unit we want to build
    --[[
        unitBuildList = {
            { CHOSEN="ucs1511", EDA="ues1511", GUARD="ugs1511" },
            { CHOSEN="ucs1512", EDA="ues1512", GUARD="ugs1512" },
            { CHOSEN="ucs1501", EDA="ues1001", GUARD="ugs1501" }
        }
    --]]
    -- These builders have already left the idle pool. Validate the request
    -- against the selected units instead of searching that pool a second time.
    local unitBuildList = RushReliability.SelectStructures(armyIndex, baseName, formerTable, useBuilder)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] unitBuildList:"..repr(unitBuildList))
    end
    if not unitBuildList or not unitBuildList[1] then
        AILog("- WARNING: Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] unitBuildList is empty on first index?!? Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
        ExitPlatoon(platoon)
        return
    end
    -- get position for the next expansion
    local minimumAlloy = formerTable.AIPlanData.MinimumAlloy or false
    local maximumAlloy = formerTable.AIPlanData.MaximumAlloy or false
    platoon.ai.nextBuildingtpIds = unitBuildList[1]
    platoon.ai.nextBuildingtpId, platoon.ai.constructionSpacing = getNextbuildingAndSpacing(platoon)
    platoon.ai.nextExpansionPosition, platoon.ai.expansionCenter = GetNextExpansionPosition(platoon, minimumAlloy, maximumAlloy)
    if not platoon.ai.nextExpansionPosition then
        AILog("- WARNING: Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] no place for an expansion found. Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
        ExitPlatoon(platoon)
        return
    end
    -- loop as long as we have a unit in the buildlist
    while unitBuildList[1] do
        -- select the next building we want to build
        platoon.ai.nextBuildingtpIds = table.remove(unitBuildList, 1)
        platoon.ai.nextBuildingtpId, platoon.ai.constructionSpacing = getNextbuildingAndSpacing(platoon)
        -- find a place to build (always relative to the base, not the engineer)
        platoon.ai.placeToBuild = platoon.ai.nextExpansionPosition or FindNextConstructionPosition(platoon)
        platoon.ai.nextExpansionPosition = nil
        if platoon.ai.placeToBuild then
            if formerTable.DebugPlatoon then
                AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] nextBuilding: ["..platoon.ai.nextBuildingtpId.."] ("..UnitTemplates[platoon.ai.nextBuildingtpId].general.unitTypeName..") at position:("..platoon.ai.placeToBuild.x..", "..platoon.ai.placeToBuild.z..")")
            end
        else
            AILog("- WARNING: Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] no placeToBuild found!")
            ExitPlatoon(platoon)
            return
        end
        -- main engineer loop. - Move to target and build
        while platoon.ai.placeToBuild do
            --rebuild unit table, maybe we lost some in battle
            useBuilder = platoon:GetUnits()
            -- save range to buildplace to all engineers
            for i, builder in pairs(useBuilder) do
                builder.ai.rangeToBuildLocation = Distance2DSquared( builder:GetPosition().x,  builder:GetPosition().z, platoon.ai.placeToBuild.x, platoon.ai.placeToBuild.z )
            end
            -- sort builder by range, closest first
            table.sort(useBuilder, SortBuilderUnitsAscendingByRangeToBuildLocationValue)
            local transition=false
            -- loop over units and assign tasks
            for i, builder in pairs(useBuilder) do
                local beforeState=builder.ai.eState
                if formerTable.DebugPlatoon then
                    AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..".")
                end
                if not IsValidPlatoonUnit(builder) then
                    AILog("- WARNING: Fn planEstablishBaseExpansion():[A:"..builder.army.id.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
                elseif not platoon.ai.placeToBuild then
                    if formerTable.DebugPlatoon then
                        AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] placeToBuild = nil.")
                    end
                    break
                elseif not builder.ai.eState then
                    builder.ai.eState = subPlanSetConstructionArea(builder)
                elseif builder.ai.eState == "StartMoveToDestination" then
                    builder.ai.eState = subPlanStartMoveToDestination(builder, nil) -- do not reserve eco here
                elseif builder.ai.eState == "MovingToDestination" then
                    builder.ai.eState = subPlanMovingToDestination(builder, platoon.ai.placeToBuild, builder.ai.buildRange)
                    builder.ai.eState = subPlanDisbandOnFinishedUnit(builder)
                elseif builder.ai.eState == "MovingDestinationReached" then
                    if AIFunctions.IsStrategyActive(armyIndex, baseName, "EnemyInLandPanicZone")
                        or AIFunctions.IsStrategyActive(armyIndex, baseName, "EnemyInAirPanicZone")
                        or AIFunctions.IsStrategyActive(armyIndex, baseName, "EnemyInNavalPanicZone")
                    then
                        ExitPlatoon(platoon)
                        return
                    end
                    -- Time to reassign the builders to their new home
                    UnassignPlatoonUnitsFromOldBase(platoon)
                    builder.ai.eState = subPlanStartToBuild(builder)
                elseif builder.ai.eState == "Building" then
                    builder.ai.eState = subPlanBuilding(builder)
                elseif builder.ai.eState == "Assisting" then
                    builder.ai.eState = subPlanBuildingAssist(builder)
                elseif builder.ai.eState == "Finishing" then
                    builder.ai.eState = subPlanFinishing(builder)
                elseif builder.ai.eState == "Finished" then
                    builder.ai.eState = subPlanFinished(builder)
                elseif builder.ai.eState == "Disband" then
                    if lobbyOptionsAI.debugUnitEState then
                        builder.ai.orderText = "disband from build platoon"
                    end
                    ClearUnitTemporaryPlatoonData(builder, "planEstablishBaseExpansion")
                    platoon:RemoveUnits(UnitAsArray(builder))
                else
                    AILog("- WARNING: Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
                end
                if builder.platoon==platoon and builder.ai.eState~=beforeState then transition=true end
                if platoon:GetNumOfUnits() < 1 then
                    if formerTable.DebugPlatoon then
                        AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
                    end
                    ExitPlatoon(platoon)
                end
            end
            WaitTicks(transition and 1 or 10)
        end
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planEstablishBaseExpansion():[A:"..armyIndex.."][P:"..platoon.id.."] Disbanding... Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planEstablishBaseExpansion")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planEstablishBaseExpansion platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Get the position of the next free expansion area
---@param platoon Platoon Platoon instance
---@param minAlloy any Minimum alloy requirement or nil
---@param maxAlloy any Maximum alloy requirement or nil
---@return any Position formatted as {x=0,y=0,z=0} or nil if no valid expansion found
function GetNextExpansionPosition(platoon, minAlloy, maxAlloy)
    local searchRadiusInner = 100
    local searchRadiusOuter = 500
    local maximumEnemyThreat = math.huge
    if platoon.ai.formerTable.AIPlanData then
        searchRadiusInner = platoon.ai.formerTable.AIPlanData.SearchInnerRing
        searchRadiusOuter = platoon.ai.formerTable.AIPlanData.SearchOuterRing
        maximumEnemyThreat = platoon.ai.formerTable.AIPlanData.MaximumEnemyThreat or maximumEnemyThreat
    else
        AILog("- WARNING: Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] Former "..platoon.ai.formerTable.FormerName.." missing AIPlanData!")
    end
    local searchRadiusInnerSquared = searchRadiusInner * searchRadiusInner
    local searchRadiusOuterSquared = searchRadiusOuter * searchRadiusOuter
    local Distance2D = Distance2D
    local Distance2DSquared = Distance2DSquared
    local basePosition = platoon.ai.basePosition
    local baseDistanceSquared
    local pathDistance
    local bestPathDistance
    local lastNodePosition
    local pathNodes
    local pathInfo
    local placeToBuild
    local selectedExpansionCenter
    local platoonPosition = platoon:GetPosition()
    for markerIndex, expansionData in pairs(AIMarkerGenerator.GetLandExpansions()) do
        if (not minAlloy or expansionData.AlloyInRange >= minAlloy) and (not maxAlloy or expansionData.AlloyInRange <= maxAlloy) then
            baseDistanceSquared = Distance2DSquared(basePosition.x, basePosition.z, expansionData.x, expansionData.z)
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] checking expansion ("..markerIndex..") at ("..repr(expansionData)..") baseDistance")
            end
            local expansionThreat = AITargetManager.GetThreatFromHeatMapPosition(platoon.army.id, expansionData, "Hover")
            if baseDistanceSquared >= searchRadiusInnerSquared
                and baseDistanceSquared <= searchRadiusOuterSquared
                and expansionThreat <= maximumEnemyThreat
                and AIFunctions.WouldCreateNewLandBase(platoon.army.id, expansionData)
            then
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] expansion inside base search radius")
                end
                pathNodes, pathInfo = AIMarkerGenerator.GeneratePathTo(platoon.army.id, platoonPosition, expansionData, platoon.ai.movementLayer, true, CalculatePlatoonThreat(platoon))
                if pathNodes then
                    pathNodes = AIMarkerGenerator.StraightenPath(pathNodes)
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] path found, nodeCount:"..table.getn(pathNodes))
                    end
                    pathDistance = 0
                    lastNodePosition = platoonPosition
                    for nodeIndex, nodePosition in ipairs(pathNodes) do
                        local segmentDistance = Distance2D(lastNodePosition.x, lastNodePosition.z, nodePosition.x, nodePosition.z)
                        pathDistance = pathDistance + segmentDistance
                        lastNodePosition = nodePosition
                    end
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] total pathDistance:"..pathDistance.." currentBest:"..repr(bestPathDistance))
                    end
                    if not bestPathDistance or bestPathDistance > pathDistance then
                        if platoon.ai.formerTable.DebugPlatoon then
                            AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] path is better -> checking factories")
                        end
                        local factoryCount = AIFunctions.GetNumTeamUnitsAroundPosition(platoon.army.id, expansionData, 30, Tags.STRUCTURE * Tags.FACTORY, false)
                        if platoon.ai.formerTable.DebugPlatoon then
                            AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] factoryCountAtExpansion:"..factoryCount)
                        end
                        if factoryCount <= 0 then
                            local enemyCount = AIFunctions.GetNumEnemyUnitsAroundPosition(platoon.army.id, expansionData, 30, Tags.ALL_UNITS, false)
                            if platoon.ai.formerTable.DebugPlatoon then
                                AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] enemyCountAtExpansion:"..enemyCount)
                            end
                            if enemyCount <= 0 then
                                local candidateBuildPosition = FindExpansionConstructionPosition(platoon, expansionData)
                                if candidateBuildPosition and AIFunctions.WouldCreateNewLandBase(platoon.army.id, candidateBuildPosition) then
                                    if platoon.ai.formerTable.DebugPlatoon then
                                        AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] expansion SELECTED newBestPathDistance:"..pathDistance)
                                    end
                                    bestPathDistance = pathDistance
                                    placeToBuild = candidateBuildPosition
                                    selectedExpansionCenter = expansionData
                                else
                                    if platoon.ai.formerTable.DebugPlatoon then
                                        AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] rejected: no valid build position found")
                                    end
                                end
                            else
                                if platoon.ai.formerTable.DebugPlatoon then
                                    AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] rejected: enemy units present")
                                end
                            end
                        else
                            if platoon.ai.formerTable.DebugPlatoon then
                                AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] rejected: factories already present")
                            end
                        end
                    else
                        if platoon.ai.formerTable.DebugPlatoon then
                            AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] rejected: path not better than currentBest")
                        end
                    end
                else
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] no path to expansion found")
                    end
                end
            else
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] expansion outside search radius ("..searchRadiusInner.."-"..searchRadiusOuter..") or assigned to an existing base")
                end
            end
        end
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn GetNextExpansionPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] FINAL selected pathDistance:"..repr(bestPathDistance).." buildPosition:"..repr(placeToBuild))
    end
    return placeToBuild, selectedExpansionCenter
end

---Clear the base assignment for all enginers inside the platoon (They will be reassigned to the new base)
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return nil
function UnassignPlatoonUnitsFromOldBase(platoon)
    for i, unit in pairs(platoon:GetUnits()) do
        if IsValidPlatoonUnit(unit) then
            AIFunctions.SetUnitBaseAssignment(platoon.army.id, unit, nil)
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn UnassignPlatoonUnitsFromOldBase():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..unit.id.index.."] removing base assignment from unit")
            end
        end
    end
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
------------------------------------------- Transfer engineers from expansion to main base -------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Moving engineers from location back to main base
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planEngineerTransfer(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerTransfer():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    -- disband the platoon if we don't have any units for it
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planEngineerTransfer():[A:"..armyIndex.."][P:"..platoon.id.."] No engineer to transfer found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planEngineerTransfer():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to transfer")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planEngineerTransfer")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    if #useBuilder < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planEngineerTransfer():[A:"..armyIndex.."][P:"..platoon.id.."] No engineer to transfer found")
        end
        ExitPlatoon(platoon)
        return
    end
    -- remove unit over the max limit
    useBuilder = RemoveOverMaxBuilder(useBuilder, maxUnits)
    -- assign units to this platton
    platoon:AssignUnits(useBuilder)
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    -- move engineers to the new base
    local path, info, basePosition
    while Armies[armyIndex]:PlatoonExists(platoon) do
        for i, unit in pairs(platoon:GetUnits()) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planEngineerTransfer():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..unit.id.index.."] [eState] = "..repr(unit.ai.eState)..".")
            end
            if not IsValidPlatoonUnit(unit) then
                AILog("- WARNING: Fn planEngineerTransfer():[A:"..unit.army.id.."][U:"..unit.id.index.."] unit is not a valid platoon unit!")
            elseif not unit.ai.eState then
                unit.ai.eState = subPlanSetMainAsDestination(unit)
            elseif unit.ai.eState == "StartMoveToDestination" then
                unit.ai.eState = subPlanStartMoveToDestination(unit, nil) -- do not reserve eco here
            elseif unit.ai.eState == "MovingToDestination" then
                unit.ai.eState = subPlanMovingToDestination(unit, unit.destination, 60)
            elseif unit.ai.eState == "MovingDestinationCanceled" then
                unit.ai.eState = "Disband"
            elseif unit.ai.eState == "MovingDestinationReached" then
                unit.ai.eState = subPlanUnassignUnitFromBase(unit)
            elseif unit.ai.eState == "Disband" then
                if lobbyOptionsAI.debugUnitEState then
                    unit.ai.orderText = "disband from build platoon"
                end
                ClearUnitTemporaryPlatoonData(unit, "planAssistBuilding")
                platoon:RemoveUnits(UnitAsArray(unit))
            else
                AILog("- WARNING: Fn planEngineerTransfer():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..unit.id.index.."] unknown unit eState ??? ["..repr(unit.ai.eState).."]")
            end
        end
        if platoon:GetNumOfUnits() < 1 then
            if formerTable.DebugPlatoon then
                AILog("* Fn planEngineerTransfer():[A:"..armyIndex.."][P:"..platoon.id.."] no engineer left in platoon, exiting function")
            end
            break
        end
        WaitTicks(10)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planEngineerTransfer")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planEngineerTransfer platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Sub function to set the path from the expansion to the main base
---@param unit table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the unit
function subPlanSetMainAsDestination(unit)
    local basePosition = RushReliability.MainBasePosition(unit.army.id)
    if basePosition then
        local path, info = AIMarkerGenerator.GeneratePathTo(unit.army.id, unit:GetPosition(), basePosition, unit.platoon.ai.movementLayer, true)
        if path then
            unit.ai.path = path
            unit.ai.lastPosition = false
            unit.ai.highestDist = false
            unit.destination = basePosition
            return "StartMoveToDestination"
        end
    end
    if unit.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanSetMainAsDestination():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] no path to destination (need transport), Disbanding")
    end
    return "Disband"
end

---Sub function to unassign units from (old) base
---@param unit table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the unit
function subPlanUnassignUnitFromBase(unit)
    if lobbyOptionsAI.debugUnitEState then
        unit.ai.orderText = "Unassigned from base "..repr(unit.assignedToBase)
    end
    ClearUnitTemporaryPlatoonData(unit, "planEngineerTransfer")
    --assing unit to the new base
    AIFunctions.SetUnitBaseAssignment(unit.army.id, unit, nil)
    return "Disband"
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------------- Assist Buildings ----------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Releases optional upgrade assistance when committed construction needs its resources or the base is threatened.
---@param armyIndex integer Army index
---@param baseName string Base name
---@return string|nil Reason to release the assisting engineer
function GetExtractorAssistStopReason(armyIndex, baseName)
    if AIFunctions.IsStrategyActive(armyIndex, baseName, "EnemyInLandPanicZone") then return "Base under attack." end
    local army = Armies[armyIndex]
    local alloyTrend = army.economy.totals.alloys.balance
    local energyTrend = army.economy.totals.energy.balance
    for _, reservation in pairs(army.ai.ecoReserve) do
        alloyTrend = alloyTrend - (reservation.resourcePerSecond or 0)
        energyTrend = energyTrend - (reservation.energyPerSecond or 0)
    end
    if alloyTrend < 0 then return "Alloy needed by other construction." end
    if energyTrend < 0 then return "Energy needed by other construction." end
end

---Budget optional assistants together, including workers still approaching.
---Uses the current vanilla recruitment policy with Scom's reservation accounting.
function GetAffordableBuildAssistEngineers(platoon, engineers, maximumCount)
    local formerTable = platoon.ai.formerTable
    if (formerTable.AllowEcoStorageDrain and not formerTable.MaintainAssistSurplus)
        or not (formerTable.AssistBuildUnits or formerTable.AssistUpgradeUnits) then return engineers end
    if maximumCount <= 0 then return {} end
    local army = platoon.army
    local possibleUnits
    if formerTable.AssistBuildUnits then
        possibleUnits = AIFunctions.GetUnitsThatDesiresBuildAssistAtBase(army.id, platoon.ai.baseName, formerTable)
    else
        possibleUnits = AIFunctions.GetUnitsThatDesiresUpgradeAssistAtBase(army.id, platoon.ai.baseName, formerTable)
    end
    if not possibleUnits or #possibleUnits == 0 then return {} end
    local alloyCostPerBuildPower, energyCostPerBuildPower = 0, 0
    for _, targetUnit in ipairs(possibleUnits) do
        local economy = UnitTemplates[targetUnit.tpId].economy
        alloyCostPerBuildPower = math.max(alloyCostPerBuildPower, economy.cost.alloys / economy.buildTime)
        energyCostPerBuildPower = math.max(energyCostPerBuildPower, economy.cost.energy / economy.buildTime)
    end
    local alloys, energy = RushBalance.Resources(army)
    if not alloys or not energy then return {} end
    local availableAlloy, availableEnergy = RushBalance.Balance(alloys), RushBalance.Balance(energy)
    -- Active workers and approach reservations already consume this budget.
    -- Count assigned workers that have not reached either accounting boundary.
    for _, engineer in pairs(platoon:GetUnits()) do
        local target = engineer.unitBeingAssist
        local construction = target and target.resourceEntities and target.resourceEntities.construction
        local registered = construction and construction.buildPowerSources and construction.buildPowerSources[engineer.id]
        if not engineer.dead and not engineer.ai.reservedEco and not registered then
            local buildPower = engineer.construction.buildPower
            availableAlloy = availableAlloy - alloyCostPerBuildPower * buildPower
            availableEnergy = availableEnergy - energyCostPerBuildPower * buildPower
        end
    end
    local affordableEngineers = {}
    for _, engineer in ipairs(engineers) do
        local buildPower = engineer.construction.buildPower
        local alloyCost, energyCost = alloyCostPerBuildPower * buildPower, energyCostPerBuildPower * buildPower
        if availableAlloy >= alloyCost and availableEnergy >= energyCost then
            affordableEngineers[#affordableEngineers + 1] = engineer
            availableAlloy = availableAlloy - alloyCost
            availableEnergy = availableEnergy - energyCost
            if #affordableEngineers >= maximumCount then break end
        end
    end
    return affordableEngineers
end

---Executing Assist orders for engineers. Get unused engineers, move the engineer to a build/upgrade unit and assist.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planAssistBuilding(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    local minimumAlloyStorageLevelForAssist = formerTable.MinimumAlloyStorageLevelForAssist
    local minimumAlloyTrendForAssist = formerTable.MinimumAlloyTrendForAssist
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    -- disband the platoon if we don't have any units for it
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for assist found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to assist")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planAssistBuilding")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    useBuilder = GetAffordableBuildAssistEngineers(platoon, useBuilder, maxUnits)
    if #useBuilder < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for assist found")
        end
        ExitPlatoon(platoon)
        return
    end
    -- disband the platoon if we don't have any units for it
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No builder left for platoon")
        end
        ExitPlatoon(platoon)
        return
    end
    -- assign units to this platton
    platoon:AssignUnits(useBuilder)
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Set platoon movement layer to: "..platoon.ai.movementLayer)
    end
    -- find a unit that needs assist
    local possibleUnits
    if formerTable.AssistBuildUnits then
        possibleUnits = AIFunctions.GetUnitsThatDesiresBuildAssistAtBase(armyIndex, baseName, formerTable)
    elseif formerTable.AssistUpgradeUnits then
        possibleUnits = AIFunctions.GetUnitsThatDesiresUpgradeAssistAtBase(armyIndex, baseName, formerTable)
    else
        AILog("- WARNING: Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] no formerTable.AssistUnits* found!!!")
    end
    if not possibleUnits then
        if formerTable.DebugPlatoon then
            AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No units that needs assist found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#possibleUnits..") units need assisting")
    end
    -- filter possibleUnits list by eco and add assister count
    possibleUnits = SetAssister(platoon, useBuilder, possibleUnits)
    if not possibleUnits then
        if formerTable.DebugPlatoon then
            AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No units left after assister filter")
        end
        ExitPlatoon(platoon)
        return
    end
    -- calculate average distance between unit that needs assist and engineers
    useBuilder = SetAssistRange(useBuilder, possibleUnits)
    -- remove over max builder based on assist range
    RemoveOverMaxBuilderFromPlatoonByAssistRange(platoon, useBuilder, maxUnits)
    -- main loop
    while Armies[armyIndex]:PlatoonExists(platoon) do
        for possibleUnitIndex = #possibleUnits, 1, -1 do
            local possibleUnit = possibleUnits[possibleUnitIndex]
            if possibleUnit.dead or (possibleUnit:IsCompleted() and not possibleUnit.upgradeTarget) then
                table.remove(possibleUnits, possibleUnitIndex)
            end
        end
        if not possibleUnits[1] then
            for _, builder in pairs(platoon:GetUnits()) do
                HostClearOrder(UnitAsArray(builder))
                builder.unitBeingAssist = nil
                if builder.ai.reservedEco then
                    builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
                    AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
                end
            end
            ExitPlatoon(platoon)
            return
        end
        local assistStopReason
        if minimumAlloyStorageLevelForAssist and not AIFunctions.MoreThanEcoStorageLevel(armyIndex, baseName, minimumAlloyStorageLevelForAssist, 0) then
            assistStopReason = "Alloy storage below ("..minimumAlloyStorageLevelForAssist.."%)."
        elseif minimumAlloyTrendForAssist and Armies[armyIndex].economy.totals.alloys.balance < minimumAlloyTrendForAssist then
            assistStopReason = "Alloy trend below ("..minimumAlloyTrendForAssist..")."
        elseif formerTable.MaintainAssistSurplus then
            assistStopReason = GetExtractorAssistStopReason(armyIndex, baseName)
        end
        if assistStopReason then
            if formerTable.DebugPlatoon then
                AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] "..assistStopReason.." Disband assist platoon.")
            end
            for _, builder in pairs(platoon:GetUnits()) do
                HostClearOrder(UnitAsArray(builder))
                builder.unitBeingAssist = nil
                if builder.ai.reservedEco then
                    builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
                    AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
                end
            end
            ExitPlatoon(platoon)
            return
        end
        -- Add newly available builders until the configured maximum is reached.
        subPlanGetMoreBuilders(platoon, maxUnits)
        useBuilder = platoon:GetUnits()
        if ASSISTDEBUGDRAW and armyIndex == GetFocusArmy() then
            for i, builder in pairs(useBuilder) do
                if not builder.ai.engineerAssistDebugThread then
                    builder.ai.engineerAssistDebugThread = NewThread(EngineerAssistDebugThread, builder)
                end
            end
        end
        for i, builder in pairs(platoon:GetUnits()) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..".")
            end
            if builder.unitBeingAssist and builder.unitBeingAssist.dead then
                if builder.ai.reservedEco then
                    builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
                    AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
                end
                builder.ai.eState = nil
            end
            if not IsValidPlatoonUnit(builder) then
                AILog("- WARNING: Fn planAssistBuilding():[A:"..builder.army.id.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
            elseif not builder.ai.eState then
                if RushHeavyPolicy.Enabled(builder.army) then
                    RushReliability.ApplyBuilderStep(builder, platoon, subPlanSetAssistTarget, possibleUnits)
                else builder.ai.eState = subPlanSetAssistTarget(builder, possibleUnits) end
            elseif builder.ai.eState == "StartMoveToDestination" then
                builder.ai.eState = subPlanStartMoveToDestination(builder, builder.unitBeingAssist:GetPosition(), builder.unitBeingAssist.tpId)
            elseif builder.ai.eState == "MovingToDestination" then
                builder.ai.eState = subPlanMovingToDestination(builder, builder.unitBeingAssist:GetPosition(), builder.ai.buildRange)
                builder.ai.eState = subPlanDisbandOnFinishedUnit(builder)
            elseif builder.ai.eState == "MovingDestinationCanceled" then
                --ToDo: check if we can use subPlanDisbandOnFinishedUnit here
                builder.ai.eState = subDisbandBuilderWithFinishedUnitBeingAssist(builder)
            elseif builder.ai.eState == "MovingDestinationReached" then
                builder.ai.eState = subPlanStartToAssist(builder)
            elseif builder.ai.eState == "Assisting" then
                if not formerTable.AllowEcoStorageDrain and (AIFunctions.IsStrategyActive(armyIndex,baseName,"EnemyInLandPanicZone")
                    or not RushBalance.AssistAffordable(builder,builder.unitBeingAssist,true)) then
                    HostClearOrder(UnitAsArray(builder));builder.unitBeingAssist=nil;builder.ai.eState="Disband"
                else builder.ai.eState = subPlanBuildingAssist(builder) end
            elseif builder.ai.eState == "Finishing" then
                builder.ai.eState = subDisbandBuilderWithFinishedUnitBeingAssist(builder)
            elseif builder.ai.eState == "Disband" then
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "disband from build platoon"
                end
                ClearUnitTemporaryPlatoonData(builder, "planAssistBuilding")
                platoon:RemoveUnits(UnitAsArray(builder))
            else
                AILog("- WARNING: Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
            end
            if platoon:GetNumOfUnits() < 1 then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planAssistBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
                end
                ExitPlatoon(platoon)
            end
        end
        WaitTicks(10)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planAssistBuilding")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planAssistBuilding platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Draw debug markers for engineer assist behavior.
---@param builder table Unit class table. Contains functions and data for a unit
---@return nil
function EngineerAssistDebugThread(builder)
    local builderPosition
    local assistPosition
    while builder.platoon and not builder.dead do
        if not builder.platoon or not builder.platoon.ai then
            break
        end
        builderPosition = builder:GetPosition()
        if builder.unitBeingAssist and not builder.unitBeingAssist.dead then
            assistPosition = builder.unitBeingAssist:GetPosition()
            Engine.DrawCircle(SnapToGround(assistPosition), 1, AIFunctions.HEXtoRGBA("FF000000"))
            Engine.DrawArrow(builderPosition, assistPosition, AIFunctions.HEXtoRGBA("FFFFA500"))
        end
        if builder.ai.eState == "StartMoveToDestination" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FF00FFFF"))
        elseif builder.ai.eState == "MovingToDestination" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FF40FF4F"))
        elseif builder.ai.eState == "MovingDestinationCanceled" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FFFF0000"))
        elseif builder.ai.eState == "MovingDestinationReached" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FFFFFF00"))
        elseif builder.ai.eState == "Assisting" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FFFFA500"))
        elseif builder.ai.eState == "Finishing" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FFFF40FF"))
        elseif builder.ai.eState == "Disband" then
            Engine.DrawCircle(builderPosition, 0.5, AIFunctions.HEXtoRGBA("FF000000"))
        end
        WaitTicks(1)
    end
    builder.ai.engineerAssistDebugThread = nil
end

---Filter possibleUnits list by eco and add assister count
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param builders table Builder units used for eco drain checks
---@param possibleUnits table units that need assist for build, upgrade or repair
---@return table|nil Returns filtered possibleUnits list
function SetAssister(platoon, builders, possibleUnits)
    for i, unitNeedAssist in pairs(possibleUnits) do
        -- check if we have the needed eco to build this
        if platoon.ai.formerTable.AllowEcoStorageDrain or RushBalance.AssistAffordable(builders[1],unitNeedAssist,false) then
            -- get num assister
            if (not unitNeedAssist:IsCompleted() or unitNeedAssist.upgradeTarget) then
                -- save numbers of assister to the unit
                unitNeedAssist.assister = AIFunctions.GetNumAssistersAndBuilders(platoon.army.id, unitNeedAssist)
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn SetAssister():[A:"..platoon.army.id.."][P:"..platoon.id.."] Unit ["..unitNeedAssist.tpId.."] has ("..unitNeedAssist.assister..") Assisters.")
                end
            else
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn SetAssister():[A:"..platoon.army.id.."][P:"..platoon.id.."] assist unit finished ["..unitNeedAssist.tpId.."]")
                end
                possibleUnits[i] = nil
            end
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn SetAssister():[A:"..platoon.army.id.."][P:"..platoon.id.."] No Eco to assist unit ["..unitNeedAssist.tpId.."]")
            end
            possibleUnits[i] = nil
        end
    end
    -- copy table to remove nil values
    local cleanPossibleUnits = {}
    for _, unit in pairs(possibleUnits) do
        if unit then
            cleanPossibleUnits[#cleanPossibleUnits + 1] = unit
        end
    end
    possibleUnits = cleanPossibleUnits
    if not possibleUnits[1] then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn SetAssister():[A:"..platoon.army.id.."][P:"..platoon.id.."] No units left that needs assist (no eco to assist)")
        end
        ExitPlatoon(platoon)
        return
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn SetAssister():[A:"..platoon.army.id.."][P:"..platoon.id.."] Found ("..#possibleUnits..") units need assisting")
    end
    -- sort the table in case we have 2 or more entries
    if possibleUnits[1] and possibleUnits[2] then
        table.sort(possibleUnits, SortPossibleUnitsAscendingByAssisterValue)
    end
    return possibleUnits
end

---Calculate average distance between unit that needs assist and builders
---@param builders table Builder units that can assist
---@param possibleUnits table units that need assist for build, upgrade or repair
---@return table Returns builder table with assistrange set
function SetAssistRange(builders, possibleUnits)
    local Distance2DSquared = Distance2DSquared
    for i, builder in pairs(builders) do
        builder.ai.assistRange = 0
        local builderPos = builder:GetPosition()
        for i, unitNeedAssist in pairs(possibleUnits) do
            local unitPos = unitNeedAssist:GetPosition()
            local distSquared = Distance2DSquared(builderPos.x, builderPos.z, unitPos.x, unitPos.z)
            builder.ai.assistRange = (builder.ai.assistRange + distSquared) / 2
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "new assistRange:"..builder.ai.assistRange
        end
    end
    return builders
end

---Sub function to set the target to assist and path to the the work area
---@param builder table Unit class table. Contains functions and data for a unit
---@param possibleUnits table units that need assist for build, upgrade or repair
---@return string Returns the next e(xecute)State for the builder
function subPlanSetAssistTarget(builder, possibleUnits)
    local rush = RushHeavyPolicy.Enabled(builder.army)
    if rush then
        -- Keep native construction work; only new target selection is redirected.
        local current = builder.unitBeingAssist
        if RushReliability.Own(builder.army, current) and builder.unitBeingBuilt == current
            and not current:IsCompleted() then return "Assisting" end
        builder.unitBeingAssist = nil
    end
    local closestDistSquared = builder.platoon.ai.baseRadius * builder.platoon.ai.baseRadius
    local lowestAssisterCount = math.huge
    local pos, distSquared, path, info
    builder.ai.buildRange = builder.tp.construction.range or 6
    builder.ai.highestDist = false
    builder.ai.targetProgress = 0
    -- get the unit with the lowest assister count and assist it
    for i, unitNeedAssist in pairs(possibleUnits) do
        if not unitNeedAssist.dead and (not unitNeedAssist:IsCompleted() or unitNeedAssist.upgradeTarget)
            and (not rush or RushReliability.Own(builder.army, unitNeedAssist)
                and not RushHeavyPolicy.IsFirstTarget(unitNeedAssist)) then
            pos = unitNeedAssist:GetPosition()
            distSquared = Distance2DSquared(builder:GetPosition().x, builder:GetPosition().z, pos.x, pos.z)
            if distSquared < closestDistSquared and unitNeedAssist.assister <= lowestAssisterCount then
                closestDistSquared = distSquared
                lowestAssisterCount = unitNeedAssist.assister
                builder.unitBeingAssist = unitNeedAssist
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetAssistTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] assign unitNeedAssist.")
                end
            else
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetAssistTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitNeedAssist is too far away or has to many assisters.")
                end
            end
        elseif unitNeedAssist.dead then
            AILog("- WARNING: Fn subPlanSetAssistTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitNeedAssist is not a valid unit")
        end
    end
    if builder.unitBeingAssist and not builder.unitBeingAssist.dead then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSetAssistTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] search for path to assist unit: [id:"..builder.unitBeingAssist.id.index.."]")
        end
        local owner, assignment, unitAI = builder.army, builder.platoon, builder.ai
        local assignmentAI = assignment.ai
        path, info = AIMarkerGenerator.GeneratePathTo(builder.army.id, builder:GetPosition(), builder.unitBeingAssist:GetPosition(), builder.platoon.ai.movementLayer, true)
        if rush and not RushReliability.CurrentAssignment(builder, owner, assignment, unitAI, assignmentAI) then return nil end
        if rush and (not RushReliability.Own(builder.army, builder.unitBeingAssist)
            or RushHeavyPolicy.IsFirstTarget(builder.unitBeingAssist)) then
            builder.unitBeingAssist = nil
            return "Disband"
        end
        if path then
            -- set variables for the next task
            builder.ai.path = path
            builder.ai.buildRange = builder.tp.construction.range or 6
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
            builder.unitBeingAssist.assister = builder.unitBeingAssist.assister + 1
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanSetAssistTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] StartMoveToDestination unit: [id:"..builder.unitBeingAssist.id.index.."]")
            end
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "found path to unit that needs assist. -> Start moving"
            end
            return "StartMoveToDestination"
        end
        -- ToDo: Transport engineer to destination, for now just block the buildplace
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSetAssistTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no path to assist unit, need Transport!.")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "No path, need transport! ["..builder.unitBeingAssist.."]"
        end
    end
    builder.unitBeingAssist = nil
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "no assist target! -> disband"
    end
    return "Disband"
end

---Waits for matching host work without treating target completion or order replacement as a start failure.
function WaitForEngineerOrderWork(builder, target, order)
    local platoon = builder.platoon
    local owner,unitAI,platoonAI=builder.army,builder.ai,platoon and platoon.ai
    local orderTask = order and order.orderTask
    -- using builder.ai.stuckCount variable to check if we have found work after some time
    builder.ai.stuckCount = 0
    while RushReliability.CurrentAssignment(builder,owner,platoon,unitAI,platoonAI) do
        if not target or target.dead then return "Finished" end
        if orderTask == OrderTasks.ASSISTUNIT and target:IsCompleted() and not target.upgradeTarget then return "Finished" end
        if orderTask == OrderTasks.REPAIR then
            if not RushReliability.Own(owner,target) then return "Canceled" end
            if IsRepairTargetFinished(target) then return "Finished" end
        end
        if not order or not builder.orders or builder.orders.activeOrder ~= order or order.targetUnit ~= target then return "Canceled" end
        if orderTask == OrderTasks.ASSISTUNIT then
            if builder.unitBeingBuilt == (target.upgradeTarget or target) then return "Working" end
            if not builder.assistBehaviorIsActive or builder.assistBehaviorAssistedUnit ~= target then return "Canceled" end
        elseif orderTask == OrderTasks.REPAIR then
            if builder.unitBeingRepaired == target or builder.unitBeingBuilt == target then return "Working" end
            if not builder.repairBehaviorIsActive or builder.repairBehaviorTarget ~= target then return "Canceled" end
        elseif orderTask == OrderTasks.RECLAIM then
            if builder.unitBeingReclaimed == target then return "Working" end
            if not builder.reclaimBehaviorIsActive or builder.reclaimBehaviorTarget ~= target then return "Canceled" end
        else
            return "Canceled"
        end
        builder.ai.stuckCount = builder.ai.stuckCount + 1
        if builder.ai.stuckCount > 30 then
            HostClearOrder(UnitAsArray(builder))
            return "TimedOut"
        end
        WaitTicks(1)
    end
    return "Canceled"
end
---Sub function to start assisting
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartToAssist(builder)
    -- did we reserve eco while moving to the buildplace?
    if builder.ai.reservedEco then
        builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
    end
    local assistTarget = builder.unitBeingAssist
    if not assistTarget or assistTarget.dead or (assistTarget:IsCompleted() and not assistTarget.upgradeTarget) then
        builder.unitBeingAssist = nil
        return "Disband"
    end
    if not builder.platoon.ai.formerTable.AllowEcoStorageDrain and not RushBalance.AssistAffordable(builder,assistTarget,false) then
        -- we don't have the eco to build this, cancel this building
        builder.unitBeingAssist = nil
        return "Disband"
    end
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "StartToAssist ["..assistTarget.tpId.."]"
    end
    HostClearOrder(UnitAsArray(builder))
    HostIssueOrder(OrderTasks.ASSISTUNIT, UnitAsArray(builder), false, assistTarget:GetPosition(), {targetGlobalId = assistTarget.id})
    local workState = WaitForEngineerOrderWork(builder, assistTarget, builder.orders and builder.orders.activeOrder)
    if workState == "Working" then
        return "Assisting"
    end
    if workState == "TimedOut" then
        AILog("- WARNING: Fn subPlanStartToAssist():[A:"..builder.army.id.."][U:"..builder.id.index.."] No construction work started after "..builder.ai.stuckCount.." checks.")
    end
    builder.unitBeingAssist = nil
    return "Disband"
end

---Stop all builders with UnitBeingAssist finished
---@param builder table Unit class table. Contains functions and data for a unit
---@return nil
function subDisbandBuilderWithFinishedUnitBeingAssist(builder)
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subDisbandBuilderWithFinishedUnitBeingAssist():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Finished assisting unit")
    end
    for i, unit in pairs(builder.platoon:GetUnits()) do
        if builder.unitBeingBuilt then
            AILog("* Fn subDisbandBuilderWithFinishedUnitBeingAssist():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..unit.id.index.."] still assisting unitBeingBuilt!")
        elseif unit.unitBeingAssist then
            if not unit.unitBeingAssist.dead then
                if unit.unitBeingAssist:IsCompleted() then
                    if builder.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subDisbandBuilderWithFinishedUnitBeingAssist():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..unit.id.index.."] found finished unitBeingAssist. Disband!")
                    end
                    unit.unitBeingAssist = nil
                    unit.ai.eState = "Disband"
                else
                    if builder.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subDisbandBuilderWithFinishedUnitBeingAssist():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..unit.id.index.."] still assisting unitBeingAssist!")
                    end
                end
            else
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subDisbandBuilderWithFinishedUnitBeingAssist():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..unit.id.index.."] found invalid unit. Disband!")
                end
                HostClearOrder(UnitAsArray(unit))
                unit.ai.eState = "Disband"
            end
        end
        if unit.ai.eState == "Disband" then
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "assisting finished -> disband"
            end
            HostClearOrder(UnitAsArray(unit))
            if unit.ai.reservedEco then
                unit:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
                AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
            end
        else
            if lobbyOptionsAI.debugUnitEState then
                builder.ai.orderText = "waiting for finish assisting"
            end
        end
    end
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------------- Repair Buildings ----------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing Repair orders for engineers. Get unused engineers, move the engineer to a building and repair it.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
-- Release only this repair assignment's intent and approach reservation.
function ReleaseRushRepairAssignment(builder,platoon)
    if not platoon or not builder or builder.platoon~=platoon or builder.army~=platoon.army or not builder.ai then return false end
    local claim=builder.ai.rushRepairClaim
    if claim and claim.platoon==platoon then
        local target=claim.target
        if target and not target.dead and not target.deleted and target.army==builder.army then target.assister=math.max(0,(target.assister or 1)-1) end
        builder.ai.rushRepairClaim=nil
    end
    ClearConstructionBuilderEconomyReservation(builder)
    builder.unitNeedRepair=nil
    return true
end
function planRepairBuilding(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    -- disband the platoon if we don't have any units for it
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for repair found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to repair")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planRepairBuilding")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    if #useBuilder < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for repair found")
        end
        ExitPlatoon(platoon)
        return
    end
    -- assign units to this platton
    platoon:AssignUnits(useBuilder)
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Set platoon movement layer to: "..platoon.ai.movementLayer)
    end
    -- find a unit that needs repair
    local possibleUnits = AIFunctions.GetUnitsThatDesiresRepairAtBase(armyIndex, baseName, formerTable, useBuilder)
    if not possibleUnits or not next(possibleUnits) then
        if formerTable.DebugPlatoon then
            AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No units that needs repair found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#possibleUnits..") units need repair")
    end
    -- filter possibleUnits list by eco and add assister count
    possibleUnits = SetRepairList(platoon, useBuilder, possibleUnits)
    if not possibleUnits or not next(possibleUnits) then
        if formerTable.DebugPlatoon then
            AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No units left after SetRepairList")
        end
        ExitPlatoon(platoon)
        return
    end
    -- calculate average distance between unit that needs repair and engineers
    useBuilder = SetAssistRange(useBuilder, possibleUnits)
    -- remove over max builder based on assist range
    RemoveOverMaxBuilderFromPlatoonByAssistRange(platoon, useBuilder, maxUnits)
    -- main loop
    while Armies[armyIndex]:PlatoonExists(platoon) do
        local currentBuilders={}
        for _,u in pairs(platoon:GetUnits()) do currentBuilders[#currentBuilders+1]=u end
        for i, builder in ipairs(currentBuilders) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..".")
            end
            if builder.platoon==platoon and RushReliability.Own(Armies[armyIndex],builder) and builder.unitNeedRepair
                and (builder.unitNeedRepair.dead or builder.unitNeedRepair.deleted or builder.unitNeedRepair.army~=builder.army) then
                if builder.ai.reservedEco then
                    builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
                    AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
                end
                builder.unitNeedRepair = nil
                builder.ai.eState = nil
            end
            if builder.platoon~=platoon or not RushReliability.Own(Armies[armyIndex],builder) then
                -- A yielding helper may have lost this unit; its replacement work is not ours.
            elseif not IsValidPlatoonUnit(builder) then
                AILog("- WARNING: Fn planRepairBuilding():[A:"..builder.army.id.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
            elseif not builder.ai.eState then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanSetRepairTarget, possibleUnits)
            elseif builder.ai.eState == "StartMoveToDestination" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanStartMoveToDestination, builder.unitNeedRepair:GetPosition(), builder.unitNeedRepair.tpId)
            elseif builder.ai.eState == "MovingToDestination" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanMovingToDestination, builder.unitNeedRepair:GetPosition(), builder.ai.buildRange)
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanDisbandOnFinishedUnit)
            elseif builder.ai.eState == "MovingDestinationCanceled" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanDisbandOnFinishedUnit)
            elseif builder.ai.eState == "MovingDestinationReached" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanStartToRepair)
            elseif builder.ai.eState == "Repairing" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanRepairing)
            elseif builder.ai.eState == "Finishing" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanDisbandOnFinishedUnit)
            elseif builder.ai.eState == "Disband" then
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "disband from repair platoon"
                end
                ReleaseRushRepairAssignment(builder,platoon)
                HostClearOrder(UnitAsArray(builder))
                ClearUnitTemporaryPlatoonData(builder, "planRepairBuilding")
                platoon:RemoveUnits(UnitAsArray(builder))
            else
                AILog("- WARNING: Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
            end
            if platoon:GetNumOfUnits() < 1 then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planRepairBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
                end
                ExitPlatoon(platoon)
                return
            end
        end
        WaitTicks(10)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        if unit.platoon==platoon and RushReliability.Own(Armies[armyIndex],unit) then
            ReleaseRushRepairAssignment(unit,platoon)
            ClearUnitTemporaryPlatoonData(unit, "planRepairBuilding")
        end
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planRepairBuilding platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Filter possibleUnits list by eco and add repairer count
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param builders table List of units that can repair
---@param possibleUnits table List of units that need repair
---@return table|nil Returns filtered possibleUnits list
function SetRepairList(platoon, builders, possibleUnits)
    for i, unitNeedRepair in pairs(possibleUnits) do
        -- check if repair eco is available
        if AIFunctions.CanResumeConstructionWithoutEconomyCheck(platoon.ai.formerTable, unitNeedRepair) or platoon.ai.formerTable.AllowEcoStorageDrain or AIFunctions.IsBuildableWithoutEconStorageDrain(platoon.army.id, builders[1].tpId, unitNeedRepair.tpId) then
            -- get current repairer count
            if not unitNeedRepair.dead and not IsRepairTargetFinished(unitNeedRepair) then
                -- save number of repairers to the unit
                unitNeedRepair.assister = AIFunctions.GetNumAssistersAndBuilders(platoon.army.id, unitNeedRepair)
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn SetRepairList():[A:"..platoon.army.id.."][P:"..platoon.id.."] Unit ["..unitNeedRepair.tpId.."] has ("..unitNeedRepair.assister..") repairers.")
                end
            else
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn SetRepairList():[A:"..platoon.army.id.."][P:"..platoon.id.."] repair unit finished ["..unitNeedRepair.tpId.."]")
                end
                possibleUnits[i] = nil
            end
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn SetRepairList():[A:"..platoon.army.id.."][P:"..platoon.id.."] No Eco to repair unit ["..unitNeedRepair.tpId.."]")
            end
            possibleUnits[i] = nil
        end
    end
    -- copy table to remove nil values
    local cleanPossibleUnits = {}
    for _, unit in pairs(possibleUnits) do
        if unit then
            cleanPossibleUnits[#cleanPossibleUnits + 1] = unit
        end
    end
    possibleUnits = cleanPossibleUnits
    if not possibleUnits[1] then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn SetRepairList():[A:"..platoon.army.id.."][P:"..platoon.id.."] No units left that need repair (no eco to repair)")
        end
        ExitPlatoon(platoon)
        return
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn SetRepairList():[A:"..platoon.army.id.."][P:"..platoon.id.."] Found ("..#possibleUnits..") units need repair")
    end
    -- sort the table in case we have 2 or more entries
    if possibleUnits[1] and possibleUnits[2] then
        table.sort(possibleUnits, SortPossibleUnitsAscendingByAssisterValue)
    end
    return possibleUnits
end

---Sub function to set the target to repair and path to the the work area
---@param builder table Unit class table. Contains functions and data for a unit
---@param possibleUnits table List of units that may need repair
---@return string Returns the next executeState for the builder
function subPlanSetRepairTarget(builder, possibleUnits)
    local owner,assignment,unitAI,assignmentAI=builder.army,builder.platoon,builder.ai,builder.platoon.ai
    if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
    ReleaseRushRepairAssignment(builder,assignment)
    builder.unitNeedRepair = nil
    local closestDistSquared = builder.platoon.ai.baseRadius * builder.platoon.ai.baseRadius
    local maxAssisterCount = 20
    local pos, distSquared, path, info
    builder.ai.buildRange = builder.tp.construction.range or 6
    builder.ai.highestDist = false
    builder.ai.targetProgress = 0
    local builderPosition = builder:GetPosition()
    -- get the unit with the lowest assister count and repair it
    for i, unitNeedRepair in next, possibleUnits do
        -- remove invalid or dead units immediately
        if not unitNeedRepair or unitNeedRepair.dead or unitNeedRepair.deleted or unitNeedRepair.army~=owner then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanSetRepairTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitNeedRepair invalid or dead, removed from table")
            end
            possibleUnits[i] = nil
        -- remove units that no longer need repair
        elseif IsRepairTargetFinished(unitNeedRepair) then
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanSetRepairTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unit fully repaired, removed from table.["..unitNeedRepair.id.index.."]")
            end
            possibleUnits[i] = nil
        else
            pos = unitNeedRepair:GetPosition()
            distSquared = Distance2DSquared(builderPosition.x, builderPosition.z, pos.x, pos.z)
            if distSquared < closestDistSquared and unitNeedRepair.assister <= maxAssisterCount then
                closestDistSquared = distSquared
                maxAssisterCount = unitNeedRepair.assister
                builder.unitNeedRepair = unitNeedRepair
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetRepairTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] assign closest unitNeedRepair.["..unitNeedRepair.id.index.."]")
                end
            else
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetRepairTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitNeedRepair too far or too many assisters.")
                end
            end
        end
    end
    if builder.unitNeedRepair and not builder.unitNeedRepair.dead then
        local target=builder.unitNeedRepair
        path, info = AIMarkerGenerator.GeneratePathTo(owner.id, RushMovementV18.Copy(builderPosition), RushMovementV18.Copy(target:GetPosition()), assignmentAI.movementLayer, true)
        if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
        if builder.unitNeedRepair~=target or target.dead or target.deleted or target.army~=owner or IsRepairTargetFinished(target) then
            ReleaseRushRepairAssignment(builder,assignment);return "Disband"
        end
        if path then
            -- set variables for next task
            builder.ai.path = path
            builder.ai.buildRange = builder.tp.construction.range or 6
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
            builder.unitNeedRepair.assister = (builder.unitNeedRepair.assister or 0) + 1
            builder.ai.rushRepairClaim={platoon=assignment,target=builder.unitNeedRepair}
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanSetRepairTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."] switching [eState] = "..repr(builder.platoon.ai.eState).." to StartMoveToDestination.")
            end
            return "StartMoveToDestination"
        end
        -- no path available
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSetRepairTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no path, need transport.")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "No path, need transport!"
        end
    end
    builder.unitNeedRepair = nil
    return "Disband"
end

---Sub function to start repair
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartToRepair(builder)
    local owner,assignment,unitAI,assignmentAI=builder.army,builder.platoon,builder.ai,builder.platoon.ai
    if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
    -- did we reserve eco while moving to the buildplace?
    if builder.ai.reservedEco then
        builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
    end
    local repairTarget = builder.unitNeedRepair
    if not repairTarget or repairTarget.dead or repairTarget.deleted or repairTarget.army~=owner or IsRepairTargetFinished(repairTarget) then
        builder.unitNeedRepair = nil
        return "Disband"
    end
    if not AIFunctions.CanResumeConstructionWithoutEconomyCheck(builder.platoon.ai.formerTable, repairTarget) and not builder.platoon.ai.formerTable.AllowEcoStorageDrain and not AIFunctions.IsBuildableWithoutEconStorageDrain(builder.army.id, builder.tpId, repairTarget.tpId) then
        -- we don't have the eco to repair this, cancel this repair
        builder.unitNeedRepair = nil
        return "Disband"
    end
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "StartToRepair ["..repairTarget.tpId.."]"
    end
    HostClearOrder(UnitAsArray(builder))
    HostIssueOrder(OrderTasks.REPAIR, UnitAsArray(builder), false, repairTarget:GetPosition(), {targetGlobalId = repairTarget.id})
    local workState = WaitForEngineerOrderWork(builder, repairTarget, builder.orders and builder.orders.activeOrder)
    if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
    if not RushReliability.Own(owner,repairTarget) then builder.unitNeedRepair=nil;return "Disband" end
    if workState == "Working" then
        return "Repairing"
    end
    if workState == "TimedOut" then
        AILog("- WARNING: Fn subPlanStartToRepair():[A:"..builder.army.id.."][U:"..builder.id.index.."] No construction or repair work started after "..builder.ai.stuckCount.." checks.")
    end
    builder.unitNeedRepair = nil
    return "Disband"
end

---Sub function that waits for finishing the construction repair
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanRepairing(builder)
    local repairTarget = builder.unitNeedRepair
    local repairOrder = builder.orders and builder.orders.activeOrder
    if repairTarget and not repairTarget.dead and not repairTarget.deleted and repairTarget.army==builder.army and not IsRepairTargetFinished(repairTarget)
        and repairOrder and repairOrder.orderTask == OrderTasks.REPAIR and repairOrder.targetUnit == repairTarget
        and builder.repairBehaviorIsActive and builder.repairBehaviorTarget == repairTarget then
        -- Repair owns both construction and HP restoration, including the gap between their routines.
        return builder.ai.eState
    end
    if repairOrder and repairOrder.orderTask == OrderTasks.REPAIR and repairOrder.targetUnit == repairTarget then
        HostClearOrder(UnitAsArray(builder))
    end
    builder.unitNeedRepair = nil
    return "Disband"
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------- Reclaim Buildings ----------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing Reclaim orders for engineers. Get unused engineers, move the engineer to a building and reclaim it.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planReclaimBuilding(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    -- disband the platoon if we don't have any units for it
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for assist found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to assist")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planReclaimBuilding")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    if #useBuilder < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for assist found")
        end
        ExitPlatoon(platoon)
        return
    end
    -- assign units to this platton
    platoon:AssignUnits(useBuilder)
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Set platoon movement layer to: "..platoon.ai.movementLayer)
    end
    -- find a unit that needs assist
    local possibleUnits = AIFunctions.GetReclaimAbleUnitsAtBase(armyIndex, baseName, formerTable)
    if not possibleUnits then
        if formerTable.DebugPlatoon then
            AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] No units that should be reclaimed found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#possibleUnits..") units that should be reclaimed")
    end
    -- calculate average distance between unit that needs assist and engineers
    useBuilder = SetAssistRange(useBuilder, possibleUnits)
    -- remove over max builder based on assist range
    RemoveOverMaxBuilderFromPlatoonByAssistRange(platoon, useBuilder, maxUnits)
    -- main loop
    while Armies[armyIndex]:PlatoonExists(platoon) do
        for i, builder in pairs(platoon:GetUnits()) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..".")
            end
            if builder.unitToReclaim and builder.unitToReclaim.dead then
                if builder.ai.reservedEco then
                    builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
                    AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
                end
                builder.ai.eState = nil
            end
            if not IsValidPlatoonUnit(builder) then
                AILog("- WARNING: Fn planReclaimBuilding():[A:"..builder.army.id.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
            elseif not builder.ai.eState then
                builder.ai.eState = subPlanSetReclaimTarget(builder, possibleUnits)
            elseif builder.ai.eState == "StartMoveToDestination" then
                builder.ai.eState = subPlanStartMoveToDestination(builder, builder.unitToReclaim:GetPosition(), nil) -- do not reserve eco here
            elseif builder.ai.eState == "MovingToDestination" then
                builder.ai.eState = subPlanMovingToDestination(builder, builder.unitToReclaim:GetPosition(), builder.ai.buildRange)
                builder.ai.eState = subPlanDisbandOnFinishedUnit(builder)
            elseif builder.ai.eState == "MovingDestinationCanceled" then
                builder.ai.eState = subPlanDisbandOnFinishedUnit(builder)
            elseif builder.ai.eState == "MovingDestinationReached" then
                builder.ai.eState = subPlanStartToReclaim(builder)
            elseif builder.ai.eState == "Reclaiming" then
                builder.ai.eState = subPlanReclaiming(builder)
            elseif builder.ai.eState == "Disband" then
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "disband from relcaim platoon"
                end
                ClearUnitTemporaryPlatoonData(builder, "planReclaimBuilding")
                platoon:RemoveUnits(UnitAsArray(builder))
            else
                AILog("- WARNING: Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
            end
            if platoon:GetNumOfUnits() < 1 then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planReclaimBuilding():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
                end
                ExitPlatoon(platoon)
            end
        end
        WaitTicks(10)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planReclaimBuilding")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planReclaimBuilding platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Sub function to set the target to reclaim and path to the the work area
---@param builder table Unit class table. Contains functions and data for a unit
---@param possibleUnits table units that can be reclaimed
---@return string Returns the next e(xecute)State for the builder
function subPlanSetReclaimTarget(builder, possibleUnits)
    local closestDistSquared = builder.platoon.ai.baseRadius * builder.platoon.ai.baseRadius
    local pos, distSquared, path, info
    builder.ai.buildRange = builder.tp.construction.range or 6
    builder.ai.highestDist = false
    builder.ai.targetProgress = 0
    builder.unitToReclaim = nil
    -- get the closest unit and reclaim it
    for i, unitToReclaim in pairs(possibleUnits) do
        if not unitToReclaim.dead then
            pos = unitToReclaim:GetPosition()
            distSquared = Distance2DSquared(builder:GetPosition().x, builder:GetPosition().z, pos.x, pos.z)
            if distSquared < closestDistSquared then
                closestDistSquared = distSquared
                builder.unitToReclaim = unitToReclaim
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetReclaimTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] assign closest (dist:"..math.sqrt(distSquared)..") unitToReclaim.[U:"..unitToReclaim.id.index.."]")
                end
            else
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetReclaimTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitToReclaim is too far away. (dist:"..math.sqrt(distSquared)..")")
                end
            end
        else
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("- WARNING: Fn subPlanSetReclaimTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitToReclaim is not a valid unit")
            end
        end
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanSetReclaimTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Check if we have something to reclaim...")
    end
    if builder.unitToReclaim then
        path, info = AIMarkerGenerator.GeneratePathTo(builder.army.id, builder:GetPosition(), builder.unitToReclaim:GetPosition(), builder.platoon.ai.movementLayer, true)
        if path then
            -- set variables for the next task
            builder.ai.path = path
            builder.ai.buildRange = builder.tp.construction.range or 6
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
            if builder.platoon.ai.formerTable.DebugPlatoon then
                AILog("- WARNING: Fn subPlanSetReclaimTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] path to unitToReclaim found -> StartMoveToDestination.")
            end
            return "StartMoveToDestination"
        end
        -- ToDo: Transport engineer to destination, for now just block the buildplace
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("- WARNING: Fn subPlanSetReclaimTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no path to assist unit, need Transport!.")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "No path, need transport! ["..builder.unitToReclaim.."]"
        end
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanSetReclaimTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] no unitToReclaim found -> Disband")
    end
    return "Disband"
end

---Sub function to start assisting
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartToReclaim(builder)
    local reclaimTarget = builder.unitToReclaim
    if not reclaimTarget or reclaimTarget.dead then
        builder.unitToReclaim = nil
        return "Disband"
    end
    if lobbyOptionsAI.debugUnitEState then
        builder.ai.orderText = "StartToReclaim ["..reclaimTarget.tpId.."]"
    end
    HostClearOrder(UnitAsArray(builder))
    HostIssueOrder(OrderTasks.RECLAIM, UnitAsArray(builder), false, reclaimTarget:GetPosition(), {targetGlobalId = reclaimTarget.id})
    local workState = WaitForEngineerOrderWork(builder, reclaimTarget, builder.orders and builder.orders.activeOrder)
    if workState == "Working" then
        return "Reclaiming"
    end
    if workState == "TimedOut" then
        AILog("- WARNING: Fn subPlanStartToReclaim():[A:"..builder.army.id.."][U:"..builder.id.index.."] No reclaim work started after "..builder.ai.stuckCount.." checks.")
    end
    builder.unitToReclaim = nil
    return "Disband"
end

---Sub function that waits for finishing the reclaim
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanReclaiming(builder)
    local reclaimTarget = builder.unitToReclaim
    local reclaimOrder = builder.orders and builder.orders.activeOrder
    if reclaimTarget and not reclaimTarget.dead and reclaimOrder and reclaimOrder.orderTask == OrderTasks.RECLAIM
        and reclaimOrder.targetUnit == reclaimTarget and builder.reclaimBehaviorIsActive and builder.reclaimBehaviorTarget == reclaimTarget then
        return builder.ai.eState
    end
    builder.unitToReclaim = nil
    return "Disband"
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------- Reclaim Map Props -----------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

local mapReclaimTargetExclusionRadiusSquared = 100

---Clears target and movement data before an engineer searches for the next map prop.
---@param builder table Unit class table. Contains functions and data for a unit
---@return nil
local function ResetMapReclaimBuilderTarget(builder)
    builder.unitToReclaim = nil
    builder.ai.eState = nil
    builder.ai.path = nil
    builder.ai.buildRange = nil
    builder.ai.lastPosition = nil
    builder.ai.lastProgressPosition = nil
    builder.ai.progressCheckTicks = nil
    builder.ai.stuckCount = nil
    builder.ai.highestDist = nil
    builder.ai.targetProgress = nil
    builder.ai.logStuckState = nil
    builder.ai.rushGenericMove = nil
end

---Builds a list of positions reserved by assigned or active reclaim targets.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return table Reclaim target positions
local function GetReservedMapReclaimTargetPositions(platoon)
    local reclaimTargetPositions = {}
    for _, armyUnit in pairs(Armies[platoon.army.id].units) do
        if not armyUnit.dead then
            local reclaimTarget = armyUnit.unitToReclaim
            if not reclaimTarget and armyUnit.reclaimBehaviorIsActive then
                reclaimTarget = armyUnit.reclaimBehaviorTarget or armyUnit.unitBeingReclaimed
            end
            if reclaimTarget and not reclaimTarget.dead then
                local reclaimTargetPosition = reclaimTarget:GetPosition()
                reclaimTargetPositions[#reclaimTargetPositions + 1] = { x = reclaimTargetPosition.x, z = reclaimTargetPosition.z }
            end
        end
    end
    for _, reclaimProp in pairs(__Entities.Props) do
        if not reclaimProp.dead and reclaimProp.reclaimers and next(reclaimProp.reclaimers) then
            local reclaimTargetPosition = reclaimProp:GetPosition()
            reclaimTargetPositions[#reclaimTargetPositions + 1] = { x = reclaimTargetPosition.x, z = reclaimTargetPosition.z }
        end
    end
    return reclaimTargetPositions
end

---Checks whether a target position is outside every reserved reclaim area.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param reclaimTargetPosition table Position of the candidate prop
---@return boolean Returns true if no reclaim target is within 10 units
local function IsMapReclaimTargetPositionAvailable(platoon, reclaimTargetPosition)
    for _, reservedReclaimTargetPosition in pairs(platoon.ai.reclaimTargetPositions) do
        if Distance2DSquared(reclaimTargetPosition.x, reclaimTargetPosition.z, reservedReclaimTargetPosition.x, reservedReclaimTargetPosition.z) <= mapReclaimTargetExclusionRadiusSquared then
            return false
        end
    end
    return true
end

---Executing reclaim orders for engineers. Engineers remain in the platoon until no living props remain on the map.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planReclaimMap(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    platoon.ai = {}
    local planAI = platoon.ai
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    platoon.ai.unreachableReclaimProps = setmetatable({}, {__mode="k"})
    local useBuilder, _, maximumUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for map reclaim found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to reclaim map props")
    end
    CheckUnitsForLeftover(useBuilder, "planReclaimMap")
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, platoon.ai.basePosition)
    useBuilder = RemoveOverMaxBuilder(useBuilder, maximumUnits)
    if #useBuilder < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] No builder left after reserving ("..reserveForBase..") units for base")
        end
        ExitPlatoon(platoon)
        return
    end
    platoon:AssignUnits(useBuilder)
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] Assigned ("..#useBuilder..") builders, maximum ("..maximumUnits.."), reserved for base ("..reserveForBase..")")
    end
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] Set platoon movement layer to: "..platoon.ai.movementLayer)
    end
    while platoon.ai==planAI and Armies[armyIndex].ai.isAlive~=false and Armies[armyIndex]:PlatoonExists(platoon) and AIFunctions.HasReclaimablePropsOnMap() do
        if formerTable.DebugPlatoon then
            AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] REPEAT ------------------------------------------- platoon units: "..platoon:GetNumOfUnits())
        end
        local previousPlatoonUnitCount = platoon:GetNumOfUnits()
        if Armies[armyIndex].ai.bases[baseName] then subPlanGetMoreBuilders(platoon, maximumUnits) end
        if platoon.ai~=planAI or Armies[armyIndex].ai.isAlive==false then return end
        local currentPlatoonUnitCount = platoon:GetNumOfUnits()
        if formerTable.DebugPlatoon and currentPlatoonUnitCount > previousPlatoonUnitCount then
            AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] Added ("..(currentPlatoonUnitCount - previousPlatoonUnitCount)..") builders, platoon units: ("..currentPlatoonUnitCount.."/"..maximumUnits..")")
        end
        platoon.ai.reclaimTargetPositions = GetReservedMapReclaimTargetPositions(platoon)
        if formerTable.DebugPlatoon then
            AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] Reserved reclaim target positions: ("..#platoon.ai.reclaimTargetPositions..")")
        end
        for _, builder in pairs(platoon:GetUnits()) do
            if platoon.ai~=planAI or Armies[armyIndex].ai.isAlive==false then return end
            if formerTable.DebugPlatoon then
                local reclaimTargetIndex = builder.unitToReclaim and builder.unitToReclaim.id.index or "nil"
                AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..", reclaim target [P:"..reclaimTargetIndex.."]")
            end
            if not IsValidPlatoonUnit(builder) then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planReclaimMap():[A:"..armyIndex.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
                end
            elseif builder.platoon ~= platoon then
                -- Ignore a unit transferred out while another helper yielded.
            elseif not RushReliability.Own(Armies[armyIndex],builder) then
                -- A stale snapshot must not issue orders for another owner.
            elseif RushReliability.ReleaseRecalledBuilder(builder, platoon) then
                -- Cooperative release reserves this T3 for its requesting director.
            elseif builder.ai.eState == "Disband" then
                -- Generic movement has exhausted its checked route retries.
                -- Retire this prop temporarily instead of immediately selecting
                -- it again and repeating the same failed path indefinitely.
                local target=builder.unitToReclaim
                if target and not target.dead and not target.deleted then platoon.ai.unreachableReclaimProps[target]=GetGameTimeSeconds() end
                AILog("[RushWork] army="..armyIndex.." event=reclaim-target-deferred builder="..builder.id.index.." target="..tostring(target and target.id and target.id.index).." reason=movement-recovery-exhausted",true)
                HostClearOrder(UnitAsArray(builder))
                ResetMapReclaimBuilderTarget(builder)
            elseif builder.unitToReclaim and (builder.unitToReclaim.dead or builder.unitToReclaim.deleted) then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] reclaim target [P:"..builder.unitToReclaim.id.index.."] is dead, searching for a new target")
                end
                HostClearOrder(UnitAsArray(builder))
                ResetMapReclaimBuilderTarget(builder)
            elseif not builder.unitToReclaim and (builder.ai.eState == "StartMoveToDestination"
                or builder.ai.eState == "MovingToDestination" or builder.ai.eState == "MovingDestinationReached"
                or builder.ai.eState == "Reclaiming") then
                -- A canceled target is not a valid argument to a movement helper.
                HostClearOrder(UnitAsArray(builder))
                ResetMapReclaimBuilderTarget(builder)
            elseif not builder.ai.eState then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanSetMapReclaimTarget)
            elseif builder.ai.eState == "StartMoveToDestination" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanStartMoveToDestination, builder.unitToReclaim:GetPosition(), nil)
            elseif builder.ai.eState == "MovingToDestination" then
                local applied = RushReliability.ApplyBuilderStep(builder, platoon, subPlanMovingToDestination, builder.unitToReclaim:GetPosition(), builder.ai.buildRange)
                if applied and formerTable.DebugPlatoon and builder.unitToReclaim and builder.ai.eState == "MovingDestinationReached" then
                    AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] reached reclaim target [P:"..builder.unitToReclaim.id.index.."]")
                end
            elseif builder.ai.eState == "MovingDestinationReached" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanStartMapReclaim)
            elseif builder.ai.eState == "Reclaiming" then
                RushReliability.ApplyBuilderStep(builder, platoon, subPlanMapReclaiming)
            else
                AILog("- WARNING: Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
                HostClearOrder(UnitAsArray(builder))
                ResetMapReclaimBuilderTarget(builder)
            end
        end
        WaitTicks(10)
    end
    -- A restarted plan owns its own cleanup; the old coroutine must not clear it.
    if platoon.ai~=planAI or Armies[armyIndex].ai.isAlive==false then return end
    if formerTable.DebugPlatoon then
        if Armies[armyIndex]:PlatoonExists(platoon) then
            AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] No living props remain on the map, disbanding platoon")
        else
            AILog("* Fn planReclaimMap():[A:"..armyIndex.."][P:"..platoon.id.."] Platoon no longer exists, plan finished")
        end
    end
    if Armies[armyIndex]:PlatoonExists(platoon) then
        local platoonUnits = platoon:GetUnits()
        HostClearOrder(platoonUnits)
        for _, unit in pairs(platoonUnits) do
            ResetMapReclaimBuilderTarget(unit)
            ClearUnitTemporaryPlatoonData(unit, "planReclaimMap")
            if lobbyOptionsAI.debugUnitEState then
                unit.ai.orderText = "disband from planReclaimMap platoon (finished)"
            end
        end
        ExitPlatoon(platoon)
    end
end

---Selects the closest reachable prop outside all reserved reclaim areas.
---@param builder table Unit class table. Contains functions and data for a unit
---@return string|nil Returns StartMoveToDestination when a target was assigned
function subPlanSetMapReclaimTarget(builder)
    local owner,assignment,unitAI=builder.army,builder.platoon,builder.ai
    local assignmentAI=assignment and assignment.ai
    if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
    local prop,path = RushTacticsV8.ReclaimTarget(builder,
        builder.platoon.ai.reclaimTargetPositions, builder.platoon.ai.unreachableReclaimProps)
    if not RushReliability.CurrentAssignment(builder,owner,assignment,unitAI,assignmentAI) then return nil end
    if not prop or prop.dead or prop.deleted or type(path)~="table" or #path==0 then return nil end
    local position=prop:GetPosition()
    builder.unitToReclaim=prop
    builder.ai.path=path
    builder.ai.buildRange=builder.tp.construction.range or 6
    builder.ai.lastPosition=false
    builder.ai.highestDist=false
    builder.ai.targetProgress=0
    builder.platoon.ai.reclaimTargetPositions[#builder.platoon.ai.reclaimTargetPositions+1]
        ={x=position.x,z=position.z}
    return "StartMoveToDestination"
end

---Issues the reclaim order after the engineer reaches its assigned prop.
---@param builder table Unit class table. Contains functions and data for a unit
---@return string|nil Returns Reclaiming after the reclaim behavior starts
function subPlanStartMapReclaim(builder)
    local platoon = builder.platoon
    local owner,unitAI,platoonAI=builder.army,builder.ai,platoon and platoon.ai
    if not RushReliability.CurrentAssignment(builder,owner,platoon,unitAI,platoonAI) then return nil end
    local isPlatoonDebugEnabled = platoon.ai.formerTable.DebugPlatoon
    local reclaimTarget = builder.unitToReclaim
    if not reclaimTarget or reclaimTarget.dead then
        if isPlatoonDebugEnabled then
            local reclaimTargetIndex = reclaimTarget and reclaimTarget.id.index or "nil"
            AILog("* Fn subPlanStartMapReclaim():[A:"..builder.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] reclaim target [P:"..reclaimTargetIndex.."] is invalid before issuing reclaim order")
        end
        ResetMapReclaimBuilderTarget(builder)
        return nil
    end
    if isPlatoonDebugEnabled then
        local reclaimTargetPosition = reclaimTarget:GetPosition()
        AILog("* Fn subPlanStartMapReclaim():[A:"..builder.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] issuing reclaim order for prop [P:"..reclaimTarget.id.index.."] at position [x:"..reclaimTargetPosition.x.." z:"..reclaimTargetPosition.z.."]")
    end
    HostClearOrder(UnitAsArray(builder))
    HostIssueOrder(OrderTasks.RECLAIM, UnitAsArray(builder), false, reclaimTarget:GetPosition(), { targetGlobalId = reclaimTarget.id })
    local workState = WaitForEngineerOrderWork(builder, reclaimTarget, builder.orders and builder.orders.activeOrder)
    if not RushReliability.CurrentAssignment(builder,owner,platoon,unitAI,platoonAI) then
        if isPlatoonDebugEnabled then
            AILog("* Fn subPlanStartMapReclaim():[A:"..builder.army.id.."][P:"..platoon.id.."][U:"..builder.id.index.."] builder was destroyed or removed before reclaim started")
        end
        return nil
    end
    if workState == "Working" then
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMapReclaim():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] reclaiming prop [P:"..reclaimTarget.id.index.."]")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "reclaiming map prop ["..reclaimTarget.tpId.."]"
        end
        return "Reclaiming"
    end
    if builder.platoon then
        if workState == "TimedOut" and builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("- WARNING: Fn subPlanStartMapReclaim():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] reclaim order for prop [P:"..reclaimTarget.id.index.."] did not start")
        end
        ResetMapReclaimBuilderTarget(builder)
    end
    return nil
end

---Keeps the engineer assigned until the current prop has been reclaimed.
---@param builder table Unit class table. Contains functions and data for a unit
---@return string|nil Returns Reclaiming while active or nil when the engineer needs a new target
function subPlanMapReclaiming(builder)
    local reclaimTarget = builder.unitToReclaim
    if reclaimTarget and not reclaimTarget.dead and builder.reclaimBehaviorIsActive and builder.reclaimBehaviorTarget == reclaimTarget then
        return builder.ai.eState
    end
    if builder.platoon.ai.formerTable.DebugPlatoon then
        local reclaimTarget = builder.unitToReclaim or builder.unitBeingReclaimed
        local reclaimTargetIndex = reclaimTarget and reclaimTarget.id.index or "nil"
        local reclaimTargetDead = reclaimTarget and reclaimTarget.dead or false
        AILog("* Fn subPlanMapReclaiming():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] reclaim ended for prop [P:"..reclaimTargetIndex.."], target dead: "..repr(reclaimTargetDead)..", behavior active: "..repr(builder.reclaimBehaviorIsActive)..", unitBeingReclaimed: "..repr(builder.unitBeingReclaimed and true or false))
    end
    ResetMapReclaimBuilderTarget(builder)
    return nil
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
------------------------------------------------------ Recharge Shield Structures ------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing Shield Recharge orders for engineers.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planRechargeShieldStructures(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- set platoon local variables
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    platoon.ai.baseRadius = Armies[armyIndex].ai.bases[baseName].radius
    -- get units from the former NeedMobileBuilder table
    local useBuilder, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedMobileBuilder(armyIndex, baseName, formerTable)
    -- disband the platoon if we don't have any units for it
    if not useBuilder then
        if formerTable.DebugPlatoon then
            AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for Recharge found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#useBuilder..") units ready to Recharge")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useBuilder, "planRechargeShieldStructures")
    -- remove as much units as we need to stay at base
    useBuilder = RemoveReservedUnits(useBuilder, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    if #useBuilder < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] No builder for Recharge found")
        end
        ExitPlatoon(platoon)
        return
    end
    -- assign units to this platton
    platoon:AssignUnits(useBuilder)
    -- get the most restrictive movement layer for all platoon units
    platoon.ai.movementLayer = RushMovementV18.MovementLayer(platoon)
    if formerTable.DebugPlatoon then
        AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] Set platoon movement layer to: "..platoon.ai.movementLayer)
    end
    -- find a unit that needs Recharge
    local possibleUnits = AIFunctions.GetShieldStructuresThatDesiresRechargeAtBase(armyIndex, baseName, formerTable)
    if not possibleUnits then
        if formerTable.DebugPlatoon then
            AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] No units that needs Recharge found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] Found ("..#possibleUnits..") units need Recharge")
    end
    -- filter possibleUnits list by eco and add assister count
    possibleUnits = SetShieldRechargeList(platoon, useBuilder, possibleUnits)
    -- calculate average distance between unit that needs Recharge and engineers
    useBuilder = SetAssistRange(useBuilder, possibleUnits)
    -- remove over max builder based on assist range
    RemoveOverMaxBuilderFromPlatoonByAssistRange(platoon, useBuilder, maxUnits)
    -- main loop
    while Armies[armyIndex]:PlatoonExists(platoon) do
        for i, builder in pairs(platoon:GetUnits()) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] [eState] = "..repr(builder.ai.eState)..".")
            end
            if builder.unitBeingRecharge and builder.unitBeingRecharge.dead then
                builder.ai.eState = nil
            end
            if not IsValidPlatoonUnit(builder) then
                AILog("- WARNING: Fn planRechargeShieldStructures():[A:"..builder.army.id.."][U:"..builder.id.index.."] unit is not a valid platoon unit!")
            elseif not builder.ai.eState then
                builder.ai.eState = subPlanSetRechargeTarget(builder, possibleUnits)
            elseif builder.ai.eState == "StartMoveToDestination" then
                builder.ai.eState = subPlanStartMoveToDestination(builder, builder.unitBeingRecharge:GetPosition(), builder.unitBeingRecharge.tpId)
            elseif builder.ai.eState == "MovingToDestination" then
                builder.ai.eState = subPlanMovingToDestination(builder, builder.unitBeingRecharge:GetPosition(), builder.ai.buildRange)
                builder.ai.eState = subPlanResetOnFinishedUnit(builder)
            elseif builder.ai.eState == "MovingDestinationCanceled" then
                builder.ai.eState = subPlanResetOnFinishedUnit(builder)
            elseif builder.ai.eState == "MovingDestinationReached" then
                builder.ai.eState = subPlanStartToRecharge(builder)
            elseif builder.ai.eState == "Recharging" then
                builder.ai.eState = subPlanRecharging(builder)
            elseif builder.ai.eState == "Finishing" then
                builder.ai.eState = subPlanResetOnFinishedUnit(builder)
            elseif builder.ai.eState == "Disband" then
                if lobbyOptionsAI.debugUnitEState then
                    builder.ai.orderText = "disband from Recharge platoon"
                end
                ClearUnitTemporaryPlatoonData(builder, "planRechargeShieldStructures")
                platoon:RemoveUnits(UnitAsArray(builder))
            else
                AILog("- WARNING: Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..builder.id.index.."] unknown builder eState ??? ["..repr(builder.ai.eState).."]")
            end
            if platoon:GetNumOfUnits() < 1 then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planRechargeShieldStructures():[A:"..armyIndex.."][P:"..platoon.id.."] no units left in platoon, exiting function")
                end
                ExitPlatoon(platoon)
            end
        end
        WaitTicks(10)
        -- filter possibleUnits list by eco and add assister count
        possibleUnits = SetShieldRechargeList(platoon, useBuilder, possibleUnits)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planRechargeShieldStructures")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from planRechargeShieldStructures platoon (finished)"
        end
    end
    -- disband the units from this platoon
    ExitPlatoon(platoon)
end

---Filter possible shield unit list by Recharger count
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param builders table Builder units used for recharge
---@param possibleUnits table shield units that need recharge
---@return table|nil Returns filtered possibleUnits list
function SetShieldRechargeList(platoon, builders, possibleUnits)
    local health
    for i, shieldUnitNeedRecharge in pairs(possibleUnits) do
        -- get num assister
        health = 100
        if not shieldUnitNeedRecharge.dead then
            health = 100 / shieldUnitNeedRecharge:GetMaxHealth() * shieldUnitNeedRecharge:GetHealth()
        end
        if health < 100 then
            -- save numbers of assister to the unit
            shieldUnitNeedRecharge.assister = AIFunctions.GetNumAssistersAndBuilders(platoon.army.id, shieldUnitNeedRecharge)
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn SetShieldRechargeList():[A:"..platoon.army.id.."][P:"..platoon.id.."] Unit ["..shieldUnitNeedRecharge.tpId.."] has ("..shieldUnitNeedRecharge.assister..") recharger.")
            end
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn SetShieldRechargeList():[A:"..platoon.army.id.."][P:"..platoon.id.."] Recharge unit finished ["..shieldUnitNeedRecharge.tpId.."]")
            end
            possibleUnits[i] = nil
        end
    end
    -- copy table to remove nil values
    -- copy table to remove nil values
    local cleanPossibleUnits = {}
    for _, unit in pairs(possibleUnits) do
        if unit then
            cleanPossibleUnits[#cleanPossibleUnits + 1] = unit
        end
    end
    possibleUnits = cleanPossibleUnits
    if not possibleUnits[1] then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn SetShieldRechargeList():[A:"..platoon.army.id.."][P:"..platoon.id.."] No units left that needs recharge ")
        end
        ExitPlatoon(platoon)
        return
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn SetShieldRechargeList():[A:"..platoon.army.id.."][P:"..platoon.id.."] Found ("..#possibleUnits..") units need recharge")
    end
    -- sort the table in case we have 2 or more entries
    if possibleUnits[1] and possibleUnits[2] then
        table.sort(possibleUnits, SortPossibleUnitsAscendingByAssisterValue)
    end
    return possibleUnits
end

---Sub function to set the target for shield recharge and path to the the work area
---@param builder table Unit class table. Contains functions and data for a unit
---@param possibleUnits table shield units that need recharge
---@return string Returns the next e(xecute)State for the builder
function subPlanSetRechargeTarget(builder, possibleUnits)
    local closestDistSquared = builder.platoon.ai.baseRadius * builder.platoon.ai.baseRadius
    local maxAssisterCount = 20
    local pos, distSquared, path, info
    builder.ai.buildRange = builder.tp.construction.range or 6
    builder.ai.highestDist = false
    builder.ai.targetProgress = 0
    -- get the unit with the lowest assister count and repair it
    for i, unitNeedRecharge in pairs(possibleUnits) do
        if not unitNeedRecharge.dead then
            pos = unitNeedRecharge:GetPosition()
            distSquared = Distance2DSquared(builder:GetPosition().x, builder:GetPosition().z, pos.x, pos.z)
            if distSquared < closestDistSquared and unitNeedRecharge.assister <= maxAssisterCount then
                closestDistSquared = distSquared
                maxAssisterCount = unitNeedRecharge.assister
                builder.unitBeingRecharge = unitNeedRecharge
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetRechargeTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] assign closest unitNeedRecharge.["..unitNeedRecharge.id.index.."] assisters ("..unitNeedRecharge.assister..").")
                end
            else
                if builder.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanSetRechargeTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitNeedRecharge is too far away ("..math.sqrt(distSquared)..") or has to many assisters ("..unitNeedRecharge.assister..").")
                end
            end
        else
            AILog("- WARNING: Fn subPlanSetRechargeTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] unitNeedRecharge is not a valid unit")
        end
    end
    if builder.unitBeingRecharge then
        path, info = AIMarkerGenerator.GeneratePathTo(builder.army.id, builder:GetPosition(), builder.unitBeingRecharge:GetPosition(), builder.platoon.ai.movementLayer, true)
        if path then
            -- set variables for the next task
            builder.ai.path = path
            builder.ai.buildRange = builder.tp.construction.range or 6
            builder.ai.lastPosition = false
            builder.ai.highestDist = false
            builder.unitBeingRecharge.assister = builder.unitBeingRecharge.assister + 1
            return "StartMoveToDestination"
        end
        -- ToDo: Transport engineer to destination, for now just block the buildplace
        if builder.platoon.ai.formerTable.DebugPlatoon then
            AILog("- WARNING: Fn subPlanSetRechargeTarget():[A:"..builder.army.id.."][P:"..builder.platoon.id.."][U:"..builder.id.index.."] Builder has no path to assist unit, need Transport!.")
        end
        if lobbyOptionsAI.debugUnitEState then
            builder.ai.orderText = "No path, need transport! ["..builder.unitBeingRecharge.."]"
        end
    end
    builder.unitBeingRecharge = nil
    return "Disband"
end

---Sub function to start shield recharge
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartToRecharge(builder)
    -- did we reserve eco while moving to the buildplace?
    if builder.ai.reservedEco then
        builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
    end
    -- Host shields regenerate themselves; no engineer recharge order or work routine exists.
    builder.unitBeingRecharge = nil
    return "Disband"
end

---Sub function that waits for finishing the shield recharge
---@param builder table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanRecharging(builder)
    -- Do not simulate an unsupported host action by changing unit health.
    return subPlanStartToRecharge(builder)
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------- Upgrade Structure ----------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing Upgrade orders for structures.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planUpgradeStructure(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    -- get units from the former NeedMobileBuilder table
    local useUnit, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedUpgradeableUnit(armyIndex, baseName, formerTable)
    -- disband the platoon if we don't have any units for it
    if not useUnit then
        if formerTable.DebugPlatoon then
            AILog("* Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."] No unit for upgrade found")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."] Possible useable Upgradeableunit = ("..#useUnit..")")
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useUnit, "planUpgradeStructure")
    -- remove as much units as we need to stay at base
    useUnit = RemoveReservedUnits(useUnit, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    if #useUnit < 1 then
        if formerTable.DebugPlatoon then
            AILog("* Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."] No unit for upgrade found")
        end
        ExitPlatoon(platoon)
        return
    end
    -- remove unit over the max limit
    useUnit = RemoveOverMaxBuilder(useUnit, maxUnits)
    if formerTable.DebugPlatoon then
        AILog("* Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."] actual useable Upgradeableunit = ("..#useUnit..")")
    end
    -- assign units to this platton
    platoon:AssignUnits(useUnit)
    useUnit = nil
    -- Upgrade all units in platoon
    while Armies[armyIndex]:PlatoonExists(platoon) do
        for i, unit in pairs(platoon:GetUnits()) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..unit.id.index.."] [eState] = "..repr(unit.ai.eState)..".")
            end
            if not IsValidPlatoonUnit(unit) then
                AILog("- WARNING: Fn planUpgradeStructure():[A:"..unit.army.id.."][U:"..unit.id.index.."] unit is not a valid platoon unit!")
            elseif not unit.ai.eState then
                unit.ai.eState = subPlanStartUpgrade(unit)
            elseif unit.ai.eState == "Upgrading" then
                unit.ai.eState = subPlanUpgrading(unit)
            elseif unit.ai.eState == "Disband" then
                if formerTable.DebugPlatoon then
                    AILog("* Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..unit.id.index.."] eState = ["..unit.ai.eState.."]")
                end
                if lobbyOptionsAI.debugUnitEState then
                    unit.ai.orderText = "disband from upgrade platoon"
                end
                -- Detach AI ownership without issuing Stop: a queue accepted
                -- between selection and dispatch still belongs to the engine.
                if not RushReliability.Working(unit) then
                    ClearUnitTemporaryPlatoonData(unit, "planUpgradeStructure")
                else unit.ai.eState=nil end
                platoon:OnUnitRemoved(unit)
            else
                AILog("- WARNING: Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..unit.id.index.."] unknown unit eState ??? ["..repr(unit.ai.eState).."]")
            end
        end
        if platoon:GetNumOfUnits()==0 then break end
        WaitTicks(10)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planUpgradeStructure")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from upgrade platoon (finished)"
        end
    end
    -- disband the units from this platoon
    if formerTable.DebugPlatoon then
        AILog(" Fn planUpgradeStructure():[A:"..armyIndex.."][P:"..platoon.id.."] DisbandPlatoon!")
    end
    ExitPlatoon(platoon)
end

---Sub function to start unit upgrade
---@param unit table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the unit
function subPlanStartUpgrade(unit)
    return RushReliability.StartUpgrade(unit)
end

-- Native queue acceptance, not target HP, defines whether paid work is alive.
function subPlanUpgrading(unit)
    return RushReliability.UpdateUpgrade(unit)
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------- Build in Factory -----------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing build orders for factories.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planBuildInFactory(platoon, armyIndex, baseName, formerTable)
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."] Base: ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    -- get units and assign them to the platoon
    local useFactory, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedFactory(armyIndex, baseName, formerTable)
    if not useFactory then
        AILog("- WARNING: Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."] Base: "..baseName..", Former ("..formerTable.FormerName.."), AIPlan ["..formerTable.AIPlan.."] no factory found! (need more factories)")
        ExitPlatoon(platoon)
        return
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(useFactory, "planBuildInFactory")
    -- remove as much units as we need to stay at base
    useFactory = RemoveReservedUnits(useFactory, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    if #useFactory < 1 then
        AILog("- WARNING: Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."] Base: "..baseName..", Former ("..formerTable.FormerName.."), AIPlan ["..formerTable.AIPlan.."] no factory left! (need more factories)")
        ExitPlatoon(platoon)
        return
    end
    -- remove unit over the max limit
    useFactory = RemoveOverMaxBuilder(useFactory, maxUnits)
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."] Possible useable Factories = ("..#useFactory..")")
    end
    -- assign units to this platton
    platoon:AssignUnits(useFactory)
    useFactory = nil
    -- what do we want to build ?
    if formerTable.SelectHighestTechBuildable then
        -- Panic production is selected per factory so upgraded factories do
        -- not get stuck with a random unit from the wrong technology tier.
        platoon.ai.unitBuildList = formerTable.WantUnits
    else
        platoon.ai.unitBuildList = AIFunctions.GetWantUnits(armyIndex, baseName, formerTable)
    end
    if not platoon.ai.unitBuildList or not platoon.ai.unitBuildList[1] then
        if formerTable.DebugPlatoon then
            AILog("* Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."] Found no unitBuildList to build (no unit or eco)")
        end
        ExitPlatoon(platoon)
        return
    end
    if formerTable.DebugPlatoon then
        AILog("* Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."] unitBuildList:"..repr(platoon.ai.unitBuildList))
    end
    -- build loop
    while Armies[armyIndex]:PlatoonExists(platoon) do
        for i, factory in pairs(platoon:GetUnits()) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..factory.id.index.."] [eState] = "..repr(factory.ai.eState)..".")
            end
            -- Disable repeatBuild
            if factory:GetRepeatBuild() then
                AILog("- WARNING: Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..factory.id.index.."] Factory has repeatBuild = true!?!.")
                factory:SetRepeatBuild(false)
            end
            -- Advance ready state transitions in this pass; productive
            -- native work still sleeps at the existing polling cadence.
            for transition=1,4 do
                local unitAI,platoonAI=factory.ai,platoon.ai
                if not RushReliability.CurrentAssignment(factory,Armies[armyIndex],platoon,unitAI,platoonAI) then break end
                local previousState=unitAI.eState
                if not IsValidPlatoonUnit(factory) then
                    AILog("- WARNING: Fn planBuildInFactory():[A:"..factory.army.id.."][U:"..factory.id.index.."] factory is not a valid platoon unit!")
                elseif not factory.ai.eState then
                    local baseInPanic = AIFunctions.IsStrategyActive(armyIndex, baseName, "EnemyInLandPanicZone")
                        or AIFunctions.IsStrategyActive(armyIndex, baseName, "EnemyInAirPanicZone")
                        or AIFunctions.IsStrategyActive(armyIndex, baseName, "EnemyInNavalPanicZone")
                    local openingEconomyFocus = AIFunctions.IsStrategyActive(armyIndex, baseName, "OpeningEconomyFocus")
                    if baseInPanic and not formerTable.PanicProduction then
                        factory.ai.eState = "Disband"
                    elseif not baseInPanic and openingEconomyFocus and not formerTable.OpeningEconomyProduction then
                        factory.ai.eState = "Disband"
                    else
                        RushReliability.ApplyBuilderStep(factory,platoon,subPlanStartProducing)
                    end
                elseif factory.ai.eState == "WaitProductionStart" then
                    RushReliability.ApplyBuilderStep(factory,platoon,subPlanWaitProductionStart)
                elseif factory.ai.eState == "Producing" then
                    RushReliability.ApplyBuilderStep(factory,platoon,subPlanProducing)
                elseif factory.ai.eState == "Disband" then
                    if lobbyOptionsAI.debugUnitEState then
                        factory.ai.orderText = "disband from producing platoon"
                    end
                    ClearUnitTemporaryPlatoonData(factory, "planBuildInFactory")
                    platoon:RemoveUnits({factory})
                else
                    AILog("- WARNING: Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..factory.id.index.."] unknown factory eState ??? ["..repr(factory.ai.eState).."]")
                end
                if not RushReliability.CurrentAssignment(factory,Armies[armyIndex],platoon,unitAI,platoonAI)
                    or previousState==unitAI.eState then break end
            end
        end
        WaitTicks(10)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planBuildInFactory")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from upgrade platoon (finished)"
        end
    end
    -- disband the units from this platoon
    if formerTable.DebugPlatoon then
        AILog(" Fn planBuildInFactory():[A:"..armyIndex.."][P:"..platoon.id.."] DisbandPlatoon!")
    end
    ExitPlatoon(platoon)
end

---Selects the highest-tier affordable-role template that this exact factory can build.
---Wanted lines remain ordered, so a tank line can fall back to bots or other direct-fire units.
---@param factory table Factory unit
---@param wantedLines table Ordered tag expressions from the former
---@return string|nil templateId
local function GetHighestTechBuildableFactoryUnit(factory, wantedLines)
    local factionTemplates = factory.factionTag and Tags[factory.factionTag]
    if not factionTemplates then return nil end

    for _, wantedLine in ipairs(wantedLines or {}) do
        local selectedId
        local selectedTech = -1
        local selectedBuildTime = math.huge
        for tpId in pairs(wantedLine) do
            if AvailableUnits[tpId]
                and factionTemplates[tpId]
                and not (Tags.DEMO_UI_ONLY and Tags.DEMO_UI_ONLY[tpId])
                and buildQueueUtils.CanBuild(factory, tpId)
            then
                local template = UnitTemplates[tpId]
                local general = template and template.general or {}
                local economy = template and template.economy or {}
                local tech = general.techNumber
                    or (Tags.TECH4[tpId] and 4)
                    or (Tags.TECH3[tpId] and 3)
                    or (Tags.TECH2[tpId] and 2)
                    or 1
                local buildTime = economy.buildTime or math.huge
                if tech > selectedTech
                    or tech == selectedTech and buildTime < selectedBuildTime
                    or tech == selectedTech and buildTime == selectedBuildTime
                        and (not selectedId or tpId < selectedId)
                then
                    selectedId = tpId
                    selectedTech = tech
                    selectedBuildTime = buildTime
                end
            end
        end
        if selectedId then return selectedId end
    end
end

---Sub function to start production in factory
---@param unit table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the unit
function subPlanStartProducing(unit)
    local platoon = unit.platoon
    local ai = platoon.ai
    local formerTable = ai.formerTable
    local unitBuildList = ai.unitBuildList
    local factionTag = unit.factionTag
    local armyId = unit.army.id
    local platoonId = platoon.id
    local unitIndex = unit.id.index
    --check if we build a single unit or a template with different units
    local NextFactionUnittpId
    if formerTable.SelectHighestTechBuildable then
        local selectedId = GetHighestTechBuildableFactoryUnit(unit, formerTable.WantUnits)
        if selectedId then
            NextFactionUnittpId = {}
            NextFactionUnittpId[factionTag] = selectedId
        end
    elseif formerTable.SequentialTemplateBuild then
        -- Keep the selected entry until native acceptance. An economy dip
        -- must not silently consume part of a finite production template.
        if unitBuildList[1] then
            NextFactionUnittpId = unitBuildList[1]
        else
        -- we have no unit left in unitBuildList, so we disband the factory
            return "Disband"
        end
    else
        --Singe build. Get the first (and normaly the only) unit from the list.
        NextFactionUnittpId = unitBuildList[1]
    end
    -- do we have a unit that can be build from the current factory?
    local factionTemplateId = NextFactionUnittpId and NextFactionUnittpId[factionTag]
    if factionTemplateId then
        -- do we have a buildable unit for this factory?
        if buildQueueUtils.CanBuild(unit, factionTemplateId) then
            -- check if we have the ECO to start a production
            if ( type(formerTable.AllowEcoStorageDrain) == "number" and AIFunctions.IsEcoStorageDrainAllowed(unit, formerTable.AllowEcoStorageDrain, factionTemplateId) )
            or ( type(formerTable.AllowEcoStorageDrain) ~= "number" and ( formerTable.AllowEcoStorageDrain or AIFunctions.IsBuildableWithoutEconStorageDrain(armyId, unit.tpId, factionTemplateId) ) ) then
                if formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartProducing():[A:"..armyId.."][P:"..platoonId.."][U:"..unitIndex.."] Factory starting to build: ["..factionTemplateId.."] ("..repr(UnitTemplates[factionTemplateId].general.unitTypeName)..")")
                end
                if lobbyOptionsAI.debugUnitEState then
                    unit.ai.orderText = "Constructing ["..factionTemplateId.."] "..repr(UnitTemplates[factionTemplateId].general.unitTypeName)..""
                end

                -- reserve eco immediately so parallel factories do not pass the same eco check before the real build consumption starts
                AIFunctions.SetReserveEco(unit.army.id, unit.id.index, factionTemplateId, unit:GetPosition())
                unit:AddCallback(ClearReserveEcoCallback, "OnDestroyed")
                -- start producing
                if not buildQueueUtils.AddToBuildQueue(unit, factionTemplateId, buildQueueUtils.NewEntryIds(1)) then
                    unit:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
                    AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
                    return "Disband"
                end
                if formerTable.SequentialTemplateBuild and unitBuildList[1]==NextFactionUnittpId then
                    table.remove(unitBuildList,1)
                end
                -- if we don't have the eco and don't build a template then disband the factory
            elseif not formerTable.SequentialTemplateBuild then
                if formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartProducing():[A:"..armyId.."][P:"..platoonId.."][U:"..unitIndex.."] Factory disbanded due low eco")
                end
                if lobbyOptionsAI.debugUnitEState then
                    unit.ai.orderText = "disband from factory platoon (low eco)"
                end
                return "Disband"
            -- if we don't have the eco but building a template, delay the factory and wait for better eco
            else
                if formerTable.DebugPlatoon then
                    AILog("* Fn subPlanStartProducing():[A:"..armyId.."][P:"..platoonId.."][U:"..unitIndex.."] Factory builder delayed due low eco")
                end
                if lobbyOptionsAI.debugUnitEState then
                    unit.ai.orderText = "Delayed due low ECO"
                end
                return nil
            end
        else
            if formerTable.DebugPlatoon then
                AILog("- WARNING: Fn subPlanStartProducing():[A:"..armyId.."][P:"..platoonId.."][U:"..unitIndex.."] Factory CanBuild("..factionTemplateId..") = FALSE")
                AILog("- WARNING: Fn subPlanStartProducing():Please check [Tags] for [WantUnits] in former ["..formerTable.FormerName.."]")
            end
            if lobbyOptionsAI.debugUnitEState then
                unit.ai.orderText = "CanBuild("..factionTemplateId..") = FALSE"
            end
            return "Disband"
        end
        return "WaitProductionStart"
    else
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "Unable to build unit for factory faction"
        end
        --we can't build the unit. try the next one or disband
        if formerTable.SequentialTemplateBuild then
            if unitBuildList[1]==NextFactionUnittpId then table.remove(unitBuildList,1) end
            if formerTable.DebugPlatoon then
                AILog("- WARNING: Fn subPlanStartProducing():[A:"..armyId.."][P:"..platoonId.."][U:"..unitIndex.."] NextFactionUnittpId[factionTag] = nil -> next unit - Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
            end
            -- next unit
            return nil
        end
        if formerTable.DebugPlatoon then
            AILog("- WARNING: Fn subPlanStartProducing():[A:"..armyId.."][P:"..platoonId.."][U:"..unitIndex.."] NextFactionUnittpId[factionTag] = nil -> Disband - Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."]")
        end
        return "Disband"
    end
end

---Waits until factory production has actually started after a build queue change.
---@param unit table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the unit
function subPlanWaitProductionStart(unit)
    local target=unit.unitBeingBuilt or unit.productionBehaviorTargetUnit
    if target and not target.dead and not target:IsCompleted() then
        if unit.unitBeingBuilt and unit.ai.reservedEco then
            unit:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
            AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
        end
        return "Producing"
    end
    -- Native acceptance was synchronous. A remaining entry can wait for
    -- pause, cap or roll-off; an already consumed entry may have completed
    -- between observations. Neither case needs a second start countdown.
    if unit.buildQueue and next(unit.buildQueue) then return unit.ai.eState end
    if unit.ai.reservedEco then
        unit:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
    end
    return "Producing"
end

---Sub function to wait for production in factory finished
---@param unit table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the unit
function subPlanProducing(unit)
    if unit.unitBeingBuilt and unit.ai.reservedEco then
        unit:RemoveCallback(ClearReserveEcoCallback,"OnDestroyed")
        AIFunctions.ClearReserveEco(unit.army.id,unit.id.index)
    end
    local productionTarget = unit.productionBehaviorTargetUnit
    if not unit.unitBeingBuilt and unit.productionBehaviorIsActive and productionTarget and not productionTarget.dead and not productionTarget:IsCompleted() then
        -- Production behavior survives a paused build routine.
        return unit.ai.eState
    end
    if not unit.unitBeingBuilt then
        if unit.buildQueue and next(unit.buildQueue) then return unit.ai.eState end
        if unit.platoon.ai.formerTable.SequentialTemplateBuild then
            if unit.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanProducing():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Finished building -> next unit")
            end
            if lobbyOptionsAI.debugUnitEState then
                unit.ai.orderText = "Finished build -> next unit"
            end
            -- next unit
            return nil
        end
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanProducing():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Finished building -> Disband")
        end
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "Finished build -> Disband"
        end
        return "Disband"
    elseif unit.unitBeingBuilt:IsCompleted() then
        if unit.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanProducing():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Factory has finished building: ["..unit.unitBeingBuilt.tpId.."] ("..repr(unit.unitBeingBuilt.tp.general.unitTypeName)..") (waiting for unitBeingBuilt == nil)")
        end
    end
    local health = 100 / unit.unitBeingBuilt:GetMaxHealth() * unit.unitBeingBuilt:GetHealth()
    if unit.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanProducing():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] Factory is building: ["..unit.unitBeingBuilt.tpId.."] ("..repr(unit.unitBeingBuilt.tp.general.unitTypeName)..") ("..health.."% health)")
    end
    return unit.ai.eState
end

--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
------------------------------------------------------------- Scout Map --------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------

---Executing scout orders for land and air scouts.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planScoutMap(platoon, armyIndex, baseName, formerTable)
    platoon.ai = {}
    platoon.ai.creationTime = GetFormatedGameTime()
    platoon.ai.formerTable = formerTable
    platoon.ai.baseName = baseName
    platoon.ai.basePosition = Armies[armyIndex].ai.bases[baseName].position
    if formerTable.DebugPlatoon then
        AILog("* Fn planScoutMap():[A:"..armyIndex.."][P:"..platoon.id.."] Base ["..baseName.."], Former ["..formerTable.FormerName.."], AIPlan ["..formerTable.AIPlan.."] started!")
    end
    -- get units and assign them to the platoon
    local scouts, minUnits, maxUnits, reserveForBase = AIFunctions.GetNeedUnits(armyIndex, baseName, formerTable)
    if not scouts[1] then
        AILog("- WARNING: Fn planScoutMap():[A:"..armyIndex.."][P:"..platoon.id.."] Base: "..baseName..", Former ("..formerTable.FormerName.."), AIPlan ["..formerTable.AIPlan.."] no scout found! (need more factories)")
        ExitPlatoon(platoon)
        return
    end
    -- Check if there are any variables left from a previous function
    CheckUnitsForLeftover(scouts, "planScoutMap")
    -- remove as much units as we need to stay at base
    scouts = RemoveReservedUnits(scouts, reserveForBase, Armies[armyIndex].ai.bases[baseName].position)
    if #scouts < 1 then
        AILog("- WARNING: Fn planScoutMap():[A:"..armyIndex.."][P:"..platoon.id.."] Base: "..baseName..", Former ("..formerTable.FormerName.."), AIPlan ["..formerTable.AIPlan.."] no scout found! (need more factories)")
        ExitPlatoon(platoon)
        return
    end
    -- remove unit over the max limit
    scouts = RemoveOverMaxBuilder(scouts, maxUnits)
    if formerTable.DebugPlatoon then
        AILog("* Fn planScoutMap():[A:"..armyIndex.."][P:"..platoon.id.."] Possible useable Factories = ("..#scouts..")")
    end
    -- assign units to this platton
    platoon:AssignUnits(scouts)
    scouts = nil
    -- build loop
    while Armies[armyIndex]:PlatoonExists(platoon) do
        --check if we need to assign more builders to the platoon.
        subPlanGetMoreScouts(platoon, maxUnits)
        for i, scout in pairs(platoon:GetUnits()) do
            if formerTable.DebugPlatoon then
                AILog("* Fn planScoutMap():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..scout.id.index.."] [eState] = "..repr(scout.ai.eState)..".")
            end
            if not IsValidPlatoonUnit(scout) then
                AILog("- WARNING: Fn planScoutMap():[A:"..scout.army.id.."][U:"..scout.id.index.."] scout is not a valid platoon unit!")
            elseif not scout.ai.eState then
                scout.ai.eState = subPlanInitScout(scout)
            elseif scout.ai.eState == "GetScoutTarget" then
                scout.ai.eState = subPlanGetScoutTarget(scout)
            elseif scout.ai.eState == "ReturnToBase" then
                scout.ai.eState = subPlanStartReturnToBase(scout)
            elseif scout.ai.eState == "MovingReturnToBase" then
                scout.ai.eState = subPlanMovingToDestination(scout, scout.destination, 4)
            elseif scout.ai.eState == "StartScoutingTarget" then
                scout.ai.eState = subPlanStartMoveToDestination(scout, nil) -- do not reserve eco here
            elseif scout.ai.eState == "MovingToDestination" then
                scout.ai.eState = subPlanMovingToDestination(scout, scout.destination, 4)
                scout.ai.eState = subPlanCheckForAlreadyScoutedDestination(scout)
            elseif scout.ai.eState == "MovingDestinationReached" then
                scout.ai.eState = subPlanDestinationScouted(scout)
            elseif scout.ai.eState == "Disband" then
                if lobbyOptionsAI.debugUnitEState then
                    scout.ai.orderText = "disband from scout platoon"
                end
                ClearUnitTemporaryPlatoonData(scout, "planScoutMap")
                platoon:RemoveUnits(UnitAsArray(scout))
            else
                AILog("- WARNING: Fn planScoutMap():[A:"..armyIndex.."][P:"..platoon.id.."][U:"..scout.id.index.."] unknown scout eState ??? ["..repr(scout.ai.eState).."]")
            end
        end
        WaitTicks(10)
    end
    -- remove unused variables from the unit
    for i, unit in pairs(platoon:GetUnits()) do
        ClearUnitTemporaryPlatoonData(unit, "planScoutMap")
        if lobbyOptionsAI.debugUnitEState then
            unit.ai.orderText = "disband from scout platoon (finished)"
        end
    end
    -- disband the units from this platoon
    if formerTable.DebugPlatoon then
        AILog(" Fn planScoutMap():[A:"..armyIndex.."][P:"..platoon.id.."] DisbandPlatoon!")
    end
    ExitPlatoon(platoon)
end

---Sub function to add more scouts to the platoon
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param maxUnits integer number of units that can be assigned to the platoon
---@return nil
function subPlanGetMoreScouts(platoon, maxUnits)
    local platoonUnitCount = platoon:GetNumOfUnits()
    local neededUnitCount = maxUnits - platoonUnitCount
    --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] Platoon has ("..platoonUnitCount.."/"..maxUnits..") units, and can use "..neededUnitCount.." additional units.")
    -- get units from the former NeedMobileBuilder table
    if neededUnitCount > 0 then
        local useScouts, _, _, reserveForBase = AIFunctions.GetNeedUnits(platoon.army.id, platoon.ai.baseName, platoon.ai.formerTable)
        if useScouts then
            --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] Found ("..#useScouts..") units ready to work")
            -- Check if there are any variables left from a previous function
            CheckUnitsForLeftover(useScouts, "subPlanGetMoreBuilders")
            -- remove as much units as we need to stay at base
            useScouts = RemoveReservedUnits(useScouts, reserveForBase, platoon.ai.basePosition)
            -- remove unit over the max limit
            useScouts = RemoveOverMaxBuilder(useScouts, maxUnits - platoonUnitCount)
            -- assign unts to platoon
            platoonUnitCount = table.getn(useScouts)
            --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] adding "..platoonUnitCount.." builders to the platoon")
            platoon:AssignUnits(useScouts)
        else
            --AILog("* Fn subPlanGetMoreBuilders():[A:"..platoon.army.id.."][P:"..platoon.id.."] No additional builder for platoon found")
        end
    end
    return
end

---Initialize scout variables
---@param scout table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanInitScout(scout)
    scout.scoutRadius = AIFunctions.GetActiveUnitIntelRadius(scout)
    if scout.scoutRadius <= 0 then
        AILog("- WARNING: Fn subPlanInitScout():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] scoutRadius = "..scout.scoutRadius)
    end
    scout.movementLayer = (RushMovementV18.UnitMovementLayer(scout) or "Land")
    if scout.platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanInitScout():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] scoutRadius = "..scout.scoutRadius)
    end
    --return "GetScoutTarget"
    scout.ai.eState = "GetScoutTarget"
    return subPlanGetScoutTarget(scout)
end

---Search for the grid cell that hasn't been scouted for the longest time
---@param scout table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanGetScoutTarget(scout)
    local scoutDestination, path, info
    scout.platoon.ai.cachedScoutTable = scout.platoon.ai.cachedScoutTable or false
    scout.platoon.ai.cachedScoutTableTick = scout.platoon.ai.cachedScoutTableTick or 0
    if not scout.platoon.ai.cachedScoutTable or GetGameTimeSeconds() - scout.platoon.ai.cachedScoutTableTick > 5 then
        local highPrioList, lowPrioList = AITargetManager.GetScoutTable(scout.army.id)
        scout.platoon.ai.cachedScoutTable = {highPrioList = highPrioList, lowPrioList = lowPrioList}
        scout.platoon.ai.cachedScoutTableTick = GetGameTimeSeconds()
    end
    local highPrioList = scout.platoon.ai.cachedScoutTable.highPrioList
    local lowPrioList = scout.platoon.ai.cachedScoutTable.lowPrioList
    local unitPosition = scout:GetPosition()
    --check highPrioList
    for i, location in pairs(highPrioList) do
        if scout.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] loop over highPrioList: "..i.." ("..location.id..")")
        end
        local _, terrainHeight = Engine.SampleTerrainHeight({x = location.x, y = 0, z = location.z})
        scoutDestination = {x = location.x, y = terrainHeight, z = location.z}
        if scout.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] check GetLastScoutBy for : ("..scoutDestination.x..","..scoutDestination.z..") ...")
        end
        -- is no scout on the way and we can path to the destination
        if not AITargetManager.GetLastScoutBy(scout.army.id, scoutDestination) then
            if scout.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] GetLastScoutBy for : ("..scoutDestination.x..","..scoutDestination.z..") is false, send scout!")
            end
            path, info = AIMarkerGenerator.GeneratePathTo(scout.army.id, unitPosition, scoutDestination, scout.movementLayer, true)
            if path then
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] path found highPrioList["..i.."] ("..location.id..") "..repr(info))
                end
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] scoutDestination "..repr(scoutDestination).." will be scouted from unit: "..scout.id.index)
                end
                AITargetManager.SetWillBeScoutedFrom(scout.army.id, scoutDestination, scout.id.index)
                if lobbyOptionsAI.debugUnitEState then
                    scout.ai.orderText = "scouting highPrioList"
                end
                -- exit the in pairs(highPrioList) loop, we found a path to a scout destination
                break
            else
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] no path found. info: ("..repr(info)..")")
                end
            end
        else
            if scout.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] GetLastScoutBy for : ("..scoutDestination.x..","..scoutDestination.z..") is true, no scout needed here.")
            end
        end
    end
    --check for areas that need scouting nearby
    if not path then
        scout.scoutRadius = AIFunctions.GetActiveUnitIntelRadius(scout)
        scoutDestination = AITargetManager.GetUnScoutedNearby(scout.army.id, unitPosition, scout.scoutRadius)
        if scoutDestination then
            if scout.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] get unscouted area nearby : ("..scoutDestination.x..","..scoutDestination.z..") sending scout.")
            end
            path, info = AIMarkerGenerator.GeneratePathTo(scout.army.id, unitPosition, scoutDestination, scout.movementLayer, true)
            if path then
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] path found. "..repr(info))
                end
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] scoutDestination "..repr(scoutDestination).." will be scouted from unit: "..scout.id.index)
                end
                AITargetManager.SetWillBeScoutedFrom(scout.army.id, scoutDestination, scout.id.index)
                if lobbyOptionsAI.debugUnitEState then
                    scout.ai.orderText = "scouting nearby"
                end
                -- exit the in pairs(highPrioList) loop, we found a path to a scout destination
            else
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] no path found. info: ("..repr(info)..")")
                end
            end
        end
    end
    --check lowPrioList
    if not path then
        for i, location in pairs(lowPrioList) do
            if scout.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] loop over lowPrioList: "..i.." ("..location.id..")")
            end
            local _, terrainHeight = Engine.SampleTerrainHeight({x = location.x, y = 0, z = location.z})
            scoutDestination = {x = location.x, y = terrainHeight, z = location.z}
            if scout.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] check GetLastScoutBy for : ("..scoutDestination.x..","..scoutDestination.z..") ...")
            end
            -- is no scout on the way and we can path to the destination
            if not AITargetManager.GetLastScoutBy(scout.army.id, scoutDestination) then
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] GetLastScoutBy for : ("..scoutDestination.x..","..scoutDestination.z..") is false, send scout!")
                end
                path, info = AIMarkerGenerator.GeneratePathTo(scout.army.id, unitPosition, scoutDestination, scout.movementLayer, true)
                if path then
                    if scout.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] path found lowPrioList["..i.."] ("..location.id..") "..repr(info))
                    end
                    if scout.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] scoutDestination "..repr(scoutDestination).." will be scouted from unit: "..scout.id.index)
                    end
                    AITargetManager.SetWillBeScoutedFrom(scout.army.id, scoutDestination, scout.id.index)
                    if lobbyOptionsAI.debugUnitEState then
                        scout.ai.orderText = "scouting lowPrioList"
                    end
                    -- exit the in pairs(lowPrioList) loop, we found a path to a scout destination
                    break
                else
                    if scout.platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] no path found. info: ("..repr(info)..")")
                    end
                end
            else
                if scout.platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] GetLastScoutBy for : ("..scoutDestination.x..","..scoutDestination.z..") is true, no scout needed here.")
                end
            end
        end
    end
    if path then
        if not scoutDestination then
            AILog("- WARNING: Fn subPlanGetScoutTarget():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] scoutDestination = nil!!!")
        end
        scout.ai.path = path
        scout.destination = scoutDestination
        --return "StartScoutingTarget"
        scout.ai.eState = "StartScoutingTarget"
        return subPlanStartMoveToDestination(scout, nil)
    end
    local distToBaseSquared = Distance2DSquared(unitPosition.x, unitPosition.z, scout.platoon.ai.basePosition.x, scout.platoon.ai.basePosition.z)
    if distToBaseSquared < 400 then
        return "GetScoutTarget"
    end
    return "ReturnToBase"
end

---Set a path back to the base
---@param scout table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanStartReturnToBase(scout)
    local basePosition = scout.platoon.ai.basePosition
    local path, info = AIMarkerGenerator.GeneratePathTo(scout.army.id, scout:GetPosition(), basePosition, scout.movementLayer, true)
    if path then
        if scout.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartReturnToBase():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] path found return to base")
        end
        if lobbyOptionsAI.debugUnitEState then
            scout.ai.orderText = "Returning to base"
        end
        HostClearOrder(UnitAsArray(scout))
        WaitTicks(3)
        scout.destination = basePosition
        for z, nodePos in pairs(path) do
            HostIssueOrder(OrderTasks.MOVE, UnitAsArray(scout), true, nodePos, nil) --orderTask, unitsArray, append, position, payload
        end
        return "MovingReturnToBase"
    else
        if scout.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartReturnToBase():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] no path to base found. info: ("..repr(info)..")")
        end
    end
    return "Disband"
end

---Check if our destination is still reserved for this scout
---@param scout table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanCheckForAlreadyScoutedDestination(scout)
    local lastScoutUnitIndex = AITargetManager.GetLastScoutBy(scout.army.id, scout.destination)
    if lastScoutUnitIndex == scout.id.index then
        return scout.ai.eState
    end
    if not lastScoutUnitIndex then
        local lastScoutedTime = AITargetManager.GetLastScouted(scout.army.id, scout.destination)
        local lastScoutOrderTime = AITargetManager.GetLastScoutOrder(scout.army.id, scout.destination)
        if lastScoutOrderTime and lastScoutedTime and lastScoutedTime >= lastScoutOrderTime then
            if scout.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanCheckForAlreadyScoutedDestination():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] destination was scouted by scout map update "..repr(scout.destination))
            end
        else
            if scout.platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanCheckForAlreadyScoutedDestination():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] destination scout reservation was cleared without confirmed scouting update "..repr(scout.destination))
            end
        end
    else
        if scout.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanCheckForAlreadyScoutedDestination():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] destination is reserved by another scout (U:"..lastScoutUnitIndex..") "..repr(scout.destination))
        end
    end
    HostClearOrder(UnitAsArray(scout))
    --return "GetScoutTarget"
    scout.ai.eState = "GetScoutTarget"
    return subPlanGetScoutTarget(scout)
end

---Remove WillBeScoutedFrom flag from soutmap
---@param scout table Unit class table. Contains functions and data for a unit
---@return string Returns the next e(xecute)State for the builder
function subPlanDestinationScouted(scout)
    if AITargetManager.GetLastScoutBy(scout.army.id, scout.destination) == scout.id.index then
        if scout.platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanDestinationScouted():[A:"..scout.army.id.."][P:"..scout.platoon.id.."][U:"..scout.id.index.."] clear scout plan for "..repr(scout.destination))
        end
        AITargetManager.SetWillBeScoutedFrom(scout.army.id, scout.destination, false)
    end
    --return "GetScoutTarget"
    scout.ai.eState = "GetScoutTarget"
    return subPlanGetScoutTarget(scout)
end

