---Executing attack orders for orbital units.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planAttackOrbitalLaser(platoon, armyIndex, baseName, formerTable)
    platoon.ai.formerTable = formerTable
    local satPos
    local realSatTargetUnit
    local targetAvailable
    local closestTarget
    local actualPriority
    local dist
    local closestTargetDist
--[[
        platoon:SetPrioritizedTargetList('Attack',
            {
                Tags.COMMAND,
                Tags.STRUCTURE * Tags.SHIELD * Tags.TECH4,
                Tags.STRUCTURE * Tags.SHIELD - Tags.TECH4,
                Tags.STRUCTURE * Tags.ECONOMIC * Tags.ENERGY_PRODUCTION * Tags.ALLOYS_PRODUCTION * Tags.TECH4,
                Tags.STRUCTURE * Tags.ARTILLERY * (Tags.TECH3 + Tags.TECH4),
                Tags.STRUCTURE * Tags.ORBITALSYSTEM,
                Tags.STRUCTURE * Tags.DEFENCE * Tags.ANTI_PROJECTILE * (Tags.TECH3 + Tags.TECH4),
                Tags.STRUCTURE * Tags.NUKE,
                Tags.MOBILE * Tags.TECH4 - Tags.AIR - Tags.INSIGNIFICANTUNIT,
                Tags.MOBILE * Tags.ENGINEER - Tags.COMMAND - Tags.ENGINEERING_STATION,
                Tags.STRUCTURE * Tags.ALLOYS_EXTRACTION,
                Tags.STRUCTURE * Tags.FACTORY,
                Tags.STRUCTURE * Tags.ENERGY_PRODUCTION,
                Tags.ALL_UNITS
            }
        )
]]--
    while true do
        -- assign all free satellites to this platoon
        local ownUnits = Armies[armyIndex].units
        for _, unit in pairs(ownUnits) do
--[[
            if unit.tp.hasTags.ORBITAL_LASER and unit:IsCompleted() and not unit.assignedToBase and not unit.platoon then
                platoon:AssignUnits(UnitAsArray(unit))
            end
--]]
        end

        WaitTicks(20)
        -- loop over every satellite and check if we need a new target, then attack it
--AILog("planAttackOrbitalLaser(): *****************************************************************************************************")
        for satIndex, sat in pairs(platoon:GetUnits()) do
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] search targets for sat "..satIndex)
            local satPos = sat:GetPosition()
            -- is the satellite free for a new target? or retarget after 60 seconds.
            if not IsAttackTargetAvailable(sat.actualTarget) or GetGameTimeSeconds() - sat.lastTargetting > 60 then
                -- reset the target if its dead or time for a new target
                sat.actualTarget = false
                -- loop over all targets
                for targetIndex, satTarget in pairs(Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.satelliteTargets or {}) do
                    if not satTarget.underWater then
                        local realSatTargetUnit = AIFunctions.GetEnemyUnitsAroundPosition(armyIndex, satTarget.pos, 1, satTarget.tags, true)[1]
                        if IsAttackTargetAvailable(realSatTargetUnit) then
                            -- check if the (unshielded) target is already targeted by a sat
                            local targetAvailable = true
                            if satTarget.protectedByShield < 1 or satTarget.priority < 50 then
                                for _, s in pairs(platoon:GetUnits()) do
                                    if realSatTargetUnit == s.actualTarget then
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] unprotected target is already attacked by another satellite"
                                        targetAvailable = false
                                        break -- break for for i, s in pairs(platoon:GetUnits()) do
                                    end
                                end
                            end
                            -- target is free or has shields
                            local closestTarget = false
                            if targetAvailable then
                                -- if the target is protected by shields or if the target has high priority, attack it.
                                if satTarget.protectedByShield >= 1 or satTarget.priority >= 50  then
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] protected target: priority: "..satTarget.priority.." - protectedByShield:"..satTarget.protectedByShield.." - shieldRadius: "..repr(satTarget.shieldRadius or 0).." - techCategory: "..repr(satTarget.techCategory or 0).." - distToBase: "..math.floor(satTarget.distToBase).." - name: "..satTarget.name.."" )
                                    closestTarget = realSatTargetUnit
                                else
                                    -- find the closest target for the satellite
                                    local actualPriority = satTarget.priority
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] search for targets with the same actualPriority "..actualPriority)
                                    local closestTargetDist = false
                                    for cI, cTarget in pairs(Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.satelliteTargets or {}) do
                                        if not cTarget.underWater and cTarget.protectedByShield < 1 then
                                            -- has the target the same priority?
                                            if cTarget.priority == actualPriority then
                                                -- check for the closest target
                                                local dist = Distance2D(cTarget.pos.x, cTarget.pos.z, satPos.x, satPos.z)
                                                if not closestTargetDist or dist < closestTargetDist then
                                                    local candidateSatTargetUnit = AIFunctions.GetEnemyUnitsAroundPosition(armyIndex, cTarget.pos, 1, cTarget.tags, true)[1]
                                                    if IsAttackTargetAvailable(candidateSatTargetUnit) then
                                                        -- check if the target is already attacked by an satellite
                                                        targetAvailable = true
                                                        for _, s in pairs(platoon:GetUnits()) do
                                                            if candidateSatTargetUnit == s.actualTarget then
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] actualPriority target is already attacked by another satellite")
                                                                targetAvailable = false
                                                                break -- break for _, s in pairs(platoon:GetUnits()) do
                                                            end
                                                        end
                                                        if targetAvailable then
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] possible target: priority: "..cTarget.priority.." - protectedByShield:"..cTarget.protectedByShield.." - shieldRadius: "..repr(cTarget.shieldRadius or 0).." - techCategory: "..repr(cTarget.techCategory or 0).." - distToSat: "..math.floor(dist).." - name: "..cTarget.name.."" )
                                                            closestTarget = candidateSatTargetUnit
                                                            closestTargetDist = dist
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] end searching for priority targets, actualPriority: "..actualPriority.." - dist:"..repr(closestTargetDist) )
                            if closestTarget then
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] attacking target:" )
                                -- attack closestTarget
                                --IssueOrder( { order = "Attack", units = {sat}, targetUnit = closestTarget.id, addToQueue = false } )
                                sat.actualTarget = closestTarget
                                sat.lastTargetting = GetGameTimeSeconds()
                                break
                            end
                        end
                    end
                end
            else
--AILog("planAttackOrbitalLaser(): [S:"..satIndex.."] Sat has already a target!")
            end -- if not sat.actualTarget
        end -- for satIndex, sat in pairs(platoon:GetUnits()) do
--AILog("planAttackOrbitalLaser(): -----------------------------------------------------------------------------------------------------")
    end
end

---Runs the artillery attack plan and assigns idle artillery to the platoon.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2", "NAVAL 5")
---@param formerTable table Former table from active AI modDirectory/formers folder
---@return nil
function planAttackArtillery(platoon, armyIndex, baseName, formerTable)
    platoon.ai.formerTable = formerTable
    local realArtyTargetUnit, allArtyHaveTarget
    local x, y, z
--[[
    platoon:SetPrioritizedTargetList('Attack',
        {
            Tags.COMMAND,
            Tags.STRUCTURE * Tags.SHIELD * Tags.TECH4,
            Tags.STRUCTURE * Tags.SHIELD - Tags.TECH4,
            Tags.STRUCTURE * Tags.ECONOMIC * Tags.ENERGY_PRODUCTION * Tags.ALLOYS_PRODUCTION * Tags.TECH4,
            Tags.STRUCTURE * Tags.ARTILLERY * (Tags.TECH3 + Tags.TECH4),
            Tags.STRUCTURE * Tags.ORBITALSYSTEM,
            Tags.STRUCTURE * Tags.DEFENCE * Tags.ANTI_PROJECTILE * (Tags.TECH3 + Tags.TECH4),
            Tags.STRUCTURE * Tags.NUKE,
            Tags.MOBILE * Tags.TECH4 - Tags.AIR - Tags.INSIGNIFICANTUNIT,
            Tags.ALL_UNITS
        }
    )
]]--
    while true do
        -- assign all free artilleries to this platoon
        local ownUnits = Armies[armyIndex].units
        for _, unit in pairs(ownUnits) do
            if unit.tp.hasTags.ARTILLERY and not unit.assignedToBase and not unit.platoon and unit:IsCompleted() then
                platoon:AssignUnits(UnitAsArray(unit))
            end
        end
        WaitTicks(20)
        if Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.artilleryTargets then
            for targetIndex, artyTarget in pairs(Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.artilleryTargets or {}) do
                if not artyTarget.underWater then
                    local realArtyTargetUnit = AIFunctions.GetEnemyUnitsAroundPosition(armyIndex, artyTarget.pos, 1, artyTarget.tags, true)[1]
                    if realArtyTargetUnit and not realArtyTargetUnit.CaptureInProgress and not realArtyTargetUnit.ReclaimInProgress then
                        allArtyHaveTarget = true
                        for artyIndex, arty in pairs(platoon:GetUnits()) do
                            if not arty.dead then
                                local artyPosition = arty:GetPosition()
                                local distanceToArtillery = Distance2D(artyPosition.x, artyPosition.z, artyTarget.pos.x, artyTarget.pos.z)
                                local artilleryMinRange = arty.tp.Weapon[1].MinRadius
                                local artilleryMaxRange = arty.tp.Weapon[1].MaxRadius
                                if not arty.dead and distanceToArtillery > artilleryMinRange and distanceToArtillery < artilleryMaxRange then
                                -- does the arty has a target ?
                                    if not arty.actualTarget or arty.actualTarget.dead or GetGameTimeSeconds() - arty.lastTargetting > 60 then
                                        --IssueOrder( { order = "Attack", units = {arty}, targetUnit = artyTarget.id, addToQueue = false } )
                                        arty.actualTarget = realArtyTargetUnit
                                        arty.lastTargetting = GetGameTimeSeconds()
                                        allArtyHaveTarget = false
                                    end
                                end
                            end
                        end
                        if allArtyHaveTarget then
                            break -- break for targetIndex, artyTarget in pairs(Armies[armyIndex].ai.targets.artilleryTargets) do
                        end
                    end
                end
            end
        end
    end
end

---Executing attack orders for strategic missiles.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param baseName string Name of the base. (e.g. "MAIN", "EXPANSION 3", "OUTPOST 2",  "NAVAL 5")
---@param formerTable table data from platoon formers located in the active AI modDirectory/formers folder
---@return nil
function planAttackNuke(platoon, armyIndex, baseName, formerTable)
    platoon.ai.formerTable = formerTable
    local mapSizeX, mapSizeZ = GetMapSize()
    local platoonUnits
    local LauncherFull
    local launcherReady
    local launcherCount
    local enemyAntiMissile
    local EnemyUnits
    local enemyTargetPositions
    local missileCount
    local EnemyTarget
    local NukeSiloAmmoCount
    local TargetPosition
    local realNukeTargetUnit
    local TargetPos
    local tooClose

    while true do
        ---------------------------------------------------------------------------------------------------
        -- assign all free nuke launchers to this platoon
        ---------------------------------------------------------------------------------------------------
        local ownUnits = Armies[armyIndex].units
        for _, unit in pairs(ownUnits) do
            if unit.tp.hasTags.NUKE and not unit.assignedToBase and not unit.platoon and unit:IsCompleted() then
                platoon:AssignUnits(UnitAsArray(unit))
            end
        end
        ---------------------------------------------------------------------------------------------------
        -- Count Launchers, set them to automode, count stored missiles
        ---------------------------------------------------------------------------------------------------
        local launcherFull = {}
        local launcherReady = {}
        local highMissileCountLauncherReady = {}
        local missileCount = 0
        local launcherCount = 0
        local highestMissileCount = 0
        local nukeSiloAmmoCount = 0
        local nukeLaunched = false
        WaitTicks(100)
        local platoonUnits = platoon:GetUnits()
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] While loop PULSE")
        end
        for _, launcher in pairs(platoonUnits) do
            -- We found a dead unit inside this platoon. Disband the platton; It will be reformed
            if not launcher or launcher.dead then
                ExitPlatoon(platoon)
                return
            end
            nukeSiloAmmoCount = launcher:GetNukeSiloAmmoCount() or 0
            if not highMissileCountLauncherReady.missileCount or highMissileCountLauncherReady.missileCount < nukeSiloAmmoCount then
                highMissileCountLauncherReady = {launcher}
                highMissileCountLauncherReady.missileCount = nukeSiloAmmoCount
            end
            -- check if the launcher is full:
            if nukeSiloAmmoCount > 0 then
                table.insert(launcherReady, launcher)
                missileCount = missileCount + nukeSiloAmmoCount
            end
            launcherCount = launcherCount + 1
            -- count experimental launcher seraphim
        end
        local enemyAntiMissile = AIFunctions.GetEnemyUnitsAroundPosition(armyIndex, {mapSizeX/2,0,mapSizeZ/2}, mapSizeX+mapSizeZ, Tags.STRUCTURE * ((Tags.DEFENCE * Tags.ANTI_PROJECTILE * Tags.TECH3) + (Tags.SHIELD * Tags.TECH4)), true)
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] ************************************************************************************************")
        end
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] Checking for Targets. Launcher:("..launcherCount..") Ready:("..table.getn(launcherReady)..") - Missiles:("..missileCount..") - enemyAntiMissile:("..table.getn(enemyAntiMissile)..")")
        end
        -- don't check all nuke functions if we have no missile.
        if launcherCount < 1 or table.getn(launcherReady) < 1 then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] No launcher ready. Target search loop stoped")
            end
            nukeLaunched = true
        end
        ---------------------------------------------------------------------------------------------------
        -- Unprotected Target, launch a single nuke on primary targets.
        ---------------------------------------------------------------------------------------------------
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] Unprotected Target ")
        end
        if not nukeLaunched and Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.nukeTargets and table.getn(launcherReady) > 0 then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] launcherReady > 0")
            end
            for _, nukeTarget in pairs(Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.nukeTargets or {}) do
                if nukeTarget.protectedBySMD == 0 then
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] nuke targets: priority: "..nukeTarget.priority.." - protectedBySMD:"..nukeTarget.protectedBySMD.." - shieldRadius: "..(nukeTarget.shieldRadius or 0).." - name: "..nukeTarget.name.."")
                    end
                    local realNukeTargetUnit = false
                    if nukeTarget.name ~= "EcoValue" then
                        realNukeTargetUnit = AIFunctions.GetEnemyUnitsAroundPosition(armyIndex, nukeTarget.pos, 1, nukeTarget.categories, true)[1]
                    end
                    if realNukeTargetUnit and not realNukeTargetUnit.dead or nukeTarget.name == "EcoValue" then
                        if platoon.ai.formerTable.DebugPlatoon then
                            AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] Found a real target ("..repr(realNukeTargetUnit ~= nil)..") or EcoValue ("..repr(nukeTarget.name == "EcoValue")..")")
                        end
                        -- Only shoot if the target is not protected by antimissile or experimental shields
                        local targetPosition = false
                        if nukeTarget.name ~= "EcoValue" and realNukeTargetUnit.tp.hasTags.MOBILE and realNukeTargetUnit.tp.hasTags.TECH4 then
                            -- Lead target function for moving units
                            if platoon.ai.formerTable.DebugPlatoon then
                                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] LeadNukeTarget")
                            end
                            if table.getn(highMissileCountLauncherReady) > 1 then
                                targetPosition = LeadNukeTarget(platoon, armyIndex, highMissileCountLauncherReady, realNukeTargetUnit)
                            else
                                targetPosition = LeadNukeTarget(platoon, armyIndex, launcherReady, realNukeTargetUnit)
                            end
                        else
                            if platoon.ai.formerTable.DebugPlatoon then
                                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] Unleaded NukeTarget")
                            end
                            targetPosition = nukeTarget.pos
                        end
                        if targetPosition then
                            if platoon.ai.formerTable.DebugPlatoon then
                                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] TargetPos: ("..targetPosition.x..", "..targetPosition.z..")")
                            end
                            -- Only shoot if we are not damaging our own structures
                            if AIFunctions.GetNumUnitsAroundPosition(armyIndex, targetPosition, 32, Tags.STRUCTURE - Tags.TECH1, false) <= 3 then
                                if platoon.ai.formerTable.DebugPlatoon then
                                    AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] no friendly units in range.")
                                end
                                if NukeSingleAttack(platoon, armyIndex, highMissileCountLauncherReady, targetPosition) then
                                    nukeLaunched = true
                                    if platoon.ai.formerTable.DebugPlatoon then
                                        AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] FIRE highMissileCountLauncherReady: priority: "..nukeTarget.priority.." - name: "..nukeTarget.name.."")
                                    end
                                elseif NukeSingleAttack(platoon, armyIndex, launcherReady, targetPosition) then
                                    nukeLaunched = true
                                    if platoon.ai.formerTable.DebugPlatoon then
                                        AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] FIRE launcherReady: priority: "..nukeTarget.priority.." - name: "..nukeTarget.name.."")
                                    end
                                else
                                    if platoon.ai.formerTable.DebugPlatoon then
                                        AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] Fn NukeSingleAttack did not fire! priority: "..nukeTarget.priority.." - name: "..nukeTarget.name.."")
                                    end
                                end
                            else
                                if platoon.ai.formerTable.DebugPlatoon then
                                    AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] Launcher cant fire; friendly units in range! cout: "..AIFunctions.GetNumUnitsAroundPosition(armyIndex, targetPosition, 32, Tags.STRUCTURE - Tags.TECH1, false))
                                end
                            end
                        else
                            if platoon.ai.formerTable.DebugPlatoon then
                                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] no TargetPos!")
                            end
                        end
                    else
                        AIWarn(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] No real target found", platoon.ai.formerTable.DebugPlatoon)
                    end
                    if nukeLaunched then
                        break
                    end
                else
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."]["..nukeTarget.name.."] is protected by SMD!")
                    end
                    -- targets are sorted with unprotected targets first. If we get the first protected target then we don't need to continue
                    break
                end
            end
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] Armies[armyIndex].ai.targets.nukeTargets = 0 or no launcher ready")
            end
        end
        ---------------------------------------------------------------------------------------------------
        -- Jericho! Check if we can attack multiple targets at the same time
        ---------------------------------------------------------------------------------------------------
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] Jericho ")
        end
        if not nukeLaunched and Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.nukeTargets and table.getn(launcherReady) > 0 then
            local enemyTargetPositions = {}
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] (Jericho) Searching for enemyTargetPositions")
            end
            for _, nukeTarget in pairs(Armies[armyIndex].ai.targets and Armies[armyIndex].ai.targets.nukeTargets or {}) do
                -- get position of the possible next target
                local tooClose = false
                -- loop over all already attacked targets
                for _, enemyTargetPosition in pairs(enemyTargetPositions) do
                    -- Check if the target is closer then 40 to an already attacked target
                    if Distance2DSquared(nukeTarget.pos.x,nukeTarget.pos.z,enemyTargetPosition.x,enemyTargetPosition.z) < (40)*(40) then
                        tooClose = true
                        break -- break out of the enemyTargetPositions loop
                    end
                end
                if not tooClose then
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] (Jericho) Adding Target ("..nukeTarget.name..") to target list")
                    end
                    table.insert(enemyTargetPositions, nukeTarget.pos)
                else
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] (Jericho) Target to close to other target in list ("..nukeTarget.name..")")
                    end
                end
            end
            ---------------------------------------------------------------------------------------------------
            -- Now, if we have targets start Jericho bombardment
            ---------------------------------------------------------------------------------------------------
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] (Jericho) Checking for Launcher:("..launcherCount..") Ready:("..table.getn(launcherReady)..") - Missiles:("..missileCount..") - Enemy Targets:("..table.getn(enemyTargetPositions)..")")
            end
            if enemyTargetPositions[1] then
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] Jericho!")
                end
                -- loop over all targets
                if NukeSingleAttack(platoon, armyIndex, launcherReady, enemyTargetPositions) then
                    nukeLaunched = true
                end
            end
        end
        ---------------------------------------------------------------------------------------------------
        -- Wait some seconds before we start the next missile
        ---------------------------------------------------------------------------------------------------
        if nukeLaunched == true then
            AIWarn(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] nuke launched, waiting for impact...", platoon.ai.formerTable.DebugPlatoon)
            WaitTicks(450)-- wait 45 seconds for the missile flight, then get new targets
            AIWarn(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] nuke should have reached the tearget, next loop.", platoon.ai.formerTable.DebugPlatoon)
        end
    end -- while true do
    AIWarn(" Fn planAttackNuke():[A:"..armyIndex.."][P:"..platoon.id.."] Function END", platoon.ai.formerTable.DebugPlatoon)
end

---Calculate impact position to shooting ahead of a moving target.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param launcher table Strategic missile launcher unit
---@param target table Enemy target unit
---@return table|false Position where we want to shoot at. Formated as {0,0,0}
LeadNukeTarget = function(platoon, armyIndex, launcher, target)
    local LauncherPos = launcher:GetPosition()
    local TargetPos
    -- Get target position in 1 second intervals.
    -- This allows us to get speed and direction from the target
    local TargetStartPosition=0
    local Target1SecPos=0
    local Target2SecPos=0
    local XmovePerSec=0
    local YmovePerSec=0
    local XmovePerSecCheck=-1
    local YmovePerSecCheck=-1
    -- Check if the target is runing straight or circling
    -- If x/y and xcheck/ycheck are equal, we can be sure the target is moving straight
    -- in one direction. At least for the last 2 seconds.
    local LoopSaveGuard = 0
    if platoon.ai.formerTable.DebugPlatoon then
        AILog(" Fn LeadNukeTarget():[A:"..armyIndex.."][P:"..platoon.id.."] START Loop")
    end
    while target and not target.dead and (XmovePerSec ~= XmovePerSecCheck or YmovePerSec ~= YmovePerSecCheck) and LoopSaveGuard < 10 do
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn LeadNukeTarget():[A:"..armyIndex.."][P:"..platoon.id.."] START Loop no:"..LoopSaveGuard)
        end
        if not target or target.dead then return false end
        -- 1st position of target
        TargetStartPosition = target:GetPosition()
        WaitTicks(10)
        -- 2nd position of target after 1 second
        Target1SecPos = target:GetPosition()
        XmovePerSec = (TargetStartPosition.x - Target1SecPos.x)
        YmovePerSec = (TargetStartPosition.z - Target1SecPos.z)
        WaitTicks(10)
        -- 3rd position of target after 2 seconds to verify straight movement
        Target2SecPos = target:GetPosition()
        XmovePerSecCheck = (Target1SecPos.x - Target2SecPos.x)
        YmovePerSecCheck = (Target1SecPos.z - Target2SecPos.z)
        --We leave the while-do check after 10 loops (20 seconds) and try collateral damage
        --This can happen if a player try to fool the targetingsystem by circling a unit.
        LoopSaveGuard = LoopSaveGuard + 1
    end
    if not target or target.dead then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn LeadNukeTarget():[A:"..armyIndex.."][P:"..platoon.id.."] not target or target.dead")
        end
        return false
    end
    local NukeStart = 10
    local NukeLand = 5
    local FlightDistance = Distance2D(LauncherPos.x, LauncherPos.z, Target2SecPos.x, Target2SecPos.z)
    local MissileImpactTime = NukeStart + NukeLand + FlightDistance / 30
    if platoon.ai.formerTable.DebugPlatoon then
        AILog(" Fn LeadNukeTarget():[A:"..armyIndex.."][P:"..platoon.id.."] MissileImpactTime: "..MissileImpactTime)
    end
    -- Create missile impact corrdinates based on movePerSec * MissileImpactTime
    local MissileImpactX = Target2SecPos.x - (XmovePerSec * MissileImpactTime)
    local MissileImpactY = Target2SecPos.z - (YmovePerSec * MissileImpactTime)
    if LoopSaveGuard >=9 and TargetPos then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn LeadNukeTarget():[A:"..armyIndex.."][P:"..platoon.id.."] LoopSaveGuard: "..LoopSaveGuard)
        end
        return TargetPos
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog(" Fn LeadNukeTarget():[A:"..armyIndex.."][P:"..platoon.id.."] TargetPos: ("..MissileImpactX..", "..MissileImpactY..")")
    end
    return {MissileImpactX, Target2SecPos[2], MissileImpactY}
end

---Launch a single nuke to attack a single enemy target.
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param Launchers table Strategic missile launcher units
---@param EnemyTargetPosition table Position of the enemy target
---@return boolean|nil Returns true if we fired a nuke
NukeSingleAttack = function(platoon, armyIndex, Launchers, EnemyTargetPosition)
    if platoon.ai.formerTable.DebugPlatoon then
        AILog(" Fn NukeSingleAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Launcher count: "..table.getn(Launchers))
    end
    if table.getn(Launchers) <= 0 then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn NukeSingleAttack():[A:"..armyIndex.."][P:"..platoon.id.."] No Launcher ready.")
        end
        return false
    end
    -- loop over all nuke launcher
    for k, Launcher in pairs(Launchers) do
        if not Launcher or Launcher.dead then
            -- We found a dead unit inside this platoon. Disband the platton; It will be reformed
            ExitPlatoon(platoon)
            return
        end
        -- check if the target is closer then 20000
        LauncherPos = Launcher:GetPosition()
        if Distance2DSquared(LauncherPos.x,LauncherPos.z,EnemyTargetPosition.x,EnemyTargetPosition.z) < (20000)*(20000) then
            -- Attack the target
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn NukeSingleAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Attacking Enemy Position! ("..EnemyTargetPosition.x..", "..EnemyTargetPosition.z..")")
            end
            IssueNuke({Launcher}, EnemyTargetPosition)
            -- stop seraching for available launchers and check the next target
            return true
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn NukeSingleAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Target out of range. Skiped")
            end
        end
    end
    return false
end

---Launch all strategic missiles and distribute them to all enemy targets
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param armyIndex integer Index number of the army
---@param Launchers table Strategic missile launcher units
---@param enemyTargetPositions table Enemy target positions
---@return boolean|nil Returns true if we fired a nuke
NukeJerichoAttack = function(platoon, armyIndex, Launchers, enemyTargetPositions)
    if platoon.ai.formerTable.DebugPlatoon then
        AILog(" Fn NukeJerichoAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Launcher: "..table.getn(Launchers))
    end
    if table.getn(Launchers) <= 0 then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn NukeJerichoAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Launcher empty")
        end
        return false
    end
    local nukeLaunched = false
    for _, ActualTargetPos in pairs(enemyTargetPositions) do
        -- loop over all nuke launcher
        for k, Launcher in pairs(Launchers) do
            if not Launcher or Launcher.dead then
                -- We found a dead unit inside this platoon. Disband the platton; It will be reformed
                ExitPlatoon(platoon)
                return
            end
            -- check if the target is closer then 20000
            LauncherPos = Launcher:GetPosition()
            if Distance2DSquared(LauncherPos.x,LauncherPos.z,ActualTargetPos.x,ActualTargetPos.z) < (20000)*(20000) then
                -- Attack the target
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog(" Fn NukeJerichoAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Attacking Enemy Position!")
                end
                IssueNuke({Launcher}, ActualTargetPos)
                nukeLaunched = true
                -- remove the launcher from the table, so it can"t be used for the next target
                table.remove(Launchers, k)
                -- stop seraching for available launchers and check the next target
                break -- for k, Launcher in Launcher do
            else
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog(" Fn NukeJerichoAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Target out of range. Skiped")
                end
            end
        end
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn NukeJerichoAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Launcher after shoot: "..table.getn(Launchers))
        end
        if table.getn(Launchers) < 1 then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog(" Fn NukeJerichoAttack():[A:"..armyIndex.."][P:"..platoon.id.."] All Launchers are bussy! Break!")
            end
            -- stop seraching for targets, we don't hava a launcher ready.
            break -- for _, ActualTargetPos in enemyTargetPositions do
        end
    end
    if table.getn(Launchers) >= 1 then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog(" Fn NukeJerichoAttack():[A:"..armyIndex.."][P:"..platoon.id.."] Unused Launchers. Doing Jericho again...")
        end
        -- we have still launchers ready, let"s do Jericho attack again!
        NukeJerichoAttack(platoon, armyIndex, Launchers, enemyTargetPositions)
    end
    return nukeLaunched
end

---Unregister (disband) a platoon if it still exists
---@param platoon table Platoon class table. Contains functions and data for platoons
---@return nil
ExitPlatoon = function(platoon)
    if Armies[platoon.army.id]:PlatoonExists(platoon) then
        for i, unit in pairs(platoon:GetUnits()) do
            -- Construction exits can bypass individual arrival and finishing states.
            if platoon.ai.formerTable.AIPlan == "planBuildWithEngineer" then
                if not RushReliability.ReleaseConstructionQueueUnit(unit) then
                    HostClearOrder(UnitAsArray(unit))
                    ClearConstructionBuilderEconomyReservation(unit)
                end
            end
            ClearUnitTemporaryPlatoonData(unit, platoon.ai.formerTable.AIPlan)
            if lobbyOptionsAI.debugUnitEState then
                unit.ai.orderText = "disband from "..platoon.ai.formerTable.AIPlan.."."
            end
        end
        platoon.army:DisbandPlatoon(platoon)
    end
end

---Callback on units dead to clear saved eco requirement for building a unit
---@param unit table Unit class table. Contains functions and data for a unit
---@return nil
function ClearReserveEcoCallback(unit)
    AIFunctions.ClearReserveEco(unit.army.id, unit.id.index)
    return
end
---Release a construction engineer's approach reservation before its request or assignment ends.
---@param builder table Engineer whose construction reservation is no longer needed
---@return nil
function ClearConstructionBuilderEconomyReservation(builder)
    if builder.ai and builder.ai.reservedEco then
        builder:RemoveCallback(ClearReserveEcoCallback, "OnDestroyed")
        AIFunctions.ClearReserveEco(builder.army.id, builder.id.index)
    end
end

---Remove variables that are used to execute platoon functions
---@param unit table Unit class table. Contains functions and data for a unit
---@param functionName string Name of the AI function from where this was called
---@return nil
function ClearUnitTemporaryPlatoonData(unit, functionName)
    RushReliability.ReleaseConstructionQueueUnit(unit)
    unit.ai = unit.ai or {}
    unit.ai.rushAirOrders = nil
    unit.ai.rushMoveQueue = nil
    unit.ai.rushMoveSuspended = nil
    unit.ai.rushFleetMicroOrders = nil
    unit.ai.rushOrderlessSince = nil
    unit.ai.rushResumeAfter = nil
    unit.ai.rushMoveProgressAt = nil
    unit.ai.rushBuildMove = nil
    unit.ai.rushBuilderObservation = nil
    unit.ai.rushGenericMove = nil
    unit.ai.rushNoBuildOrdersSince = nil
    unit.ai.rushAlloyRetries = nil
    unit.ai.rushAlloySafetyAt = nil
    unit.ai.nextResourceSpot = nil
    unit.ai.pathDistanceToField = nil
    unit.ai.alloyConstructionTarget = nil
    if unit.unitBeingBuilt then
        AILog("- WARNING: Fn ClearUnitTemporaryPlatoonData():[U:"..unit.id.index.."] unit.unitBeingBuilt is not NIL, data was not cleared in "..functionName.." - checked at ["..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline.."]")
    end
    if unit.unitBeingAssist then
        AILog("- WARNING: Fn ClearUnitTemporaryPlatoonData():[U:"..unit.id.index.."] unit.unitBeingAssist is not NIL, data was not cleared in "..functionName.." - checked at ["..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline.."]")
        -- This AI-owned target belongs to the ended platoon, not the engineer's next assignment.
        unit.unitBeingAssist = nil
    end
    if unit.unitBeingRepaired then
        AILog("- WARNING: Fn ClearUnitTemporaryPlatoonData():[U:"..unit.id.index.."] unit.unitBeingRepaired is not NIL, data was not cleared in "..functionName.." - checked at ["..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline.."]")
    end
    if unit.unitNeedRepair then
        AILog("- WARNING: Fn "..functionName.."():[U:"..unit.id.index.."] unit.unitNeedRepair is not NIL (last Fn:"..repr(unit.ai.lastFunctionName)..")")
        unit.unitNeedRepair = nil
    end
    if unit.unitBeingReclaimed then
        AILog("- WARNING: Fn ClearUnitTemporaryPlatoonData():[U:"..unit.id.index.."] unit.unitBeingReclaimed is not NIL, data was not cleared in "..functionName.." - checked at ["..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline.."]")
    end
    if unit.unitBeingCaptured then
