    if unit.unitBeingRecharge then
        AILog("- WARNING: Fn ClearUnitTemporaryPlatoonData():[U:"..unit.id.index.."] unit.unitBeingRecharge is not NIL, data was not cleared in "..functionName.." - checked at ["..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline.."]")
