---Check if a unit is still a valid member of an platoon
---@param unit table Unit class table. Contains functions and data for a unit
---@return boolean Returns true if unit is valid platoon member
IsValidPlatoonUnit = function(unit)
    if not unit then
        local info = debug.getinfo(2)
        local functionName = info.short_src .. ":" .. info.currentline
        --AILog("- WARNING: Fn IsValidPlatoonUnit(): unit object table is empty (nil) - called from: "..functionName)
        return false
    elseif unit.dead then
        local info = debug.getinfo(2)
        local functionName = info.short_src .. ":" .. info.currentline
        --AILog("- WARNING: Fn IsValidPlatoonUnit():[A:"..unit.army.id.."][U:"..unit.id.index.."] unit.dead = true - called from: "..functionName)
        return false
    elseif not unit.platoon then
        local info = debug.getinfo(2)
        local functionName = info.short_src .. ":" .. info.currentline
        --AILog("- WARNING: Fn IsValidPlatoonUnit():[A:"..unit.army.id.."][U:"..unit.id.index.."] unit.platoon = false - called from: "..functionName)
        return false
    end
    return true
end

---Remove x number of units from the builder table so that they are available for other tasks at the base
---@param builders table units(mostly engineers) from a platoon
---@param reserveForBase integer number of units that should stay at base
---@param basePosition table Base position formated as {x=0,y=0,z=0}
---@return table units without those who should stay at base
RemoveReservedUnits = function(builders, reserveForBase, basePosition)
    if not reserveForBase or type(reserveForBase) ~= "number" then
        AILog("- WARNING: Fn RemoveReservedUnits(): reserveForBase is not a number "..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline)
        return builders
    end
    -- get the distance from base to the builder
    for i, builder in pairs(builders) do
        builder.ai.rangeToBuildLocation = Distance2DSquared( builder:GetPosition().x,  builder:GetPosition().z, basePosition.x, basePosition.z )
    end
    -- sort builders by range, closest first
    table.sort(builders, SortBuilderUnitsAscendingByRangeToBuildLocationValue)
    -- remove reserved builder that are closest to the base
    local returnTable = {}
    for i, builder in pairs(builders) do
        if i > reserveForBase then
            table.insert(returnTable, builder)
        end
        builder.ai.rangeToBuildLocation = nil
    end
    return returnTable
end

---Remove units from the builder table until we have x left
---@param builder table units(mostly engineers) from a platoon
---@param maxUnits integer number of units that should stay inside the platoon
---@return table units availale for the platoon
RemoveOverMaxBuilder = function(builder, maxUnits)
    if not maxUnits or type(maxUnits) ~= "number" then
        AILog("- WARNING: Fn RemoveOverMaxBuilder(): maxUnits is not a number "..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline)
        return builder
    end
    local returnTable = {}
    for i, builder in pairs(builder) do
        if i <= maxUnits then
            table.insert(returnTable, builder)
        end
    end
    return returnTable
end

---Remove units from the platoon until we have x left
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param builders table builder units sorted in the preferred retention order
---@param maxUnits integer number of units that should stay inside the platoon
---@return nil
RemoveOverMaxBuilderFromPlatoon = function(platoon, builders, maxUnits)
    if not maxUnits or type(maxUnits) ~= "number" then
        AILog("- WARNING: Fn RemoveOverMaxBuilderFromPlatoon(): maxUnits is not a number "..string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline)
        return
    end
    for i, builder in pairs(builders) do
        if i > maxUnits then
            ClearUnitTemporaryPlatoonData(builder, string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline)
            platoon:RemoveUnits(UnitAsArray(builder))
        end
    end
end

---Remove units from the platoon until we have "maxUnits" left based on assist range
---@param platoon table Platoon class table. Contains functions and data for platoons
---@param builders table units(mostly engineers) from a platoon
---@param maxUnits integer number of units that should stay inside the platoon
---@return nil
function RemoveOverMaxBuilderFromPlatoonByAssistRange(platoon, builders, maxUnits)
    table.sort(builders, SortBuilderUnitsAscendingByAssistRangeValue)
    for i, builder in pairs(builders) do
        if i > maxUnits then
            ClearUnitTemporaryPlatoonData(builder, string.gsub(debug.getinfo(2).short_src, "in file: ", "")..":"..debug.getinfo(2).currentline)
            platoon:RemoveUnits(UnitAsArray(builder))
        end
    end
end

---Create a text string representing braveness value in a percent bar
---@param value integer Braveness value
---@return string Returns a text string representing braveness value in a percent bar
function CreateBravenessBar(value)
    value = value + 10
    local bar = ''
    local count = 0
    for i = 1, value do
        if value <= 10 then
            bar = bar..'-'
        else
            bar = bar..'+'
        end
        count = count + 1
    end
    for i = count, 19 do
        bar = bar..' '
    end
    return "["..bar.."]"
end

-- Tactical movement changes must not erase mobile-factory production queues.
local ClearUnitOrders=Import("host/managers/orders/hostOrderManager.lua").ClearOrdersForUnit
local function ClearCombatOrders(units)
    for _,unit in pairs(units) do
        if not unit.dead and not unit.deleted then
            if RushMovementV18.Suspended(unit) then RushMovementV18.Forget(unit,true)
            else RushMovementV18.Forget(unit,false);ClearUnitOrders(unit) end
        end
    end
end

-- Path helpers may yield. Every commander caller retains its original lease.
local function CommanderRequest(platoon,commander)
    local army,data=platoon and platoon.army,platoon and platoon.ai
    commander=commander or platoon and platoon:GetUnits()[1]
    local armyAI,unitAI=army and army.ai,commander and commander.ai
    local function current()
        return army and armyAI and Armies[army.id]==army and army.ai==armyAI
            and platoon.army==army
            and RushReliability.CurrentAssignment(commander,army,platoon,unitAI,data)
    end
    local accepted={}
    local orders=commander and commander.orders or {}
    if orders.activeOrder then accepted[orders.activeOrder]=true end
    for _,order in pairs(orders.queuedOrders or {}) do accepted[order]=true end
    local function sameOrders()
        if not current() then return false end
        local native=commander.orders or {}
        if native.activeOrder and not accepted[native.activeOrder] then return false end
        for _,order in pairs(native.queuedOrders or {}) do
            if not accepted[order] then return false end
        end
        return true
    end
    return commander,data,current,sameOrders
end

local function CommanderLandOffenseAllowed(platoon)
    local settings=platoon.army.ai.settings
    local layers=settings and settings.useLayer
    return not layers or layers.land==true
end

local commanderShelterDirectionOffsets = {
    {x = 1, z = 0},
    {x = 0, z = 1},
    {x = -1, z = 0},
    {x = 0, z = -1},
}

---Checks whether a structure shield can currently protect the commander.
---@param shieldUnit table Shield structure
---@param shieldIndex integer Shield index
---@return boolean
local function IsCommanderShelterShieldUsable(shieldUnit,shieldIndex,army)
    if not RushReliability.Own(army,shieldUnit) or not shieldUnit:IsCompleted()
        or shieldUnit.CaptureInProgress or shieldUnit.ReclaimInProgress or not shieldUnit.shields
        or not shieldIndex or shieldIndex<1 or shieldIndex>shieldUnit:GetShieldCount() then return false end
    local shield=shieldUnit:GetShield(shieldIndex)
    local tp=shield and shield.tp;local radii=tp and tp.radii
    return shield and not shield.deleted and tp and tp.type=="Bubble" and radii
        and (radii.x or 0)>0 and (radii.y or radii.x)>0 and (radii.z or radii.x)>0
        and shield:IsEnabled() and shield:GetHealth()>0
end

local function CommanderShieldGeometry(shieldUnit,shieldIndex,commander)
    local shield=shieldUnit:GetShield(shieldIndex)
    local tp=shield.tp;local radii=tp.radii
    local center=RushMovementV18.Copy(shield:GetPosition())
    local footprint=commander.tp.footprint or {}
    local clearance=math.max(footprint.x or 0,footprint.y or 0)*0.5+1
    return center,math.min(radii.x,radii.z or radii.x)-clearance,radii.y or radii.x
end

local function CommanderIsSheltered(platoon,commander,position)
    local data=platoon.ai
    local pos=RushMovementV18.Copy(position or commander:GetPosition())
    local shieldUnit,shieldIndex=data.commanderShelterShieldUnit,data.commanderShelterShieldIndex
    if shieldUnit then
        if not IsCommanderShelterShieldUsable(shieldUnit,shieldIndex,platoon.army) then return false end
        local center,radius,height=CommanderShieldGeometry(shieldUnit,shieldIndex,commander)
        if radius<=0 then return false end
        local horizontal=Distance2DSquared(pos.x,pos.z,center.x,center.z)/(radius*radius)
        local vertical=(pos.y-center.y)/height
        return horizontal+vertical*vertical<=1
    end
    local radius=math.min(data.baseRadius or 30,40)
    return data.basePosition and Distance2DSquared(pos.x,pos.z,data.basePosition.x,data.basePosition.z)<=radius*radius
end

---Selects the strongest active structure shield inside the home base.
---@param platoon table Commander platoon
---@return table|nil shieldUnit
---@return integer|nil shieldIndex
local function SelectCommanderShelterShield(platoon)
    local bestShieldUnit
    local bestShieldIndex
    local bestShieldHealth
    local bestShieldDistanceSquared
    local commanderPosition = RushMovementV18.Copy(platoon:GetPosition())
    local basePosition = platoon.ai.basePosition
    local baseRadiusSquared = platoon.ai.baseRadius * platoon.ai.baseRadius
    for _, shieldUnit in pairs(Armies[platoon.army.id].units) do
        if not shieldUnit.dead and shieldUnit:IsCompleted() and shieldUnit.tp.hasTags.STRUCTURE and shieldUnit.tp.hasTags.SHIELD and shieldUnit.shields then
            local shieldUnitPosition = shieldUnit:GetPosition()
            if Distance2DSquared(basePosition.x, basePosition.z, shieldUnitPosition.x, shieldUnitPosition.z) <= baseRadiusSquared then
                for shieldIndex = 1, shieldUnit:GetShieldCount() do
                    if IsCommanderShelterShieldUsable(shieldUnit,shieldIndex,platoon.army) then
                        local shieldHealth = shieldUnit:GetShield(shieldIndex):GetHealth()
                        local shieldDistanceSquared = Distance2DSquared(commanderPosition.x, commanderPosition.z, shieldUnitPosition.x, shieldUnitPosition.z)
                        if not bestShieldHealth or shieldHealth > bestShieldHealth or shieldHealth == bestShieldHealth and shieldDistanceSquared < bestShieldDistanceSquared then
                            bestShieldUnit = shieldUnit
                            bestShieldIndex = shieldIndex
                            bestShieldHealth = shieldHealth
                            bestShieldDistanceSquared = shieldDistanceSquared
                        end
                    end
                end
            end
        end
    end
    return bestShieldUnit, bestShieldIndex
end

---Calculates travel time to the first protection in order: active home shield, then home base.
---@param platoon table Commander platoon
---@param commander table Commander unit
---@return number protectionTravelTime
---@return table protectionPosition
---@return string protectionType
local function GetCommanderProtectionTravelData(platoon, commander)
    local _,data,current=CommanderRequest(platoon,commander)
    if not current() then return end
    local commanderPosition=RushMovementV18.Copy(commander:GetPosition())
    local protectionPosition=RushMovementV18.Copy(data.basePosition)
    local protectionType="Base"
    local shieldUnit,shieldIndex=SelectCommanderShelterShield(platoon)
    if shieldUnit then
        local center,radius,height=CommanderShieldGeometry(shieldUnit,shieldIndex,commander)
        local dx,dz=commanderPosition.x-center.x,commanderPosition.z-center.z
        local distance=math.sqrt(dx*dx+dz*dz)
        if radius>0 then
            local candidate
            if distance<=radius then
                candidate=RushMovementV18.Copy(commanderPosition)
            elseif distance>0 then
                -- Leave room for the ACU's elevation inside the bubble.
                candidate={x=center.x+dx/distance*radius*0.85,y=center.y,z=center.z+dz/distance*radius*0.85}
                SnapToGround(candidate,candidate)
            end
            if candidate then
                local horizontal=Distance2DSquared(candidate.x,candidate.z,center.x,center.z)/(radius*radius)
                local vertical=(candidate.y-center.y)/height
                if horizontal+vertical*vertical<=1 then protectionPosition=candidate;protectionType="Shield" end
            end
        end
    end
    if Distance2DSquared(commanderPosition.x,commanderPosition.z,protectionPosition.x,protectionPosition.z)<=4 then
        return 0,protectionPosition,protectionType
    end
    local layer=data.movementLayer
    local request=RushMovementV18.Capture(platoon,{commander})
    local path=AIMarkerGenerator.GeneratePathTo(platoon.army.id,commanderPosition,protectionPosition,layer,true,0)
    if not current() or data.movementLayer~=layer then return end
    if (type(path)~="table" or #path==0) and protectionType=="Shield" then
        protectionPosition=RushMovementV18.Copy(data.basePosition)
        protectionType="Base"
        if Distance2DSquared(commanderPosition.x,commanderPosition.z,protectionPosition.x,protectionPosition.z)<=4 then
            return 0,protectionPosition,protectionType
        end
        path=AIMarkerGenerator.GeneratePathTo(platoon.army.id,commanderPosition,protectionPosition,layer,true,0)
        if not current() or data.movementLayer~=layer then return end
    end
    local distance=math.huge
    if type(path)=="table" and #path>0 then
        path=RushMovementV18.ShortenPath(platoon,commanderPosition,path,layer,0,request)
        if not current() or data.movementLayer~=layer then return end
        distance=0
        local previous=commanderPosition
        for _,node in ipairs(path) do
            distance=distance+Distance2D(previous.x,previous.z,node.x,node.z)
            previous=node
        end
    end
    -- Native GetPathDistance estimates grid steps, so it cannot price a
    -- shortened long leg or an unreachable shelter accurately.
    local speed=commander.tp.movement and commander.tp.movement.speed or 0
    return speed>0 and distance/speed or math.huge,protectionPosition,protectionType
end

---Calculates how long one enemy weapon can fire before the commander reaches protection.
---@param commanderPosition table Commander start position
---@param protectionPosition table Commander protection position
---@param protectionTravelTime number Seconds until protection
---@param enemyPosition table Enemy start position
---@param enemySpeed number Enemy movement speed
---@param weaponRange number Weapon range against land
---@return number
local function CalculateEnemyWeaponFiringDurationBeforeProtection(commanderPosition, protectionPosition, protectionTravelTime, enemyPosition, enemySpeed, weaponRange)
    if protectionTravelTime <= 0 then return 0 end
    if protectionTravelTime == math.huge then return math.huge end
    local commanderVelocityX = (protectionPosition.x - commanderPosition.x) / protectionTravelTime
    local commanderVelocityZ = (protectionPosition.z - commanderPosition.z) / protectionTravelTime
    local relativePositionX = commanderPosition.x - enemyPosition.x
    local relativePositionZ = commanderPosition.z - enemyPosition.z
    local quadraticA = commanderVelocityX * commanderVelocityX + commanderVelocityZ * commanderVelocityZ - enemySpeed * enemySpeed
    local quadraticB = 2 * (relativePositionX * commanderVelocityX + relativePositionZ * commanderVelocityZ - weaponRange * enemySpeed)
    local quadraticC = relativePositionX * relativePositionX + relativePositionZ * relativePositionZ - weaponRange * weaponRange
    local epsilon = 0.0001
    if math.abs(quadraticA) <= epsilon then
        if quadraticC <= 0 then
            if quadraticB <= 0 then return protectionTravelTime end
            return math.min(protectionTravelTime, math.max(0, -quadraticC / quadraticB))
        end
        if quadraticB >= 0 then return 0 end
        local firingStartTime = -quadraticC / quadraticB
        return firingStartTime < protectionTravelTime and protectionTravelTime - firingStartTime or 0
    end
    local discriminant = quadraticB * quadraticB - 4 * quadraticA * quadraticC
    if discriminant < 0 then return quadraticC <= 0 and protectionTravelTime or 0 end
    local discriminantRoot = math.sqrt(discriminant)
    local firstRoot = (-quadraticB - discriminantRoot) / (2 * quadraticA)
    local secondRoot = (-quadraticB + discriminantRoot) / (2 * quadraticA)
    if firstRoot > secondRoot then firstRoot, secondRoot = secondRoot, firstRoot end
    if quadraticC <= 0 then
        if quadraticA <= 0 then return protectionTravelTime end
        return math.min(protectionTravelTime, math.max(0, secondRoot))
    end
    local firingStartTime = firstRoot >= 0 and firstRoot or secondRoot
    if firingStartTime < 0 or firingStartTime >= protectionTravelTime then return 0 end
    local firingEndTime = quadraticA > 0 and math.min(protectionTravelTime, secondRoot) or protectionTravelTime
    return math.max(0, firingEndTime - firingStartTime)
end

---Projects damage from local and intercept-capable enemies until the commander reaches protection.
---@param platoon table Commander platoon
---@param commander table Commander unit
---@param commanderPosition table Commander start position
---@param protectionPosition table Commander protection position
---@param protectionTravelTime number Seconds until protection
---@param commanderSpeed number Commander movement speed
---@param enemyRecords table Current shared enemy-intel snapshot
---@return number expectedDamage
---@return integer attackingUnitCount
local function CalculateCommanderExpectedDamageUntilProtection(platoon, commander, commanderPosition, protectionPosition, protectionTravelTime, commanderSpeed, enemyRecords)
    local _,_,current=CommanderRequest(platoon,commander)
    if not current() then return 0,0 end
    local expectedDamage = 0
    local attackingUnitCount = 0
    local combatSupportDistance = 25
    for _, record in ipairs(enemyRecords) do
        local enemyUnit=record.unit
        if RushCombatIntel.Visible(platoon.army,enemyUnit) and enemyUnit:IsCompleted() then
            local enemyPosition = record.pos
            local enemySpeed = enemyUnit.tp.movement and enemyUnit.tp.movement.speed or 0
            local enemyMaximumWeaponRange = AIFunctions.GetUnitMaximumWeaponRangeByLayer(enemyUnit, "Land")
            local enemyLocalReach = enemyMaximumWeaponRange + combatSupportDistance
            local enemyDistanceToCommander = Distance2D(commanderPosition.x, commanderPosition.z, enemyPosition.x, enemyPosition.z)
            local enemyIsLocal = enemyDistanceToCommander <= enemyLocalReach
            local enemyClosingSpeed = enemySpeed - commanderSpeed
            local enemyTimeToCommanderSafetyRange = enemyClosingSpeed > 0 and (enemyDistanceToCommander - enemyLocalReach) / enemyClosingSpeed or math.huge
            local enemyCanIntercept = not enemyIsLocal and enemyClosingSpeed > 0 and enemyTimeToCommanderSafetyRange <= protectionTravelTime and (enemyUnit.tp.hasTags.AIR or AIMarkerGenerator.CanGraphAreaTo(enemyPosition, commanderPosition, (RushMovementV18.UnitMovementLayer(enemyUnit) or "Land")))
            if not current() then return 0,0 end
            local enemyExpectedDamage = 0
            if enemyIsLocal or enemyCanIntercept then
                for _, weapon in ipairs(enemyUnit.weapons or {}) do
                    if weapon.enabled and not weapon.isDeathExplosion and weapon:CanShootAt(commander) then
                        local weaponDamagePerSecond = AIFunctions.GetWeaponDamagePerSecond(weapon.tp)
                        if weaponDamagePerSecond > 0 then
                            local firingDuration = CalculateEnemyWeaponFiringDurationBeforeProtection(commanderPosition, protectionPosition, protectionTravelTime, enemyPosition, enemySpeed, weapon.tp.rangeMax or 0)
                            enemyExpectedDamage = enemyExpectedDamage + weaponDamagePerSecond * firingDuration
                        end
                    end
                end
            end
            if enemyExpectedDamage > 0 then
                expectedDamage = expectedDamage + enemyExpectedDamage
                attackingUnitCount = attackingUnitCount + 1
            end
        end
    end
    return expectedDamage, attackingUnitCount
end

---Returns the closest completed mobile enemy that can attack land inside the effective home panic zone.
---@param platoon table Commander platoon
---@return table|nil threatPosition
local function GetClosestCommanderShelterThreatPosition(platoon)
    local commanderPosition = RushMovementV18.Copy(platoon:GetPosition())
    local panicZoneRadius = AITargetManager.GetDangerZoneRadii(false)
    local closestThreatDistanceSquared
    local closestThreatPosition
    for _, enemyUnit in pairs(AIFunctions.GetEnemyUnitsOnMap(platoon.army.id)) do
        if RushCombatIntel.Visible(platoon.army,enemyUnit) and enemyUnit:IsCompleted() and enemyUnit.tp.hasTags.MOBILE then
            local enemyWeaponRange = AIFunctions.GetUnitMaximumWeaponRangeByLayer(enemyUnit, "Land")
            if enemyWeaponRange > 0 then
                local enemyPosition = enemyUnit:GetPosition()
                local effectivePanicZoneRadius = panicZoneRadius + enemyWeaponRange
                if Distance2DSquared(platoon.ai.basePosition.x, platoon.ai.basePosition.z, enemyPosition.x, enemyPosition.z) <= effectivePanicZoneRadius * effectivePanicZoneRadius then
                    local threatDistanceSquared = Distance2DSquared(commanderPosition.x, commanderPosition.z, enemyPosition.x, enemyPosition.z)
                    if not closestThreatDistanceSquared or threatDistanceSquared < closestThreatDistanceSquared then
                        closestThreatDistanceSquared = threatDistanceSquared
                        closestThreatPosition = RushMovementV18.Copy(enemyPosition)
                    end
                end
            end
        end
    end
    return closestThreatPosition
end

---Starts movement to the next reachable zigzag point around a center and favors the side away from a panic-zone threat.
---@param platoon table Commander platoon
---@param centerPosition table Movement center
---@param movementOffset number Distance from the center
---@param threatPosition table|nil Position to keep away from
---@return boolean
local function StartCommanderZigzagMovement(platoon, centerPosition, movementOffset, threatPosition)
    local commander,data,current=CommanderRequest(platoon)
    if not current() then return false,"stale-request" end
    centerPosition=RushMovementV18.Copy(centerPosition)
    local orderedDirectionIndices = {}
    if threatPosition then
        orderedDirectionIndices = {1, 2, 3, 4}
        table.sort(orderedDirectionIndices, function(firstDirectionIndex, secondDirectionIndex)
            local firstDirection = commanderShelterDirectionOffsets[firstDirectionIndex]
            local secondDirection = commanderShelterDirectionOffsets[secondDirectionIndex]
            local firstDistanceSquared = Distance2DSquared(centerPosition.x + firstDirection.x * movementOffset, centerPosition.z + firstDirection.z * movementOffset, threatPosition.x, threatPosition.z)
            local secondDistanceSquared = Distance2DSquared(centerPosition.x + secondDirection.x * movementOffset, centerPosition.z + secondDirection.z * movementOffset, threatPosition.x, threatPosition.z)
            return firstDistanceSquared == secondDistanceSquared and firstDirectionIndex < secondDirectionIndex or firstDistanceSquared > secondDistanceSquared
        end)
        if data.commanderShelterPointIndex == orderedDirectionIndices[1] then orderedDirectionIndices[1], orderedDirectionIndices[2] = orderedDirectionIndices[2], orderedDirectionIndices[1] end
    else
        local firstDirectionIndex
        if data.commanderShelterPointIndex then
            firstDirectionIndex = data.commanderShelterPointIndex + 1
        else
            local commanderPosition = platoon:GetPosition()
            local differenceX = commanderPosition.x - centerPosition.x
            local differenceZ = commanderPosition.z - centerPosition.z
            firstDirectionIndex = math.abs(differenceX) >= math.abs(differenceZ) and (differenceX >= 0 and 1 or 3) or (differenceZ >= 0 and 2 or 4)
        end
        for directionOffset = 0, table.getn(commanderShelterDirectionOffsets) - 1 do
            table.insert(orderedDirectionIndices, ((firstDirectionIndex + directionOffset - 1) % table.getn(commanderShelterDirectionOffsets)) + 1)
        end
    end
    for _, directionIndex in ipairs(orderedDirectionIndices) do
        local direction = commanderShelterDirectionOffsets[directionIndex]
        local candidatePosition = {x = centerPosition.x + direction.x * movementOffset, y = centerPosition.y, z = centerPosition.z + direction.z * movementOffset}
        local clampedPosition = RushMovementV18.Clamp(candidatePosition)
        candidatePosition.x = clampedPosition.x
        candidatePosition.y = clampedPosition.y
        candidatePosition.z = clampedPosition.z
        SnapToGround(candidatePosition, candidatePosition)
        if not data.commanderShelterShieldUnit or CommanderIsSheltered(platoon,commander,candidatePosition) then
            local moving,reason=InitMoveToDestination(platoon,candidatePosition)
            if not current() or reason=="stale-request" then return false,"stale-request" end
            if moving then
                data.commanderShelterPointIndex=directionIndex
                data.commanderShelterMovementActive=true
                data.commanderShelterProgress={goal=data.gatherPoint,position=RushMovementV18.Copy(commander:GetPosition()),at=GetGameTimeSeconds()}
                return true
            end
        end
    end
    return false
end

---Starts commander movement under an active shield or around the home base when no shield is available.
---@param platoon table Commander platoon
---@return boolean
local function StartCommanderShelterMovement(platoon)
    local commander,data,current=CommanderRequest(platoon)
    if not current() then return false,"stale-request" end
    local threatPosition = GetClosestCommanderShelterThreatPosition(platoon)
    local shieldUnit = data.commanderShelterShieldUnit
    local shieldIndex = data.commanderShelterShieldIndex
    if not IsCommanderShelterShieldUsable(shieldUnit,shieldIndex,platoon.army) then
        shieldUnit, shieldIndex = SelectCommanderShelterShield(platoon)
        data.commanderShelterShieldUnit = shieldUnit
        data.commanderShelterShieldIndex = shieldIndex
    end
    local commanderFootprint = commander.tp.footprint or {}
    local commanderHalfExtent = math.max(commanderFootprint.x or 0, commanderFootprint.y or 0) * 0.5
    if shieldUnit then
        local shieldCenterPosition,protectionRadius=CommanderShieldGeometry(shieldUnit,shieldIndex,commander)
        local shieldUnitFootprint = shieldUnit.tp.footprint or {}
        local shieldUnitHalfExtent = math.max(shieldUnitFootprint.x or 0, shieldUnitFootprint.y or 0) * 0.5
        local minimumMovementOffset = shieldUnitHalfExtent + commanderHalfExtent + 1
        local maximumMovementOffset = protectionRadius
        if maximumMovementOffset >= minimumMovementOffset then
            local moving,reason=StartCommanderZigzagMovement(platoon,shieldCenterPosition,
                (minimumMovementOffset+maximumMovementOffset)*0.5,threatPosition)
            if not current() or reason=="stale-request" then return false,"stale-request" end
            if moving then return true end
        end
        data.commanderShelterShieldUnit = nil
        data.commanderShelterShieldIndex = nil
    end
    local commanderWeaponRange = AIFunctions.GetUnitMaximumWeaponRangeByLayer(commander, "Land")
    local fallbackMovementOffset = math.min(35,(data.baseRadius or 70)*0.5,math.max(commanderWeaponRange*0.5,commanderHalfExtent*4))
    return StartCommanderZigzagMovement(platoon, data.basePosition, fallbackMovementOffset, threatPosition)
end

---Clears commander shelter movement state.
---@param platoon table Commander platoon
---@return nil
local function ClearCommanderShelterData(platoon)
    platoon.ai.commanderShelterShieldUnit = nil
    platoon.ai.commanderShelterShieldIndex = nil
    platoon.ai.commanderShelterPointIndex = nil
    platoon.ai.commanderShelterMovementActive = nil
    platoon.ai.commanderShelterProgress = nil
end

-- Retry an obstructed shelter point, while allowing long productive approaches.
local function CommanderShelterStalled(platoon,commander)
    local data=platoon.ai;local now=GetGameTimeSeconds()
    if commander.toggles and commander.toggles.Pause then
        if data.commanderShelterProgress then data.commanderShelterProgress.at=now end
        return false
    end
    local pos=RushMovementV18.Copy(commander:GetPosition())
    local watch=data.commanderShelterProgress
    if not watch or watch.goal~=data.gatherPoint then
        data.commanderShelterProgress={goal=data.gatherPoint,position=pos,at=now}
    elseif Distance2DSquared(pos.x,pos.z,watch.position.x,watch.position.z)>1 then
        watch.position,watch.at=pos,now
    elseif now-watch.at>=15 then
        watch.at=now
        return true
    end
    return false
end

---Checks whether every commander platoon unit reached the precise shelter movement point.
---@param platoon table Commander platoon
---@return boolean
local function CommanderShelterMovementReached(platoon)
    local destination = platoon.ai.gatherPoint
    if not destination then return true end
    for _, unit in pairs(platoon:GetUnits()) do
        if not unit.dead then
            local unitPosition = unit:GetPosition()
            if Distance2DSquared(unitPosition.x, unitPosition.z, destination.x, destination.z) > 4 then return false end
        end
    end
    for _, unit in pairs(platoon:GetUnits()) do
        if not unit.dead then
            unit.ai.moveToDestinationReached = true
        end
    end
    return true
end

