---Draws debug visuals representing the current state of the platoon during a land single attack operation.
---@param platoon table Platoon class table containing units and related data
---@return nil
function DebugDrawPlanLandSingleAttack(platoon)
    local platoonPosition = {}
    local targetPosition = {}
    while Armies[platoon.army.id]:PlatoonExists(platoon) do
        platoonPosition = platoon:GetPosition()
        local _, terrainHeight = Engine.SampleTerrainHeight(platoonPosition)
        platoonPosition.y = terrainHeight + 10

        Engine.DrawCircle(platoonPosition, 25, AIFunctions.HEXtoRGBA("FF000000"))
        Engine.DrawCircle(platoonPosition, 75, AIFunctions.HEXtoRGBA("FF000040"))
        Engine.DrawCircle(platoonPosition, 95, AIFunctions.HEXtoRGBA("FF000040"))
        Engine.DrawCircle(platoonPosition, 115, AIFunctions.HEXtoRGBA("FF000040"))
        Engine.DrawCircle(platoonPosition, 130, AIFunctions.HEXtoRGBA("FF000040"))

        if platoon.ai.eState == "SelectMainTarget" then
            Engine.DrawCircle(platoonPosition, 15, AIFunctions.HEXtoRGBA("FFFF8080"))
            Engine.DrawCircle(platoonPosition, 10, AIFunctions.HEXtoRGBA("FF000000"))
        elseif platoon.ai.eState == "StartMoveToTarget" then
            Engine.DrawCircle(platoonPosition, 15, AIFunctions.HEXtoRGBA("FFFF8080"))
            Engine.DrawCircle(platoonPosition, 10, AIFunctions.HEXtoRGBA("FFFF8080"))
            if platoon.ai.primaryTarget and not platoon.ai.primaryTarget.dead then
                targetPosition = platoon.ai.primaryTarget:GetPosition()
                local _, terrainHeight = Engine.SampleTerrainHeight(targetPosition)
                targetPosition.y = terrainHeight + 10
                Engine.DrawArrow(platoonPosition, targetPosition, AIFunctions.HEXtoRGBA("FFFF8080") )
            end
        elseif platoon.ai.eState == "MovingToTarget" then
            Engine.DrawCircle(platoonPosition, 15, AIFunctions.HEXtoRGBA("FFFF8080"))
            if platoon.ai.primaryTarget and not platoon.ai.primaryTarget.dead then
                targetPosition = platoon.ai.primaryTarget:GetPosition()
                local _, terrainHeight = Engine.SampleTerrainHeight(targetPosition)
                targetPosition.y = terrainHeight + 10
                Engine.DrawArrow(platoonPosition, targetPosition, AIFunctions.HEXtoRGBA("FFFF8080") )
            end
        elseif platoon.ai.eState == "MicroingPlatoon" then
            Engine.DrawCircle(platoonPosition, 15, AIFunctions.HEXtoRGBA("FFFF0000"))
            Engine.DrawCircle(platoonPosition, 10, AIFunctions.HEXtoRGBA("FFFF0000"))
            for _, unit in ipairs(platoon:GetUnits()) do
                if unit.ai.microTarget and not unit.ai.microTarget.dead then
                    targetPosition = unit.ai.microTarget:GetPosition()
                    local _, terrainHeight = Engine.SampleTerrainHeight(targetPosition)
                    targetPosition.y = terrainHeight + 10
                    Engine.DrawArrow(platoonPosition, targetPosition, AIFunctions.HEXtoRGBA("FFFF0000") )
                end
            end
        elseif platoon.ai.eState == "StartWithdraw" then
            Engine.DrawCircle(platoonPosition, 15, AIFunctions.HEXtoRGBA("FFFF40FF"))
            Engine.DrawCircle(platoonPosition, 10, AIFunctions.HEXtoRGBA("FFFF8080"))
            if platoon.ai.gatherPoint then
                local gatherPoint = platoon.ai.gatherPoint
                local _, terrainHeight = Engine.SampleTerrainHeight(gatherPoint)
                gatherPoint.y = terrainHeight + 10
                Engine.DrawArrow(platoonPosition, gatherPoint, AIFunctions.HEXtoRGBA("FFFF40FF") )
            end
        elseif platoon.ai.eState == "Withdraw" then
            Engine.DrawCircle(platoonPosition, 15, AIFunctions.HEXtoRGBA("FFFF40FF"))
            if platoon.ai.gatherPoint then
                local gatherPoint = platoon.ai.gatherPoint
                local _, terrainHeight = Engine.SampleTerrainHeight(gatherPoint)
                gatherPoint.y = terrainHeight + 10
                Engine.DrawArrow(platoonPosition, gatherPoint, AIFunctions.HEXtoRGBA("FFFF40FF") )
            end
        elseif platoon.ai.eState == "Disband" then
            Engine.DrawCircle(platoonPosition, 25, AIFunctions.HEXtoRGBA("FF000000"))
            Engine.DrawCircle(platoonPosition, 20, AIFunctions.HEXtoRGBA("FF000000"))
            Engine.DrawCircle(platoonPosition, 15, AIFunctions.HEXtoRGBA("FF000000"))
            Engine.DrawCircle(platoonPosition, 10, AIFunctions.HEXtoRGBA("FF000000"))
        end
        WaitTicks(1)
    end
end

---Updates the state of a platoon based on its braveness score.
---@param platoon table Platoon class table containing units and related data
---@param braveness number The braveness score of the platoon
---@param underAttack boolean Indicates if the platoon is currently under attack
---@param shielded boolean Indicates if the platoon is within a shield
---@param tactShielded boolean Indicates if the platoon is protected by tactical missile defense
---@param commanderIsInImmediateDanger boolean Indicates local or predicted interception danger independent of base distance
---@param bravenessWithoutBaseRange number Braveness score excluding distance from the home base
---@param commanderStaysHome boolean Indicates that map-wide danger requires permanent home shelter
---@param commanderFacesLethalDamage boolean Indicates projected lethal damage before reaching protection
---@return string The updated state of the platoon based on its braveness
function UpdateStateByBraveness(platoon, braveness, underAttack, shielded, tactShielded, commanderIsInImmediateDanger, bravenessWithoutBaseRange, commanderStaysHome, commanderFacesLethalDamage)
    -- Home posture limits roaming; it must not forbid defending the home itself.
    local homeDefence = RushTacticsV8.CanDefendHome(platoon, commanderFacesLethalDamage)
    local commanderNeedsProtection = commanderFacesLethalDamage or (commanderIsInImmediateDanger and not homeDefence)
        or (commanderStaysHome and not homeDefence)
    if commanderNeedsProtection then
        local phase=platoon.ai.commanderWithdrawalPhase
        local currentWithdrawalProvidesRequiredProtection=phase=="ReturnToShelter" or phase=="ReturnToBase"
        if platoon.ai.eState ~= "CommanderShelter" and platoon.ai.eState ~= "StartWithdraw" and (platoon.ai.eState ~= "Withdraw" or not currentWithdrawalProvidesRequiredProtection) then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn UpdateStateByBraveness():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..repr(platoon.ai.eState).." to StartWithdraw. (commander needs protection)")
            end
            return "StartWithdraw"
        end
        return platoon.ai.eState
    end
    if platoon.ai.eState == "CommanderShelter" or platoon.ai.commanderWithdrawalPhase == "ReturnToShelter"
        or (homeDefence and (platoon.ai.eState == "Withdraw" or platoon.ai.eState == "StartWithdraw")) then
        platoon.ai.commanderWithdrawalPhase = nil
        platoon.ai.commanderWithdrawalNeedsEmergencySupport = nil
        ClearCommanderShelterData(platoon)
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn UpdateStateByBraveness():[A:"..platoon.army.id.."][P:"..platoon.id.."] leaving commander shelter. (CommanderStaysHome inactive)")
        end
        return (not homeDefence and braveness < 0) and "StartWithdraw" or "SelectMainTarget"
    end
    local commanderNeedsWithdrawal = braveness < 0
    if commanderNeedsWithdrawal and not homeDefence then
        if platoon.ai.eState ~= "StartWithdraw" and platoon.ai.eState ~= "Withdraw" then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn UpdateStateByBraveness():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..repr(platoon.ai.eState).." to StartWithdraw. (commander needs withdrawal)")
            end
            return "StartWithdraw"
        end
    end
    return platoon.ai.eState
end

---Calculates the braveness of a unit, which determines whether the unit will attack or withdraw.
---@param mainPlatoonUnit table Unit class table containing the unit's current state and related data
---@return number bravenessCount The total braveness score calculated for the unit
---@return boolean underAttack Indicates if the unit is currently under attack
---@return boolean shielded Indicates if the unit is within a shield
---@return boolean tactShielded Indicates if the unit is protected by tactical missile defense
---@return boolean commanderIsInImmediateDanger Indicates local or predicted interception danger independent of base distance
---@return number bravenessWithoutBaseRange Braveness score excluding distance from the home base
---@return boolean commanderFacesLethalDamage Indicates projected lethal damage before reaching protection
function subPlanCalculateBraveness(mainPlatoonUnit)
    -- *************************************************************************************************
    -- get threat and calculate mainPlatoonUnit braveness (decides if the unit will attack or withdraw).
    -- *************************************************************************************************
    local braveness = {}
    braveness['Hitted'] = 0
    local platoon = mainPlatoonUnit.platoon
    local _,data,current=CommanderRequest(platoon,mainPlatoonUnit)
    if not current() then return 0,false,false,false,false,0,false end
    local basePosition = data.basePosition
    local armyIndex = platoon.army.id
    local unitT1, unitT2, unitT3, unitT4, threat, shielded, tactShielded, underAttack, rangeToBase
    local mainPlatoonUnitPosition = RushMovementV18.Copy(mainPlatoonUnit:GetPosition())
    local commanderHealthPercentage = 100 / math.max(1,mainPlatoonUnit:GetMaxHealth()) * mainPlatoonUnit:GetHealth()
    local commanderSpeed = mainPlatoonUnit.tp.movement and mainPlatoonUnit.tp.movement.speed or 0
    local intel=RushCombatIntel.Get(platoon.army)
    local protectionTravelTime, protectionPosition, protectionType = GetCommanderProtectionTravelData(platoon, mainPlatoonUnit)
    if not current() or not protectionTravelTime or not protectionPosition then return 0,false,false,false,false,0,false end
    local expectedDamageUntilProtection, attackingUnitCount = CalculateCommanderExpectedDamageUntilProtection(platoon, mainPlatoonUnit, mainPlatoonUnitPosition, protectionPosition, protectionTravelTime, commanderSpeed, intel.enemy)
    if not current() then return 0,false,false,false,false,0,false end
    local commanderHealthReserve = mainPlatoonUnit:GetMaxHealth() * 0.10
    local commanderDamageBudget = math.max(0, mainPlatoonUnit:GetHealth() - commanderHealthReserve)
    local commanderFacesLethalDamage = expectedDamageUntilProtection > 0 and expectedDamageUntilProtection >= commanderDamageBudget
    if lobbyOptionsAI.debugGameTelemetry and data.commanderLethalDamageTelemetryActive ~= commanderFacesLethalDamage then
        data.commanderLethalDamageTelemetryActive = commanderFacesLethalDamage
        AILog(" --- CommanderLethalDamage [A:"..armyIndex.."][P:"..platoon.id.."] State:"..(commanderFacesLethalDamage and "ON" or "OFF").." ExpectedDamage:"..string.format("%.1f", expectedDamageUntilProtection).." DamageBudget:"..string.format("%.1f", commanderDamageBudget).." Reserve:"..string.format("%.1f", commanderHealthReserve).." Attackers:"..attackingUnitCount.." Protection:"..protectionType.." TravelTime:"..string.format("%.1f", protectionTravelTime))
    end
    -- We gain 1 Braveness if we have full health -------------------------------------------------------------------------------------------------------------------------
    if commanderHealthPercentage == 100 then
        braveness['Health100%'] = 1
    end
    -- We gain 1 Braveness for every 7% health we have over 30% health (+10 on 100% health) -------------------------------------------------------------------------------
    braveness['Health'] = math.floor((commanderHealthPercentage - 30) / 7)
    -- Compare nearby ground and air-to-land threats against the matching friendly weapon layers. --------------------------------------------------------------------------
    local combatSupportDistance = 25
    local friendlyLandCombatThreat = 0
    local friendlyAntiAirCombatThreat = 0
    local mobileSupportThreat=0
    for _,entry in ipairs(intel.friendlyShards) do
        if entry.owner==platoon.army or platoon.army:IsAlly(entry.owner) then
            for _,record in ipairs(entry.data.records) do
                local friendlyUnit=record.unit
                local unitAI=friendlyUnit.ai
                local supporting=friendlyUnit.platoon and friendlyUnit.platoon.ai
                local operation=supporting and supporting.rushOperation
                local withdrawing=supporting and friendlyUnit.platoon~=platoon and (supporting.withdraw
                    or supporting.commanderWithdrawalPhase
                    or (operation and operation.policy and operation.policy.phase=="Retreat"))
                if not friendlyUnit.dead and not friendlyUnit.deleted and friendlyUnit.army==entry.owner
                    and not friendlyUnit.CaptureInProgress and not friendlyUnit.ReclaimInProgress
                    and not withdrawing and not (unitAI and unitAI.eState=="RepairHome") then
                    local friendlyUnitPosition=record.pos
                    local distance=Distance2DSquared(mainPlatoonUnitPosition.x,mainPlatoonUnitPosition.z,
                        friendlyUnitPosition.x,friendlyUnitPosition.z)
                    local friendlyLandThreat=AIFunctions.GetUnitThreatValueByLayer(friendlyUnit,"Land")
                    local friendlyLandReach=AIFunctions.GetUnitMaximumWeaponRangeByLayer(friendlyUnit,"Land")+combatSupportDistance
                    if friendlyLandThreat>0 and distance<=friendlyLandReach*friendlyLandReach then
                        friendlyLandCombatThreat=friendlyLandCombatThreat+friendlyLandThreat
                        if friendlyUnit:HasTags(Tags.MOBILE-Tags.ENGINEER-Tags.COMMAND) and distance<=55*55 then
                            mobileSupportThreat=mobileSupportThreat+friendlyLandThreat
                        end
                    end
                    local friendlyAntiAirThreat=AIFunctions.GetUnitThreatValueByLayer(friendlyUnit,"Air")
                    local friendlyAntiAirReach=AIFunctions.GetUnitMaximumWeaponRangeByLayer(friendlyUnit,"Air")+combatSupportDistance
                    if friendlyAntiAirThreat>0 and distance<=friendlyAntiAirReach*friendlyAntiAirReach then
                        friendlyAntiAirCombatThreat=friendlyAntiAirCombatThreat+friendlyAntiAirThreat
                    end
                end
            end
        end
    end
    data.commanderMobileSupportThreat=mobileSupportThreat
    local enemyLocalGroundThreat = 0
    local enemyLocalAirToLandThreat = 0
    local enemyInterceptGroundThreat = 0
    local enemyInterceptAirToLandThreat = 0
    for _, record in ipairs(intel.enemy) do
        local enemyUnit=record.unit
        if RushCombatIntel.Visible(platoon.army,enemyUnit) and enemyUnit:IsCompleted() then
            local enemyLandThreat = AIFunctions.GetUnitThreatValueByLayer(enemyUnit, "Land")
            if enemyLandThreat > 0 then
                local enemyUnitPosition = record.pos
                local enemyWeaponRange = AIFunctions.GetUnitMaximumWeaponRangeByLayer(enemyUnit, "Land")
                local enemyLocalReach = enemyWeaponRange + combatSupportDistance
                local enemyDistanceToCommander = Distance2D(mainPlatoonUnitPosition.x, mainPlatoonUnitPosition.z, enemyUnitPosition.x, enemyUnitPosition.z)
                local enemyIsAir = enemyUnit.tp.hasTags.AIR
                if enemyDistanceToCommander <= enemyLocalReach then
                    if enemyIsAir then
                        enemyLocalAirToLandThreat = enemyLocalAirToLandThreat + enemyLandThreat
                    else
                        enemyLocalGroundThreat = enemyLocalGroundThreat + enemyLandThreat
                    end
                else
                    local enemySpeed = enemyUnit.tp.movement and enemyUnit.tp.movement.speed or 0
                    local enemyClosingSpeed = enemySpeed - commanderSpeed
                    if enemyClosingSpeed > 0 then
                        local enemyTimeToCommanderSafetyRange = (enemyDistanceToCommander - enemyLocalReach) / enemyClosingSpeed
                        local intercepts=enemyTimeToCommanderSafetyRange <= protectionTravelTime
                            and (enemyIsAir or AIMarkerGenerator.CanGraphAreaTo(enemyUnitPosition, mainPlatoonUnitPosition, (RushMovementV18.UnitMovementLayer(enemyUnit) or "Land")))
                        if not current() then return 0,false,false,false,false,0,false end
                        if intercepts then
                            if enemyIsAir then
                                enemyInterceptAirToLandThreat = enemyInterceptAirToLandThreat + enemyLandThreat
                            else
                                enemyInterceptGroundThreat = enemyInterceptGroundThreat + enemyLandThreat
                            end
                        end
                    end
                end
            end
        end
    end
    local planData=data.formerTable.AIPlanData
    local attackEnemyStrength=planData.AttackEnemyStrength
    if data.eState=="MicroingPlatoon" and commanderHealthPercentage>=55 then
        attackEnemyStrength=math.max(attackEnemyStrength,planData.ContinueEnemyStrength or attackEnemyStrength)
    end
    local commanderFacesOverwhelmingLocalGroundThreat = enemyLocalGroundThreat > friendlyLandCombatThreat / 100 * attackEnemyStrength
    local commanderFacesOverwhelmingLocalAirThreat = enemyLocalAirToLandThreat > friendlyAntiAirCombatThreat / 100 * attackEnemyStrength
    local commanderFacesOverwhelmingLocalThreat = commanderFacesOverwhelmingLocalGroundThreat or commanderFacesOverwhelmingLocalAirThreat
    if commanderFacesOverwhelmingLocalThreat then
        braveness['CombatThreat'] = -100
    else
        local localCombatThreatAdvantage = 0
        if enemyLocalGroundThreat > 0 then localCombatThreatAdvantage = localCombatThreatAdvantage + math.min(3, math.floor(friendlyLandCombatThreat / enemyLocalGroundThreat - 1)) end
        if enemyLocalAirToLandThreat > 0 then localCombatThreatAdvantage = localCombatThreatAdvantage + math.min(3, math.floor(friendlyAntiAirCombatThreat / enemyLocalAirToLandThreat - 1)) end
        if localCombatThreatAdvantage ~= 0 then braveness['CombatThreat'] = localCombatThreatAdvantage end
    end
    local commanderFacesCurrentOverwhelmingInterceptionThreat = enemyInterceptGroundThreat > friendlyLandCombatThreat / 100 * attackEnemyStrength or enemyInterceptAirToLandThreat > friendlyAntiAirCombatThreat / 100 * attackEnemyStrength
    local previousCommanderInterceptionThreatActive = data.commanderInterceptionThreatActive
    local commanderInterceptionThreatActive = previousCommanderInterceptionThreatActive == true
    local currentGameTimeSeconds = GetGameTimeSeconds()
    local commanderInterceptionThreatReleaseDelaySeconds = 10
    if commanderFacesCurrentOverwhelmingInterceptionThreat then
        commanderInterceptionThreatActive = true
        data.commanderInterceptionThreatSafeStartTime = nil
    elseif commanderInterceptionThreatActive then
        data.commanderInterceptionThreatSafeStartTime = data.commanderInterceptionThreatSafeStartTime or currentGameTimeSeconds
        if data.commanderInterceptionThreatSafeStartTime + commanderInterceptionThreatReleaseDelaySeconds <= currentGameTimeSeconds then
            commanderInterceptionThreatActive = false
            data.commanderInterceptionThreatSafeStartTime = nil
        end
    else
        data.commanderInterceptionThreatSafeStartTime = nil
    end
    data.commanderInterceptionThreatActive = commanderInterceptionThreatActive
    local commanderFacesOverwhelmingInterceptionThreat = commanderInterceptionThreatActive
    if commanderFacesOverwhelmingInterceptionThreat then braveness['InterceptionThreat'] = -100 end
    if lobbyOptionsAI.debugGameTelemetry and data.commanderCurrentInterceptionThreatTelemetryActive ~= commanderFacesCurrentOverwhelmingInterceptionThreat then
        data.commanderCurrentInterceptionThreatTelemetryActive = commanderFacesCurrentOverwhelmingInterceptionThreat
        AILog(" --- CommanderInterceptionThreatRaw [A:"..armyIndex.."][P:"..platoon.id.."] State:"..(commanderFacesCurrentOverwhelmingInterceptionThreat and "ON" or "OFF").." Ground:"..string.format("%.1f", enemyInterceptGroundThreat).."/"..string.format("%.1f", friendlyLandCombatThreat).." AirToLand:"..string.format("%.1f", enemyInterceptAirToLandThreat).."/"..string.format("%.1f", friendlyAntiAirCombatThreat).." TimeToProtection:"..string.format("%.1f", protectionTravelTime))
    end
    if lobbyOptionsAI.debugGameTelemetry and previousCommanderInterceptionThreatActive ~= commanderFacesOverwhelmingInterceptionThreat then
        AILog(" --- CommanderInterceptionThreat [A:"..armyIndex.."][P:"..platoon.id.."] State:"..(commanderFacesOverwhelmingInterceptionThreat and "ON" or "OFF").." Ground:"..string.format("%.1f", enemyInterceptGroundThreat).."/"..string.format("%.1f", friendlyLandCombatThreat).." AirToLand:"..string.format("%.1f", enemyInterceptAirToLandThreat).."/"..string.format("%.1f", friendlyAntiAirCombatThreat).." TimeToProtection:"..string.format("%.1f", protectionTravelTime))
    end
    -- We gain 0.5 Braveness if we have at least 5 Anti Air units in close range ------------------------------------------------------------------------------------------
    if AIFunctions.GetNumUnitsAroundPosition(armyIndex, mainPlatoonUnitPosition, 30, Tags.MOBILE * Tags.ANTI_AIR, false) >= 5 then
        braveness['AllyAA'] = 0.5
    end
    -- We gain 0.1 Braveness for every tactical missile defense nearby ----------------------------------------------------------------------------------------------------
    unitT2 = AIFunctions.GetNumUnitsAroundPosition(armyIndex, mainPlatoonUnitPosition, 28, Tags.STRUCTURE * Tags.DEFENCE * Tags.ANTI_PROJECTILE * Tags.TECH2, false)
    if unitT2 > 0 then
        tactShielded = true
        braveness['TMD'] = unitT2 * 0.1
    end
    -- We gain 0.5 Braveness for every Tech2 and 1 Braveness for every tech3 shield nearby --------------------------------------------------------------------------------
    unitT1 = AIFunctions.GetNumUnitsAroundPosition(armyIndex, mainPlatoonUnitPosition, 12, Tags.MOBILE * Tags.SHIELD * (Tags.TECH2 + Tags.TECH3), false)
    unitT2 = AIFunctions.GetNumUnitsAroundPosition(armyIndex, mainPlatoonUnitPosition, 12, Tags.STRUCTURE * Tags.SHIELD * Tags.TECH2, false)
    unitT3 = AIFunctions.GetNumUnitsAroundPosition(armyIndex, mainPlatoonUnitPosition, 21, Tags.STRUCTURE * Tags.SHIELD * Tags.TECH3, false)
    unitT4 = AIFunctions.GetNumUnitsAroundPosition(armyIndex, mainPlatoonUnitPosition, 30, Tags.STRUCTURE * Tags.SHIELD * Tags.TECH4, false)
    threat = unitT1 * 0.5 + unitT2 * 0.5 + unitT3 * 1 + unitT4 * 2
    if threat > 0 then
        shielded = true
        braveness['Shield'] = threat
    end
    -- We gain 1 Braveness if overcharge is available ---------------------------------------------------------------------------------------------------------------------
    -- We gain 1 Braveness for every enhancement --------------------------------------------------------------------------------------------------------------------------

    -- We lose 5 Braveness for every additional enemy ACU nearby (+0 for 1 ACU, +5 for 2 ACUs, +10 for 3 ACUs
    unitT1 = AIFunctions.GetNumEnemyUnitsAroundPosition(armyIndex, mainPlatoonUnitPosition, 60, Tags.COMMAND, false)
    threat = unitT1 - 1
    if threat > 0 then
        braveness['EnemyACU'] = - math.floor(threat * 5)
    end
    -- We lose 1 Braveness if we got damaged in the last 4 seconds --------------------------------------------------------------------------------------------------------
    underAttack = AIFunctions.IsUnderAttack(mainPlatoonUnit)
    if underAttack then
        braveness['Hitted'] = braveness['Hitted'] - 3
    end
    data.commanderNeedsLocalEmergencySupport = commanderFacesOverwhelmingLocalThreat or underAttack or commanderHealthPercentage < 30
    local commanderIsInImmediateDanger = commanderFacesOverwhelmingLocalThreat or commanderFacesOverwhelmingInterceptionThreat or commanderFacesLethalDamage or commanderHealthPercentage < 30
    -- Healthy supported commanders can advance; damage and actual local threats still force withdrawal.
    local ownThreat=math.max(1,AIFunctions.GetUnitThreatValueByLayer(mainPlatoonUnit,"Land"))
    braveness['Support']=commanderHealthPercentage>=65 and math.min(5,math.floor(mobileSupportThreat/ownThreat*3)) or 0
    rangeToBase = Distance2D(mainPlatoonUnitPosition.x,mainPlatoonUnitPosition.z, basePosition.x, basePosition.z)
    braveness['Range'] = - math.floor(rangeToBase/(commanderHealthPercentage>=65 and 25 or 20))
    -- debug
    local bravenessCount = 0
    for name, value in pairs(braveness) do
        --AILog("* Fn planLandSingleAttack():[A:"..armyIndex.."][P:"..platoon.id.."] name:"..repr(name).." - value: ("..value..")")
        bravenessCount = bravenessCount + value
    end
    local bravenessWithoutBaseRange = bravenessCount - braveness['Range']
    if data.formerTable.DebugPlatoon then
        AILog("* Fn subPlanCalculateBraveness():[A:"..armyIndex.."][P:"..platoon.id.."] bravenessCount:"..bravenessCount.." "..CreateBravenessBar(bravenessCount))
    end
    if data.formerTable.DebugPlatoon then
        AILog(repr(braveness))
    end
    mainPlatoonUnit.braveness = "bravenessCount:"..bravenessCount..CreateBravenessBar(bravenessCount)
    return bravenessCount, underAttack, shielded, tactShielded, commanderIsInImmediateDanger, bravenessWithoutBaseRange, commanderFacesLethalDamage
end

---Release only the idle-work controller's own order before resuming combat.
function StopCommanderProductionAssist(platoon, commander, reason)
    return RushCommanderWork.Stop(platoon, commander, reason)
end
---Assist local production without replacing the commander's combat or withdrawal plan.
function UpdateCommanderProductionAssist(platoon, sheltered)
    local commander=platoon:GetUnits()[1]
    if commander then return RushCommanderWork.Update(platoon,commander,sheltered) end
end

local function CommanderSearchRadius(platoon,commander)
    local data=platoon.ai
    local radius=AITargetManager.GetDangerZoneRadii(false)
    local health=commander:GetHealth()/math.max(1,commander:GetMaxHealth())
    if health>=0.65 and not data.commanderStaysHome and not RushCommanderPressure.SurvivalMap() then
        local own=math.max(1,AIFunctions.GetUnitThreatValueByLayer(commander,"Land"))
        local range=AIFunctions.GetUnitMaximumWeaponRangeByLayer(commander,"Land")
        radius=math.max(radius,data.baseRadius*2+range*3
            +math.min(120,(data.commanderMobileSupportThreat or 0)/own*60))
    end
    local profile=RushTacticsV8.CommanderCombatProfile(platoon,commander)
    if profile then radius=math.max(data.baseRadius,radius*(profile.searchScale or 1)) end
    if not CommanderLandOffenseAllowed(platoon) then radius=math.min(radius,data.baseRadius) end
    return math.min(data.formerTable.AIPlanData.TargetSearchRadius,radius)
end
-- Approach at firing range and evaluate the protection available at that position.
-- Enemy records come from the shared native-intel snapshot, including live weapons.
local function CommanderAttackPosition(platoon, commander, target, profile)
    local _,data,current,sameOrders=CommanderRequest(platoon,commander)
    if not sameOrders() then return nil,"stale-request" end
    if not IsAttackTargetAvailable(target) or not RushCombatIntel.Visible(platoon.army,target)
        or not CanPlatoonShootTarget(platoon,target) then return nil end
    local position=RushMovementV18.Copy(commander:GetPosition())
    local targetPosition=RushMovementV18.Copy(GetUnitPositionForCurrentSimulationTick(target))
    local radius=CommanderSearchRadius(platoon,commander)
    if not sameOrders() then return nil,"stale-request" end
    if Distance2DSquared(targetPosition.x,targetPosition.z,data.basePosition.x,
        data.basePosition.z)>radius*radius then return nil end
    profile=profile or RushTacticsV8.CommanderCombatProfile(platoon,commander,target)
    if not sameOrders() then return nil,"stale-request" end
    local range=profile and profile.range or 0
    if not profile or not profile.weapon or range<=0 then return nil end
    local dx,dz=targetPosition.x-position.x,targetPosition.z-position.z
    local distance=math.sqrt(dx*dx+dz*dz)
    local firingRange=math.min(range-0.5,math.max((profile.minRange or 0)+1,range*0.85))
    local advance=math.max(0,distance-math.max(1,firingRange))
    local destination={x=position.x,y=position.y,z=position.z}
    if distance>0 then
        destination.x=position.x+dx/distance*advance
        destination.z=position.z+dz/distance*advance
        SnapToGround(destination,destination)
    end
    if not isPosWithinPlayableArea(destination) then return nil end
    local home=Distance2DSquared(destination.x,destination.z,data.basePosition.x,data.basePosition.z)
        <=data.baseRadius*data.baseRadius
    if not home and (profile.canAdvance==false
        or commander:GetHealth()<commander:GetMaxHealth()*math.max(0.55,profile.healthFloor or 0)) then return nil end
    local support=RushCombatIntel.FriendlyThreat(platoon,destination,55,"Land",not home)
    local airSupport=RushCombatIntel.FriendlyThreat(platoon,destination,55,"Air",false)
    local own=AIFunctions.GetUnitThreatValueByLayer(commander,"Land")
    local ownAA=AIFunctions.GetUnitThreatValueByLayer(commander,"Air")
    local exposure=RushCombatIntel.Exposure(platoon.army,destination,"Land",15)
    local strength=(data.formerTable.AIPlanData.AttackEnemyStrength or 85)/100
        *(home and 1 or profile.strengthScale or 1)
    if exposure.total-(exposure.air or 0)>(own+support)*strength
        or (exposure.air or 0)>(ownAA+airSupport)*strength
        or (not home and exposure.static>support and exposure.maxStaticRange>range) then return nil end
    local connected=AIMarkerGenerator.CanGraphAreaTo(position,destination,data.movementLayer)
    if not sameOrders() then return nil,"stale-request" end
    if not connected or not IsAttackTargetAvailable(target) then return nil end
    return destination
end
local function SelectCommanderAttackTarget(platoon,commander)
    local _,data,current,sameOrders=CommanderRequest(platoon,commander)
    if not sameOrders() then return nil,nil,"stale-request" end
    local plan=data.formerTable.AIPlanData
    local base=data.basePosition
    local position=RushMovementV18.Copy(commander:GetPosition())
    local panic=AITargetManager.GetDangerZoneRadii(false)
    local radius=CommanderSearchRadius(platoon,commander)
    if not sameOrders() then return nil,nil,"stale-request" end
    local candidates={}
    local now=GetGameTimeSeconds()
    local blocked=data.commanderBlockedTargets
    for _,target in ipairs(RushCombatIntel.EnemiesInRadius(platoon.army,base,radius,true)) do
        local untilTime=blocked and blocked[target]
        if untilTime and untilTime<=now then blocked[target]=nil;untilTime=nil end
        if not untilTime and target:HasTags(plan.TargetSearchCategory) and CanPlatoonShootTarget(platoon,target) then
            local targetPosition=RushMovementV18.Copy(GetUnitPositionForCurrentSimulationTick(target))
            local distance=Distance2D(position.x,position.z,targetPosition.x,targetPosition.z)
            local home=Distance2DSquared(base.x,base.z,targetPosition.x,targetPosition.z)<=panic*panic
            local targetHealth=target:GetHealth()/math.max(1,target:GetMaxHealth())
            local score=target:HasTags(Tags.COMMAND) and 260+(1-targetHealth)*400
                or target:HasTags(Tags.FACTORY) and 230
                or target:HasTags(Tags.ENGINEER) and 210
                or target:HasTags(Tags.ALLOYS_EXTRACTION+Tags.ENERGY_PRODUCTION) and 190 or 120
            score=score-distance*1.5+(home and target:IsCompleted()
                and AIFunctions.GetUnitThreatValueByLayer(target,"Land")>0 and 350 or 0)
            local profile=RushTacticsV8.CommanderCombatProfile(platoon,commander,target)
            if not sameOrders() then return nil,nil,"stale-request" end
            if profile and profile.weapon then
                score=score+(profile.scoreBonus or 0)
                if target==data.primaryTarget then score=score+45 end
                candidates[#candidates+1]={unit=target,score=score,profile=profile}
            end
        end
    end
    table.sort(candidates,function(a,b)
        return a.score>b.score or (a.score==b.score and a.unit.id.index<b.unit.id.index)
    end)
    for _,candidate in ipairs(candidates) do
        local destination,reason=CommanderAttackPosition(platoon,commander,candidate.unit,candidate.profile)
        if not sameOrders() or reason=="stale-request" then return nil,nil,"stale-request" end
        if destination then return candidate.unit,destination end
    end
end

---Selects the main target for the platoon and determines the next action based on the target's availability and pathing success.
---@param platoon table Platoon class table containing units and related data
---@return string Next state: attack approach, local combat, continued service, or disband for construction
function subPlanSelectMainTarget(platoon)
    local commander,data,current,sameOrders=CommanderRequest(platoon)
    if not current() then return "Disband" end
    if RushMovementV18.Suspended(commander) then return data.eState or "SelectMainTarget" end
    if data.formerTable.DebugPlatoon then
        AILog("* Fn subPlanSelectMainTarget():[A:"..platoon.army.id.."][P:"..platoon.id.."] [eState] = SelectMainTarget.")
    end
    --AILog( repr(Armies[platoon.army.id].ai.highestEnemyThreat["Land"]) )
    --AILog( repr(Armies[platoon.army.id].ai.highestEnemyEcoValue["Ghost"]) )
    local target,destination,reason=SelectCommanderAttackTarget(platoon,commander)
    if not current() then return "Disband" end
    if not sameOrders() or reason=="stale-request" then return data.eState or "SelectMainTarget" end
    data.primaryTarget=target
    data.commanderForwardPressure=nil
    -- in case we have a target, move and attack it
    if IsAttackTargetAvailable(data.primaryTarget) then
        data.commanderIdleSince = nil
        StopCommanderProductionAssist(platoon, platoon:GetUnits()[1])
        data.gatherPoint = destination
        local targetPosition=RushMovementV18.Copy(GetUnitPositionForCurrentSimulationTick(target))
        data.commanderForwardPressure=Distance2DSquared(targetPosition.x,targetPosition.z,
            data.basePosition.x,data.basePosition.z)>data.baseRadius*data.baseRadius
        if data.formerTable.DebugPlatoon then
            AILog("* Fn subPlanSelectMainTarget():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..data.eState.." to StartMoveToTarget. (we have a path target)")
        end
        return "StartMoveToTarget"
    end
    -- Defend against a nearby enemy even when it is outside the home target zone.
    local nearby = GetClosestShootableEnemy(platoon, platoon:GetPosition(),
        CalculatePlatoonEngagementRadius(platoon), Tags.ALL_UNITS)
    if not current() then return "Disband" end
    if not sameOrders() then return data.eState or "SelectMainTarget" end
    if IsAttackTargetAvailable(nearby) then
        data.commanderIdleSince = nil
        StopCommanderProductionAssist(platoon, platoon:GetUnits()[1])
        data.microTarget = nearby
        return "MicroingPlatoon"
    end
    if not data.rushCommanderService and data.path
        and not RushCommanderWork.ConstructionTarget(commander) then
        -- Release the last attack move before testing whether the ACU can assist.
        RushMovementV18.Forget(commander,false)
        ClearCombatOrders({commander})
        data.path = false
        commander.ai.path = false
        commander.ai.moveToDestinationReached = nil
    end
    local supportState,supportReason=subPlanCommanderSupport(platoon,true)
    if not current() then return "Disband" end
    if supportReason=="stale-request" then return data.eState or "SelectMainTarget" end
    if supportState then return supportState end
    local commanderPosition=commander:GetPosition()
    if Distance2DSquared(commanderPosition.x,commanderPosition.z,data.basePosition.x,
        data.basePosition.z)>data.baseRadius*data.baseRadius then
        data.commanderIdleSince=nil
        return "StartWithdraw"
    end
    local working=UpdateCommanderProductionAssist(platoon)
    if not current() then return "Disband" end
    if working then
        data.commanderIdleSince = nil
        return data.eState
    end
    if data.commanderIsInImmediateDanger or data.commanderFacesLethalDamage
        or data.commanderUnderAttack then
        data.commanderIdleSince = nil
        return data.eState
    end
    -- No useful combat/service job: release construction power immediately.
    -- The short handoff prevents the combat former reclaiming it in the same pass.
    platoon.army.ai.rushCommanderWorkYieldUntil = GetGameTimeSeconds() + 4
    return "Disband"
end

-- Aura and field-shield support uses the commander's existing plan. Every
-- queued move is owned explicitly so a newer construction/combat job wins.
function subPlanCommanderSupport(platoon,starting)
    local unit,data,current,sameOrders=CommanderRequest(platoon)
    local army,unitAI=platoon.army,unit and unit.ai
    if not current() then return not starting and "Disband" or nil end
    local record=data.rushCommanderSupport
    if unit.toggles and unit.toggles.Pause then
        if record then record.progressAt=GetGameTimeSeconds();record.lastPosition=RushMovementV18.Copy(unit:GetPosition()) end
        return not starting and "CommanderSupport" or nil
    end
    if record and unitAI.rushMoveQueue then RushMovementV18.MaintainUnit(unit) end
    local function abandoned()
        return not starting and (current() and (data.eState or "SelectMainTarget") or "Disband") or nil,"stale-request"
    end
    local function ownOrders()
        if not record then return false end
        local orders=unit.orders or {}
        if orders.activeOrder and not record.orders[orders.activeOrder] then return false end
        for _,order in pairs(orders.queuedOrders or {}) do
            if not record.orders[order] then return false end
        end
        return true
    end
    local function finish(stale)
        if current() then
            if data.rushCommanderSupport==record then
                if ownOrders() then RushMovementV18.Forget(unit,false);ClearCombatOrders({unit}) end
                data.rushCommanderSupport=nil;data.rushCommanderSupportAnchor=nil
            end
            if record and record.path then
                if data.path==record.path then data.path=false end
                if unitAI.rushMoveQueue and unitAI.rushMoveQueue.source==record.path then RushMovementV18.Forget(unit,true) end
                if unitAI.path==record.unitPath then unitAI.path=false;unitAI.moveToDestinationReached=nil end
            end
        end
        return not starting and "SelectMainTarget" or nil,stale and "stale-request" or nil
    end
    if record and not ownOrders() then return finish(true) end
    if not CommanderLandOffenseAllowed(platoon) then return finish() end
    if RushCommanderWork.ConstructionTarget(unit) then return finish() end
    if GetGameTimeSeconds()<(data.commanderSupportRetry or 0) then return finish() end
    if not starting then
        local enemy=GetClosestShootableEnemy(platoon,unit:GetPosition(),
            CalculatePlatoonEngagementRadius(platoon),Tags.ALL_UNITS)
        if not current() or data.rushCommanderSupport~=record then return abandoned() end
        if record and not ownOrders() or not record and not sameOrders() then return finish(true) end
        if IsAttackTargetAvailable(enemy) then
            finish()
            if not current() then return "Disband" end
            data.microTarget=enemy
            return "MicroingPlatoon"
        end
    end
    local destination,anchor,radius=RushTacticsV8.CommanderSupportPosition(platoon,unit)
    if not current() or data.rushCommanderSupport~=record then return abandoned() end
    if not record and not sameOrders() then return finish(true) end
    if not destination then return finish() end
    if not record then
        local service=data.rushCommanderService
        if service then
            local orders=unit.orders or {}
            if (service.kind or "assist")~="assist" or not service.product
                or service.product:HasTags(Tags.STRUCTURE) or orders.activeOrder~=service.order
                or orders.queuedOrders and next(orders.queuedOrders) then return nil end
            StopCommanderProductionAssist(platoon,unit)
        end
        local orders=unit.orders or {}
        if orders.activeOrder or orders.queuedOrders and next(orders.queuedOrders) then
            return not starting and "SelectMainTarget" or nil
        end
        RushMovementV18.Forget(unit,false)
        record={orders={},progressAt=GetGameTimeSeconds(),lastPosition=RushMovementV18.Copy(unit:GetPosition())}
        data.rushCommanderSupport=record
    end
    if not ownOrders() then return finish(true) end
    data.rushCommanderSupportAnchor=anchor
    local position,now=RushMovementV18.Copy(unit:GetPosition()),GetGameTimeSeconds()
    local reach=math.max(1.5,math.min(4,radius*0.15))
    local distance=Distance2DSquared(position.x,position.z,destination.x,destination.z)
    if Distance2DSquared(position.x,position.z,record.lastPosition.x,record.lastPosition.z)>4 then
        record.lastPosition=position;record.progressAt=now
    end
    if distance<=reach*reach then
        if next(record.orders) then RushMovementV18.Forget(unit,false);ClearCombatOrders({unit}) end
        record.orders={};record.progressAt=now;record.destination=nil;record.path=nil;record.unitPath=nil
        data.path=false;unitAI.path=false
        return "CommanderSupport"
    end
    if now-record.progressAt>=20 then
        data.commanderSupportRetry=now+10
        return finish()
    end
    local moved=not record.destination or Distance2DSquared(destination.x,destination.z,
        record.destination.x,record.destination.z)>math.max(3,radius*0.25)^2
    local orders=unit.orders or {}
    if (moved or not orders.activeOrder and not (orders.queuedOrders and next(orders.queuedOrders)))
        and now>=(record.nextPath or 0) then
        local maximum=math.max(1,AIFunctions.GetUnitThreatValueByLayer(unit,"Land"))*0.75
        local request=RushMovementV18.Capture(platoon,{unit})
        local layer=data.movementLayer
        local path=AIMarkerGenerator.GeneratePathTo(army.id,position,destination,layer,true,maximum)
        if not current() or data.rushCommanderSupport~=record then return abandoned() end
        if not ownOrders() then return finish(true) end
        path=path and AIMarkerGenerator.StraightenPath(path)
        if not current() or data.rushCommanderSupport~=record or data.movementLayer~=layer then return abandoned() end
        path=path and RushMovementV18.ShortenPath(platoon,position,path,layer,maximum,request)
        if not current() or data.rushCommanderSupport~=record or data.movementLayer~=layer then return abandoned() end
        if not ownOrders() then return finish(true) end
        if not path or #path==0 then data.commanderSupportRetry=now+10;return finish() end
        local freshPosition,freshAnchor,freshRadius=RushTacticsV8.CommanderSupportPosition(platoon,unit)
        if not current() or data.rushCommanderSupport~=record then return abandoned() end
        if not ownOrders() then return finish(true) end
        if not freshPosition or freshAnchor~=anchor or Distance2DSquared(destination.x,destination.z,
            freshPosition.x,freshPosition.z)>math.max(3,math.min(radius,freshRadius)*0.25)^2 then return finish() end
        path=RushMovementV18.CopyPath(path)
        local previousPath,previousGoal,previousThreat=data.path,data.gatherPoint,data.rushMovementThreat
        data.path,data.gatherPoint,data.rushMovementThreat=path,RushMovementV18.Copy(destination),maximum
        local accepted,reason=RushMovementV18.Begin(platoon,path,destination,OrderTasks.MOVE,request)
        if not accepted then
            if current() and data.path==path then
                data.path,data.gatherPoint,data.rushMovementThreat=previousPath,previousGoal,previousThreat
            end
            return finish(reason=="stale-request")
        end
        if not current() or data.rushCommanderSupport~=record then return abandoned() end
        local queue=unitAI.rushMoveQueue
        if not queue or queue.source~=path then return finish(true) end
        record.orders=queue.orders;record.unitPath=queue.path
        record.destination=RushMovementV18.Copy(destination);record.nextPath=GetGameTimeSeconds()+2;record.path=path
        unitAI.moveToDestinationReached=nil
    end
    return "CommanderSupport"
end

---Starts the movement of the platoon towards the primary target.
---@param platoon table Platoon class table containing units and related data
---@return string The next state of the platoon, "MovingToTarget"
function subPlanStartMoveToTarget(platoon)
    local commander,data,current,sameOrders=CommanderRequest(platoon)
    if not current() then return "Disband" end
    local target=data.primaryTarget
    if not IsAttackTargetAvailable(data.primaryTarget) then
        data.primaryTarget = false
        return "SelectMainTarget"
    end
    local destination,reason=CommanderAttackPosition(platoon,commander,target)
    if not current() then return "Disband" end
    if not sameOrders() or reason=="stale-request" or data.primaryTarget~=target then return data.eState or "SelectMainTarget" end
    if not destination then return "SelectMainTarget" end
    local moving,moveReason=InitMoveToDestination(platoon,destination,true)
    if not current() then return "Disband" end
    if moveReason=="stale-request" or data.primaryTarget~=target then return data.eState or "SelectMainTarget" end
    if not IsAttackTargetAvailable(target) then return "SelectMainTarget" end
    if moving then
        local position=RushMovementV18.Copy(commander:GetPosition())
        local targetPosition=RushMovementV18.Copy(GetUnitPositionForCurrentSimulationTick(data.primaryTarget))
        local watch=data.commanderApproachWatch
        if not watch or watch.target~=data.primaryTarget then
            data.commanderApproachWatch={target=data.primaryTarget,at=GetGameTimeSeconds(),
                distance=Distance2DSquared(position.x,position.z,targetPosition.x,targetPosition.z)}
        end
        if data.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToTarget():[A:"..platoon.army.id.."][P:"..platoon.id.."] initialized movement to PrimaryTarget.")
        end
        if data.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartMoveToTarget():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..data.eState.." to MovingToTarget. (after InitMoveToDestination)")
        end
        return "MovingToTarget"
    end
    data.commanderBlockedTargets=data.commanderBlockedTargets or setmetatable({},{__mode="k"})
    data.commanderBlockedTargets[target]=GetGameTimeSeconds()+12
    data.commanderForwardPressure=nil
    return "SelectMainTarget"
end

---Handles the movement of the platoon towards its target, adjusting for obstacles and enemy units encountered en route.
---@param platoon table Platoon class table containing units and related data
---@return string The next state of the platoon, potentially "MicroingPlatoon" if close to the target or encountering enemies, or "StartMoveToTarget" if stuck
function subPlanMovingToTarget(platoon)
    local commander,data,current,sameOrders=CommanderRequest(platoon)
    if not current() then return "Disband" end
    if RushMovementV18.Suspended(commander) then return data.eState or "SelectMainTarget" end
    local target=data.primaryTarget
    if data.formerTable.DebugPlatoon then
        AILog("* Fn subPlanMovingToTarget():[A:"..platoon.army.id.."][P:"..platoon.id.."] [eState] = MovingToTarget.")
    end
    -- check if the target has moved
    if not IsAttackTargetAvailable(data.primaryTarget)
        or not RushCombatIntel.Visible(platoon.army,data.primaryTarget) then
        RushMovementV18.Forget(commander,false)
        ClearCombatOrders(platoon:GetUnits())
        data.primaryTarget = false
        return "SelectMainTarget"
    end
    local destination,reason=CommanderAttackPosition(platoon,commander,target)
    if not current() then return "Disband" end
    if not sameOrders() or reason=="stale-request" or data.primaryTarget~=target then return data.eState or "SelectMainTarget" end
    if not destination then
        RushMovementV18.Forget(commander,false)
        ClearCombatOrders(platoon:GetUnits())
        return "SelectMainTarget"
    end
    for _,weapon in ipairs(commander.weapons or {}) do
        local target=weapon.targetUnit or data.primaryTarget
        if IsAttackTargetAvailable(target) and weapon.enabled and not weapon.isDeathExplosion
            and weapon:CanShootAt(target) and weapon:IsTargetInRange(target) then
            RushMovementV18.Forget(commander,false)
        ClearCombatOrders(platoon:GetUnits())
            data.commanderApproachWatch=nil
            return "MicroingPlatoon"
        end
    end
    local gatherPoint = data.gatherPoint
    local position=RushMovementV18.Copy(commander:GetPosition())
    local targetPosition=RushMovementV18.Copy(GetUnitPositionForCurrentSimulationTick(data.primaryTarget))
    local distance=Distance2DSquared(position.x,position.z,targetPosition.x,targetPosition.z)
    local watch=data.commanderApproachWatch
    if watch and watch.target==data.primaryTarget then
        if distance<watch.distance-4 then watch.distance=distance;watch.at=GetGameTimeSeconds()
        elseif GetGameTimeSeconds()-watch.at>=15 then
            data.commanderBlockedTargets=data.commanderBlockedTargets or setmetatable({},{__mode="k"})
            data.commanderBlockedTargets[data.primaryTarget]=GetGameTimeSeconds()+15
            RushMovementV18.Forget(commander,false)
        ClearCombatOrders(platoon:GetUnits())
            return "SelectMainTarget"
        end
    end
    if Distance2DSquared(gatherPoint.x,gatherPoint.z,destination.x,destination.z)>144 then
        return "StartMoveToTarget"
    end
    --check if all units have reached the gatherPoint
    local stillMoving = false
    for _, unit in pairs(platoon:GetUnits()) do
        local unitStillMoving,reason=MoveToDestination(unit,data.gatherPoint)
        if not current() then return "Disband" end
        if reason=="stale-request" then return data.eState or "SelectMainTarget" end
        stillMoving = stillMoving or unitStillMoving
    end
    if not stillMoving then
        if data.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMovingToTarget():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..data.eState.." to MicroingPlatoon. (reached destination)")
        end
        return "MicroingPlatoon"
    end
    return data.eState
end

---Initiates the withdrawal of the platoon, clearing orders and setting a path to retreat.
---@param platoon table Platoon class table containing units and related data
---@return string The next state of the platoon, "Withdraw"
function subPlanStartWithdraw(platoon,upgradeReturn)
    local _,data,current=CommanderRequest(platoon)
    if not current() then return "Disband" end
    data.commanderForwardPressure=nil
    data.commanderApproachWatch=nil
    if data.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] initialize commander withdrawal")
    end
    local commanderShelterShieldUnit = not upgradeReturn and SelectCommanderShelterShield(platoon)
    if not upgradeReturn and (data.commanderStaysHome or data.commanderFacesLethalDamage and commanderShelterShieldUnit) then
        data.commanderWithdrawalPhase = "ReturnToShelter"
        ClearCommanderShelterData(platoon)
        local moving,reason=StartCommanderShelterMovement(platoon)
        if not current() then return "Disband" end
        if reason=="stale-request" then return data.eState or "SelectMainTarget" end
        if moving then
            if data.formerTable.DebugPlatoon then
                AILog("* Fn subPlanStartWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] moving commander to home shelter")
            end
            return "Withdraw"
        end
        if CommanderIsSheltered(platoon,platoon:GetUnits()[1]) then
            data.commanderWithdrawalPhase=nil
            data.commanderWithdrawalNeedsEmergencySupport=nil
            return "CommanderShelter"
        end
    end
    data.commanderWithdrawalPhase = "ReturnToBase"
    local moving,reason=InitMoveToDestination(platoon,data.basePosition)
    if not current() then return "Disband" end
    if reason=="stale-request" then return data.eState or "SelectMainTarget" end
    if moving then
        ClearCommanderShelterData(platoon)
        if data.formerTable.DebugPlatoon then
            AILog("* Fn subPlanStartWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..data.eState.." to Withdraw")
        end
        return "Withdraw"
    end
    if data.formerTable.DebugPlatoon then
        AILog("* Fn subPlanStartWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..data.eState.." to MicroingPlatoon. (need transport!!!)")
    end
    data.commanderWithdrawalPhase = nil
    data.commanderWithdrawalNeedsEmergencySupport = nil
    return "MicroingPlatoon"
end

---Handles commander withdrawal to the home base, releases emergency support there, and enters home shelter.
---@param platoon table The platoon that is executing the withdrawal.
---@return string The next state for the platoon, which could be "SelectMainTarget", "Disband", or the current state "Withdraw" if still in progress.
function subPlanWithdraw(platoon,upgradeReturn)
    local commander,data,current=CommanderRequest(platoon)
    if not current() then return "Disband" end
    if data.formerTable.DebugPlatoon then
        AILog("* Fn subPlanWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] moving to withdrawal destination")
    end
    if data.commanderWithdrawalPhase=="ReturnToShelter" and CommanderShelterStalled(platoon,commander) then
        local _,reason=StartCommanderShelterMovement(platoon)
        if not current() then return "Disband" end
        if reason=="stale-request" then return data.eState or "Withdraw" end
    end
    --check if all units have reached the gatherPoint
    local stillMoving = false
    for _, unit in pairs(platoon:GetUnits()) do
        local unitStillMoving,reason=MoveToDestination(unit,data.gatherPoint)
        if not current() then return "Disband" end
        if reason=="stale-request" then return data.eState or "SelectMainTarget" end
        stillMoving = stillMoving or unitStillMoving
    end
    if not stillMoving then
        if data.commanderWithdrawalPhase == "ReturnToShelter" then
            data.commanderWithdrawalPhase = nil
            data.commanderWithdrawalNeedsEmergencySupport = nil
            local _,reason=StartCommanderShelterMovement(platoon)
            if not current() then return "Disband" end
            if reason=="stale-request" then return data.eState or "SelectMainTarget" end
            if data.formerTable.DebugPlatoon then
                AILog("* Fn subPlanWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] commander reached home shelter")
            end
            return "CommanderShelter"
        end
        if data.commanderWithdrawalPhase == "ReturnToBase" then
            data.commanderWithdrawalPhase = nil
            data.commanderWithdrawalNeedsEmergencySupport = nil
            ClearCommanderShelterData(platoon)
            if upgradeReturn then return "SelectMainTarget" end
            local _,reason=StartCommanderShelterMovement(platoon)
            if not current() then return "Disband" end
            if reason=="stale-request" then return data.eState or "SelectMainTarget" end
            if data.formerTable.DebugPlatoon then
                AILog("* Fn subPlanWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] commander reached home base and enters shelter movement")
            end
            return "CommanderShelter"
        end
        local armyIndex = platoon.army.id
        local noEngineerAvailable = AIFunctions.LessThanUnitsInArmy(armyIndex, data.baseName, 1, Tags.MOBILE * Tags.LAND * Tags.ENGINEER - Tags.COMMAND, false)
        local noEnemyInCombatRange = AIFunctions.GetNumEnemyUnitsAroundPosition(armyIndex, platoon:GetPosition(), CalculatePlatoonEngagementRadius(platoon), Tags.ALL_UNITS, false) < 1
        if AIFunctions.IsStrategyActive(armyIndex, data.baseName, "BaseNeedsRecover") and noEngineerAvailable and noEnemyInCombatRange then
            if data.formerTable.DebugPlatoon then
                AILog("* Fn subPlanWithdraw():[A:"..armyIndex.."][P:"..platoon.id.."] switching [eState] = "..data.eState.." to Disband. (base recover needs commander)")
            end
            return "Disband"
        end
        if data.formerTable.DebugPlatoon then
            AILog("* Fn subPlanWithdraw():[A:"..armyIndex.."][P:"..platoon.id.."] switching [eState] = "..data.eState.." to SelectMainTarget. (reached home base)")
        end
        return "SelectMainTarget"
    end
    if data.formerTable.DebugPlatoon then
        AILog("* Fn subPlanWithdraw():[A:"..platoon.army.id.."][P:"..platoon.id.."] still moving to withdrawal destination")
    end
    return data.eState --("Withdraw")
end

---Keeps home protection while allowing useful work already in construction reach.
---@param platoon table Commander platoon
---@return string Commander shelter state
function subPlanCommanderShelter(platoon)
    local commander,data,current=CommanderRequest(platoon)
    if not current() then return "Disband" end
    if RushTacticsV8.CanDefendHome(platoon, data.commanderFacesLethalDamage)
        or (not data.commanderStaysHome and not data.commanderFacesLethalDamage and not data.commanderIsInImmediateDanger) then
        ClearCommanderShelterData(platoon)
        return "SelectMainTarget"
    end
    local shieldUnit = data.commanderShelterShieldUnit
    local shieldIndex = data.commanderShelterShieldIndex
    if shieldUnit and not IsCommanderShelterShieldUsable(shieldUnit,shieldIndex,platoon.army) then
        StopCommanderProductionAssist(platoon,commander,"defence")
        data.commanderShelterShieldUnit = nil
        data.commanderShelterShieldIndex = nil
        local _,reason=StartCommanderShelterMovement(platoon)
        if not current() then return "Disband" end
        if reason=="stale-request" then return data.eState or "CommanderShelter" end
    elseif not shieldUnit then
        local newShieldUnit, newShieldIndex = SelectCommanderShelterShield(platoon)
        if newShieldUnit then
            StopCommanderProductionAssist(platoon,commander,"defence")
            data.commanderShelterShieldUnit = newShieldUnit
            data.commanderShelterShieldIndex = newShieldIndex
            local _,reason=StartCommanderShelterMovement(platoon)
            if not current() then return "Disband" end
            if reason=="stale-request" then return data.eState or "CommanderShelter" end
        end
    end
    local protected=CommanderIsSheltered(platoon,commander)
    if protected and not data.commanderFacesLethalDamage
        and not data.commanderIsInImmediateDanger and not data.commanderUnderAttack then
        local service=data.rushCommanderService
        -- Keep a service order that already owns the commander; otherwise
        -- wait for the precise shelter point before handing off movement.
        if service or not data.commanderShelterMovementActive or CommanderShelterMovementReached(platoon) then
            data.commanderShelterMovementActive=false
            data.path=false
            commander.ai.path=false
            UpdateCommanderProductionAssist(platoon,true)
            if not current() then return "Disband" end
            return "CommanderShelter"
        end
    else
        StopCommanderProductionAssist(platoon,commander,"defence")
    end
    if not data.commanderShelterMovementActive then
        local _,reason=StartCommanderShelterMovement(platoon)
        if not current() then return "Disband" end
        if reason=="stale-request" then return data.eState or "CommanderShelter" end
        return "CommanderShelter"
    end
    -- Productive travel has no arbitrary 15-second expiry. The common move
    -- observer handles real stalls without sending the ACU back to old nodes.
    local moving,moveReason=MoveToDestination(commander,data.gatherPoint)
    if not current() then return "Disband" end
    if moveReason=="stale-request" then return data.eState or "CommanderShelter" end
    if not moving or CommanderShelterStalled(platoon,commander) then
        local _,reason=StartCommanderShelterMovement(platoon)
        if not current() then return "Disband" end
        if reason=="stale-request" then return data.eState or "CommanderShelter" end
    end
    return "CommanderShelter"
end

---Handles the micro-management of the platoon during close combat, adjusting unit positions for optimal engagement.
---@param platoon table Platoon class table containing units and related data
---@return string The next state of the platoon, either continuing micro-management or transitioning to "FinishMicroingPlatoon"
function subPlanMicroingSinglePlatoon(platoon)
    local commander,platoonAI,current,sameOrders=CommanderRequest(platoon)
    if not current() then return "Disband" end
    if RushMovementV18.Suspended(commander) then return platoonAI.eState or "SelectMainTarget" end
    -- do we have targets in range?
    local platoonPosition = RushMovementV18.Copy(platoon:GetPosition())
    local primary=platoon.ai.primaryTarget
    local primaryPosition=IsAttackTargetAvailable(primary) and RushCombatIntel.Visible(platoon.army,primary)
        and RushMovementV18.Copy(GetUnitPositionForCurrentSimulationTick(primary))
    local engagement=CalculatePlatoonEngagementRadius(platoon)
    if primaryPosition and RushCombatIntel.Visible(platoon.army,primary) and CanPlatoonShootTarget(platoon,primary)
        and Distance2DSquared(platoonPosition.x,platoonPosition.z,primaryPosition.x,primaryPosition.z)<=engagement*engagement then
        platoon.ai.microTarget=primary
    else
        local nearby=GetClosestShootableEnemy(platoon,platoonPosition,engagement,Tags.ALL_UNITS)
        if not current() then return "Disband" end
        if not sameOrders() then return platoonAI.eState or "SelectMainTarget" end
        platoonAI.microTarget=nearby
    end
    if IsAttackTargetAvailable(platoon.ai.microTarget) then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMicroingSinglePlatoon():[A:" .. platoon.army.id .. "][P:" .. platoon.id .. "] microTarget present, call MicroingAttackUnits")
        end
        if not sameOrders() then return platoonAI.eState or "SelectMainTarget" end
        RushMovementV18.Forget(commander,true)
        -- set unit data
        SetUnitMicroData(platoon)
        -- Shared land micro only assigns targets and orders to PlatoonControlled units.
        for _, unit in pairs(platoon:GetUnits()) do unit.ai.eState = "PlatoonControlled" end
        -- First micro turn for attack units
        local unitsToCover, eState = MicroingAttackUnits(platoon)
        if not current() then return "Disband" end
        if platoon.ai.eState ~= eState then
            return eState
        end
        WaitTicks(1)
        if not current() then return "Disband" end
        -- Second micro turn for cover/shield units
        MicroingSupportUnits(platoon, unitsToCover)
    else
        -- no micro target in range, continue moving to the (new) primary target
        if not sameOrders() then return platoonAI.eState or "SelectMainTarget" end
        RushMovementV18.Forget(commander,false)
        ClearCombatOrders(platoon:GetUnits())
        ClearLandMicroFormationData(platoon)
        platoon.ai.microTarget = false
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMicroingSinglePlatoon():[A:" .. platoon.army.id .. "][P:" .. platoon.id .. "] switching [eState] = " .. platoon.ai.eState .. " to SelectMainTarget. (lost microTarget)")
        end
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMicroingSinglePlatoon():[A:" .. platoon.army.id .. "][P:" .. platoon.id .. "] switching [eState] = " .. platoon.ai.eState .. " to SelectMainTarget. (lost microTarget)")
        end
        return "SelectMainTarget"
    end
    return current() and platoonAI.eState or "Disband"
end

