---Initializes the movement of a support platoon towards the primary platoon.
---@param platoon table The support platoon that is executing this movement plan.
---@return string The next state for the platoon, either "MoveToPrimaryPlatoon", "SelectMainTarget", or "BackToBaseInit".
function subPlanMoveToPrimaryPlatoonInit(platoon)
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanMoveToPrimaryPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] set new platoon.ai.gatherPoint at primary platoon position")
    end
    --inform the primary platoon that we are approaching
    local primaryPlatoon = platoon.army:GetPlatoonWithUniqueName(platoon.ai.primaryPlatoonUniqueName or "PrimaryLandPlatoon")
    if primaryPlatoon and not primaryPlatoon.dead then
        local primaryPlatoonPosition = GetPrimaryPlatoonPosition(platoon)
        platoon.ai.gatherPoint = primaryPlatoonPosition
        if platoon.ai.gatherPoint then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanMoveToPrimaryPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] added to primary platoon search list")
            end

            -- can be nil if the primary platoon was just created but not initialized
            if primaryPlatoon.ai and primaryPlatoon.ai.approachingPlatoons then
                primaryPlatoon.ai.approachingPlatoons[platoon.id] = platoon
                if InitMoveToDestination(platoon, platoon.ai.gatherPoint) then
                    if lobbyOptionsAI.debugGameTelemetry then
                        local currentGameTime = GetGameTimeSeconds()
                        local secondsSincePreviousPathInitialization = platoon.ai.primaryPlatoonPathInitializationTime and currentGameTime - platoon.ai.primaryPlatoonPathInitializationTime or -1
                        local platoonPosition = platoon:GetPosition()
                        local distanceToPrimaryPlatoon = math.floor(math.sqrt(Distance2DSquared(platoonPosition.x, platoonPosition.z, primaryPlatoonPosition.x, primaryPlatoonPosition.z)))
                        local distanceToDestination = math.floor(math.sqrt(Distance2DSquared(platoonPosition.x, platoonPosition.z, platoon.ai.gatherPoint.x, platoon.ai.gatherPoint.z)))
                        AILog(" --- TacticalLandSupportPath [A:"..platoon.army.id.."][P:"..platoon.id.."]["..platoon.ai.formerTable.FormerName.."] Event:Initialized Reason:"..tostring(platoon.ai.primaryPlatoonPathInitializationReason or "Initial").." Interval:"..tostring(secondsSincePreviousPathInitialization).." DistanceToPrimary:"..tostring(distanceToPrimaryPlatoon).." DistanceToDestination:"..tostring(distanceToDestination))
                        platoon.ai.primaryPlatoonPathInitializationTime = currentGameTime
                        platoon.ai.primaryPlatoonPathInitializationReason = nil
                    end
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanMoveToPrimaryPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] moving to primary platoon position")
                    end
                    return "MoveToPrimaryPlatoon"
                else
                    if platoon.ai.formerTable.DebugPlatoon then
                        AILog("* Fn subPlanMoveToPrimaryPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] no path to primary platoon -> BackToBaseInit")
                    end
                    return "BackToBaseInit"
                end
            end
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanMoveToPrimaryPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] primary land platoon is not initialized yet.")
            end
            return "SelectMainTarget"
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanMoveToPrimaryPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to BackToBaseInit. (no PrimaryPlatoonPosition)")
            end
            return "BackToBaseInit"
        end
    else
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMoveToPrimaryPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to BackToBaseInit. (no primary platoon)")
        end
        return "BackToBaseInit"
    end
end

---Handles the movement of a support platoon towards the primary platoon.
---@param platoon table The support platoon executing this movement plan.
---@return string The next state for the platoon, either "SelectMainTarget", "MergingPlatoon", or the current state if movement is still ongoing.
function subPlanMoveToPrimaryPlatoon(platoon)
    --check if the target area has changed
    if not platoon.ai.path then
        platoon.ai.primaryPlatoonPathInitializationReason = "MissingPath"
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to SelectMainTarget. (missing path)")
        end
        return "SelectMainTarget"
    end
    local pathTargetPosition = platoon.ai.path[table.getn(platoon.ai.path)]
    if not pathTargetPosition then
        platoon.ai.primaryPlatoonPathInitializationReason = "MissingPathTarget"
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to SelectMainTarget. (missing path target position)")
        end
        return "SelectMainTarget"
    end
    local primaryPlatoon = platoon.army:GetPlatoonWithUniqueName(platoon.ai.primaryPlatoonUniqueName or "PrimaryLandPlatoon")
    local primaryPlatoonPosition = primaryPlatoon and not primaryPlatoon.dead and primaryPlatoon:GetPosition()
    local platoonPosition = platoon:GetPosition()
    if not primaryPlatoonPosition then
        platoon.ai.primaryPlatoonPathInitializationReason = "PrimaryUnavailable"
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to SelectMainTarget. (no primaryPlatoonPosition)")
        end
        return "SelectMainTarget"
    end
    if Distance2DSquared(pathTargetPosition.x, pathTargetPosition.z, primaryPlatoonPosition.x, primaryPlatoonPosition.z) > 900 then -- 30
        platoon.ai.primaryPlatoonPathInitializationReason = "PrimaryPositionMoved"
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to SelectMainTarget. (primary platoon position moved more than 30 units)")
        end
        return "SelectMainTarget"
    end
    for _, unit in pairs(platoon:GetUnits()) do
        if unit.ai.eState == "PlatoonControlled" then
            local destinationWasReached = unit.ai.moveToDestinationReached
            if not MoveToDestination(unit, platoon.ai.gatherPoint) and not destinationWasReached then
                if lobbyOptionsAI.debugUnitEState then
                    unit.ai.orderText = "primary platoon reached"
                end
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unit has reached the previous primary platoon position")
                end
            end
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..unit.id.index.."] unhandled unit.ai.eState: ["..repr(unit.ai.eState).."]")
            end
        end
    end
    local distanceBetweenPlatoonsSquared = Distance2DSquared(platoonPosition.x, platoonPosition.z, primaryPlatoonPosition.x, primaryPlatoonPosition.z)
    if distanceBetweenPlatoonsSquared <= 900 then -- 30
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to MergingPlatoonInit. (distanceBetweenPlatoons <= 30)")
        end
        return "MergingPlatoonInit"
    end
    local previousPrimaryPlatoonPosition = platoon.ai.gatherPoint
    if previousPrimaryPlatoonPosition and Distance2DSquared(platoonPosition.x, platoonPosition.z, previousPrimaryPlatoonPosition.x, previousPrimaryPlatoonPosition.z) <= 900 then -- 30
        platoon.ai.primaryPlatoonPathInitializationReason = "PreviousDestinationReached"
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to SelectMainTarget. (previous primary platoon position reached)")
        end
        return "SelectMainTarget"
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanMoveToPrimaryPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] distance to primary platoon: ("..math.floor(math.sqrt(distanceBetweenPlatoonsSquared))..")")
    end
    return platoon.ai.eState --("MoveToTargetArea")
end

---Retrieves the position of the primary platoon if it exists and is valid.
---@param platoon table Platoon class table containing units and related data
---@return table|boolean The position of the primary platoon as a table, or false if the primary platoon is not valid
function GetPrimaryPlatoonPosition(platoon)
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn GetPrimaryPlatoonPosition():[A:"..platoon.army.id.."][P:"..platoon.id.."] Searching for primary platoon position")
    end
    local primaryPlatoon = platoon.army:GetPlatoonWithUniqueName(platoon.ai.primaryPlatoonUniqueName or "PrimaryLandPlatoon")
    if primaryPlatoon and not primaryPlatoon.dead then
        return primaryPlatoon:GetPosition()
    end
    return false
end

---Initializes the merging process of a platoon with the primary platoon. Verifies the existence of the primary platoon and updates the merging state. Informs the primary platoon of the merging process and transitions to the "MergingPlatoon" state.
---@param platoon table The platoon that is ready to merge with the primary platoon.
---@return string The next state for the platoon, either "MergingPlatoon" if the primary platoon is valid, or "SelectMainTarget" if the primary platoon does not exist or is dead.
function subPlanMergingPlatoonInit(platoon)
    local primaryPlatoon = platoon.army:GetPlatoonWithUniqueName(platoon.ai.primaryPlatoonUniqueName or "PrimaryLandPlatoon")
    if not primaryPlatoon or primaryPlatoon.dead then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMergingPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..repr(platoon.ai.eState).." to MoveToTargetAreaInit. (no primaryPlatoon)")
        end
        return "SelectMainTarget"
    end
    if not primaryPlatoon.ai or not primaryPlatoon.ai.mergingPlatoons then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMergingPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..repr(platoon.ai.eState).." to SelectMainTarget. (primary platoon is not initialized)")
        end
        return "SelectMainTarget"
    end
    if lobbyOptionsAI.debugGameTelemetry then
        local currentGameTime = GetGameTimeSeconds()
        local secondsSincePathInitialization = platoon.ai.primaryPlatoonPathInitializationTime and currentGameTime - platoon.ai.primaryPlatoonPathInitializationTime or -1
        local platoonPosition = platoon:GetPosition()
        local primaryPlatoonPosition = primaryPlatoon:GetPosition()
        local distanceToPrimaryPlatoon = math.floor(math.sqrt(Distance2DSquared(platoonPosition.x, platoonPosition.z, primaryPlatoonPosition.x, primaryPlatoonPosition.z)))
        AILog(" --- TacticalLandSupportPath [A:"..platoon.army.id.."][P:"..platoon.id.."]["..platoon.ai.formerTable.FormerName.."] Event:Merge Interval:"..tostring(secondsSincePathInitialization).." DistanceToPrimary:"..tostring(distanceToPrimaryPlatoon))
    end
    primaryPlatoon.ai.mergingPlatoons[platoon.id] = platoon
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanMergingPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] Informed primary platoon that we are ready for merging units!")
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanMergingPlatoonInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..repr(platoon.ai.eState).." to MergingPlatoon.")
    end
    return "MergingPlatoon"
end

---Handles the merging process of a platoon with the primary platoon. Verifies its registration in the current primary merge table and waits for the merge to complete.
---@param platoon table The platoon that is currently in the process of merging with the primary platoon.
---@return string The current state of the platoon, or "SelectMainTarget" if the primary platoon does not exist or is dead.
function subPlanMergingPlatoon(platoon)
    local primaryPlatoon = platoon.army:GetPlatoonWithUniqueName(platoon.ai.primaryPlatoonUniqueName or "PrimaryLandPlatoon")
    if primaryPlatoon and not primaryPlatoon.dead then
        if not primaryPlatoon.ai or not primaryPlatoon.ai.mergingPlatoons or primaryPlatoon.ai.mergingPlatoons[platoon.id] ~= platoon then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanMergingPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to SelectMainTarget. (not registered in primary merge table)")
            end
            return "SelectMainTarget"
        end
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMergingPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] waiting for primary platoon that we are getting merged!")
        end
    else
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanMergingPlatoon():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to MoveToTargetAreaInit. (no primaryPlatoon)")
        end
        return "SelectMainTarget"
    end
    return platoon.ai.eState --("MergingPlatoon")
end

---Checks whether all living platoon units are within the configured disband distance from their base.
---@param platoon table The platoon returning to its base.
---@return boolean Returns true if all living units are within the configured distance.
local function AreAllPlatoonUnitsWithinBaseDisbandDistance(platoon)
    local returnToBaseDisbandDistance = platoon.ai.formerTable.AIPlanData and platoon.ai.formerTable.AIPlanData.ReturnToBaseDisbandDistance
    if not returnToBaseDisbandDistance then return false end
    local returnToBaseDisbandDistanceSquared = returnToBaseDisbandDistance * returnToBaseDisbandDistance
    for _, unit in pairs(platoon:GetUnits()) do
        if not unit.dead then
            local unitPosition = unit:GetPosition()
            if Distance2DSquared(unitPosition.x, unitPosition.z, platoon.ai.basePosition.x, platoon.ai.basePosition.z) > returnToBaseDisbandDistanceSquared then return false end
        end
    end
    return true
end

---Initializes the process for sending the platoon back to its base by setting a gather point and generating a path. If successful, transitions to the "BackToBase" state.
---@param platoon table The platoon that is being sent back to base.
---@return string The next state for the platoon, either "BackToBase" if the path is generated, or "RepairHome" if no path to the base position is found.
function subPlanBackToBaseInit(platoon)
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanBackToBaseInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] set new platoon.ai.gatherPoint at home base")
    end
    if AreAllPlatoonUnitsWithinBaseDisbandDistance(platoon) then
        ClearCombatOrders(platoon:GetUnits())
        return "Disband"
    end
    --set a position where all units meet
    platoon.ai.gatherPoint = platoon.ai.basePosition
    if InitMoveToDestination(platoon, platoon.ai.gatherPoint) then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanBackToBaseInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] moving to home base")
        end
        return "BackToBase"
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanBackToBaseInit():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to RepairHome. (no path to basePosition)")
    end
    return "RepairHome"
end

---Manages the process of moving the platoon back to its base. Checks if the primary platoon exists and switches state accordingly. Tracks unit movements and adjusts if they become stuck. Transitions to "Disband" when the home base is reached.
---@param platoon table The platoon that is moving back to base.
---@return string The next state for the platoon, either "SelectMainTarget" if the primary platoon exists, "Disband" if the platoon reaches home base, or the current state "BackToBase" if still in progress.
function subPlanBackToBase(platoon)
    local returnToBaseAndDisband = platoon.ai.formerTable.AIPlanData and platoon.ai.formerTable.AIPlanData.DefendBase == true
    if returnToBaseAndDisband and AreAllPlatoonUnitsWithinBaseDisbandDistance(platoon) then
        ClearCombatOrders(platoon:GetUnits())
        return "Disband"
    end
    if not returnToBaseAndDisband then
        local primaryPlatoon = platoon.army:GetPlatoonWithUniqueName(platoon.ai.primaryPlatoonUniqueName or "PrimaryLandPlatoon")
        -- A primary platoon's existence alone must not cancel a strength-based land withdrawal.
        if primaryPlatoon and not primaryPlatoon.dead and (platoon.ai.isNavalPlatoon or platoon.ai.supportThreatIsAttackable ~= false) then
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanBackToBase():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to SelectMainTarget. (primary platoon exists)")
            end
            return "SelectMainTarget"
        end
    end
    --check if all units have reached the gatherPoint
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanBackToBase():[A:"..platoon.army.id.."][P:"..platoon.id.."] moving to home base")
    end

    local stillMoving = false
    for i, unit in pairs(platoon:GetUnits()) do
        if unit.ai.eState == "PlatoonControlled" then
            if MoveToDestination(unit, platoon.ai.gatherPoint) then
                stillMoving = true
            else
                if lobbyOptionsAI.debugUnitEState then
                    unit.ai.orderText = "home base reached"
                end
                if platoon.ai.formerTable.DebugPlatoon then
                    AILog("* Fn subPlanBackToBase():[A:"..unit.army.id.."][P:"..unit.platoon.id.."][U:"..unit.id.index.."] unit has reached home base")
                end
            end
        else
            if platoon.ai.formerTable.DebugPlatoon then
                AILog("* Fn subPlanBackToBase():[A:"..platoon.army.id.."][P:"..platoon.id.."][U:"..unit.id.index.."] unhandled unit.ai.eState: ["..repr(unit.ai.eState).."]")
            end
        end
    end
    if not stillMoving then
        if platoon.ai.formerTable.DebugPlatoon then
            AILog("* Fn subPlanBackToBase():[A:"..platoon.army.id.."][P:"..platoon.id.."] switching [eState] = "..platoon.ai.eState.." to Disband. (reached home)")
        end
        return "Disband"
    end
    if platoon.ai.formerTable.DebugPlatoon then
        AILog("* Fn subPlanBackToBase():[A:"..platoon.army.id.."][P:"..platoon.id.."] still moving to home base")
    end
    return platoon.ai.eState --("BackToBase")
end

